        *(int*)(e + 0x54) = vy;
        *(int*)(e + 0x58) = vz;

        *(int*)(e + 0x44) += vx;
        *(int*)(e + 0x48) += vy;
        *(int*)(e + 0x4c) += vz;

        *(int*)(e + 0x1c) = *(int*)(anchor + 0x1c) + *(int*)(e + 0x44);
        *(int*)(e + 0x20) = *(int*)(anchor + 0x20) + *(int*)(e + 0x48);
        *(int*)(e + 0x24) = *(int*)(anchor + 0x24) + *(int*)(e + 0x4c);

