    private static void EntityHandler_00450D30(uint* entity)
    {
        byte* e = (byte*)entity;

        *(int*)(e + 0x50) = 0;
        *(int*)(e + 0x54) = 0;
        *(int*)(e + 0x58) = 0;

        if (*(short*)(e + 0x10) == unchecked((short)0xFF01)) *(short*)(e + 0x10) = 1;
        if (*(short*)(e + 0x10) == unchecked((short)0xFFFE)) return;

        if (*(short*)(e + 0x10) == 0)
        {
