            // sera le sien, et la valeur est rangee en positif dans +0x9a.
            short opening = *(short*)(e + 0x30);
            *(short*)(e + 0x10) = unchecked((short)0xFFFF);
            *(short*)(e + 0x9a) = opening;
            *(short*)(e + 0x98) = 0;

