            FreezeAllEntities();

            // Le son d'ouverture : meme double indirection que EntityHandler_004509B0, a +8 pres.
            byte soundId = (*(byte**)(*(byte**)(s_Unknown_005e97cc + 0xa8)))[8];
            TryPlaySoundNearEntity(entity, soundId, 0x146, 0x3000, 0, 0);

            entity[0] &= 0xFBFFFFFF;
            *(short*)(e + 0x10) = 2;
            *(short*)(e + 0x12) = 0;
        }

        if (*(short*)(e + 0x10) == 2)
        {
