                // identifiant, et l'identifiant est celui range en +0x9a a l'amorcage.
                int flagBit = *(short*)(e + 0x9a);
                if ((Mem.s_StateBank0_005e96e0[flagBit >> 3] & (1 << (flagBit & 7))) != 0)
                {
                    *(short*)(e + 0x10) = 0x12C;
                    *(short*)(e + 0x12) = 0;
                    return;
                }

                int contents = *(int*)(e + 0x48);
                short rest;

                if (*(short*)(e + 0x14) == -1)
                {
                    if (contents == 0)
                    {
                        // Vide et sans etiquette : on repart directement sur la fermeture.
                        *(short*)(e + 0x10) = 0x28;
                        *(short*)(e + 0x12) = 0;
                        goto tail;
                    }

                    rest = *(short*)(e + 0x98);
                    *(short*)(e + 0x98) = 0x28;
                }
                else
                {
                    if (contents == 0)
                    {
                        *(short*)(e + 0x10) = 0x14;
                        *(short*)(e + 0x12) = 0;
                        goto tail;
                    }

                    rest = *(short*)(e + 0x98);
                    *(short*)(e + 0x98) = 0x14;
                }

                // L'objet sort du coffre : une entite d'effet, dont le type est le contenu decale
                // dans la plage 0xC0.
                SpawnEffectEntity(e, (byte)(contents + 0xC0), 0, -1);
                *(short*)(e + 0x98) = rest;
                *(short*)(e + 0x12) = 0;
                *(short*)(e + 0x10) = 0x3E7;
            }
        }

    tail:
        state = *(short*)(e + 0x10);

        if (state == 0x14)
        {
