            entity[0] &= 0xFBFFFFFF;
            *(short*)(e + 0x10) = 0xC9;
        }

        if (*(short*)(e + 0x10) == 0xC9)
        {
            // La refermeture : le couvercle revient de 0x46 par image jusqu'a repasser par zero.
            *(short*)(e + 0x34) += 0x46;
