            byte* labels = *(byte**)(*(byte**)(s_Unknown_005e97c8 + 0x70) + 0x118);
            BindMenuLabels(labels, *(uint*)(e + 0x6c), s_WorldMapDescriptor_005633b0, 0);

            // `mov [esi+10h],di`, et EDI vaut 0xC8 ici — pas zero.
            *(short*)(e + 0x10) = 0xC8;
        }
