    private static readonly byte* s_ItemMessageScratch_005de620 = (byte*)NativeMemory.AllocZeroed(0x80);

    /// <summary>
    /// Ghidra: FUN_00530f20 @ 0x00530f20 — <b>la remise d'un objet au groupe</b>, avec la boite de
    /// dialogue qui l'annonce. C'est ce qu'un coffre appelle quand on en prend le contenu.
    ///
    /// <para>Le deroule est en quatre temps. Le monde se fige ; chaque membre du groupe qui peut se
    /// servir de l'objet prend une <b>animation de reaction</b> choisie par sa classe dans
    /// <see cref="s_ReactionAnimations_0056aaa0"/>, apres que son etat d'animation courant a ete mis
    /// de cote en <c>+0x40</c> et <c>+0x42</c> ; l'inventaire du porteur est parcouru ; et une
    /// phrase est composee puis confiee au moteur de texte.</para>
    ///
    /// <para><b>La valeur de retour dit si l'objet est passe</b> : zero quand il est remis,
    /// <c>quantite + 1</c> quand il ne l'est pas — inventaire plein, ou destinataire qui n'est pas
    /// un membre du groupe. Les deux appelants ne lisent que <c>AX</c> (<c>neg ax</c>) ou
    /// <c>AL</c>, d'ou les retrecissements explicites a leurs sites.</para>
    ///
    /// <para><b>L'objet n'est pas rangé ici.</b> La fonction ne fait que vider les deux mots
    /// <c>+0x310</c> et <c>+0x312</c> de l'emplacement libre ; le rangement proprement dit est dans
    /// le rappel de fin de boite, que l'appelant passe en troisieme argument. Ne pas s'attendre a
    /// voir une copie de la fiche d'objet dans ce corps.</para>
    ///
    /// <para>L'inventaire du porteur fait dix emplacements de <c>0x280</c> octets a
    /// <c>MainMem + 0xf0000 + indice * 0x2000 + 0x300</c>. Un emplacement dont les seize premiers
    /// octets — le nom court — egalent ceux de l'objet est un <b>empilement</b> : si l'objet porte
    /// un des bits <c>0x30</c> en <c>+0x13</c>, la remise se fait dans cet emplacement-la sans
    /// chercher plus loin.</para>
    ///
    /// <para>Le champ <c>+0x86</c> de la fiche d'objet, entre <c>0x32c9</c> et <c>0x32cf</c>, decrit
    /// une famille a part : elle passe outre l'inventaire des que les trois bits bas de
    /// <c>+0x150</c> du bloc du porteur valent 4. TODO(REVERSE) : la nature de cette famille n'est
    /// pas etablie.</para>
    /// </summary>
    /// <param name="recipient">Ghidra <c>param_1</c> — l'entite a qui l'objet est remis. Sans le
    /// bit <c>0x800000</c> (membre du groupe), la fonction refuse sans rien afficher.</param>
    /// <param name="amount">Ghidra <c>param_2</c> — l'indice de la fiche d'objet, pas une
    /// quantite : il indexe la table de <c>0x140</c> octets pointee par <c>DAT_00600824</c> et sert
    /// aussi a placer l'icone dans sa planche (colonne = indice % 10, ligne = indice / 10 + 4, au
    /// pas de 24 pixels).</param>
    /// <param name="callback">Ghidra <c>param_3</c> — l'adresse du rappel de fin de boite, range
    /// tel quel en <c>+0x8a8</c> du descripteur. Deux des trois appelants reconstruits y passent
    /// <c>0x00450700</c> ; <see cref="EntityHandler_00473ED0"/>, le coffre de la table 0x0056adc8,
    /// y passe <c>0x00474320</c>. Les deux adresses portent <b>le meme corps</b> — voir
    /// <see cref="ChestPickupDone_00450700"/>.</param>
    private static int GrantChestContents_00530F20(uint* recipient, int amount, uint callback)
    {
        if ((*recipient & 0x800000) == 0) return amount + 1;

        FreezeAllEntities();                                 // Ghidra: FUN_00535300(0)

        *Mem.Entity(0x005f7b50) = (byte)amount;
        Mem.s_PanelSelection_005e9060[0x3c] = 1;             // Ghidra: DAT_005e909c
        Mem.s_PanelSelection_005e9060[0x3d] = 3;             // Ghidra: DAT_005e909d
        Mem.s_PanelSelection_005e9060[0x3e] = 0;             // Ghidra: DAT_005e909e

        byte* item = *(byte**)Mem.Entity(0x00600824) + amount * 0x140;

        // Le sous-repertoire +0x94 porte le descripteur d'icone en +0xc et, en +0x28, le mot que
        // les reactions du groupe recopient.
        byte* iconDirectory = *(byte**)(Mem.s_MainResourceDirectory_005e97c4 + 0x94);
        byte* icon = *(byte**)(iconDirectory + 0xc);
        icon[7] = *Mem.Entity(0x005f7b50);
        icon[0] = (byte)(amount % 10 * 0x18);
        icon[1] = (byte)((amount / 10 + 4) * 0x18);

        byte* mainMem = GetMainMemPtr();

        // --- les reactions du groupe ---------------------------------------------------------
        if (s_PartySize_005e9020 != 0)
        {
            byte* slot = Inp.s_SlotFlags_005e93c0;
            byte* block = mainMem + 0xf0150;

            for (int i = s_PartySize_005e9020; i != 0; i--, slot += 0x9c, block += 0x2000)
            {
                // L'etat d'animation courant est mis de cote ; FUN_00530ed0 le rendra.
                slot[0x40] = slot[0x1a];
                slot[0x42] = slot[0x18];

                uint flags = *(uint*)slot;
                if ((flags & 0x80000000) == 0 || (flags & 0x50000000) != 0) continue;

                // +0xf0112 du bloc du personnage porte les classes qui savent se servir d'un objet,
                // +0x12 de la fiche celles auxquelles il est destine.
                if ((*(ushort*)(block - 0x3e) & *(ushort*)(item + 0x12)) == 0) continue;

                *(uint*)(slot + 0x18) = ((uint*)s_ReactionAnimations_0056aaa0)[*block];
                *(uint*)(slot + 0x3c) = *(uint*)(iconDirectory + 0x28);
            }
        }

        // --- ou l'objet doit aller ------------------------------------------------------------
        byte* holder = mainMem + 0xf0000 + (byte)recipient[2] * 0x2000;
        byte* target = Mem.Entity(0x005eca90);

        bool deliver = false;
        ushort family = *(ushort*)(item + 0x86);

        if (family >= 0x32c9 && family <= 0x32cf)
        {
            if ((holder[0x150] & 7) == 4)
            {
                *(ushort*)(item + 0x12) |= 0x8000;
                deliver = true;                              // l'emplacement reste celui d'avant
            }
            else
            {
                *(ushort*)(item + 0x12) &= 0x3fff;
            }
        }
        else if (recipient[0x1b] != 0)
        {
            *(ushort*)(item + 0x12) &= 0x3fff;
        }

        if (!deliver)
        {
            int occupied = 0;
            byte* stored = holder + 0x300;
            *target = 0;

            for (int i = 0; i < 10; i++, stored += 0x280)
            {
                byte chosen = (byte)i;

                if (*stored != 0)
                {
                    int k = 0;
                    while (k < 0x10 && stored[k] == item[k]) k++;

                    if (k == 0x10)
                    {
                        if ((*(ushort*)(stored + 0x12) & 0x8000) != 0)
                        {
                            *(ushort*)(item + 0x12) |= 0x8000;
                        }

                        // Empilable : on s'arrete sur cet emplacement-ci, dont l'indice reste dans
                        // `chosen` — c'est ce que l'original garde en sautant a la remise.
                        if ((item[0x13] & 0x30) != 0)
                        {
                            *target = chosen;
                            deliver = true;
                            break;
                        }
                    }

                    occupied++;
                    chosen = *target;                        // emplacement pris : on garde le dernier libre
                }

                *target = chosen;
            }

            if (!deliver)
            {
                if (occupied == 10)
                {
                    // Inventaire plein : la phrase d'echec, et l'objet reste ou il est.
                    AnnounceItem(item, recipient, 0x2b4, 0x3fc, 0x00530ed0);
                    return amount + 1;
                }

                *(ushort*)(holder + *target * 0x280 + 0x310) = 0;
                *(ushort*)(holder + *target * 0x280 + 0x312) = 0;
            }
        }

        AnnounceItem(item, recipient, 0x2ac, 0x26c, callback);
        return 0;
    }

    /// <summary>
    /// Les deux sorties de <see cref="GrantChestContents_00530F20"/> composent leur phrase de la
    /// meme facon ; l'original ecrit le code deux fois, a trois constantes pres. Reunies ici parce
    /// que c'est une unite qui se tient, pas pour eviter une repetition.
    ///
    /// <para>Quand l'objet porte le bit <c>0x8000</c>, la phrase est <b>construite</b> : un prefixe
    /// pris dans la table de libelles du repertoire, le nom de l'objet mis en forme par
    /// <see cref="BuildItemDisplayName"/>, puis un suffixe de huit octets et un NUL. Sinon elle est
    /// simplement <b>choisie</b> : le premier des bits 8 a 13 de <c>+0x12</c> designe une entree
    /// toute faite.</para>
    ///
    /// <para>La boucle de prefixe copie <b>au moins quatre octets</b> avant de s'arreter sur un
    /// NUL — <c>*src != 0 || i &lt; 4</c> — donc elle recopie les NUL des libelles courts. Transcrit
    /// tel quel : ces quatre octets sont vraisemblablement un en-tete de sequence du moteur de
    /// texte.</para>
    ///
    /// <para>La recherche de bit s'arrete a 13 <b>par le test de fin de boucle</b>, pas par une
    /// borne : si aucun bit n'est pose, l'indice sort a 14 et designe l'entree suivante de la
    /// table. Conserve.</para>
    /// </summary>
    private static void AnnounceItem(byte* item, uint* recipient, int suffix, int fallback, uint callback)
    {
        byte* labels = *(byte**)(Mem.s_MainResourceDirectory_005e97c4 + 0x70);

        if ((*(ushort*)(item + 0x12) & 0x8000) != 0)
        {
            byte* dest = s_ItemMessageScratch_005de620;
            byte* src = *(byte**)(labels + 0x2a8);

            for (int i = 0; *src != 0 || i < 4; i++)
            {
                *dest++ = *src++;
            }

            dest = BuildItemDisplayName(dest, item);         // Ghidra: FUN_0051bcc0

            byte* tail = *(byte**)(labels + suffix);
            for (int i = 0; i < 8; i++)
            {
                *dest++ = *tail++;
            }

            *dest = 0;

            BindMenuLabels(s_ItemMessageScratch_005de620, (uint)(nint)recipient,
                           s_WorldMapDescriptor_005633b0, callback);
            return;
        }

        int bit = 8;
        while ((*(ushort*)(item + 0x12) & (1 << (bit & 0x1f))) == 0 && ++bit < 0xe) { }

        BindMenuLabels(*(byte**)(labels + fallback + bit * 4), (uint)(nint)recipient,
                       s_WorldMapDescriptor_005633b0, callback);
    }

    /// <summary>
    /// Ghidra: FUN_00530ed0 @ 0x00530ed0 — <b>le miroir exact</b> de la mise de cote faite en tete
    /// de <see cref="GrantChestContents_00530F20"/> : chaque membre du groupe retrouve son animation
    /// (<c>+0x18</c> et <c>+0x1a</c> repris de <c>+0x42</c> et <c>+0x40</c>) et ses deux mots
    /// <c>+0x3c</c> / <c>+0x3e</c> sont remis a zero.
    ///
    /// <para>Il rearme en prime les quatre bits hauts de l'octet d'entree de chaque manette
    /// (<c>DAT_00604a24 + slot * 4</c>), ce qui rend la main au joueur.</para>
    ///
    /// <para>C'est le rappel de fin de boite de la <b>sortie d'echec</b> : quand l'inventaire est
    /// plein, la seule chose a faire en refermant le message est de defaire la mise en scene.</para>
    /// </summary>
    internal static void RestorePartyReactions_00530ED0()
    {
        if (s_PartySize_005e9020 == 0) return;

        byte* slot = Inp.s_SlotFlags_005e93c0;
        byte* pads = Inp.s_PlayerSlots_005e9188;

        for (int i = s_PartySize_005e9020; i != 0; i--, slot += 0x9c, pads += 0x4c)
        {
            *(ushort*)(slot + 0x1a) = slot[0x40];
            *(ushort*)(slot + 0x3c) = 0;
            *(ushort*)(slot + 0x3e) = 0;
            *(ushort*)(slot + 0x18) = slot[0x42];

            Inp.s_InputStateBase_00604a20[*pads * 4 + 4] |= 0xf0;
        }
    }

    /// <summary>
    /// Ghidra: FUN_005312d0 @ 0x005312d0 — <b>le rangement proprement dit</b> : la fiche d'objet est
    /// recopiee dans l'emplacement d'inventaire, son icone est decoupee de la VRAM et posee a la
    /// place qui revient au personnage, et le compteur d'exemplaires monte d'un.
    ///
    /// <para><b>Ne pas suivre <c>Blaze.c</c> sur cette fonction.</b> Ghidra y a perdu la convention
    /// de <c>FUN_0053db20</c> et de <c>FUN_00532710</c>, qu'il declare sans parametre : leurs
    /// arguments apparaissent comme des affectations a des locales (<c>puStack_20</c>,
    /// <c>uStack_24</c>) et leurs adresses de retour comme des valeurs (<c>iStack_30 = 0x53134e</c>).
    /// Les quatre appels d'ordinaux subissent le meme sort. Tout ce qui suit est transcrit depuis le
    /// desassemblage, conserve dans <c>Legacy/Raw/Blaze/Chest/</c> ; <c>Blaze.c</c> n'a servi que
    /// pour la charpente.</para>
    ///
    /// <para>Les deux sorties anticipees rendent <c>indice + 1</c>, la meme convention que
    /// <see cref="GrantChestContents_00530F20"/> : <c>DAT_005e909f</c> leve (un menu occupe l'ecran)
    /// ou destinataire qui n'est pas un membre du groupe.</para>
    ///
    /// <para><b>La famille <c>0x32c9..0x32cf</c> ne passe pas par l'inventaire</b> : quand les trois
    /// bits bas de <c>+0x150</c> du bloc du porteur valent 4, l'objet incremente un simple compteur.
    /// L'original ecrit <c>holder[famille - 0x3151]</c>, soit <c>holder[0x178 + (famille -
    /// 0x32c9)]</c> : <b>sept compteurs contigus a <c>+0x178</c></b>. Ce sont exactement les sept
    /// octets que le verbe de zone <c>0x00442F20</c> remonte a 5 quand ils sont en dessous — les
    /// deux relevés se confirment l'un l'autre. La forme d'origine est conservee ici pour rester
    /// comparable au desassemblage.</para>
    ///
    /// <para><b>La recopie ecrase le compteur, et l'original le sait</b> : les <c>0x50</c> dwords de
    /// la fiche recouvrent <c>+0x310</c> et <c>+0x312</c> de l'emplacement, donc le compteur
    /// d'exemplaires et le bit <c>0x8000</c> sont releves avant et remis apres. Le compteur plafonne
    /// a 99.</para>
    ///
    /// <para>L'icone se fait en <b>deux passes identiques</b> : un rectangle de <c>0x10 x 1</c> pour
    /// la palette, un de <c>6 x 0x18</c> pour l'image. Chacune est lue de la VRAM vers l'emplacement
    /// (<c>+0x440</c> et <c>+0x460</c>) par l'ordinal 684, puis recopiee a sa place d'affichage par
    /// l'ordinal 676. Les ordinaux 667 qui les encadrent sont des appels vides confirmes.</para>
    /// </summary>
    /// <returns>Zero si l'objet est range, <c>indice + 1</c> sinon.</returns>
    internal static int StoreItemInInventory_005312D0(uint* recipient)
    {
        RestorePartyReactions_00530ED0();                 // Ghidra: FUN_00530ed0()

        byte index = *Mem.Entity(0x005f7b50);
        if (Mem.s_Unknown_005e909f != 0) return index + 1;
        if ((*recipient & 0x800000) == 0) return index + 1;

        byte* item = *(byte**)Mem.Entity(0x00600824) + index * 0x140;
        byte* holder = GetMainMemPtr() + 0xf0000 + (byte)recipient[2] * 0x2000;

        Aud.PlayPositionalSound(0x29, 0x400, 0x1300, (int*)((byte*)recipient + 0x1c));

        // Le coffre lui-meme : on le desarme et on rend son emplacement au pool.
        uint* chest = *(uint**)((byte*)recipient + 0x6c);
        if (chest != null)
        {
            *chest &= 0x7fffffff;
            FreeEntitySlot(Mem.Entity(0x005f7b60), (byte)chest[2]);
        }

        if ((holder[0x150] & 7) == 4)
        {
            ushort family = *(ushort*)(item + 0x86);
            if (family >= 0x32c9 && family <= 0x32cf)
            {
                holder[family - 0x3151]++;
                return 0;
            }
        }

        byte target = *Mem.Entity(0x005eca90);
        byte* slot = holder + target * 0x280;

        ushort keptFlags = *(ushort*)(slot + 0x312);
        ushort keptCount = *(ushort*)(slot + 0x310);

        uint* destination = (uint*)(slot + 0x300);
        uint* source = (uint*)item;
        for (int i = 0x50; i != 0; i--) *destination++ = *source++;

        // --- l'icone, deux passes ---------------------------------------------------------------
        byte* atlas = Mem.s_EntityDecodeTable_005e8f00;
        short* rect = stackalloc short[4];

        // Passe 1 : la palette. DAT_005e8fa6 place la planche dans la VRAM.
        ushort clutOrigin = *(ushort*)(atlas + 0xa6);
        rect[0] = (short)(((index & 0xf) + (clutOrigin & 0x3f)) * 0x10);
        rect[1] = (short)((index >> 4) + (clutOrigin >> 6));
        rect[2] = 0x10;
        rect[3] = 1;

        Winsys3d.Ordinal_667(0);
        Winsys3d.Ordinal_684(rect, slot + 0x440);
        Winsys3d.Ordinal_667(0);
        Winsys3d.Ordinal_676((ushort*)rect, target * 0x10, (byte)recipient[2] + 0x1f1);

        // Passe 2 : l'image. DAT_005e8fa4 place l'autre planche, et l'icone y occupe une case de
        // 6 x 0x18 sur une grille de dix colonnes.
        ushort iconOrigin = *(ushort*)(atlas + 0xa4);
        rect[0] = (short)((iconOrigin & 0xf) * 0x40 + index % 10 * 6);
        rect[1] = (short)((iconOrigin & 0x10) * 0x10 + (index / 10 + 4) * 0x18);
        rect[2] = 6;
        rect[3] = 0x18;

        Winsys3d.Ordinal_667(0);
        Winsys3d.Ordinal_684(rect, slot + 0x460);
        Winsys3d.Ordinal_667(0);
        Winsys3d.Ordinal_676((ushort*)rect, target * 6 + 0x180, (byte)recipient[2] * 0x18 + 0x100);

        // --- le compteur, que la recopie vient d'ecraser ----------------------------------------
        *(ushort*)(slot + 0x310) = keptCount;
        *(ushort*)(slot + 0x312) |= (ushort)(keptFlags & 0x8000);

        if (*(ushort*)(slot + 0x310) < 99)
        {
            *(ushort*)(slot + 0x310) += 1;
        }

        return 0;
    }

    /// <summary>
    /// Ghidra: FUN_00450700 @ 0x00450700 — <b>le rappel de fin de boite du coffre</b> : ce que le
    /// moteur de texte appelle quand le joueur referme « untel obtient tel objet ». Quatre-vingt-sept
    /// octets, <b>absente de <c>Blaze.c</c></b> ; dump dans <c>Legacy/Raw/Blaze/Chest/</c>.
    ///
    /// <para>Elle range l'objet, puis <b>ecrit le verdict dans deux endroits</b> : l'etat du coffre
    /// en <c>+0x10</c> — <c>0xC8</c> si l'objet est passe, <c>0x64</c> sinon, les deux valeurs que
    /// <c>TickEntityTable</c> aiguille — et la table de butin <c>0x005e9860</c>, qui retient ce qui
    /// reste a donner pour que le coffre puisse etre rouvert.</para>
    ///
    /// <para>Le coffre est retrouve par <c>entite[0x41]</c>, l'octet que le script y a range juste
    /// avant d'appeler <see cref="GrantChestContents_00530F20"/>.</para>
    ///
    /// <para>
    /// <b>Le meme corps vit a une seconde adresse, <c>0x00474320</c></b>, celle que
    /// <see cref="EntityHandler_00473ED0"/> passe en rappel. Les 87 octets sont identiques dans le
    /// binaire a l'exception du deplacement relatif du <c>call</c>, et les deux visent
    /// <c>0x005312D0</c> : le compilateur a emis deux fois le meme code sans les replier. Les deux
    /// adresses sont donc aiguillees ici, dans <c>Engine/UiText.cs</c>. Dumps cote a cote dans
    /// <c>Legacy/Raw/Blaze/Chest/</c>.
    /// </para>
    /// </summary>
    internal static void ChestPickupDone_00450700(uint* entity)
    {
        byte index = ((byte*)entity)[0x41];

        *(uint*)((byte*)entity + 0x6c) = 0;
        Mem.s_PanelSelection_005e9060[0] = 0;             // Ghidra: DAT_005e9060

        byte* chest = Mem.Entity(0x005fa5e0) + index * 0x9c;
        int remaining = StoreItemInInventory_005312D0(entity);
        byte* drops = Mem.Arena(0x005e9860);

        if (remaining != 0)
        {
            *(ushort*)(chest + 0x10) = 0xC8;
            drops[*(int*)(chest + 0x44)] = (byte)remaining;
            return;
        }

        *(ushort*)(chest + 0x10) = 0x64;
        drops[*(int*)(chest + 0x44)] = 0;
    }


    // =====================================================================
    // L'INTELLIGENCE DES ENTITES DE SCENE — la famille 0x0049xxxx
    //
    // Le gestionnaire de sous-type 2 de la table installee 0x0056ad48, atteint par la passe
    // FUN_0050e680 des l'apparition d'un monstre. Ghidra n'a presque RIEN decompile de cette
    // plage : sur 0x00491290..0x004a1020 il ne rend que cinq corps, et pas celui-ci. Tout ce qui
    // suit vient du desassembleur (Legacy/Raw/Blaze/FUN_0049A980.asm et ses deux voisins).
    // =====================================================================

    /// <summary>
    /// Ghidra: FUN_00535f20 @ 0x00535f20 — <b>la lecture de situation</b> d'une entite de scene :
    /// elle remplit cinq valeurs a partir de l'entite, de sa cible et de son bloc de statistiques.
    /// C'est le seul appel qui precede la decision, et tout
    /// <see cref="TickSceneEntityAi_0049A980"/> raisonne sur ce qu'elle rend.
    ///
    /// <para>
    /// <b>Le corps est dans <c>Blaze.c</c>, mais sa signature ne l'est pas.</b> Ghidra a perdu
    /// <c>EBX</c>, <c>EBP</c> et l'adresse de retour, et — plus trompeur — il a ecrit les
    /// <b>cinq</b> sorties sur le meme <c>*param_2</c>. A le lire ainsi on obtient une fonction qui
    /// ecrase quatre fois sa propre sortie. Le desassemblage tranche : ce sont cinq pointeurs
    /// distincts, et l'arithmetique de pile les separe sans ambiguite
    /// (<c>Legacy/Raw/Blaze/FUN_00535F20.asm</c>).
    /// </para>
    /// </summary>
    /// <param name="boldness">Sortie : de 0 a 0x40. Part de l'ecart entre le niveau du poursuivi
    /// (<c>bloc par personnage + 0x146</c>) et celui de l'entite (<c>stat + 0x44</c>), corrige par
    /// le rapport <c>stat[0x4c] / stat[0x48]</c>, borne aux deux bouts. Le trait <c>0x200</c> la
    /// force a 0x40 avant correction. C'est l'echelle sur laquelle toute la suite lit ses seuils,
    /// et son complement a 0x40 sert de mesure inverse.</param>
    /// <param name="distance">Sortie : la distance a la cible, <b>en trois dimensions</b>.</param>
    /// <param name="heading">Sortie : le cap vers la cible <b>relatif</b> a l'orientation de
    /// l'entite, sur douze bits. Le trait <c>8</c> le remplace par un tirage.</param>
    /// <param name="speed">Sortie : l'echelle de deplacement, <c>0x1000</c> par defaut. Cinq
    /// conditions la modifient et trois la mettent a zero — <b>et zero veut dire « ne pense
    /// pas »</b> : l'appelant renonce a toute la decision.</param>
    /// <param name="traits">Sortie : <c>stat + 0x40</c>, le mot de comportement de l'espece.</param>
    private static void ReadSceneEntitySituation_00535F20(
        byte* entity, int* boldness, int* distance, int* heading, int* speed, uint* traits)
    {
        byte* mainMem = GetMainMemPtr();
        byte* stats = s_EntityStatBlocks_005ea560 + entity[8] * 0x120;
        byte* chased = *(byte**)(entity + 0x6c);

        *traits = *(uint*)(stats + 0x40);

        byte* perChar = mainMem + (chased[8] + 0x78) * 0x2000;
        *boldness = *(ushort*)(perChar + 0x146) - *(ushort*)(stats + 0x44);

        if ((*traits & 0x200) != 0) *boldness = 0x40;

        *boldness += 0x20 - (*(short*)(stats + 0x4c) * 0x20) / *(short*)(stats + 0x48);
        if (*boldness < 0) *boldness = 0;
        else if (*boldness > 0x40) *boldness = 0x40;

        int dx = (*(int*)(chased + 0x1c) - *(int*)(entity + 0x1c)) >> 0xc;
        int dy = (*(int*)(chased + 0x20) - *(int*)(entity + 0x20)) >> 0xc;
        int dz = (*(int*)(chased + 0x24) - *(int*)(entity + 0x24)) >> 0xc;

        *heading = (Winsys3d.Ordinal_457(dx, dz) - *(ushort*)(entity + 0x32)) & 0xfff;
        *distance = (int)Winsys3d.Ordinal_442((uint)(dx * dx + dy * dy + dz * dz));

        if ((*traits & 8) != 0) *heading = CrtRand() & 0xfff;

        *speed = 0x1000;
        if ((*traits & 0x4000) != 0) *speed = 0x1333;
        if ((*traits & 0x8000) != 0) *speed = 0xccc;
        if ((*traits & 4) != 0) *speed = 0x800;
        if ((*traits & 0x1c0) != 0) *speed = 0;
        if ((*(uint*)entity & 0x80) != 0) *speed = 0;

        // La derniere condition lit le bloc de statistiques, pas les traits : une entite « tenue »
        // (+0x74 non nul) ne bouge plus, sauf si son espece porte le bit de tete de stat[0x14].
        if ((*(uint*)(stats + 0x14) & 0x80000000) == 0 && *(byte**)(entity + 0x74) != null)
        {
            *speed = 0;
        }
    }

    /// <summary>
    /// Ghidra: FUN_00488160 @ 0x00488160 — <b>l'integration du mouvement</b> d'une entite de scene,
    /// appelee sans condition a la fin de chaque decision.
    ///
    /// <para>
    /// <b>Meme piege de signature que sa voisine</b> : <c>Blaze.c</c> la declare a un parametre puis
    /// lit <c>unaff_EBP</c> et <c>unaff_retaddr</c>. Le desassemblage donne deux parametres —
    /// l'entite et l'echelle de vitesse — et <c>unaff_EBP</c> n'est que le sinus dont Ghidra a jete
    /// la valeur de retour, exactement comme il le fait dans <c>FUN_0049a8e0</c>, sa jumelle.
    /// </para>
    /// <para>
    /// Les trois composantes de vitesse (<c>+0x50</c>, <c>+0x54</c>, <c>+0x58</c>) sont amorties
    /// d'un huitieme et d'un deux-cent-cinquante-sixieme par image, puis ajoutees a la position ;
    /// la poussee dirigee de <c>+0x5c</c> s'ajoute a X et Z par le sinus et le cosinus du cap. La
    /// composante verticale porte en plus le rappel de <c>+0x9a</c>, le flottement propre a
    /// l'espece.
    /// </para>
    /// </summary>
    private static void IntegrateSceneEntityMotion_00488160(byte* entity, int speed)
    {
        int course = *(short*)(entity + 0x32);
        int sin = (int)Winsys3d.GetSinTableEntry(course);   // Ghidra: Ordinal_451
        int cos = (int)Winsys3d.GetCosTableEntry(course);   // Ghidra: Ordinal_450

        int vx = *(int*)(entity + 0x50);
        int vy = *(int*)(entity + 0x54);
        int vz = *(int*)(entity + 0x58);
        int bob = *(short*)(entity + 0x9a);
        int thrust = (*(int*)(entity + 0x5c) * speed) >> 0xc;

        int nvx = vx - (vx >> 3) - (vx >> 8);
        int nvy = (bob >> 8) - (vy >> 8) - bob + vy;
        int nvz = vz - (vz >> 8) - (vz >> 3);

        *(int*)(entity + 0x50) = nvx;
        *(int*)(entity + 0x54) = nvy;
        *(int*)(entity + 0x58) = nvz;

        *(int*)(entity + 0x1c) += ((thrust * sin) >> 0xc) + nvx;
        *(int*)(entity + 0x20) += nvy;
        *(int*)(entity + 0x24) += ((thrust * cos) >> 0xc) + nvz;
    }

    /// <summary>
    /// Ghidra: FUN_004dfaf0 @ 0x004dfaf0 — <b>la fin de geste</b> : quand le compteur de
    /// <c>+0x20</c> a rattrape la borne de <c>+0x64</c>, le bit 0 du mot d'etat tombe et l'entite
    /// cesse d'etre « en cours d'animation ». Sinon il est repose.
    /// </summary>
    private static void EndSceneEntityAnimation_004DFAF0(uint* entity)
    {
        if ((int)entity[8] <= (int)entity[0x19] && (entity[0x24] & 0xa000) == 0)
        {
            entity[8] = entity[0x19];
            uint flags = *entity;

            if ((flags & 1) != 0 && (flags & 0x816) == 0)
            {
                ((byte*)entity)[0x43] = 0;
            }

            entity[0x15] = 0;
            *entity = flags & 0xfffffffe;
            return;
        }

        if ((*entity & 1) == 0) *entity |= 1;
    }

    /// <summary>
    /// Ghidra: FUN_004e3770 @ 0x004e3770 — <b>l'interruption</b> : ce qui remet une entite de scene
    /// a l'attente quand quelque chose lui arrive. Deux causes, et la seconde est le clignotement de
    /// degat (<c>+0x96</c>) que <see cref="TickEntityTable_005ecaa0"/> decompte.
    ///
    /// <para>Elle prend le <b>bloc de statistiques</b> en second parametre — celui que
    /// <see cref="ResolveEntityBlocks"/> a resolu au tout debut du gestionnaire, et le seul de ses
    /// trois resultats qui serve.</para>
    /// </summary>
    private static void InterruptSceneEntity_004E3770(uint* entity, byte* stats)
    {
        byte* e = (byte*)entity;

        if ((entity[0x24] & 0x2000a882) != 0)
        {
            if ((*entity & 0x817) == 0)
            {
                e[0x42] = 1;
                e[0x43] = 1;
            }

            entity[0x17] = 0;
        }

        if (*(short*)(e + 0x96) != 0
            && (*(uint*)(stats + 0x14) & 0x80000000) == 0
            && (*entity & 0x817) == 0)
        {
            if ((*entity & 0x40) != 0)
            {
                e[0x43] = 0;
                return;
            }

            e[0x42] = 0;
            e[0x43] = 1;
            entity[0x17] = 0;
        }
    }

    /// <summary>
    /// Ghidra: FUN_00538af0 @ 0x00538af0 — <b>rebase un bloc de statistiques sur son modele</b>, en
    /// appliquant le bonus de difficulte. Les huit resistances elementaires de <c>modele + 0x28</c>
    /// partent elargies en <c>ushort</c> dans <c>stat + 0x110</c> ; les huit <c>short</c> de
    /// <c>modele + 0x30</c> sont mis a l'echelle de <c>100 + bonus</c> pour cent.
    ///
    /// <para>Le bonus ne s'applique que si <c>stat[0x14]</c> porte son bit de tete ; sinon
    /// l'echelle vaut 100 pour cent, c'est-a-dire rien. Le <c>&gt;&gt; 0x3f</c> et le
    /// <c>&gt;&gt; 0x1f</c> que Ghidra ajoute autour de la division sont la correction de signe de
    /// l'idiome de division par 100 : le net est une division tronquee.</para>
    /// </summary>
    private static void RebaseStatBlockOnModel_00538AF0(byte* entity)
    {
        ResolveEntityBlocks(entity, out byte* stats, out _, out byte* model);

        uint bonus;
        int percent;

        if ((*(uint*)(stats + 0x14) & 0x80000000) == 0)
        {
            bonus = 0;
            percent = 100;
        }
        else
        {
            bonus = s_DifficultyBonus_0056d2c0[s_Unknown_005de034];
            percent = (int)bonus + 100;
        }

        for (int i = 0; i < 8; i++)
        {
            *(ushort*)(stats + 0x110 + i * 2) = model[0x28 + i];
        }

        for (int i = 0; i < 8; i++)
        {
            int scaled = *(short*)(model + 0x30 + i * 2) * percent;
            *(short*)(stats + 0x30 + i * 2) = (short)(scaled / 100);
        }

        *(ushort*)(stats + 0x2c) = *(ushort*)(model + 0x18);
        *(short*)(stats + 0x2e) = (short)(*(short*)(model + 0x1a) + (short)((int)bonus >> 3));
    }

    /// <summary>
    /// Ghidra: FUN_00538c10 @ 0x00538c10 — <b>l'empreinte au sol d'une entite</b> : les deux
    /// demi-etendues de sa boite de collision, prises dans une table ou dans l'autre selon qu'elle
    /// est un membre du groupe (bit <c>0x800000</c>) ou une entite de scene.
    ///
    /// <para>
    /// <b>Le meme enregistrement de huit octets sert des deux cotes</b>, et c'est ce qui a resolu
    /// le <c>TODO(REVERSE)</c> pose sur <see cref="s_ClassBodyMetrics_0056d440"/> : <c>+0</c> et
    /// <c>+4</c> sont les demi-etendues, <c>+2</c> la hauteur de la bulle d'etat que
    /// <see cref="StatusBubbleHeight_00538BC0"/> lit deja. Les deux lectures se confirment l'une
    /// l'autre — celle-ci prend <c>stat + 0x58</c> pour une entite de scene, celle-la
    /// <c>stat + 0x5a</c> pour la hauteur, soit le meme bloc a deux octets pres.
    /// </para>
    /// </summary>
    private static byte* EntityFootprint_00538C10(uint* entity)
    {
        if ((*entity & 0x800000) != 0)
        {
            byte characterClass = GetMainMemPtr()[(byte)entity[2] * 0x2000 + 0xf0150];
            return s_ClassBodyMetrics_0056d440 + characterClass * 8;
        }

        return s_EntityStatBlocks_005ea560 + (byte)entity[2] * 0x120 + 0x58;
    }

    /// <summary>Le format de point que <see cref="PolygonOverlapMask_005358F0"/> attend : deux
    /// coordonnees au sol empaquetees dans un dword, X en bas et Z en haut. C'est la disposition
    /// d'un registre <c>SXY</c> du GTE, ou ces points transitent.</summary>
    private static uint PackGroundPoint(int x, int z) => ((uint)z << 0x10) | ((uint)x & 0xffff);

    /// <summary>
    /// Ghidra: FUN_005358f0 @ 0x005358f0 — <b>de quel cote de chaque arete tombe chaque sommet</b> :
    /// seize produits en croix, un par couple (arete de <paramref name="edges"/>, sommet de
    /// <paramref name="corners"/>), dont seuls les <b>signes</b> sont gardes, empiles dans un mot
    /// de seize bits.
    ///
    /// <para>
    /// <b>Ghidra la declare a un parametre ; elle en prend deux.</b> Le second quadrilatere devient
    /// chez lui un <c>local_24[4]</c> jamais initialise — c'est la meme perte de signature que
    /// <c>FUN_00535f20</c>, et le site d'appel la trahit (<c>push</c>, <c>push</c>,
    /// <c>add esp,8</c>).
    /// </para>
    /// <para>
    /// <b>Le produit en croix passe par le GTE.</b> Les trois points vont dans <c>SXY0</c>,
    /// <c>SXY1</c>, <c>SXY2</c> et le resultat sort de <c>MAC0</c> — c'est <c>NCLIP</c>, l'operation
    /// d'elimination des faces arriere, detournee ici en test de cote. Le portage l'ecrit en x86 et
    /// range quand meme le resultat dans le registre : <see cref="NormalClip"/> reproduit les deux.
    /// </para>
    /// <para>
    /// <b>Le decalage est en retard d'un tour</b>, et ce n'est pas une maladresse : c'est la
    /// latence du coprocesseur d'origine. Chaque tour empile le signe du produit <i>precedent</i>,
    /// et un dernier decalage apres les boucles rattrape le seizieme. Le bit 16 qui en resulte est
    /// le zero initial, toujours nul, donc le mot rendu tient bien sur seize bits.
    /// </para>
    /// </summary>
    private static uint PolygonOverlapMask_005358F0(uint* edges, uint* corners)
    {
        EnsureGteRegisters();

        // Le quatrieme sommet est recopie en tete pour fermer le contour : les quatre aretes se
        // lisent alors comme quatre couples consecutifs.
        uint* loop = stackalloc uint[5];
        loop[0] = edges[0];
        loop[1] = edges[1];
        loop[2] = edges[2];
        loop[3] = edges[3];
        loop[4] = edges[0];

        uint* tested = stackalloc uint[4];
        tested[0] = corners[0];
        tested[1] = corners[1];
        tested[2] = corners[2];
        tested[3] = corners[3];

        uint mask = 0;
        int previous = 0;

        for (int edge = 0; edge < 4; edge++)
        {
            *(uint*)s_GteSxy806 = loop[edge];
            *(uint*)s_GteSxy807 = loop[edge + 1];

            for (int corner = 0; corner < 4; corner++)
            {
                *(uint*)s_GteSxy805 = tested[corner];
                NormalClip();

                mask = mask * 2 | ((uint)previous >> 0x1f);
                previous = ReadMac0();
            }
        }

        return mask * 2 | ((uint)previous >> 0x1f);
    }

    /// <summary>
    /// Ghidra: FUN_00535a40 @ 0x00535a40 — <b>ce que le mot de seize signes veut dire</b>. Trois
    /// reponses, et <see cref="TestMeleeReach_00535A90"/> additionne celles des deux sens :
    ///
    /// <list type="bullet">
    /// <item><c>0xffff</c> — les seize sommets sont du meme cote de toutes les aretes : recouvrement
    /// franc, <b>1</b>.</item>
    /// <item>un quartet entierement nul — un sommet du polygone teste est en dehors d'<b>une</b>
    /// arete, donc separe : <b>-1</b>, et ce -1 annule le +1 de l'autre sens.</item>
    /// <item>sinon, le compte de bits : plus de neuf sur seize vaut <b>1</b>, le reste <b>0</b>.
    /// C'est le cas des recouvrements partiels, tranche a la majorite.</item>
    /// </list>
    /// </summary>
    private static int ClassifyOverlapMask_00535A40(uint mask)
    {
        if (mask == 0xffff) return 1;

        uint quartet = 0xf;
        for (int i = 4; i != 0; i--)
        {
            if ((mask & quartet) == 0) return -1;
            quartet <<= 4;
        }

        int set = 0;
        uint bit = 1;
        for (int i = 0x10; i != 0; i--)
        {
            if ((mask & bit) != 0) set++;
            bit <<= 1;
        }

        return 9 < set ? 1 : 0;
    }

    /// <summary>
    /// Ghidra: FUN_00535a90 @ 0x00535a90 — <b>le test de portee</b> : est-ce que le geste de
    /// l'entite touche ce membre du groupe ? 1158 octets, transcrite au desassembleur
    /// (<c>Legacy/Raw/Blaze/FUN_00535A90.asm</c>).
    ///
    /// <para>
    /// <b>Elle est dans <c>Blaze.c</c> et elle y est inexploitable.</b> Ghidra y a perdu <c>EBX</c>,
    /// <c>ESI</c>, <c>EDI</c> et les arguments des quatre appels a <c>Ordinal_450</c>/<c>451</c>, il
    /// la declare a trois parametres quand <c>FUN_00519c30</c> lui en passe quatre, et il rend une
    /// des deux figures comme un tableau local jamais rempli. Ce qu'il en reste ne se lit pas.
    /// </para>
    ///
    /// <para>
    /// <b>La fonction croise deux figures a plat</b>, apres un rejet en hauteur qui, lui, est bien
    /// rendu : si l'ecart vertical entre le membre et l'entite depasse <c>sonde[3]</c> plus la
    /// demi-hauteur du membre, rien ne peut toucher — c'est le seul endroit ou la troisieme
    /// dimension compte.
    /// </para>
    /// <list type="number">
    /// <item><b>Le quadrilatere du geste</b>, construit sur la sonde : cap de l'entite decale de
    /// <c>sonde[0]</c>, avance de <c>sonde[1]</c>, largeur <c>sonde[2]</c> de part et d'autre, puis
    /// une profondeur <c>sonde[5]</c> prise sur deux caps ouverts de <c>±sonde[4]</c>. Avec la
    /// sonde de <see cref="TickSceneEntityAi_0049A980"/> (<c>0, 0x1e, 0x32, 0x64, 0, 0x50</c>) cela
    /// donne un simple rectangle de 0x64 sur 0x50, pose 0x1e devant la bete.</item>
    /// <item><b>Le rectangle du membre</b>, construit sur son empreinte
    /// (<see cref="EntityFootprint_00538C10"/>) tournee de son cap. Noter le
    /// <c>-(largeur * sinus) &gt;&gt; 12</c> : la negation precede le decalage, ce qui n'est pas la
    /// meme chose que nier le decalage.</item>
    /// <item><b>Le croisement</b>, dans les <b>deux sens</b> — chaque figure jugee contre les aretes
    /// de l'autre. C'est ce qui rattrape le cas ou l'une contient l'autre sans qu'aucun sommet ne
    /// franchisse d'arete.</item>
    /// </list>
    /// </summary>
    private static bool TestMeleeReach_00535A90(int* position, byte* member, short* probe, byte* entity)
    {
        // ---------------------------------------------------------------- le rejet en hauteur
        int half = StatusBubbleHeight_00538BC0((uint*)member) >> 1;
        int gap = ((*(int*)(member + 0x20) - position[1]) >> 0xc) + half;
        if (gap < 0) gap = -gap;
        if (gap > probe[3] + half) return false;

        // ---------------------------------------------------------------- la figure du geste
        int course = *(short*)((byte*)position + 0x16) + probe[0];
        int sin = (int)Winsys3d.GetSinTableEntry(course);   // Ghidra: Ordinal_451
        int cos = (int)Winsys3d.GetCosTableEntry(course);   // Ghidra: Ordinal_450

        // Le centre de la face avant, encore en virgule fixe : la position de l'entite avancee de
        // sonde[1]. Le decalage de douze bits n'intervient qu'apres l'ecart lateral.
        int frontX = probe[1] * sin + position[0];
        int frontZ = probe[1] * cos + position[2];

        int nearRightX = (frontX + probe[2] * cos) >> 0xc;
        int nearLeftX = (frontX - probe[2] * cos) >> 0xc;
        int nearRightZ = (frontZ - probe[2] * sin) >> 0xc;
        int nearLeftZ = (frontZ + probe[2] * sin) >> 0xc;

        int farLeftX = nearLeftX + ((int)Winsys3d.GetSinTableEntry(course - probe[4]) * probe[5] >> 0xc);
        int farLeftZ = nearLeftZ + ((int)Winsys3d.GetCosTableEntry(course - probe[4]) * probe[5] >> 0xc);
        int farRightX = nearRightX + ((int)Winsys3d.GetSinTableEntry(course + probe[4]) * probe[5] >> 0xc);
        int farRightZ = nearRightZ + ((int)Winsys3d.GetCosTableEntry(course + probe[4]) * probe[5] >> 0xc);

        uint* swing = stackalloc uint[4];
        swing[0] = PackGroundPoint(nearRightX, nearRightZ);
        swing[1] = PackGroundPoint(nearLeftX, nearLeftZ);
        swing[2] = PackGroundPoint(farLeftX, farLeftZ);
        swing[3] = PackGroundPoint(farRightX, farRightZ);

        // ---------------------------------------------------------------- la figure du membre
        int memberCourse = *(short*)(member + 0x32);
        int memberSin = (int)Winsys3d.GetSinTableEntry(memberCourse);
        int memberCos = (int)Winsys3d.GetCosTableEntry(memberCourse);

        int memberX = *(int*)(member + 0x1c) >> 0xc;
        int memberZ = *(int*)(member + 0x24) >> 0xc;

        byte* footprint = EntityFootprint_00538C10((uint*)member);
        int across = *(short*)footprint;
        int along = *(short*)(footprint + 4);

        int acrossX = (across * memberCos) >> 0xc;
        int acrossZ = (-(across * memberSin)) >> 0xc;
        int alongX = (along * memberSin) >> 0xc;
        int alongZ = (along * memberCos) >> 0xc;

        int cornerX = memberX + (acrossX >> 1) + (alongX >> 1);
        int cornerZ = memberZ + (acrossZ >> 1) + (alongZ >> 1);

        uint* body = stackalloc uint[4];
        body[0] = PackGroundPoint(cornerX, cornerZ);
        body[1] = PackGroundPoint(cornerX - alongX, cornerZ - alongZ);
        body[2] = PackGroundPoint(cornerX - alongX - acrossX, cornerZ - alongZ - acrossZ);
        body[3] = PackGroundPoint(cornerX - acrossX, cornerZ - acrossZ);

        // ---------------------------------------------------------------- le trace de mise au point
        if (Mem.s_DebugModeLatch_005633a8 == 0 && s_DebugOverlayEnabled_005de020 != 0)
        {
            throw new NotImplementedException(
                "FUN_00535a90 : le trace de mise au point (0x00535d1d a 0x00535ec8) n'est pas " +
                "transcrit. Il pose les huit sommets des deux figures en entites d'effet, par huit " +
                "appels a SpawnStatusEffectEntity_0047AC40 (sous-types 4 a 7, deux fois) dont le " +
                "descripteur est &DAT_0056aca0 — une table qui reste a relever dans le binaire, " +
                "et la seule chose qui manque pour l'ecrire. DAT_005de020 vaut 0 au chargement, " +
                "donc ce bloc ne s'atteint que par la touche de mise au point, elle-meme non " +
                "transcrite.");
        }

        // ---------------------------------------------------------------- le croisement
        int forward = ClassifyOverlapMask_00535A40(PolygonOverlapMask_005358F0(swing, body));
        int backward = ClassifyOverlapMask_00535A40(PolygonOverlapMask_005358F0(body, swing));

        return forward + backward > 0;
    }

    /// <summary>Ghidra: &amp;DAT_00564808 — le <b>descripteur d'atlas</b> que
    /// <see cref="ValidateCombatants_0053A860"/> passe a <c>FUN_0047ac40</c> quand un coup arrive
    /// avec un assaillant invalide. Huit octets, releves verbatim dans <c>.data</c> ; les huit
    /// suivants (<c>d0 28 28 08 01 00 30 02</c>) forment un second descripteur de meme forme, non
    /// designe par ce site.</summary>
    private static readonly byte* s_ErrorMarkerAtlas_00564808 = AllocBytes([
        0xa0, 0x28, 0x24, 0x08, 0x01, 0x00, 0x30, 0x02,
    ]);

    /// <summary>
    /// Ghidra: FUN_0053a860 @ 0x0053a860 — <b>le controle d'identite des deux combattants</b>, et
    /// la premiere chose que fait la resolution du coup : elle ne rend zero que si les deux sont
    /// vivants et rangés dans la table qui correspond a leur nature.
    ///
    /// <para>
    /// Le mot rendu est un <b>diagnostic</b>, pas un booleen : quartet bas pour l'assaillant,
    /// quartet haut pour la victime, et dans chaque quartet <c>1</c> pour « pas alloue »,
    /// <c>2</c> pour « membre du groupe hors de sa table », <c>4</c> pour « entite de scene hors de
    /// la sienne », <c>8</c> pour « ni l'un ni l'autre ». L'appelant n'en lit que la nullite, mais
    /// la valeur reste lisible en debogage.
    /// </para>
    /// <para>
    /// <b>Les deux bornes sont des comparaisons de POINTEUR dans l'original</b> — <c>param_1</c>
    /// contre <c>&amp;DAT_005e93c0</c>..<c>&amp;DAT_005e9594</c> et <c>&amp;DAT_005ecaa0</c>..
    /// <c>&amp;DAT_005ede20</c>. Ici les deux tables sont deux allocations distinctes, donc la
    /// comparaison se fait contre leurs etendues reconstruites : quatre emplacements de 0x9c pour
    /// le groupe, trente-deux pour la scene. Les bornes hautes du binaire sont <b>inclusives d'un
    /// emplacement de trop</b> (elles designent le premier octet APRES la table) et c'est transcrit
    /// tel quel.
    /// </para>
    /// </summary>
    private static byte ValidateCombatants_0053A860(uint* attacker, uint* victim)
    {
        byte* partyBase = Inp.s_SlotFlags_005e93c0;          // 0x005e93c0, quatre fois 0x9c
        byte* sceneBase = Mem.Entity(0x005ecaa0);            // 0x005ecaa0, trente-deux fois 0x9c

        byte report = (byte)(((*attacker & 0x80000000) == 0) ? 1 : 0);

        if ((*attacker & 0x800000) == 0)
        {
            if ((*attacker & 0x400000) == 0) report |= 8;
            else if ((byte*)attacker < sceneBase || sceneBase + 0x1380 < (byte*)attacker) report |= 4;
        }
        else if ((byte*)attacker < partyBase || partyBase + 0x1d4 < (byte*)attacker)
        {
            report |= 2;
        }

        if ((*victim & 0x80000000) == 0) report |= 0x10;

        if ((*victim & 0x800000) == 0)
        {
            if ((*victim & 0x400000) == 0) report |= 0x80;
            else if ((byte*)victim < sceneBase || sceneBase + 0x1380 < (byte*)victim) report |= 0x40;
        }
        else if ((byte*)victim < partyBase || partyBase + 0x1d4 < (byte*)victim)
        {
            report |= 0x20;
        }

        // Assaillant douteux mais victime saine : une marque visible est posee sur la victime. Le
        // cas inverse ne dit rien — c'est la seule trace laissee d'une incoherence.
        if ((report & 0x0f) != 0 && (report & 0xf0) == 0)
        {
            SpawnStatusEffectEntity_0047AC40(
                (byte*)victim, (int*)((byte*)victim + 0x1c), s_ErrorMarkerAtlas_00564808, 0x29, 0, 0);
        }

        return report;
    }

    /// <summary>
    /// Ghidra: FUN_005398a0 @ 0x005398a0 — <b>le penchant elementaire</b> : l'element nomme en
    /// <c>+0x51</c> du bloc gagne la moitie de sa valeur, et son <b>oppose</b> en perd la moitie.
    ///
    /// <para>L'oppose se designe par <c>indice ^ 1</c>, ce qui dit que les huit elements sont
    /// ranges par <b>couples contraires</b> : feu et eau, terre et air, lumiere et tenebres, sacre
    /// et mal. C'est la meme lecture que <see cref="ResolveElementalExchange_005398E0"/>, qui
    /// annule les couples l'un contre l'autre avant de compter.</para>
    /// </summary>
    private static void TiltDominantElement_005398A0(byte* block)
    {
        int element = block[0x51];

        ushort* mine = (ushort*)(block + 0x110 + element * 2);
        *mine = (ushort)((*mine >> 1) + *mine);

        ushort* opposite = (ushort*)(block + 0x110 + (element ^ 1) * 2);
        *opposite = (ushort)(*opposite - (*opposite >> 1));
    }

    /// <summary>
    /// Ghidra: FUN_005398e0 @ 0x005398e0 — <b>l'echange elementaire</b> : les huit elements de
    /// l'assaillant contre les huit de la victime, et le nombre rendu s'ajoute aux degats.
    ///
    /// <para>
    /// <b>Elle commence par vider les couples contraires, dans les DEUX blocs.</b> Feu et eau
    /// s'annulent l'un l'autre jusqu'a ce qu'il n'en reste qu'un ; idem pour les trois autres
    /// couples. Un bloc qui portait 30 de feu et 10 d'eau en ressort avec 20 de feu et rien d'eau.
    /// C'est une <b>modification en place</b> du bloc de statistiques, pas un calcul de cote : la
    /// fonction consomme ce qu'elle lit.
    /// </para>
    /// <para>
    /// <b>Puis le compte, element par element</b> : si la victime porte le meme element, il est
    /// <b>soustrait</b> — elle y resiste ; si elle ne le porte pas, il est ajoute, mais reduit au
    /// <b>quart</b> lorsqu'elle ne porte pas non plus son contraire. Attaquer par le feu paye plein
    /// tarif contre qui porte de l'eau, et au quart contre qui n'a ni l'un ni l'autre.
    /// </para>
    /// </summary>
    private static int ResolveElementalExchange_005398E0(byte* attackerBlock, byte* victimBlock)
    {
        for (int pass = 0; pass < 2; pass++)
        {
            ushort* pair = (ushort*)((pass == 0 ? attackerBlock : victimBlock) + 0x110);

            for (int couple = 0; couple < 4; couple++, pair += 2)
            {
                ushort first = pair[0];
                ushort second = pair[1];

                if (first < second)
                {
                    second = (ushort)(second - first);
                    first = 0;
                }
                else
                {
                    first = (ushort)(first - second);
                    second = 0;
                }

                pair[0] = first;
                pair[1] = second;
            }
        }

        // Le miroir de mise au point : les deux series de huit partent dans l'arene, ou l'ecran
        // « Gurkha » les relit. Le verrou vaut 1 au chargement, donc ce bloc dort en jeu normal.
        if (Mem.s_DebugModeLatch_005633a8 == 0)
        {
            for (int i = 0; i < 8; i++)
            {
                *(ushort*)(Mem.Arena(0x005e90a0) + i * 2) = *(ushort*)(attackerBlock + 0x110 + i * 2);
                *(ushort*)(Mem.Arena(0x005e90b0) + i * 2) = *(ushort*)(victimBlock + 0x110 + i * 2);
            }
        }

        int score = 0;

        for (int i = 0; i < 8; i++)
        {
            int attack = *(ushort*)(attackerBlock + 0x110 + i * 2);
            if (attack == 0) continue;

            int resisted = *(ushort*)(victimBlock + 0x110 + i * 2);

            if (resisted == 0)
            {
                if (*(short*)(victimBlock + 0x110 + (i ^ 1) * 2) == 0) attack >>= 2;
                score += attack;
            }
            else
            {
                score -= resisted;
            }
        }

        return score;
    }

    /// <summary>
    /// Ghidra: FUN_005399e0 @ 0x005399e0 — <b>l'element dominant</b> d'un bloc : l'indice du plus
    /// fort des huit, <b>decale de deux</b>, ou zero si le bloc n'en porte aucun. Le decalage n'est
    /// pas cosmetique — la valeur sert de teinte au nombre de degats que
    /// <see cref="ApplyDamage_00539A20"/> fait apparaitre, et 0 et 1 y designent deja autre chose.
    ///
    /// <para>En cas d'egalite c'est le <b>premier</b> qui gagne : la comparaison est stricte.</para>
    /// </summary>
    private static int DominantElement_005399E0(byte* block)
    {
        ushort best = 0;
        int index = 0;

        for (int i = 0; i < 8; i++)
        {
            ushort value = *(ushort*)(block + 0x110 + i * 2);
            if (best < value)
            {
                index = i;
                best = value;
            }
        }

        return best != 0 ? index + 2 : index;
    }

    /// <summary>
    /// Ghidra: FUN_00539a20 @ 0x00539a20 — <b>l'application des degats</b> : le nombre calcule est
    /// retire des points de vie, affiche, et la mort constatee.
    ///
    /// <para>
    /// <b>Le nombre passe par le bloc de statistiques avant d'etre utilise.</b> Il est ecrit en
    /// <c>+0x100</c> et <c>+0x102</c>, l'evenement d'objet equipe part, <b>puis il est relu</b> —
    /// c'est ce qui permet a un objet de modifier les degats qu'on subit ou qu'on inflige. L'ordre
    /// est le mecanisme, pas un detour.
    /// </para>
    /// <para>
    /// <b>L'evenement ne part pas du meme cote selon la victime</b> : une victime membre du groupe
    /// declenche ses propres objets (evenement 10), une entite de scene declenche ceux de
    /// l'assaillant (evenement 0x14).
    /// </para>
    /// <para>
    /// <b>Deux champs de l'entite servent de boite aux lettres</b> : le nombre part en <c>+0x18</c>
    /// et l'element en <c>+0x1a</c> le temps de l'appel a <c>FUN_0047a9d0</c>, puis le dword
    /// d'origine est remis. Le sauvetage de <c>+0x0a</c> qui l'accompagne est un <b>aller-retour a
    /// vide</b> — rien ne l'ecrit entre les deux — et il est conserve tel quel.
    /// </para>
    /// <para>
    /// A la mort, une entite de scene qui n'est pas marquee <c>0x80000000</c> dans <c>+0x14</c>
    /// laisse un effet dont le sous-type depend de sa famille : <c>0x51</c> a <c>0x54</c>, les tests
    /// se recouvrant volontairement — le dernier qui repond gagne.
    /// </para>
    /// </summary>
    /// <param name="attackerBlock">Jamais lu par le corps. L'appelant le pousse quand meme ; garde
    /// pour que le site d'appel reste lisible contre l'original.</param>
    /// <returns>1 si la victime en meurt, 0 sinon.</returns>
    private static int ApplyDamage_00539A20(
        uint* attacker, uint* victim, byte* attackerBlock, byte* victimBlock, short damage, byte element)
    {
        *(short*)(victimBlock + 0x96) = 0;
        *(uint*)(victimBlock + 0x40) &= 0xffffffbf;
        *(short*)(victimBlock + 0x100) = damage;
        victimBlock[0x102] = element;

        *(uint*)Mem.Arena(0x005e99c0) = 0;

        if ((*victim & 0x800000) == 0) TriggerEquippedItems_005238E0(attacker, 0x14);
        else TriggerEquippedItems_005238E0(victim, 10);

        // La relecture : l'evenement ci-dessus a pu changer les deux.
        byte shown = victimBlock[0x102];
        short dealt = *(short*)(victimBlock + 0x100);

        byte* v = (byte*)victim;
        SpawnParticle_0050F070((uint*)(v + 0x1c), (uint)(ushort)dealt, shown);

        uint savedState = *(uint*)(v + 0x18);
        *(short*)(v + 0x18) = dealt;
        ushort savedTint = *(ushort*)(v + 0x0a);
        *(ushort*)(v + 0x1a) = shown;

        *(short*)(victimBlock + 0x4c) -= dealt;

        if (*(short*)(victimBlock + 0x4c) < 1)
        {
            *(short*)(victimBlock + 0x4c) = 0;

            if ((*victim & 0x40000000) == 0)
            {
                *victim |= 0x40000000;
                *(uint*)(victimBlock + 0x40) |= 0x40000000;

                uint family = *(uint*)(victimBlock + 0x14);

                if ((*victim & 0x800000) == 0 && (family & 0x80000000) == 0)
                {
                    int leaving = 0;
                    if ((family & 0x19000) != 0) leaving = 0x51;
                    if ((family & 0xb600000) != 0) leaving = 0x52;
                    if ((family & 0x80000) != 0) leaving = 0x53;
                    if ((family & 0x4966800) != 0) leaving = 0x54;

                    if (leaving != 0) SpawnEffectEntity(v, (byte)leaving, 0, 0);
                }
            }

            *(ushort*)(v + 0x0a) = savedTint;
            *(uint*)(v + 0x18) = savedState;
            return 1;
        }

        SpawnEffectEntity(v, 0x50, 0, 0);
        *(uint*)(v + 0x18) = savedState;
        *(ushort*)(v + 0x0a) = savedTint;
        return 0;
    }

    /// <summary>
    /// Ghidra: FUN_00539b80 @ 0x00539b80 — <b>la resolution du coup</b> : ce qui se passe entre
    /// l'instant ou <see cref="TestMeleeReach_00535A90"/> a dit « touche » et l'instant ou la
    /// victime a perdu ses points de vie. C'est le cœur du combat.
    ///
    /// <para>
    /// <b>Elle recalcule les deux fiches avant de frapper</b>, et pas par prudence : les cinq passes
    /// de statistiques (<c>FUN_00538ab0</c>..<c>FUN_00538fa0</c>) reconstruisent equipement, bonus
    /// et derivees a partir de zero, si bien qu'un changement d'arme entre deux coups est pris en
    /// compte au coup suivant sans que rien n'ait a le notifier. Les deux chemins different : un
    /// membre du groupe repasse par les cinq, une entite de scene par trois seulement.
    /// </para>
    /// <para>
    /// <b>Les trois octets <c>+0x2b0</c>, <c>+0x2b1</c> et <c>+0x2b2</c> designent des lignes de
    /// 0x280 octets</b> dans le bloc du personnage, dont huit <c>char</c> signes a <c>+0x318</c>
    /// s'ajoutent aux huit elements de <c>+0x210</c>. Le premier vaut pour l'assaillant, le second
    /// pour la victime, et le <b>troisieme n'est lu que si la victime est debout</b> (posture 0 ou
    /// 6) — c'est la difference entre parer avec son arme et encaisser.
    /// </para>
    /// <para>
    /// <b>Le calcul des degats, dans l'ordre :</b> attaque et defense sont chacune bruitees d'un
    /// quart de leur ecart propre (<c>+0x2c</c>) puis bornees a zero ; un coup critique
    /// (<c>+0x2e</c> pour cent, plus cinq si l'assaillant est sous cinq pour cent de vie)
    /// <b>divise la defense par deux</b> et fait naitre l'effet <c>0xbe</c> ; l'echange elementaire
    /// s'ajoute a la difference ; un <b>type d'arme inadapte</b> (aucun bit commun entre la ligne
    /// d'arme et <c>+0x14</c> de la victime, sur le masque <c>0x6099500</c>) divise le tout
    /// <b>par quatre</b> ; le reste est borne a zero, augmente d'un sixieme de l'attaque moins un
    /// trente-deuxieme de la defense, et borne a <b>un</b>. Personne ne fait jamais zero.
    /// </para>
    /// <para>
    /// <b>Ce qui suit n'arrive que si l'assaillant est un membre du groupe</b> : le son (choisi sur
    /// la classe, six variantes, decalees par le resultat du coup), l'experience — l'ecart entre le
    /// niveau de la victime et celui de l'assaillant, au trente-deuxieme, plus un —, le compte de
    /// victimes, l'effet elementaire visible, et le bandeau de nom.
    /// </para>
    /// <para>
    /// <b>Une entite de scene qui survit garde qui l'a frappee</b> en <c>+0x09</c>, et si son octet
    /// <c>+0x0d</c> designe le genre 10, elle <b>lance son script</b> : c'est ainsi qu'un monstre
    /// reagit au fait d'etre attaque.
    /// </para>
    /// </summary>
    /// <returns>1 si le coup a ete refuse au controle d'identite, 0 sinon.</returns>
    private static int ResolveMeleeHit_00539B80(uint* attacker, uint* victim)
    {
        if (ValidateCombatants_0053A860(attacker, victim) != 0) return 1;

        *(byte**)((byte*)attacker + 0x70) = (byte*)victim;   // chacun retient l'autre
        *(byte**)((byte*)victim + 0x70) = (byte*)attacker;

        byte* attackerBlock = RefreshCombatantBlock(attacker, 0x2b0, false);
        byte* victimBlock = RefreshCombatantBlock(victim, 0x2b1, true);

        // Le bloc par personnage de l'ASSAILLANT, calcule sans egard a sa nature — le binaire le
        // fait aussi pour une entite de scene, et ne s'en sert alors jamais.
        byte* attackerCharacter = GetMainMemPtr() + ((byte)attacker[2] + 0x78) * 0x2000;

        if ((*attacker & 0x800000) != 0)
        {
            *(uint*)Mem.Arena(0x005e99c0) = 0;
            TriggerEquippedItems_005238E0(attacker, 2);
        }

        if ((*victim & 0x800000) != 0)
        {
            *(uint*)Mem.Arena(0x005e99c0) = 0;
            TriggerEquippedItems_005238E0(victim, 0xc);
        }

        // ---------------------------------------------------------------- attaque et defense
        short attackSpread = *(short*)(attackerBlock + 0x2c);
        int attack = *(short*)(attackerBlock + 0x30)
                     + ((CrtRand() % (attackSpread + 1) - (attackSpread >> 1)) >> 2);
        if (attack < 0) attack = 0;

        short defenceSpread = *(short*)(victimBlock + 0x2c);
        int defence = *(short*)(victimBlock + 0x32)
                      + ((CrtRand() % (defenceSpread + 1) - (defenceSpread >> 1)) >> 2);
        if (defence < 0) defence = 0;

        // ---------------------------------------------------------------- le coup critique
        int criticalChance = *(ushort*)(attackerBlock + 0x2e);

        if ((*attacker & 0x800000) != 0
            && *(short*)(attackerBlock + 0x4c) <= *(short*)(attackerBlock + 0x48) * 5 / 100)
        {
            criticalChance += 5;
        }

        sbyte outcome = (sbyte)(CrtRand() % 100 < criticalChance ? 1 : 0);

        if (outcome != 0)
        {
            defence >>= 1;
            SpawnEffectEntity((byte*)victim, 0xbe, 0, -1);
        }

        // ---------------------------------------------------------------- les degats
        int damage = ResolveElementalExchange_005398E0(attackerBlock, victimBlock) + (attack - defence);
        int element = DominantElement_005399E0(attackerBlock);

        if ((*attacker & 0x800000) != 0
            && (*victim & 0x400000) != 0
            && (*(uint*)(victimBlock + 0x14) & 0x6099500) != 0
            && attackerCharacter[0x2b0] != 0xff
            && (*(uint*)(attackerCharacter + attackerCharacter[0x2b0] * 0x280 + 0x314)
                & *(uint*)(victimBlock + 0x14) & 0x6099500) == 0
            && (*(uint*)(attackerBlock + 0x40) & 0x8000000) == 0)
        {
            // L'arme ne mord pas sur cette famille : le quart, et un troisieme son.
            damage >>= 2;
            outcome = 2;
        }

        if (damage < 0) damage = 0;
        damage += *(short*)(attackerBlock + 0x30) / 6 - (*(short*)(victimBlock + 0x32) >> 5);
        if (damage < 1) damage = 1;

        if (Mem.s_DebugModeLatch_005633a8 == 0 && s_DebugOverlayEnabled_005de020 != 0)
        {
            throw new NotImplementedException(
                "FUN_00539b80 : le bandeau de mise au point du combat (0x00539df2 environ) n'est " +
                "pas transcrit. Il recopie une vingtaine de valeurs du calcul dans l'arene " +
                "(DAT_005e90c0..DAT_005e90e8 : les huit elements de chaque camp, les deux indices " +
                "d'entite, l'issue, la chance de critique, l'attaque, la defense et les degats) " +
                "puis appelle FUN_00544350 avec la table de libelles du repertoire de zone " +
                "(+0x70, +0x5f0) et &DAT_005633b0. DAT_005de020 vaut 0 au chargement, donc ce " +
                "bloc ne s'atteint que par la touche de mise au point, elle-meme non transcrite.");
        }

        // ---------------------------------------------------------------- le coup porte
        int killed = ApplyDamage_00539A20(
            attacker, victim, attackerBlock, victimBlock, (short)damage, (byte)element);

        if (killed != 0 && (*attacker & 0x800000) != 0
            && *(int*)(attackerCharacter + 0x15c) != -1)
        {
            *(int*)(attackerCharacter + 0x15c) += 1;
        }

        // ---------------------------------------------------------------- ce qui n'est qu'au groupe
        if ((*attacker & 0x800000) != 0)
        {
            TriggerEquippedItems_005238E0(attacker, 3);

            int voice = (attackerBlock[0x50] & 7) switch
            {
                0 or 2 or 4 or 5 or 6 => outcome + 0x32,
                _ => outcome + 0x35,
            };

            Aud.PlayPositionalSound(voice, 0x400, 0x1200, (int*)((byte*)attacker + 0x1c));

            int gained = (*(ushort*)(victimBlock + 0x44) - *(ushort*)(attackerBlock + 0x46)) >> 5;
            if (gained < 0) gained = 0;
            *(int*)(attackerCharacter + 0x158) += gained + 1;

            CheckLevelUp_00539190((byte*)attacker, attackerCharacter);

            if (*(short*)(attackerBlock + 0x82) != 0)
            {
                // L'effet elementaire visible, pris sur l'element le plus fort de la VICTIME —
                // pas de l'assaillant, et pas celui qui a servi a teinter le nombre.
                ushort strongest = 0;
                uint which = 0;

                for (uint i = 0; i < 8; i++)
                {
                    ushort value = *(ushort*)(victimBlock + 0x110 + i * 2);
                    if (strongest < value)
                    {
                        which = i;
                        strongest = value;
                    }
                }

                if (strongest != 0)
                {
                    byte* atlas = *(byte**)(*(byte**)(Mem.s_MainResourceDirectory_005e97c4 + 0x94) + 0x20)
                                  + which * 0x18;

                    SpawnStatusEffectEntity_0047AC40(
                        (byte*)victim, (int*)((byte*)victim + 0x1c), atlas, 0x29, 0, 0);
                }
            }

            if (*(short*)(attackerBlock + 0x84) != 0 || Mem.s_DebugModeLatch_005633a8 == 0)
            {
                // Le bandeau : le nom de la victime, ses points de vie et son maximum. Les seize
                // octets du nom sont recopies tels quels, puis tout zero SUIVI d'un non-zero
                // devient une espace — c'est ainsi que le jeu rejoint deux mots ranges dans un
                // champ a trous.
                byte* banner = Mem.Entity(0x005fa5d0);
                ((uint*)banner)[0] = ((uint*)victimBlock)[0];
                ((uint*)banner)[1] = ((uint*)victimBlock)[1];
                ((uint*)banner)[2] = ((uint*)victimBlock)[2];
                ((uint*)banner)[3] = ((uint*)victimBlock)[3];

                for (int i = 0; i < 0xf; i++)
                {
                    if (banner[i] == 0 && banner[i + 1] != 0) banner[i] = 0x20;
                }

                *(ushort*)Mem.Arena(0x005e9a22) = *(ushort*)(victimBlock + 0x4c);
                *(ushort*)Mem.Arena(0x005e9aec) = *(ushort*)(victimBlock + 0x4e);
                *(byte*)Mem.Camera(0x005de0b4) = 0xff;
            }
        }

        if ((*victim & 0x800000) != 0)
        {
            TriggerEquippedItems_005238E0(victim, 0xd);
            return 0;
        }

        // Une entite de scene retient qui l'a frappee, et reagit si son genre le prevoit.
        ((byte*)victim)[9] = (byte)attacker[2];

        if ((((byte*)victim)[0x0d] & 0xf) == 10)
        {
            RunEntityScript(s_Unknown_005e97cc, (byte*)victim, *(ushort*)((byte*)victim + 0x0e));
        }

        return 0;
    }

    /// <summary>
    /// Ghidra: les deux blocs jumeaux de <c>FUN_00539b80</c> (0x00539bc0 et 0x00539c60) —
    /// <b>refaire la fiche d'un combattant avant le coup</b>, et rendre le bloc de statistiques sur
    /// lequel tout le calcul va porter.
    ///
    /// <para>Les deux moities du binaire sont ecrites ici en une seule parce qu'elles ne different
    /// que par l'octet de ligne d'arme (<c>+0x2b0</c> pour l'assaillant, <c>+0x2b1</c> pour la
    /// victime) et par le bloc supplementaire de <paramref name="withStanceRow"/>, que seule la
    /// victime porte.</para>
    /// </summary>
    /// <param name="rowByte">L'octet du bloc par personnage qui designe la ligne de 0x280 a
    /// ajouter aux elements.</param>
    /// <param name="withStanceRow">La victime ajoute une seconde ligne, celle de <c>+0x2b2</c>, et
    /// seulement si elle est debout — posture 0 ou 6.</param>
    private static byte* RefreshCombatantBlock(uint* fighter, int rowByte, bool withStanceRow)
    {
        if ((*fighter & 0x800000) == 0)
        {
            byte* stats = s_EntityStatBlocks_005ea560 + (byte)fighter[2] * 0x120;

            RebaseStatBlockOnModel_00538AF0((byte*)fighter);   // Ghidra: FUN_00538af0
            ScaleStatBlockByDifficulty(stats);                 // Ghidra: FUN_00538f50
            FinalizeEquipmentEffects(stats);                   // Ghidra: FUN_00538fa0
            return stats;
        }

        byte* character = GetMainMemPtr() + ((byte)fighter[2] + 0x78) * 0x2000;
        byte* block = character + 0x100;

        CommitStagedStatBlock(character);                      // Ghidra: FUN_00538ab0
        ScaleStatBlockByDifficulty(block);                     // Ghidra: FUN_00538f50
        ComputeDerivedStats(character);                        // Ghidra: FUN_00538c50
        ApplyEquipmentStatBonuses(character);                  // Ghidra: FUN_00538e20
        FinalizeEquipmentEffects(block);                       // Ghidra: FUN_00538fa0

        AddElementRow(character, character[rowByte]);

        if (withStanceRow)
        {
            int stance = character[0x150] & 7;
            if (stance == 0 || stance == 6) AddElementRow(character, character[0x2b2]);
        }

        TiltDominantElement_005398A0(block);                   // Ghidra: FUN_005398a0
        return block;
    }

    /// <summary>Ghidra: la boucle de huit tours qui suit chaque octet de ligne — les huit
    /// <c>char</c> <b>signes</b> de <c>personnage + ligne * 0x280 + 0x318</c> s'ajoutent aux huit
    /// elements de <c>personnage + 0x210</c>. Une ligne de <c>0xff</c> veut dire « aucune ».</summary>
    private static void AddElementRow(byte* character, byte row)
    {
        if (row == 0xff) return;

        for (int i = 0; i < 8; i++)
        {
            *(short*)(character + 0x210 + i * 2) += (short)(sbyte)character[row * 0x280 + 0x318 + i];
        }
    }

    /// <summary>
    /// Ghidra: FUN_00519c30 @ 0x00519c30 — <b>le balayage du groupe</b> : lequel des membres le
    /// geste en cours touche-t-il ? Elle rend le <b>plus proche</b> de ceux que
    /// <see cref="TestMeleeReach_00535A90"/> accepte, et pose <c>DAT_005de0b8</c> a 1 quand il y en
    /// a un.
    ///
    /// <para>
    /// <b>La parade est ici, pas dans le combat.</b> Si le membre trouve porte le bit 4, que sa
    /// classe (<c>bloc par personnage + 0x150</c>, trois bits bas) vaut 0 ou 6, et qu'il fait face
    /// au coup a moins d'un demi-tour pres, alors il <b>pare</b> : ses statistiques sont refaites,
    /// l'assaillant est note en <c>+0x70</c>, l'evenement d'objet equipe 0x0e part, un son joue —
    /// et <c>DAT_005de0b8</c> est remis a <b>zero</b>, ce qui dit a l'appelant « touche, mais pas
    /// de degats ». C'est la seule difference entre parer et encaisser.
    /// </para>
    /// </summary>
    private static byte* SweepPartyForMeleeHit_00519C30(byte* entity, int* position, short* probe, uint flags)
    {
        byte* found = null;
        int nearest = 0x7fff;

        *Mem.Camera(0x005de0b8) = 0;

        byte* slot = Inp.s_SlotFlags_005e93c0;
        for (int n = s_PartySize_005e9020; n != 0; n--, slot += 0x9c)
        {
            if ((*(uint*)slot & 0x50002040) != 0) continue;
            if (*(short*)(slot + 0x12) != 0 || *(short*)(slot + 0x96) != 0) continue;
            if (!TestMeleeReach_00535A90(position, slot, probe, entity)) continue;

            int dx = (*(int*)(slot + 0x1c) - *(int*)(entity + 0x1c)) >> 0xc;
            int dz = (*(int*)(slot + 0x24) - *(int*)(entity + 0x24)) >> 0xc;
            int range = (int)Winsys3d.Ordinal_442((uint)(dx * dx + dz * dz));

            if (range < nearest)
            {
                *Mem.Camera(0x005de0b8) = 1;
                found = slot;
                nearest = range;
            }
        }

        if (found == null)
        {
            *Mem.Camera(0x005de0b8) = 0;
            return null;
        }

        if ((flags & 0x800) == 0 && (*found & 4) != 0)
        {
            byte stance = (byte)(GetMainMemPtr()[(found[8] + 0x78) * 0x2000 + 0x150] & 7);

            if ((stance == 0 || stance == 6)
                && (uint)((*(short*)(found + 0x32) - *(short*)((byte*)position + 0x16) - *probe - 0x400) & 0xfff) < 0x800)
            {
                byte index = found[8];
                RebaseStatBlockOnModel_00538AF0(found);
                ScaleStatBlockByDifficulty(s_EntityStatBlocks_005ea560 + index * 0x120);
                FinalizeEquipmentEffects(s_EntityStatBlocks_005ea560 + index * 0x120);

                *(byte**)(found + 0x70) = entity;
                *(uint*)Mem.Arena(0x005e99c0) = 0;
                TriggerEquippedItems_005238E0((uint*)found, 0xe);
                Aud.PlayPositionalSound(8, 0x800, 0x1000, (int*)(found + 0x1c));

                // Le coup a bien porte, mais la parade annule les degats : l'appelant lit ce
                // drapeau et ne va pas jusqu'a la resolution.
                *Mem.Camera(0x005de0b8) = 0;
                return found;
            }
        }

        *Mem.Camera(0x005de0b8) = 1;
        return found;
    }

    /// <summary>
    /// Ghidra: <c>0x0049a980</c> — <b>l'intelligence d'une entite de scene</b> : le gestionnaire du
    /// sous-type 2 de la table installee <c>0x0056ad48</c>, celui que la passe
    /// <see cref="TickEntityTable_005ecaa0"/> appelle a chaque image pour chaque monstre. 2175
    /// octets, <b>absente de <c>Blaze.c</c></b> — Ghidra ne rend que cinq corps sur toute la plage
    /// <c>0x00491290..0x004a1020</c>, et pas celui-ci. Transcrite au desassembleur, releve garde
    /// sous <c>Legacy/Raw/Blaze/FUN_0049A980.asm</c>.
    ///
    /// <para>
    /// <b>La fonction se lit en trois temps</b>, et c'est ce decoupage qui la rend abordable malgre
    /// sa taille : <i>decider</i> ce qu'on fait de l'image en cours, <i>appliquer</i> le mouvement
    /// et l'animation, puis <i>replanifier</i> pour la suite. Les 43 cibles de saut ne sont que les
    /// sorties de la premiere partie, qui convergent toutes sur la deuxieme.
    /// </para>
    ///
    /// <para>
    /// <b>Deux champs portent l'etat</b>, et les confondre rend le tout illisible. <c>+0x42</c> est
    /// la <b>posture</b> : cinq valeurs, aiguillees par une table de sauts a <c>0x0049b200</c>
    /// (relevee dans le binaire) — 0 attendre, 1 se tourner, 2 s'approcher jusqu'a une distance
    /// tenue en <c>+0x10</c>, 3 marcher ou bondir, 4 foncer. <c>+0x43</c> est le <b>compte a
    /// rebours</b> qui la maintient : tant qu'il n'est pas nul, la replanification ne reprend pas
    /// la main.
    /// </para>
    /// <para>
    /// <b>Tout se decide sur deux nombres</b> que <see cref="ReadSceneEntitySituation_00535F20"/>
    /// rend : la <i>hardiesse</i> (0 a 0x40, tiree de l'ecart de niveau et de l'etat de sante) et
    /// son complement a 0x40. La premiere elargit les cones de virage et allonge les pas ; le
    /// second elargit les seuils de tirage. Une bete faible face a un groupe fort hesite, tourne
    /// plus lentement et frappe moins souvent — c'est une seule soustraction qui le produit.
    /// </para>
    /// <para>
    /// <b>Une vitesse nulle veut dire « ne pense pas ».</b> Les trois conditions qui l'annulent
    /// (traits <c>0x1c0</c>, bit <c>0x80</c> de l'entite, entite tenue) court-circuitent la
    /// decision <i>et</i> la replanification, mais pas l'application : l'entite continue d'etre
    /// integree et animee.
    /// </para>
    /// </summary>
    private static void TickSceneEntityAi_0049A980(byte* record)
    {
        byte* e = record;

        // Des trois blocs resolus, seul celui de statistiques sert — a la toute fin, en argument
        // de l'interruption. Les deux autres sont ecrits sur la pile et jamais relus.
        ResolveEntityBlocks(e, out byte* stats, out _, out _);

        // La sonde du geste, posee sur la pile avant meme la lecture de situation et relue une
        // seule fois : c'est le gabarit que FUN_00519c30 croise avec chaque membre du groupe.
        short* probe = stackalloc short[6];
        probe[0] = 0;
        probe[1] = 0x1e;
        probe[2] = 0x32;
        probe[3] = 0x64;
        probe[4] = 0;
        probe[5] = 0x50;

        int boldness, distance, heading, speed;
        uint traits;
        ReadSceneEntitySituation_00535F20(e, &boldness, &distance, &heading, &speed, &traits);

        int timid = 0x40 - boldness;

        // ---------------------------------------------------------------- 1. decider
        if (DecideSceneEntityAction(e, probe, boldness, distance, heading, speed, traits))
        {
            // Ghidra: LAB_0049ae97 — la poussee est remise a zero sur les seules sorties qui
            // viennent de poser une vitesse propre.
            *(int*)(e + 0x5c) = 0;
        }

        // ---------------------------------------------------------------- 2. appliquer
        IntegrateSceneEntityMotion_00488160(e, speed);
        FinalizeEntityPlacement2((uint*)e);
        EndSceneEntityAnimation_004DFAF0((uint*)e);
        InterruptSceneEntity_004E3770((uint*)e, stats);

        // ---------------------------------------------------------------- 3. replanifier
        if (speed == 0) return;
        if ((*(uint*)e & 0x817) != 0) return;
        if (e[0x43] != 0) return;

        ReplanSceneEntityAction(e, boldness, timid);
    }

    /// <summary>
    /// Ghidra: <c>0x0049aa0d..0x0049ae96</c> — <b>le premier temps</b> de
    /// <see cref="TickSceneEntityAi_0049A980"/> : ce que l'entite fait de l'image en cours, selon
    /// qu'elle est deja en train d'agir ou qu'elle tient une posture.
    /// </summary>
    /// <returns><c>true</c> si la sortie passe par <c>LAB_0049ae97</c>, qui remet la poussee
    /// <c>+0x5c</c> a zero avant l'application.</returns>
    private static bool DecideSceneEntityAction(
        byte* e, short* probe, int boldness, int distance, int heading, int speed, uint traits)
    {
        if (speed == 0) return false;

        AdvanceEntityAnimation_004DB5A0((uint*)e);
        uint flags = *(uint*)e;

        // ================================================================ le geste en cours
        if ((flags & 2) != 0)
        {
            // Le trait 0x10 coupe court : l'espece ne poursuit pas son geste.
            if ((traits & 0x10) != 0)
            {
                e[0x43] = 0;
                *(uint*)e = flags & 0xfffffffd;
                return false;
            }

            byte posture = e[0x42];

            if (posture == 1)
            {
                // A la quatorzieme image du geste, la charge laisse une trainee. Les trois
                // vitesses sont remplacees le temps de la copie puis remises telles quelles :
                // c'est l'EFFET qui part avec la vitesse, l'entite garde la sienne.
                if (*(short*)(e + 0x1a) == 0x0e)
                {
                    int savedX = *(int*)(e + 0x50);
                    int savedY = *(int*)(e + 0x54);
                    int savedZ = *(int*)(e + 0x58);

                    int reach = (CrtRand() & 0x0f) + 0x28;
                    int course = *(short*)(e + 0x32);

                    *(int*)(e + 0x50) = (int)Winsys3d.GetSinTableEntry(course) * reach;
                    *(int*)(e + 0x58) = (int)Winsys3d.GetCosTableEntry(course) * reach;
                    *(int*)(e + 0x54) = 0x18000;

                    // Le sous-type de la trainee n'est pas une constante : il est lu dans le
                    // repertoire de zone (+0xcc), premier bloc, deuxieme octet, decale de 0xc0.
                    byte* block = *(byte**)(s_Unknown_005e97cc + 0xcc);
                    int subtype = (*(byte**)block)[1] + 0xc0;

                    SpawnEffectEntity(e, (byte)subtype, 0xff, -1);

                    *(int*)(e + 0x54) = savedY;
                    *(int*)(e + 0x50) = savedX;
                    *(int*)(e + 0x58) = savedZ;
                }

                // Ghidra: LAB_0049aac8
                flags = *(uint*)e;
                if ((flags & 0x2000000) != 0) *(uint*)e = flags & 0xfffffffd;
                return false;
            }

            if (posture != 0) return false;

            // Ghidra: LAB_0049aade — la posture 0 pendant un geste, c'est le COUP : a la
            // huitieme image, on regarde qui est sous le gabarit.
            if (*(short*)(e + 0x1a) == 8)
            {
                byte* victim = SweepPartyForMeleeHit_00519C30(e, (int*)(e + 0x1c), probe, 0);

                // Le drapeau vaut 1 quand le coup porte SANS etre pare — la parade le remet a
                // zero elle-meme, en ayant deja joue son propre son.
                if (*Mem.Camera(0x005de0b8) != 0)
                {
                    ResolveMeleeHit_00539B80((uint*)e, (uint*)victim);

                    *(ushort*)(victim + 0x96) = 0x10;      // le clignotement de degat
                    *(uint*)victim |= 0x40;
                    Aud.PlayPositionalSound(3, 0x300, 0x1800, (int*)(victim + 0x1c));
                }

                flags = *(uint*)e;

                if ((flags & 1) != 0)
                {
                    *(short*)(e + 0x1a) -= 1;
                    return false;
                }
            }
            else if ((flags & 1) != 0)
            {
                return false;
            }

            // Ghidra: LAB_0049ab47
            if ((flags & 0x2000000) != 0) *(uint*)e = flags & 0xfffffffd;
            return true;
        }

        // ================================================================ le recul
        // Ghidra: LAB_0049ab5b — le bit 0x10 est pose par l'interruption : l'entite encaisse,
        // et ne fait rien d'autre que se tourner vers ce qui l'a touchee.
        if ((flags & 0x10) != 0)
        {
            if ((flags & 0x2000000) != 0 && e[0x43] != 0)
            {
                e[0x43]--;
                if (e[0x43] == 0)
                {
                    flags &= 0xffffffef;
                    *(uint*)e = flags;
                }
            }

            TurnSceneEntityTowardTarget(e, boldness + 0x40, heading);
            return false;
        }

        // ================================================================ la posture tenue
        // Ghidra: LAB_0049abb5
        if ((flags & 0x804) != 0) return false;

        if ((flags & 1) != 0)
        {
            // Le geste vient de finir : une chance sur 100 par quart de hardiesse de relancer.
            if (CrtRand() % 100 >= (boldness >> 2)) return false;

            uint state = *(uint*)e;
            *(int*)(e + 0x18) = 3;
            e[0x42] = 0;
            *(int*)(e + 0x5c) = 0;
            *(uint*)e = (state & 0xfeffffff) | 2;
            return false;
        }

        // Ghidra: LAB_0049ac00 — le repartiteur des cinq postures, table de sauts 0x0049b200.
        byte held = e[0x42];
        if (held > 4) return false;

        switch (held)
        {
            // ---------------------------------------------------------- 0 : attendre
            case 0:
                if (*(ushort*)(e + 0x18) != 0)
                {
                    flags |= 0x1000000;
                    *(int*)(e + 0x18) = 0;
                    *(uint*)e = flags;
                }

                if (distance < 0x12c)
                {
                    e[0x43] = 0;
                    return false;
                }

                if (e[0x43] != 0) e[0x43]--;
                *(int*)(e + 0x5c) = 0;
                return false;

            // ---------------------------------------------------------- 1 : se tourner
            case 1:
                if (*(ushort*)(e + 0x18) != 1)
                {
                    flags |= 0x1000000;
                    *(int*)(e + 0x18) = 1;
                    *(uint*)e = flags;
                }

                // Le compte a rebours ne repart que lorsque le cap est ATTEINT — c'est ce qui
                // fait qu'une bete desorientee reste tournee vers vous avant de repartir.
                if (TurnSceneEntityTowardTarget(e, boldness * 2 + 0x80, heading)) e[0x43] = 0;
                *(int*)(e + 0x5c) = 0;
                return false;

            // ---------------------------------------------------------- 2 : s'approcher
            case 2:
                if (*(ushort*)(e + 0x18) != 1)
                {
                    flags |= 0x1000000;
                    *(int*)(e + 0x18) = 1;
                    *(uint*)e = flags;
                }

                // La distance tenue est dans +0x10, la meme case que la posture 3 remplit d'un
                // cap tire au sort : le champ sert aux deux, jamais en meme temps.
                if (distance < *(short*)(e + 0x10))
                {
                    e[0x43] = 0;
                    return false;
                }

                if (e[0x43] != 0) e[0x43]--;

                TurnSceneEntityTowardTarget(e, boldness * 2 + 0x80, heading);
                *(int*)(e + 0x5c) = (boldness + 0xc0) << 7;
                return false;

            // ---------------------------------------------------------- 3 : marcher ou bondir
            case 3:
            {
                if (e[0x43] != 0) e[0x43]--;

                if (*(ushort*)(e + 0x18) != 1)
                {
                    flags |= 0x1000000;
                    *(int*)(e + 0x18) = 1;
                    *(uint*)e = flags;
                }

                if (CrtRand() % 100 < (boldness >> 3))
                {
                    // Le bond : la poussee passe par la VITESSE, avec une composante verticale,
                    // et le bit 0 s'allume — l'entite est en l'air.
                    int thrust = (boldness + 0x100) << 7;
                    int step = (speed * thrust) >> 0xc;
                    *(int*)(e + 0x5c) = thrust;

                    int course = *(short*)(e + 0x10);
                    *(int*)(e + 0x50) += ((int)Winsys3d.GetSinTableEntry(course) * step) >> 0xc;
                    *(int*)(e + 0x58) += ((int)Winsys3d.GetCosTableEntry(course) * step) >> 0xc;
                    *(int*)(e + 0x54) += 0xa000;
                    *(uint*)e |= 1;
                    return true;
                }

                // La marche : la POSITION avance directement, sans passer par la vitesse.
                int walk = (boldness + 0x80) << 7;
                int walkStep = (speed * walk) >> 0xc;
                *(int*)(e + 0x5c) = walk;

                int walkCourse = *(short*)(e + 0x10);
                *(int*)(e + 0x1c) += ((int)Winsys3d.GetSinTableEntry(walkCourse) * walkStep) >> 0xc;
                *(int*)(e + 0x24) += ((int)Winsys3d.GetCosTableEntry(walkCourse) * walkStep) >> 0xc;

                TurnSceneEntityTowardTarget(e, boldness * 4 + 0x32, heading);
                return true;
            }

            // ---------------------------------------------------------- 4 : foncer
            default:
            {
                flags = (flags & 0xfeffffff) | 1;
                *(int*)(e + 0x18) = 6;
                *(uint*)e = flags;

                // La seule posture qui ECRASE la vitesse au lieu de s'y ajouter, et la seule
                // dont le pas se compte sur huit bits plutot que sept.
                int thrust = (boldness + 0xa0) << 8;
                int step = (speed * thrust) >> 0xc;
                *(int*)(e + 0x5c) = thrust;

                int course = *(short*)(e + 0x10);
                *(int*)(e + 0x50) = ((int)Winsys3d.GetSinTableEntry(course) * step) >> 0xc;
                *(int*)(e + 0x58) = ((int)Winsys3d.GetCosTableEntry(course) * step) >> 0xc;
                *(int*)(e + 0x54) = 0x19000;
                return true;
            }
        }
    }

    /// <summary>
    /// Ghidra: le motif <c>LAB_0049ab78</c> / <c>ac5c</c> / <c>acd6</c> / <c>0049ae07</c> —
    /// <b>tourner vers la cible, au plus de <paramref name="amount"/> par image</b>. Le meme corps
    /// est emis quatre fois par le compilateur, avec quatre largeurs differentes.
    ///
    /// <para>Le test <c>((amount + cap) &amp; 0xfff) &lt;= amount * 2</c> demande « l'ecart tient-il
    /// dans le cone ? » : si oui le cap est pris d'un coup, sinon on avance de la largeur du cone,
    /// dans le sens que donne la moitie du tour ou se trouve la cible.</para>
    /// </summary>
    /// <returns><c>true</c> si le cap a ete pris d'un coup.</returns>
    private static bool TurnSceneEntityTowardTarget(byte* e, int amount, int heading)
    {
        if (((amount + heading) & 0xfff) <= amount * 2)
        {
            *(ushort*)(e + 0x32) += (ushort)heading;
            return true;
        }

        if ((heading & 0xfff) >= 0x800) amount = -amount;
        *(ushort*)(e + 0x32) += (ushort)amount;
        return false;
    }

    /// <summary>
    /// Ghidra: <c>0x0049aeef..0x0049b1fe</c> — <b>le troisieme temps</b> : quelle posture prendre
    /// pour la suite. Elle ne tourne que lorsque le compte a rebours <c>+0x43</c> est epuise et que
    /// l'entite n'est ni en geste ni en recul.
    ///
    /// <para>
    /// <b>La distance et le cap sont RECALCULES ici, et en deux dimensions seulement</b> — la
    /// hauteur est ignoree. Ceux de <see cref="ReadSceneEntitySituation_00535F20"/> etaient a trois
    /// dimensions et sont morts a ce point : c'est deliberé, une bete ne renonce pas a vous
    /// poursuivre parce que vous etes sur une marche.
    /// </para>
    /// <para>
    /// Trois plages de distance, et dans chacune un tirage sur cent : <b>sous 0x0fa</b> le corps a
    /// corps, ou l'entite frappe, esquive de cote, ou recule ; <b>sous 0x1f4</b> l'approche ;
    /// <b>au-dela</b> l'errance, ou elle finit le plus souvent par attendre.
    /// </para>
    /// </summary>
    private static void ReplanSceneEntityAction(byte* e, int boldness, int timid)
    {
        byte* chased = *(byte**)(e + 0x6c);

        int dx = (*(int*)(chased + 0x1c) - *(int*)(e + 0x1c)) >> 0xc;
        int dz = (*(int*)(chased + 0x24) - *(int*)(e + 0x24)) >> 0xc;

        int distance = (int)Winsys3d.Ordinal_442((uint)(dx * dx + dz * dz));
        int heading = (Winsys3d.Ordinal_457(dx, dz) - *(ushort*)(e + 0x32)) & 0xfff;

        // ================================================================ le corps a corps
        if (distance < 0xfa)
        {
            int roll = CrtRand() % 100;

            if (roll < 0x1e)
            {
                // Frapper : il faut etre dans le cone ET assez pres, la portee tiree au sort
                // s'elargissant avec la timidite — une bete craintive frappe de plus loin.
                if (((heading + timid * 4 + 0x100) & 0xfff) <= timid * 8 + 0x200
                    && distance < CrtRand() % (timid * 2 + 1) + 100)
                {
                    uint state = *(uint*)e;
                    *(int*)(e + 0x18) = 3;
                    e[0x42] = 0;
                    *(int*)(e + 0x5c) = 0;
                    *(uint*)e = (state & 0xfeffffff) | 2;
                    return;
                }

                // Ghidra: LAB_0049afb2 — l'esquive de cote, dans un cone deux fois plus large.
                if (((heading + timid * 4 + 0x200) & 0xfff) > timid * 8 + 0x400
                    || CrtRand() % 100 >= (timid >> 1) + 0x20)
                {
                    HesitateSceneEntity(e);
                    return;
                }

                uint dodge = *(uint*)e;
                *(int*)(e + 0x18) = 5;
                *(uint*)e = (dodge & 0xfeffffff) | 0x10;
                *(int*)(e + 0x5c) = 0;
                e[0x43] = (byte)(CrtRand() % 5 + 10);
                return;
            }

            // Ghidra: LAB_0049b022
            if (roll < 0x3c)
            {
                HoldSceneEntityAtRange(e, timid, 0x64);
                return;
            }

            if (roll < 0x4b && distance > boldness + 100)
            {
                e[0x42] = 4;                                   // foncer
                *(ushort*)(e + 0x10) = (ushort)CrtRand();
                return;
            }

            WanderSceneEntity(e, boldness, timid, heading, 0x800);
            return;
        }

        // ================================================================ l'approche
        if (distance < 0x1f4)
        {
            int roll = CrtRand() % 100;

            if (roll < (boldness >> 1) + 0x10)
            {
                // Se tourner, mais seulement si la cible est deja dans la moitie avant.
                if (((heading + 0x400) & 0xfff) >= 0x800)
                {
                    HesitateSceneEntity(e);
                    return;
                }

                uint state = *(uint*)e;
                *(int*)(e + 0x18) = 4;
                e[0x42] = 1;
                *(int*)(e + 0x5c) = 0;
                *(uint*)e = (state & 0xfeffffff) | 2;
                return;
            }

            if (roll < 0x46)
            {
                // Le meme errement que plus haut, sans le demi-tour de 0x800 : l'entite part
                // VERS la cible au lieu de s'en ecarter.
                WanderSceneEntity(e, boldness, timid, heading, 0);
                return;
            }

            if (roll < 0x5a)
            {
                HoldSceneEntityAtRange(e, timid, 0x64);
                return;
            }

            RestSceneEntity(e, timid);
            return;
        }

        // ================================================================ l'errance
        int far = CrtRand() % 100;

        if (far < 0x1e)
        {
            RestSceneEntity(e, timid);
            return;
        }

        if (far < 0x3c)
        {
            HesitateSceneEntity(e);
            return;
        }

        // Ghidra: LAB_0049b1d3 — la seule sortie ou le cap est ENTIEREMENT tire au sort, sans
        // reference a la cible : trop loin pour qu'elle compte.
        e[0x42] = 3;
        e[0x43] = SceneEntityDelay(timid);
        *(ushort*)(e + 0x10) = (ushort)CrtRand();
    }

    /// <summary>Ghidra: le motif <c>rand() % 10 + (timide &gt;&gt; 1) + 0x14</c>, emis quatre fois
    /// — <b>la duree d'une posture</b>, de 20 a 61 images selon la timidite.</summary>
    private static byte SceneEntityDelay(int timid) => (byte)(CrtRand() % 10 + (byte)(timid >> 1) + 0x14);

    /// <summary>Ghidra: LAB_0049b1c3 — <b>l'hesitation</b> : posture 1 pour une seule image. C'est
    /// la sortie de secours de toutes les conditions qui echouent.</summary>
    private static void HesitateSceneEntity(byte* e)
    {
        e[0x42] = 1;
        e[0x43] = 1;
    }

    /// <summary>Ghidra: LAB_0049b19b — <b>le repos</b> : posture 0, pour une duree tiree.</summary>
    private static void RestSceneEntity(byte* e, int timid)
    {
        e[0x42] = 0;
        e[0x43] = SceneEntityDelay(timid);
    }

    /// <summary>Ghidra: LAB_0049b160 et LAB_0049a1f9 — <b>tenir la distance</b> : posture 2, avec
    /// la distance voulue posee dans <c>+0x10</c>. Les deux especes ne different que par elle —
    /// 0x64 pour la famille de <see cref="TickSceneEntityAi_0049A980"/>, 0x5a pour celle de
    /// <see cref="TickSceneEntityAi_00499DE0"/>.</summary>
    private static void HoldSceneEntityAtRange(byte* e, int timid, ushort range)
    {
        e[0x42] = 2;
        *(ushort*)(e + 0x10) = range;
        e[0x43] = SceneEntityDelay(timid);
    }

    /// <summary>
    /// Ghidra: LAB_0049b054, LAB_0049b10c et LAB_0049a28a — <b>marcher dans une direction proche de
    /// la cible</b> : posture 3, le cap etant celui de la cible plus un ecart tire dans une
    /// fourchette large de <c>(hardiesse + 0x80) * 16</c>, centree.
    ///
    /// <para>Les trois sites ne different que par <paramref name="bias"/> : <c>0x800</c> est un
    /// demi-tour, donc l'entite s'ELOIGNE — c'est la retraite du corps a corps ; <c>0</c> la fait
    /// avancer.</para>
    /// </summary>
    private static void WanderSceneEntity(byte* e, int boldness, int timid, int heading, int bias)
    {
        e[0x42] = 3;
        e[0x43] = SceneEntityDelay(timid);

        int spread = (boldness + 0x80) << 4;
        int offset = CrtRand() % spread - (spread >> 1);

        *(ushort*)(e + 0x10) = (ushort)(offset + heading + *(short*)(e + 0x32) + bias);
    }

    /// <summary>
    /// Ghidra: <c>0x00499de0</c> — <b>la seconde intelligence d'entite de scene</b> : le
    /// gestionnaire du sous-type <b>0</b> de la table installee <c>0x0056ad48</c>. 1377 octets,
    /// <b>absente de <c>Blaze.c</c></b>, transcrite au desassembleur
    /// (<c>Legacy/Raw/Blaze/FUN_00499DE0.asm</c>).
    ///
    /// <para>
    /// <b>C'est la sœur de <see cref="TickSceneEntityAi_0049A980"/></b> : meme decoupage en trois
    /// temps, meme lecture de situation, meme queue de quatre appels, et les memes feuilles. Elle
    /// n'est pas factorisee avec elle parce que ce sont <b>deux fonctions distinctes du binaire</b>,
    /// et que l'oracle de <c>compare-bodies.ps1</c> compare des corps — meme raison que les trois
    /// passes <c>FUN_0047aa70</c>/<c>ab70</c>/<c>acf0</c>.
    /// </para>
    ///
    /// <para>
    /// <b>Ce qui la distingue tient en cinq nombres et une absence</b>, et l'ecart dessine une bete
    /// plus petite et plus prudente :
    /// </para>
    /// <list type="bullet">
    /// <item>sa <b>sonde</b> est plus courte et plus basse — <c>0x50</c> de tolerance en hauteur et
    /// <c>0x3c</c> de portee, contre <c>0x64</c> et <c>0x50</c> ;</item>
    /// <item>son coup porte a la <b>douzieme</b> image du geste, pas a la huitieme ;</item>
    /// <item>elle n'a que <b>quatre</b> postures (table de sauts a <c>0x0049a344</c>, quatre entrees
    /// relevees dans le binaire) — il n'y a pas de « foncer » ;</item>
    /// <item>ses cones de virage sont bien plus etroits : <c>hardiesse + 0x20</c> et
    /// <c>hardiesse + 0x40</c>, la ou sa sœur ouvre a <c>hardiesse * 2 + 0x80</c> ;</item>
    /// <item><b>elle ne bondit pas et ne se recule pas</b>. Ni la branche de recul (bit
    /// <c>0x10</c>), ni la relance d'attaque en fin de geste, ni l'esquive de cote n'existent :
    /// le mot d'etat <c>0x11</c> la renvoie directement a la queue.</item>
    /// </list>
    ///
    /// <para>
    /// <b>Sa posture 3 tourne au lieu de marcher</b>, et c'est la seule difference de <i>forme</i>
    /// et non de constante. La sœur y avance en ligne droite ou bondit ; celle-ci pose une poussee
    /// <c>(hardiesse + 0xa0) &lt;&lt; 7</c> et <b>pivote vers un cap range en <c>+0x10</c></b> a
    /// <c>0x20 + hardiesse / 2</c> par image, en s'arretant des que l'ecart tient sous
    /// <c>0x100</c>. Le champ <c>+0x10</c> sert donc ici aussi a deux choses — distance voulue en
    /// posture 2, cap vise en posture 3.
    /// </para>
    /// </summary>
    private static void TickSceneEntityAi_00499DE0(byte* record)
    {
        byte* e = record;

        ResolveEntityBlocks(e, out byte* stats, out _, out _);

        short* probe = stackalloc short[6];
        probe[0] = 0;
        probe[1] = 0x1e;
        probe[2] = 0x32;
        probe[3] = 0x50;
        probe[4] = 0;
        probe[5] = 0x3c;

        int boldness, distance, heading, speed;
        uint traits;
        ReadSceneEntitySituation_00535F20(e, &boldness, &distance, &heading, &speed, &traits);

        int timid = 0x40 - boldness;

        // ---------------------------------------------------------------- 1. decider
        DecideSceneEntityAction_00499DE0(e, probe, boldness, distance, heading, speed, traits);

        // ---------------------------------------------------------------- 2. appliquer
        IntegrateSceneEntityMotion_00488160(e, speed);
        FinalizeEntityPlacement2((uint*)e);
        EndSceneEntityAnimation_004DFAF0((uint*)e);
        InterruptSceneEntity_004E3770((uint*)e, stats);

        // ---------------------------------------------------------------- 3. replanifier
        if (speed == 0) return;
        if ((*(uint*)e & 0x817) != 0) return;
        if (e[0x43] != 0) return;

        ReplanSceneEntityAction_00499DE0(e, boldness, timid);
    }

    /// <summary>
    /// Ghidra: <c>0x00499e68..0x0049a0cb</c> — <b>le premier temps</b> de
    /// <see cref="TickSceneEntityAi_00499DE0"/>. Contrairement a sa sœur, aucune sortie ne demande
    /// de remise a zero separee de la poussee : celles qui la veulent l'ecrivent elles-memes.
    /// </summary>
    private static void DecideSceneEntityAction_00499DE0(
        byte* e, short* probe, int boldness, int distance, int heading, int speed, uint traits)
    {
        if (speed == 0) return;

        AdvanceEntityAnimation_004DB5A0((uint*)e);
        uint flags = *(uint*)e;

        // ================================================================ le geste en cours
        if ((flags & 2) != 0)
        {
            if ((traits & 0x10) != 0)
            {
                e[0x43] = 0;
                *(uint*)e = flags & 0xfffffffd;
                return;
            }

            // Le coup porte a la douzieme image, et non a la huitieme comme chez la sœur.
            if (*(short*)(e + 0x1a) == 0x0c)
            {
                byte* victim = SweepPartyForMeleeHit_00519C30(e, (int*)(e + 0x1c), probe, 0);

                if (*Mem.Camera(0x005de0b8) != 0)
                {
                    // Ici le clignotement est pose AVANT la resolution, l'inverse de
                    // TickSceneEntityAi_0049A980. Sans consequence — rien ne les relit entre les
                    // deux — mais c'est bien ce que le binaire fait.
                    *(ushort*)(victim + 0x96) = 0x10;
                    *(uint*)victim |= 0x40;

                    ResolveMeleeHit_00539B80((uint*)e, (uint*)victim);
                    Aud.PlayPositionalSound(3, 0x300, 0x1800, (int*)(victim + 0x1c));
                }

                flags = *(uint*)e;

                if ((flags & 1) != 0)
                {
                    *(short*)(e + 0x1a) -= 1;
                    return;
                }
            }
            else if ((flags & 1) != 0)
            {
                return;
            }

            if ((flags & 0x2000000) != 0) *(uint*)e = flags & 0xfffffffd;
            *(int*)(e + 0x5c) = 0;
            return;
        }

        // ================================================================ la posture tenue
        // Ghidra: LAB_00499f13 — le bit 0x10 ne mene nulle part chez cette espece : pas de recul,
        // pas de relance d'attaque, la queue directement.
        if ((flags & 0x11) != 0) return;
        if ((flags & 0x804) != 0) return;

        byte held = e[0x42];
        if (held > 3) return;

        switch (held)
        {
            // ---------------------------------------------------------- 0 : attendre
            case 0:
                if (*(ushort*)(e + 0x18) != 0)
                {
                    flags |= 0x1000000;
                    *(int*)(e + 0x18) = 0;
                    *(uint*)e = flags;
                }

                if (distance < 0x12c)
                {
                    e[0x43] = 0;
                    return;
                }

                if (e[0x43] != 0) e[0x43]--;
                *(int*)(e + 0x5c) = 0;
                return;

            // ---------------------------------------------------------- 1 : se tourner
            case 1:
                if (*(ushort*)(e + 0x18) != 1)
                {
                    flags |= 0x1000000;
                    *(int*)(e + 0x18) = 1;
                    *(uint*)e = flags;
                }

                if (TurnSceneEntityTowardTarget(e, boldness + 0x20, heading)) e[0x43] = 0;
                *(int*)(e + 0x5c) = 0;
                return;

            // ---------------------------------------------------------- 2 : s'approcher
            case 2:
                if (*(ushort*)(e + 0x18) != 1)
                {
                    flags |= 0x1000000;
                    *(int*)(e + 0x18) = 1;
                    *(uint*)e = flags;
                }

                if (distance < *(short*)(e + 0x10))
                {
                    e[0x43] = 0;
                    return;
                }

                if (e[0x43] != 0) e[0x43]--;

                TurnSceneEntityTowardTarget(e, boldness + 0x40, heading);
                *(int*)(e + 0x5c) = (boldness + 0xa0) << 7;
                return;

            // ---------------------------------------------------------- 3 : errer
            default:
            {
                if (e[0x43] != 0) e[0x43]--;

                if (*(ushort*)(e + 0x18) != 1)
                {
                    flags |= 0x1000000;
                    *(int*)(e + 0x18) = 1;
                    *(uint*)e = flags;
                }

                *(int*)(e + 0x5c) = (boldness + 0xa0) << 7;

                // Le cap vise est dans +0x10 — pose par la replanification, pas par la cible.
                int bearing = (*(ushort*)(e + 0x10) - *(ushort*)(e + 0x32)) & 0xfff;
                if (((bearing + 0x100) & 0xfff) <= 0x200) return;

                int step = bearing >= 0x800 ? -0x20 - (boldness >> 1) : (boldness >> 1) + 0x20;
                *(ushort*)(e + 0x32) += (ushort)step;
                return;
            }
        }
    }

    /// <summary>
    /// Ghidra: <c>0x0049a11d..0x0049a338</c> — <b>le troisieme temps</b> de
    /// <see cref="TickSceneEntityAi_00499DE0"/>. Meme decoupage en trois plages de distance que sa
    /// sœur, mais un tirage plus simple : ni esquive de cote, ni charge, et le meme errement
    /// dessert les trois plages.
    ///
    /// <para>Sous <c>0x0fa</c>, une chance sur 0x28 de frapper — <b>plus du double</b> de la
    /// sœur — sinon tenir la distance ou errer ; entre <c>0x0fa</c> et <c>0x1f4</c>, tenir,
    /// errer ou se reposer ; au-dela, se reposer, hesiter, ou errer vers un cap entierement tire
    /// au sort.</para>
    /// </summary>
    private static void ReplanSceneEntityAction_00499DE0(byte* e, int boldness, int timid)
    {
        byte* chased = *(byte**)(e + 0x6c);

        int dx = (*(int*)(chased + 0x1c) - *(int*)(e + 0x1c)) >> 0xc;
        int dz = (*(int*)(chased + 0x24) - *(int*)(e + 0x24)) >> 0xc;

        int distance = (int)Winsys3d.Ordinal_442((uint)(dx * dx + dz * dz));
        int heading = (Winsys3d.Ordinal_457(dx, dz) - *(ushort*)(e + 0x32)) & 0xfff;

        // ================================================================ le corps a corps
        if (distance < 0xfa)
        {
            int roll = CrtRand() % 100;

            if (roll < 0x28
                && ((heading + timid * 4 + 0x100) & 0xfff) <= timid * 8 + 0x200
                && distance < CrtRand() % (timid * 2 + 1) + 100)
            {
                uint state = *(uint*)e;
                *(int*)(e + 0x18) = 3;
                *(int*)(e + 0x5c) = 0;
                *(uint*)e = (state & 0xfeffffff) | 2;
                return;
            }

            // Entre 0x28 et 0x50 elle tient la distance ; partout ailleurs elle erre. Le
            // court-circuit ci-dessus renvoie donc a l'errement quand le coup ne part pas.
            if (roll >= 0x28 && roll < 0x50)
            {
                HoldSceneEntityAtRange(e, timid, 0x5a);
                return;
            }

            WanderSceneEntity(e, boldness, timid, heading, 0);
            return;
        }

        // ================================================================ l'approche
        if (distance < 0x1f4)
        {
            int roll = CrtRand() % 100;

            if (roll < 0x32)
            {
                HoldSceneEntityAtRange(e, timid, 0x5a);
                return;
            }

            if (roll < 0x50)
            {
                WanderSceneEntity(e, boldness, timid, heading, 0);
                return;
            }

            RestSceneEntity(e, timid);
            return;
        }

        // ================================================================ l'errance
        int far = CrtRand() % 100;

        if (far < 0x1e)
        {
            RestSceneEntity(e, timid);
            return;
        }

        if (far < 0x3c)
        {
            HesitateSceneEntity(e);
            return;
        }

        e[0x42] = 3;
        e[0x43] = SceneEntityDelay(timid);
        *(ushort*)(e + 0x10) = (ushort)CrtRand();
    }

    // =============================================================================================
    // 0x0049A360 — LA COCCINELLE, sous-type 1 du bloc A de la foret. Transcrite le 2026-08-29 au
    // desassembleur (Legacy/Raw/Blaze/FUN_0049A360.asm, 1392 octets de corps ; la table de sauts a
    // quatre entrees suit a 0x0049a8d0, et 0x0049a8e0 est deja la fonction suivante).
    //
    // C'EST LA PREMIERE BETE VOLANTE ECRITE, et cela change trois choses par rapport aux deux
    // routines terrestres deja transcrites :
    //
    //   1. elle integre son mouvement par FUN_0049a8e0 et non FUN_00488160 — meme amortissement,
    //      mais SANS le rappel de +0x9a qui plaque une bete au sol ;
    //   2. elle n'appelle pas la fin de geste (FUN_004dfaf0) : a la place, un bloc de VOL fait
    //      osciller sa hauteur autour d'un plafond, par le sinus d'une phase que +0x14 accumule ;
    //   3. son interruption est FUN_004a1cf0 et non FUN_004e3770 — deux masques differents.
    //
    // Sa sonde le dit aussi : probe[4] vaut -0x100 la ou les deux terrestres ont 0, donc son gabarit
    // de frappe est decale en hauteur.
    // =============================================================================================

    /// <summary>
    /// Ghidra: FUN_0049a8e0 @ 0x0049a8e0 — <b>l'integration du mouvement d'une entite volante</b>,
    /// la jumelle de <see cref="IntegrateSceneEntityMotion_00488160"/> que la documentation de
    /// celle-ci annoncait deja.
    ///
    /// <para>
    /// <b>Meme piege de signature</b> : <c>Blaze.c</c> la declare a un parametre puis lit
    /// <c>unaff_retaddr</c> et <c>unaff_EBP</c>. Le desassemblage donne deux parametres — l'entite
    /// et l'echelle de vitesse — et <c>unaff_EBP</c> n'est que le sinus dont Ghidra a jete la valeur
    /// de retour.
    /// </para>
    /// <para>
    /// <b>La difference avec sa jumelle tient en un terme absent</b> : la composante verticale
    /// n'est qu'amortie, sans le rappel de <c>+0x9a</c>. Rien ne ramene la bete au sol — c'est le
    /// bloc de vol de <see cref="TickSceneEntityAi_0049A360"/> qui tient sa hauteur.
    /// </para>
    /// </summary>
    private static void IntegrateFlyingEntityMotion_0049A8E0(byte* e, int speed)
    {
        short heading = *(short*)(e + 0x32);

        int sin = (int)Winsys3d.GetSinTableEntry(heading);
        int cos = Winsys3d.GetCosTableEntry(heading);

        int vx = *(int*)(e + 0x50);
        vx = vx - (vx >> 3) - (vx >> 8);
        *(int*)(e + 0x50) = vx;

        int vy = *(int*)(e + 0x54);
        vy = vy - (vy >> 8) - (vy >> 3);

        int vz = *(int*)(e + 0x58);
        int push = *(int*)(e + 0x5c) * speed >> 0xc;

        vz = vz - (vz >> 3) - (vz >> 8);
        *(int*)(e + 0x58) = vz;

        *(int*)(e + 0x1c) += (push * sin >> 0xc) + vx;
        *(int*)(e + 0x54) = vy;
        *(int*)(e + 0x20) += vy;
        *(int*)(e + 0x24) += (push * cos >> 0xc) + vz;
    }

    /// <summary>
    /// Ghidra: FUN_004a1cf0 @ 0x004a1cf0 — <b>la remise a l'attente sur coup recu</b> des betes
    /// volantes, la sœur de <see cref="InterruptSceneEntity_004E3770"/>.
    ///
    /// <para>
    /// Deux masques les separent, et rien d'autre : <c>0x8882</c> au lieu de <c>0x2000a882</c> sur
    /// les drapeaux de vue <c>+0x90</c>, et <c>0x816</c> au lieu de <c>0x817</c> sur les drapeaux
    /// d'entite — le bit 1, que cette routine pose elle-meme a chaque image, est donc exclu du
    /// garde.
    /// </para>
    /// </summary>
    private static void InterruptFlyingEntity_004A1CF0(uint* entity, byte* stats)
    {
        byte* e = (byte*)entity;

        if ((entity[0x24] & 0x8882) != 0)
        {
            if ((*entity & 0x816) == 0)
            {
                e[0x42] = 1;
                e[0x43] = 1;
            }

            entity[0x17] = 0;
        }

        if (*(short*)(e + 0x96) != 0
            && (*(uint*)(stats + 0x14) & 0x80000000) == 0
            && (*entity & 0x816) == 0)
        {
            if ((*entity & 0x40) != 0)
            {
                e[0x43] = 0;
                return;
            }

            e[0x42] = 0;
            e[0x43] = 1;
            entity[0x17] = 0;
        }
    }

    /// <summary>Ghidra: <c>0x0049a4fb</c> et ses trois jumeaux — <b>l'amortissement de la
    /// poussee</b>, un seizieme par image. La ou les deux betes terrestres remettent
    /// <c>+0x5c</c> a zero d'un coup, la Coccinelle ralentit : elle vole, elle ne pile pas.</summary>
    private static void DampFlyingEntityPush(byte* e)
    {
        int push = *(int*)(e + 0x5c);
        *(int*)(e + 0x5c) = push - (push >> 4);
    }

    /// <summary>Ghidra: <c>0x0049a469</c> et ses jumeaux — <b>la montee de la poussee</b> vers une
    /// consigne, par seiziemes. Trois consignes selon la posture : <c>+0x280</c> en frappant,
    /// <c>+0x1a0</c> en approchant, <c>+0x140</c> en errant, chacune decalee de la hardiesse et
    /// multipliee par 0x80.</summary>
    private static void RampFlyingEntityPush(byte* e, int target)
    {
        int push = *(int*)(e + 0x5c);
        *(int*)(e + 0x5c) = push + ((target - push) >> 4);
    }

    /// <summary>Ghidra: <c>0x0049a802</c> et ses deux jumeaux — le compte a rebours de posture de
    /// cette espece. <b>Ce n'est pas <see cref="SceneEntityDelay"/></b> : la timidite y compte pour
    /// un quart et non pour une moitie, et le plancher est 10 au lieu de 0x14. La Coccinelle change
    /// donc d'avis nettement plus vite que ses voisines.</summary>
    private static byte FlyingEntityDelay(int timid)
        => (byte)(CrtRand() % 10 + (byte)(timid >> 2) + 0x0a);

    /// <summary>
    /// Ghidra: <c>0x0049a360</c> — <b>l'intelligence de la Coccinelle</b>, sous-type 1 de la table
    /// installee <c>0x0056ad48</c> en foret. 1392 octets, <b>absente de <c>Blaze.c</c></b> comme
    /// toute la famille ; releve garde sous <c>Legacy/Raw/Blaze/FUN_0049A360.asm</c>.
    ///
    /// <para>
    /// Meme charpente en trois temps que ses deux voisines — decider, appliquer, replanifier — et
    /// quatre postures, comme <see cref="TickSceneEntityAi_00499DE0"/> : 0 attendre, 1 se tourner,
    /// 2 s'approcher, 3 errer vers un cap range en <c>+0x12</c>. <b>Ce n'est pas <c>+0x10</c></b>
    /// comme chez la sœur : le champ change d'une espece a l'autre, et la replanification ecrit
    /// bien <c>+0x12</c>.
    /// </para>
    /// <para>
    /// <b>Elle pose le bit 1 de ses drapeaux a chaque image</b>, des l'entree, avant toute lecture.
    /// Aucune des deux voisines ne le fait ; c'est aussi ce bit que son interruption exclut de son
    /// garde (<c>0x816</c> et non <c>0x817</c>), les deux choix allant ensemble.
    /// </para>
    /// <para>
    /// <b>Son coup ne connait pas d'image de frappe.</b> Les deux terrestres attendent la huitieme
    /// ou la douzieme image du geste pour balayer le groupe ; celle-ci balaie a <b>chaque</b> image
    /// tant que le geste dure, et accelere pendant ce temps. Un contact prolonge, pas un coup
    /// porte — ce qui va avec une bete qui fonce en vol.
    /// </para>
    /// </summary>
    private static void TickSceneEntityAi_0049A360(byte* record)
    {
        byte* e = record;

        // Ghidra: `or eax,edi` avec edi = 1, avant meme la resolution des blocs.
        *(uint*)e |= 1;

        ResolveEntityBlocks(e, out byte* stats, out _, out _);

        short* probe = stackalloc short[6];
        probe[0] = 0;
        probe[1] = 0x1e;
        probe[2] = 0x50;
        probe[3] = 0x64;
        probe[4] = unchecked((short)0xff00);   // le gabarit est decale en hauteur : elle vole
        probe[5] = 0x50;

        int boldness, distance, heading, speed;
        uint traits;
        ReadSceneEntitySituation_00535F20(e, &boldness, &distance, &heading, &speed, &traits);

        int timid = 0x40 - boldness;

        // ---------------------------------------------------------------- 1. decider
        DecideFlyingEntityAction_0049A360(e, probe, boldness, distance, heading, speed, traits);

        // ---------------------------------------------------------------- 2. appliquer
        IntegrateFlyingEntityMotion_0049A8E0(e, speed);
        FinalizeEntityPlacement2((uint*)e);
        BeatWings_0049A68F(e);
        InterruptFlyingEntity_004A1CF0((uint*)e, stats);

        // ---------------------------------------------------------------- 3. replanifier
        if (speed == 0) return;
        if ((*(uint*)e & 0x816) != 0) return;
        if (e[0x43] != 0) return;

        ReplanFlyingEntityAction_0049A360(e, boldness, timid);
    }

    /// <summary>
    /// Ghidra: <c>0x0049a68f..0x0049a710</c> — <b>le vol</b>, et ce qui remplace la fin de geste
    /// chez cette espece.
    ///
    /// <para>
    /// <c>+0x14</c> accumule une <b>phase</b> — de <c>0x100</c> a <c>0x1ff</c> par image, donc
    /// jamais tout a fait la meme — et le sinus de cette phase fait osciller la hauteur autour d'un
    /// plafond. Le plafond est le plus haut de <c>+0x60</c> (le sol sous la bete) et de
    /// <c>+0x48</c>, recopie du <c>+0x60</c> de la cible tant que celle-ci ne porte pas le bit 0 :
    /// <b>la Coccinelle se cale sur l'altitude de ce qu'elle poursuit</b>, sans jamais descendre
    /// sous son propre sol.
    /// </para>
    /// <para>
    /// Pendant un geste, l'oscillation cesse : la hauteur rejoint le plafond majore de
    /// <c>0x28000</c> par huitiemes — elle prend de la hauteur pour foncer. Hors geste elle
    /// rejoint plafond + sinus par seiziemes.
    /// </para>
    /// </summary>
    private static void BeatWings_0049A68F(byte* e)
    {
        *(uint*)(e + 0x90) &= 0xdfffd8ff;

        byte* chased = *(byte**)(e + 0x6c);
        if ((*chased & 1) == 0) *(int*)(e + 0x48) = *(int*)(chased + 0x60);

        *(short*)(e + 0x14) += (short)((CrtRand() & 0xff) + 0x100);

        int ceiling = *(int*)(e + 0x60);
        if (*(int*)(e + 0x48) >= ceiling) ceiling = *(int*)(e + 0x48);

        int y = *(int*)(e + 0x20);

        if ((*(uint*)e & 2) != 0)
        {
            *(int*)(e + 0x20) = y + ((ceiling - y + 0x28000) >> 3);
            return;
        }

        int lift = ((int)Winsys3d.GetSinTableEntry(*(short*)(e + 0x14)) + 0x3200) << 6;
        *(int*)(e + 0x20) = y + ((lift + ceiling - y) >> 4);
    }

    /// <summary>
    /// Ghidra: <c>0x0049a3f2..0x0049a67a</c> — <b>le premier temps</b> de
    /// <see cref="TickSceneEntityAi_0049A360"/>.
    /// </summary>
    private static void DecideFlyingEntityAction_0049A360(
        byte* e, short* probe, int boldness, int distance, int heading, int speed, uint traits)
    {
        if (speed == 0) return;

        AdvanceEntityAnimation_004DB5A0((uint*)e);
        uint flags = *(uint*)e;

        // ================================================================ le geste en cours
        if ((flags & 2) != 0)
        {
            if ((traits & 0x10) != 0)
            {
                e[0x43] = 0;
                *(uint*)e = flags & 0xfffffffd;
                return;
            }

            // Aucun controle d'image du geste : le balayage a lieu a CHAQUE image.
            byte* victim = SweepPartyForMeleeHit_00519C30(e, (int*)(e + 0x1c), probe, 0);

            if (*Mem.Camera(0x005de0b8) != 0)
            {
                *(ushort*)(victim + 0x96) = 0x10;
                *(uint*)victim |= 0x40;

                ResolveMeleeHit_00539B80((uint*)e, (uint*)victim);
                Aud.PlayPositionalSound(3, 0x300, 0x1800, (int*)(victim + 0x1c));
            }

            // Ghidra: LAB_0049a469 — elle ACCELERE pendant le geste, la ou ses voisines remettent
            // la poussee a zero.
            RampFlyingEntityPush(e, (boldness + 0x280) << 7);

            if (e[0x43] == 0) return;
            if (--e[0x43] != 0) return;

            *(uint*)e &= 0xfffffffd;
            return;
        }

        // ================================================================ la posture tenue
        if ((flags & 0x10) != 0) return;
        if ((flags & 0x804) != 0) return;

        byte held = e[0x42];
        if (held > 3) return;

        // Le cone de virage des postures 1 et 2, identique pour les deux.
        int cone = (boldness >> 2) + 0x38;

        switch (held)
        {
            // ---------------------------------------------------------- 0 : attendre
            case 0:
                if (*(ushort*)(e + 0x18) != 0)
                {
                    flags |= 0x1000000;
                    *(int*)(e + 0x18) = 0;
                    *(uint*)e = flags;
                }

                if (distance < 0x12c)
                {
                    e[0x43] = 0;
                    return;
                }

                if (e[0x43] != 0) e[0x43]--;
                DampFlyingEntityPush(e);
                return;

            // ---------------------------------------------------------- 1 : se tourner
            case 1:
                if (*(ushort*)(e + 0x18) != 1)
                {
                    flags |= 0x1000000;
                    *(int*)(e + 0x18) = 1;
                    *(uint*)e = flags;
                }

                if (TurnSceneEntityTowardTarget(e, cone, heading)) e[0x43] = 0;
                DampFlyingEntityPush(e);
                return;

            // ---------------------------------------------------------- 2 : s'approcher
            case 2:
                if (*(ushort*)(e + 0x18) != 1)
                {
                    flags |= 0x1000000;
                    *(int*)(e + 0x18) = 1;
                    *(uint*)e = flags;
                }

                // La distance tenue est une CONSTANTE ici, la ou la sœur la lit dans +0x10.
                if (distance < 0x12c)
                {
                    e[0x43] = 0;
                    return;
                }

                if (e[0x43] != 0) e[0x43]--;

                TurnSceneEntityTowardTarget(e, cone, heading);
                RampFlyingEntityPush(e, (boldness + 0x1a0) << 7);
                return;

            // ---------------------------------------------------------- 3 : errer
            default:
            {
                if (e[0x43] != 0) e[0x43]--;

                if (*(ushort*)(e + 0x18) != 1)
                {
                    flags |= 0x1000000;
                    *(int*)(e + 0x18) = 1;
                    *(uint*)e = flags;
                }

                RampFlyingEntityPush(e, (boldness + 0x140) << 7);

                // Le cap vise est en +0x12, et non en +0x10 comme chez la sœur.
                int bearing = (*(ushort*)(e + 0x12) - *(ushort*)(e + 0x32)) & 0xfff;
                if (((bearing + 0x100) & 0xfff) <= 0x200) return;

                int step = bearing >= 0x800 ? -0x38 - (boldness >> 2) : (boldness >> 2) + 0x38;
                *(ushort*)(e + 0x32) += (ushort)step;
                return;
            }
        }
    }

    /// <summary>
    /// Ghidra: <c>0x0049a742..0x0049a8cf</c> — <b>le troisieme temps</b> : quelle posture prendre
    /// pour la suite.
    ///
    /// <para>
    /// Trois plages de distance, comme chez ses voisines, mais des seuils a elle : <b>sous
    /// 0x12c</b> une chance sur 0x3c d'engager — et l'engagement demande en plus un cap dans le
    /// cone et une distance sous <c>0xfa</c> <b>diminuee</b> d'un tirage (la sœur, elle,
    /// <i>augmente</i> son seuil du meme tirage : plus une Coccinelle hesite, plus elle doit etre
    /// pres) ; sinon elle erre vers un cap tire autour de la cible. <b>Entre 0x12c et 0x258</b>
    /// elle approche, sans condition. <b>Au-dela</b> elle attend, hesite ou erre au hasard.
    /// </para>
    /// <para>
    /// Son engagement ne pose <b>que</b> le bit 2 et un compte a rebours de <c>timidite/8 + 0x10</c> :
    /// ni animation forcee, ni remise a zero de la poussee — elle garde son elan.
    /// </para>
    /// <para>
    /// Le tirage jete de la plage moyenne (<c>call rand</c> dont le resultat n'est pas lu) est
    /// transcrit : il fait avancer le generateur, donc le retirer changerait toute la suite.
    /// </para>
    /// </summary>
    private static void ReplanFlyingEntityAction_0049A360(byte* e, int boldness, int timid)
    {
        byte* chased = *(byte**)(e + 0x6c);

        int dx = (*(int*)(chased + 0x1c) - *(int*)(e + 0x1c)) >> 0xc;
        int dz = (*(int*)(chased + 0x24) - *(int*)(e + 0x24)) >> 0xc;

        int distance = (int)Winsys3d.Ordinal_442((uint)(dx * dx + dz * dz));
        int heading = (Winsys3d.Ordinal_457(dx, dz) - *(ushort*)(e + 0x32)) & 0xfff;

        // ================================================================ le corps a corps
        if (distance < 0x12c)
        {
            if (CrtRand() % 100 >= 0x3c)
            {
                // Errer vers un cap tire AUTOUR de la cible : la largeur du tirage croit avec la
                // hardiesse, et il est centre en retranchant sa moitie.
                e[0x42] = 3;
                e[0x43] = FlyingEntityDelay(timid);

                int spread = (boldness + 0x80) << 4;
                int offset = CrtRand() % spread - (spread >> 1);

                *(short*)(e + 0x12) = (short)(offset + heading + *(short*)(e + 0x32));
                return;
            }

            if (((heading + timid * 4 + 0x100) & 0xfff) > timid * 8 + 0x200)
            {
                HesitateSceneEntity(e);
                return;
            }

            if (distance >= 0xfa - CrtRand() % (timid * 2 + 1))
            {
                HesitateSceneEntity(e);
                return;
            }

            *(uint*)e |= 2;
            e[0x43] = (byte)((timid >> 3) + 0x10);
            return;
        }

        // ================================================================ l'approche
        if (distance < 0x258)
        {
            CrtRand();                       // Ghidra: `call 00547140h` dont le resultat est jete
            e[0x42] = 2;
            e[0x43] = FlyingEntityDelay(timid);
            return;
        }

        // ================================================================ l'errance
        int far = CrtRand() % 100;

        if (far < 0x1e)
        {
            e[0x42] = 0;
            e[0x43] = FlyingEntityDelay(timid);
            return;
        }

        if (far < 0x3c)
        {
            HesitateSceneEntity(e);
            return;
        }

        e[0x42] = 3;
        e[0x43] = FlyingEntityDelay(timid);
        *(short*)(e + 0x12) = (short)CrtRand();
    }

    // =============================================================================================
    // 0x0049C8E0 — LE POISSON VOLANT, sous-type 6 du bloc A de la foret. Transcrite le 2026-08-29
    // au desassembleur (Legacy/Raw/Blaze/FUN_0049C8E0.asm, 1866 octets, absente de Blaze.c).
    //
    // SON NOM TROMPE : elle appelle FUN_00488160, l'integration TERRESTRE, et non FUN_0049a8e0
    // comme la Coccinelle. Elle ne vole pas, elle BONDIT — le bit 1 de ses drapeaux veut dire « en
    // l'air », +0x54 porte sa vitesse verticale, et l'atterrissage se detecte en comparant +0x20 au
    // sol de +0x60. C'est le tri par la fonction d'integration, recommande dans Comportement.md,
    // qui l'a dit en une ligne.
    //
    // ET ELLE S'ACCROCHE. Aucune des trois routines precedentes ne fait cela : quand son bond
    // touche un membre du groupe, elle se colle a lui (bit 0 de +0x40), range l'ecart auquel elle
    // s'est fixee dans +0x44/+0x48/+0x4c, et RECOPIE la position de sa victime a chaque image au
    // lieu d'integrer son propre mouvement. Elle mord tous les 0x1e images. Le joueur s'en
    // debarrasse en REMUANT : la routine lit son propre pad, et chaque image ou une direction est
    // tenue fait descendre le compteur de prise +0x10.
    // =============================================================================================

    /// <summary>
    /// Ghidra: <c>0x0049c8e0</c> — <b>l'intelligence du Poisson volant</b>, sous-type 6 de la table
    /// installee <c>0x0056ad48</c> en foret.
    ///
    /// <para>
    /// <b>Trois postures seulement</b>, et <b>aucune table de sauts</b> : l'aiguillage est une
    /// cascade de comparaisons (0 attendre, 1 se tourner, 2 bondir), toute autre valeur ne faisant
    /// rien. C'est la premiere des quatre routines ecrites a se passer de table — donc la recette
    /// « relever la table de sauts qui suit le corps » ne s'applique pas partout.
    /// </para>
    /// <para>
    /// Sa sonde est <c>{0, 0, 0x28, 0x32, 0, 0x3c}</c> : la plus courte des quatre, et sans le
    /// decalage vertical de la Coccinelle. Elle frappe au ras du sol, a bout portant.
    /// </para>
    /// </summary>
    private static void TickSceneEntityAi_0049C8E0(byte* record)
    {
        byte* e = record;

        ResolveEntityBlocks(e, out byte* stats, out _, out _);

        short* probe = stackalloc short[6];
        probe[0] = 0;
        probe[1] = 0;
        probe[2] = 0x28;
        probe[3] = 0x32;
        probe[4] = 0;
        probe[5] = 0x3c;

        int boldness, distance, heading, speed;
        uint traits;
        ReadSceneEntitySituation_00535F20(e, &boldness, &distance, &heading, &speed, &traits);

        int timid = 0x40 - boldness;

        // ---------------------------------------------------------------- 1. decider
        DecideLeapingEntityAction_0049C8E0(e, probe, boldness, distance, heading, speed, timid, traits);

        // ---------------------------------------------------------------- 2. appliquer
        ApplyLeapingEntityMotion_0049CD7C(e, speed);

        // ---------------------------------------------------------------- 3. replanifier
        if (speed == 0) return;
        if ((*(uint*)e & 0x817) != 0) return;
        if (e[0x43] != 0) return;

        // Accrochee, elle ne replanifie pas : c'est la prise qui mene, et seule sa rupture rend
        // la main a la decision.
        if ((e[0x40] & 1) != 0) return;

        ReplanLeapingEntityAction_0049C8E0(e, timid);
    }

    /// <summary>
    /// Ghidra: <c>0x0049c96b..0x0049cd7b</c> — <b>le premier temps</b> du Poisson volant.
    ///
    /// <para>
    /// <b>Le geste en cours a deux visages</b>, selon le bit 0 de <c>+0x40</c>. Tant qu'il est
    /// libre, chaque image cherche une victime sous le gabarit ; des qu'il en tient une, il ne
    /// cherche plus rien et se contente de decompter <c>+0x14</c> jusqu'a la morsure suivante. La
    /// prise se defait de trois facons : l'espece perd le trait <c>0x10</c>, la victime meurt
    /// (bit <c>0x40000000</c>), ou le poisson touche le sol.
    /// </para>
    /// <para>
    /// <b>Le bond se joue en deux images</b>, par le compte a rebours <c>+0x43</c> que la
    /// replanification pose a 2 : a 2 il prend son elan et tourne, a 1 il detend. Et il n'y a pas
    /// un bond mais <b>deux</b>, choisis par le bit <c>0x200</c> des drapeaux de vue — le second
    /// (bit absent) donne une poussee plus faible mais une detente verticale plus haute, melee a
    /// la timidite.
    /// </para>
    /// </summary>
    private static void DecideLeapingEntityAction_0049C8E0(
        byte* e, short* probe, int boldness, int distance, int heading, int speed, int timid,
        uint traits)
    {
        if (speed == 0) return;

        AdvanceEntityAnimation_004DB5A0((uint*)e);
        uint flags = *(uint*)e;

        // ================================================================ le geste en cours
        if ((flags & 2) != 0)
        {
            if ((traits & 0x10) != 0)
            {
                *(uint*)e = flags & 0xfffffffd;
                e[0x43] = 0;
                e[0x40] &= 0xfe;
                return;
            }

            byte* victim = null;

            if ((e[0x40] & 1) != 0)
            {
                // Deja accrochee : rien a chercher, seulement le compte avant la morsure.
                *(ushort*)(e + 0x14) -= 1;
                if (*(ushort*)(e + 0x14) == 0) victim = *(byte**)(e + 0x6c);
            }
            else
            {
                victim = SweepPartyForMeleeHit_00519C30(e, (int*)(e + 0x1c), probe, 0);

                if (victim != null)
                {
                    // L'ecart auquel elle se fixe, en coordonnees du monde : 60 fois le sinus et le
                    // cosinus du cap qui va de la victime vers elle, et l'ecart de hauteur tel quel.
                    int dz = (*(int*)(e + 0x24) - *(int*)(victim + 0x24)) >> 0xc;
                    int dx = (*(int*)(e + 0x1c) - *(int*)(victim + 0x1c)) >> 0xc;

                    int angle = Winsys3d.Ordinal_457(dx, dz);

                    *(int*)(e + 0x44) = (int)Winsys3d.GetSinTableEntry(angle) * 60;
                    *(int*)(e + 0x48) = *(int*)(e + 0x20) - *(int*)(victim + 0x20);
                    *(int*)(e + 0x4c) = Winsys3d.GetCosTableEntry(angle) * 60;

                    e[0x40] |= 1;

                    // La force de la prise : de 8 a 15 images de secouage, plus un quart de la
                    // hardiesse. Une bete hardie s'accroche plus longtemps.
                    *(ushort*)(e + 0x10) = (ushort)((CrtRand() & 7) + (boldness >> 2) + 8);

                    *(ushort*)(victim + 0x96) = 0x10;
                    *(uint*)victim |= 0x40;

                    // Elle poursuit desormais celui qu'elle tient.
                    *(byte**)(e + 0x6c) = victim;
                }
            }

            if (victim != null)
            {
                ResolveMeleeHit_00539B80((uint*)e, (uint*)victim);
                Aud.PlayPositionalSound(3, 0x300, 0x1800, (int*)(victim + 0x1c));

                if ((*(uint*)victim & 0x40000000) != 0)
                {
                    // La victime s'en va : la prise tombe avec elle.
                    e[0x40] &= 0xfe;
                    *(uint*)e &= 0xfffffffd;
                }
                else
                {
                    *(ushort*)(e + 0x14) = 0x1e;
                }
            }

            // Ghidra: LAB_0049ca9f — tant qu'elle est en l'air, le geste continue.
            flags = *(uint*)e;
            if ((flags & 1) != 0) return;

            *(uint*)e = flags & 0xfffffffd;
            e[0x43] = 0;
            e[0x40] &= 0xfe;
            *(int*)(e + 0x5c) = 0;
            return;
        }

        // ================================================================ la posture tenue
        if ((flags & 0x11) != 0) return;
        if ((flags & 0x804) != 0) return;

        // Le cone de virage, commun aux trois postures qui tournent : deux fois la hardiesse.
        int cone = boldness * 2 + 0x80;

        switch (e[0x42])
        {
            // ---------------------------------------------------------- 0 : attendre
            case 0:
                if (*(ushort*)(e + 0x18) != 0)
                {
                    flags |= 0x1000000;
                    *(int*)(e + 0x18) = 0;
                    *(uint*)e = flags;
                }

                if (distance < 0x12c)
                {
                    e[0x43] = 0;
                    return;
                }

                if (e[0x43] != 0) e[0x43]--;
                *(int*)(e + 0x5c) = 0;
                return;

            // ---------------------------------------------------------- 1 : se tourner
            case 1:
                if (*(ushort*)(e + 0x18) != 1)
                {
                    flags |= 0x1000000;
                    *(int*)(e + 0x18) = 1;
                    *(uint*)e = flags;
                }

                if (TurnSceneEntityTowardTarget(e, cone, heading)) e[0x43] = 0;
                *(int*)(e + 0x5c) = 0;
                return;

            // ---------------------------------------------------------- 2 : bondir
            case 2:
                break;

            default:
                return;
        }

        // ================================================================ le bond
        if ((*(uint*)(e + 0x90) & 0x200) == 0)
        {
            // Ghidra: LAB_0049cc4d — le bond « libre », sans appui : poussee moindre, detente plus
            // haute, et la timidite s'y ajoute par paliers de seize.
            TurnSceneEntityTowardTarget(e, cone, heading);

            *(uint*)e = flags | 0x1000002;
            *(int*)(e + 0x18) = 3;

            int freePush = (boldness + 0x140) << 7;
            *(int*)(e + 0x5c) = freePush;

            AddDirectedImpulse(e, freePush);

            int lift = (((CrtRand() & 7) + 0x10) << 4) + (timid & unchecked((int)0xfffffff0));
            *(int*)(e + 0x54) += lift << 8;

            *(uint*)e |= 1;
            *(int*)(e + 0x5c) = 0;
            return;
        }

        if (*(ushort*)(e + 0x18) != 1)
        {
            flags |= 0x1000000;
            *(int*)(e + 0x18) = 1;
            *(uint*)e = flags;
        }

        // Ghidra: LAB_0049cb0b — le compte a rebours mene les deux images du bond.
        byte step = e[0x43];

        if (step == 2)
        {
            // L'elan : elle tourne et se donne de la vitesse au sol, sans quitter le sol.
            TurnSceneEntityTowardTarget(e, cone, heading);

            *(int*)(e + 0x5c) = (boldness + 0x280) << 7;
            AddDirectedImpulseThenClear(e);

            e[0x43]--;
            return;
        }

        if (step != 1) return;

        // Ghidra: LAB_0049cba5 — la detente. Le compte ne descend que si elle a assez ralenti :
        // la vitesse au sol doit etre tombee sous un huitieme de la hardiesse.
        int vx = *(int*)(e + 0x50) >> 0xc;
        int vz = *(int*)(e + 0x58) >> 0xc;

        if ((int)Winsys3d.Ordinal_442((uint)(vx * vx + vz * vz)) <= (boldness >> 3) + 1)
        {
            e[0x43]--;
        }

        // +0x10 porte ici la portee du bond, posee a 0x12c par la replanification.
        if (distance >= *(short*)(e + 0x10)) return;

        int leapPush = (boldness + 0x200) << 7;
        *(int*)(e + 0x5c) = leapPush;
        *(uint*)e |= 0x1000002;
        *(int*)(e + 0x18) = 3;

        AddDirectedImpulse(e, leapPush);

        *(int*)(e + 0x54) = ((CrtRand() & 7) + 0x20) << 0xc;
        *(uint*)e |= 1;
        *(int*)(e + 0x5c) = 0;
    }

    /// <summary>Ghidra: le motif <c>sin * poussee &gt;&gt; 12</c> ajoute a <c>+0x50</c> et
    /// <c>+0x58</c>, repete trois fois dans le bond.</summary>
    private static void AddDirectedImpulse(byte* e, int push)
    {
        *(int*)(e + 0x50) += (int)Winsys3d.GetSinTableEntry(*(short*)(e + 0x32)) * push >> 0xc;
        *(int*)(e + 0x58) += Winsys3d.GetCosTableEntry(*(short*)(e + 0x32)) * push >> 0xc;
    }

    /// <summary>Le meme motif, mais la poussee est remise a zero <b>entre</b> les deux composantes
    /// dans le binaire — apres la multiplication du sinus, avant celle du cosinus. Sans
    /// consequence, les deux lisant la meme valeur deja chargee ; transcrit dans cet ordre.</summary>
    private static void AddDirectedImpulseThenClear(byte* e)
    {
        int push = *(int*)(e + 0x5c);

        *(int*)(e + 0x50) += (int)Winsys3d.GetSinTableEntry(*(short*)(e + 0x32)) * push >> 0xc;

        int forward = Winsys3d.GetCosTableEntry(*(short*)(e + 0x32)) * push >> 0xc;
        *(int*)(e + 0x5c) = 0;
        *(int*)(e + 0x58) += forward;
    }

    /// <summary>
    /// Ghidra: <c>0x0049cd7c..0x0049cef9</c> — <b>le deuxieme temps</b> : appliquer. Il fait trois
    /// choses qu'aucune des trois autres routines ne fait.
    ///
    /// <para>
    /// <b>1. La prise remplace le mouvement.</b> Accrochee, l'entite ne s'integre pas : sa position
    /// est recopiee de sa victime, plus l'ecart range en <c>+0x44</c>/<c>+0x48</c>/<c>+0x4c</c>.
    /// </para>
    /// <para>
    /// <b>2. Le joueur se debat.</b> La routine remonte jusqu'au <b>pad</b> de la victime — par
    /// <c>0x005e9188</c> puis <c>0x00604a20</c>, l'indexation exacte des sondes d'entree — et
    /// n'use le compteur de prise <c>+0x10</c> que si l'un des quatre bits de direction
    /// (<c>0xf0</c> du troisieme octet) est tenu. A zero, elle lache et part <b>en arriere</b> :
    /// cap + 0x800, et une detente verticale fixe de 0xa000. Le personnage porte par un autre
    /// joueur est reconnu par le bit <c>0x10000</c> de ses drapeaux, auquel cas c'est le pad du
    /// meneur qui compte.
    /// </para>
    /// <para>
    /// <b>3. L'atterrissage.</b> Sous le sol de <c>+0x60</c>, la hauteur y est ramenee, le bit
    /// « en l'air » tombe, la vitesse verticale est annulee, et un geste en cours est interrompu.
    /// Au-dessus, le bit est pose. C'est tout ce qui distingue un bond d'un vol.
    /// </para>
    /// </summary>
    private static void ApplyLeapingEntityMotion_0049CD7C(byte* e, int speed)
    {
        if ((e[0x40] & 1) != 0)
        {
            byte* host = *(byte**)(e + 0x6c);

            *(int*)(e + 0x1c) = *(int*)(host + 0x1c) + *(int*)(e + 0x44);
            *(int*)(e + 0x20) = *(int*)(host + 0x20) + *(int*)(e + 0x48);
            *(int*)(e + 0x24) = *(int*)(host + 0x24) + *(int*)(e + 0x4c);

            uint player = (*(uint*)host & 0x10000) != 0
                ? (uint)(byte)Mem.s_Unknown_005de538
                : host[8];

            byte* pad = Inp.s_InputStateBase_00604a20
                      + Inp.s_PlayerSlots_005e9188[player * 0x4c] * 0x10;

            if ((pad[2] & 0xf0) != 0)
            {
                *(ushort*)(e + 0x10) -= 1;

                if (*(ushort*)(e + 0x10) == 0)
                {
                    int away = *(short*)(e + 0x32) + 0x800;

                    *(uint*)e &= 0xfffffffd;
                    e[0x43] = 0;
                    e[0x40] &= 0xfe;

                    *(int*)(e + 0x50) += (int)Winsys3d.GetSinTableEntry(away) << 5;
                    *(int*)(e + 0x54) = 0xa000;
                    *(int*)(e + 0x58) += Winsys3d.GetCosTableEntry(away) << 5;
                }
            }
        }
        else
        {
            IntegrateSceneEntityMotion_00488160(e, speed);
        }

        // Ghidra: LAB_0049ce4c
        FinalizeEntityPlacement2((uint*)e);

        uint view = *(uint*)(e + 0x90) & 0xdfffdbff;
        *(uint*)(e + 0x90) = view;

        int ground = *(int*)(e + 0x60);

        if (*(int*)(e + 0x20) <= ground)
        {
            *(int*)(e + 0x20) = ground;

            uint flags = *(uint*)e;
            if ((flags & 3) != 0)
            {
                *(uint*)e = flags & 0xfffffffd;
                e[0x43] = 0;
                e[0x40] &= 0xfe;
            }

            *(uint*)e &= 0xfffffffe;
            *(int*)(e + 0x54) = 0;
        }
        else if ((*(uint*)e & 1) == 0)
        {
            *(uint*)e |= 1;
        }

        // Ghidra: LAB_0049ce9f — la prise se rompt aussi quand la victime disparait ou s'occupe.
        bool interrupt = (view & 0x8882) != 0;

        if ((e[0x40] & 1) != 0)
        {
            byte* host = *(byte**)(e + 0x6c);
            if ((*(uint*)host & 0x50002000) != 0 || *(ushort*)(host + 0x12) != 0) interrupt = true;
        }

        if (interrupt)
        {
            *(uint*)e &= 0xfffffffd;
            e[0x42] = 1;
            e[0x43] = 1;
            e[0x40] &= 0xfe;
            *(int*)(e + 0x5c) = 0;
        }

        // Ghidra: LAB_0049ced6 — le coup recu, meme forme que FUN_004e3770 mais ecrite ici.
        if (*(short*)(e + 0x96) == 0) return;

        uint state = *(uint*)e;

        if ((state & 0x40) != 0)
        {
            if ((state & 0x43) == 0) e[0x43] = 0;
            return;
        }

        e[0x42] = 0;
        e[0x43] = 1;
        *(int*)(e + 0x5c) = 0;
    }

    /// <summary>
    /// Ghidra: <c>0x0049cefa..0x0049d029</c> — <b>le troisieme temps</b>.
    ///
    /// <para>
    /// Trois plages, et un choix nettement plus tranche que chez ses voisines : <b>sous 0xfa</b>
    /// une chance sur deux de bondir, sinon se tourner ; <b>entre 0xfa et 0x1f4</b> 45 % se
    /// tourner, 45 % bondir, le reste attendre ; <b>au-dela</b> une chance sur deux de se tourner,
    /// sinon attendre. Elle ne se repose jamais et n'erre jamais — deux postures que cette espece
    /// n'a tout simplement pas.
    /// </para>
    /// <para>
    /// Bondir pose toujours le meme couple : posture 2, compte a rebours 2 (les deux images du
    /// bond), et <c>+0x10</c> a <b>0x12c</b> — la portee sous laquelle la detente part.
    /// </para>
    /// <para>
    /// Le cap relatif est calcule puis <b>jamais lu</b>. C'est dans le binaire ; conserve, parce
    /// que le calcul consomme les memes appels que partout ailleurs et que le retirer changerait
    /// la lecture du reste.
    /// </para>
    /// </summary>
    private static void ReplanLeapingEntityAction_0049C8E0(byte* e, int timid)
    {
        byte* chased = *(byte**)(e + 0x6c);

        int dx = (*(int*)(chased + 0x1c) - *(int*)(e + 0x1c)) >> 0xc;
        int dz = (*(int*)(chased + 0x24) - *(int*)(e + 0x24)) >> 0xc;

        int distance = (int)Winsys3d.Ordinal_442((uint)(dx * dx + dz * dz));

        // Ghidra le range en pile et ne le relit jamais.
        _ = (Winsys3d.Ordinal_457(dx, dz) - *(ushort*)(e + 0x32)) & 0xfff;

        if (distance < 0xfa)
        {
            if (CrtRand() % 100 < 0x32)
            {
                LeapAt(e);
                return;
            }

            HesitateSceneEntity(e);
            return;
        }

        if (distance < 0x1f4)
        {
            int roll = CrtRand() % 100;

            if (roll < 0x2d)
            {
                HesitateSceneEntity(e);
                return;
            }

            if (roll < 0x5a)
            {
                LeapAt(e);
                return;
            }
        }
        else if (CrtRand() % 100 < 0x32)
        {
            HesitateSceneEntity(e);
            return;
        }

        // Ghidra: LAB_0049d003 — l'attente, seule sortie commune aux deux plages lointaines.
        e[0x42] = 0;
        e[0x43] = SceneEntityDelay(timid);
    }

    /// <summary>Ghidra: le triplet <c>+0x42 = 2 ; +0x43 = 2 ; +0x10 = 0x12c</c>, pose a l'identique
    /// aux deux endroits ou la replanification decide de bondir.</summary>
    private static void LeapAt(byte* e)
    {
        e[0x42] = 2;
        e[0x43] = 2;
        *(ushort*)(e + 0x10) = 0x12c;
    }

    // =============================================================================================
    // 0x0049C0B0 — LE CRABE GEANT, sous-type 5 du bloc A de la foret. Transcrite le 2026-08-29 au
    // desassembleur (Legacy/Raw/Blaze/FUN_0049C0B0.asm, 2096 octets, absente de Blaze.c).
    //
    // ELLE EST TERRESTRE, et c'est la plus proche parente des deux premieres routines : meme
    // integration FUN_00488160, meme queue de quatre appels, meme table de sauts — quatre entrees
    // relevees a 0x0049c8cc — et les memes feuilles partagees. Le tri par la fonction d'integration
    // recommande dans Comportement.md s'est verifie du premier coup, et la replanification est
    // celle de FUN_0049a980 a deux branches pres.
    //
    // CE QUI LUI EST PROPRE : DEUX ATTAQUES, PAS UNE.
    //
    //   - La PINCE, posture 0 en geste : un balayage du gabarit a CHAQUE image de la douzieme a la
    //     quinzieme, sans verrou de coup unique — donc jusqu'a quatre occasions de toucher dans un
    //     seul geste. Aucune des quatre routines precedentes ne frappe plus d'une fois par geste.
    //
    //   - La RUEE, posture 1 en geste : une machine a trois temps portee par +0x10, decomptee de 2
    //     a 0. A 2 elle amortit sa poussee d'un seizieme et vise ; a la quatorzieme image du geste
    //     elle passe a 1 ; a 1 elle se lance, en versant (hardiesse + 0x380) << 7 dans ses VITESSES
    //     +0x50/+0x58 ; a 0 elle cherche ce qu'elle a percute, et le verrou 0x20 la limite alors a
    //     un seul contact.
    //
    // ET LA RUEE NE PORTE QU'A MOITIE. Avant d'appeler FUN_00539b80 elle divise par deux le
    // premier des huit caracteres du bloc de MODELE (+0x30, l'attaque), puis le remet tel quel
    // aussitot apres. Comme FUN_00538af0 recopie ce bloc dans la fiche a chaque coup, la division
    // se propage jusqu'aux degats et disparait ensuite sans laisser de trace. C'est la premiere
    // routine ecrite qui MODULE les degats plutot que de les subir, et le detour par le modele
    // partage — et non par la fiche de la bete — est ce qui rend l'astuce invisible a la lecture
    // de FUN_00539b80.
    //
    // Enfin, un contact reussi projette la victime a trente unites par image dans le cap du crabe,
    // la decolle du sol si elle y etait, et fait naitre l'effet 0x39 au point d'impact — le crabe
    // se pose une image sur la position de sa victime pour cela, puis reprend la sienne.
    // =============================================================================================

    /// <summary>
    /// Ghidra: <c>0x0049c0b0</c> — <b>l'intelligence du Crabe geant</b>, sous-type 5 de la table
    /// installee <c>0x0056ad48</c> en foret. Cinquieme routine d'intelligence transcrite.
    ///
    /// <para>
    /// <b>Quatre postures</b>, aiguillees par la table de sauts relevee a <c>0x0049c8cc</c>
    /// (<c>0x0049c415</c>, <c>0x0049c44e</c>, <c>0x0049c4b1</c>, <c>0x0049c539</c>) : 0 attendre,
    /// 1 se tourner, 2 s'approcher jusqu'a la distance tenue en <c>+0x10</c>, 3 marcher vers un cap
    /// range dans ce meme <c>+0x10</c>. Il n'y a pas de « foncer » comme chez
    /// <see cref="TickSceneEntityAi_0049A980"/> : la ruee prend sa place, et elle est un GESTE et
    /// non une posture.
    /// </para>
    /// <para>
    /// Sa sonde est <c>{0, 0x32, 0x3c, 0x64, 0, 0x50}</c> — la plus longue des cinq en portee comme
    /// en tolerance de hauteur, et la seule dont le deuxieme terme vaille <c>0x32</c>. Une pince
    /// qui balaie large.
    /// </para>
    /// <para>
    /// <b>Sa marche ne tient pas compte de la vitesse rendue par la lecture de situation</b>, la ou
    /// sa sœur <c>0x0049a980</c> multiplie sa poussee par elle avant d'avancer. Le crabe applique
    /// la poussee brute a sa position. Ce n'est pas un oubli de transcription : les deux corps
    /// different bien d'un <c>imul</c>.
    /// </para>
    /// </summary>
    private static void TickSceneEntityAi_0049C0B0(byte* record)
    {
        byte* e = record;

        // Le bloc de MODELE sert ici, ce qui n'arrive dans aucune des quatre routines precedentes :
        // c'est lui que la ruee ampute de la moitie de son attaque le temps d'un coup.
        ResolveEntityBlocks(e, out byte* stats, out _, out byte* model);

        short* probe = stackalloc short[6];
        probe[0] = 0;
        probe[1] = 0x32;
        probe[2] = 0x3c;
        probe[3] = 0x64;
        probe[4] = 0;
        probe[5] = 0x50;

        int boldness, distance, heading, speed;
        uint traits;
        ReadSceneEntitySituation_00535F20(e, &boldness, &distance, &heading, &speed, &traits);

        int timid = 0x40 - boldness;

        // ---------------------------------------------------------------- 1. decider
        DecideLungingEntityAction_0049C0B0(e, model, probe, boldness, distance, heading, speed, traits);

        // ---------------------------------------------------------------- 2. appliquer
        IntegrateSceneEntityMotion_00488160(e, speed);
        FinalizeEntityPlacement2((uint*)e);
        EndSceneEntityAnimation_004DFAF0((uint*)e);
        InterruptSceneEntity_004E3770((uint*)e, stats);

        // ---------------------------------------------------------------- 3. replanifier
        if (speed == 0) return;
        if ((*(uint*)e & 0x817) != 0) return;
        if (e[0x43] != 0) return;

        ReplanLungingEntityAction_0049C0B0(e, boldness, timid);
    }

    /// <summary>
    /// Ghidra: <c>0x0049c13d..0x0049c5d6</c> — <b>le premier temps</b> du Crabe geant : ce qu'il
    /// fait de l'image en cours, selon qu'il est en train de frapper ou qu'il tient une posture.
    ///
    /// <para>
    /// <b>La forme du geste se lit sur la posture</b>, et non sur un champ propre : posture 0 c'est
    /// la pince, posture 1 c'est la ruee, toute autre valeur ne fait rien de l'image. Le champ
    /// <c>+0x42</c> sert donc a deux choses selon que le bit 1 des drapeaux est mis ou non —
    /// posture tenue quand il est absent, forme du geste quand il est present.
    /// </para>
    /// <para>
    /// <b>Ni recul ni relance</b> : contrairement a <see cref="TickSceneEntityAi_0049A980"/>, le
    /// mot d'etat <c>0x11</c> renvoie directement a l'application, sans la branche qui se tourne
    /// vers l'agresseur ni la chance de relancer une attaque en fin de geste. Sur ce point le crabe
    /// suit <see cref="TickSceneEntityAi_00499DE0"/>.
    /// </para>
    /// </summary>
    private static void DecideLungingEntityAction_0049C0B0(
        byte* e, byte* model, short* probe,
        int boldness, int distance, int heading, int speed, uint traits)
    {
        if (speed == 0) return;

        AdvanceEntityAnimation_004DB5A0((uint*)e);
        uint flags = *(uint*)e;

        // ================================================================ le geste en cours
        if ((flags & 2) != 0)
        {
            // Le trait 0x10 coupe court : l'espece ne poursuit pas son geste.
            if ((traits & 0x10) != 0)
            {
                e[0x43] = 0;
                *(uint*)e = flags & 0xfffffffd;
                return;
            }

            byte posture = e[0x42];

            // ------------------------------------------------------------ 0 : LA PINCE
            if (posture == 0)
            {
                // Ghidra: LAB_0049c371 — quatre images de contact, et pas de verrou : le gabarit
                // est croise a chacune d'elles, donc une victime restee dessous encaisse quatre
                // fois. C'est ce que fait le binaire, pas une garde oubliee a la transcription.
                short frame = *(short*)(e + 0x1a);
                if (frame >= 0x0c && frame <= 0x0f)
                {
                    byte* victim = SweepPartyForMeleeHit_00519C30(e, (int*)(e + 0x1c), probe, 0);

                    if (*Mem.Camera(0x005de0b8) != 0)
                    {
                        *(ushort*)(victim + 0x96) = 0x10;      // le clignotement de degat
                        *(uint*)victim |= 0x40;
                        ResolveMeleeHit_00539B80((uint*)e, (uint*)victim);
                        Aud.PlayPositionalSound(3, 0x300, 0x1800, (int*)(victim + 0x1c));
                    }
                }

                // Ghidra: LAB_0049c3d0 — la poussee retombe dans tous les cas ; le geste ne se
                // ferme que si le bit 0x2000000 est la.
                flags = *(uint*)e;
                if ((flags & 0x2000000) != 0)
                {
                    *(int*)(e + 0x5c) = 0;
                    *(uint*)e = flags & 0xfffffffd;
                    return;
                }

                *(int*)(e + 0x5c) = 0;                          // Ghidra: LAB_0049c4a5
                return;
            }

            if (posture != 1) return;

            // ------------------------------------------------------------ 1 : LA RUEE
            short phase = *(short*)(e + 0x10);

            // -------------------------------------------------------- 2 : amortir et viser
            if (phase == 2)
            {
                int carried = *(int*)(e + 0x5c);
                *(int*)(e + 0x5c) = carried - (carried >> 4);

                // Le passage au temps suivant est cale sur l'ANIMATION, pas sur un compteur : la
                // quatorzieme image du geste est celle ou les pinces sont ecartees.
                if (*(short*)(e + 0x1a) == 0x0e) *(short*)(e + 0x10) = (short)(phase - 1);

                TurnSceneEntityTowardTarget(e, (boldness >> 2) + 0x20, heading);
                return;
            }

            // -------------------------------------------------------- 1 : se lancer
            if (phase == 1)
            {
                // La poussee la plus forte de toutes les routines ecrites, et la seule versee dans
                // les VITESSES d'un coup puis remise a zero dans la meme image : ce qui avance le
                // crabe ensuite, c'est l'inertie que FUN_00488160 amortit.
                int thrust = (boldness + 0x380) << 7;
                *(int*)(e + 0x5c) = thrust;

                int course = *(short*)(e + 0x32);
                *(int*)(e + 0x50) += ((int)Winsys3d.GetSinTableEntry(course) * thrust) >> 0xc;
                *(int*)(e + 0x58) += ((int)Winsys3d.GetCosTableEntry(course) * thrust) >> 0xc;
                *(int*)(e + 0x5c) = 0;

                *(short*)(e + 0x10) -= 1;
                return;
            }

            if (phase != 0) return;

            // -------------------------------------------------------- 0 : le contact
            // Ghidra: LAB_0049c241 — le compte a rebours ferme le geste ET leve le verrou de coup
            // unique en meme temps (0xdd efface les bits 0x02 et 0x20).
            if ((flags & 0x2000000) != 0 && e[0x43] != 0)
            {
                e[0x43]--;
                if (e[0x43] == 0) *(uint*)e = flags & 0xffffffdd;
            }

            // Ghidra: LAB_0049c25a — le verrou : une ruee ne touche qu'une fois.
            if ((*(uint*)e & 0x20) != 0) return;

            byte* prey = SweepPartyForMeleeHit_00519C30(e, (int*)(e + 0x1c), probe, 0);
            if (prey != null) *(uint*)e |= 0x20;

            // Ghidra: LAB_0049c283
            if (*Mem.Camera(0x005de0b8) == 0) return;

            *(ushort*)(prey + 0x96) = 0x10;
            *(uint*)prey |= 0x40;

            // LA MOITIE : le premier caractere du bloc de MODELE est l'attaque, et
            // RebaseStatBlockOnModel_00538AF0 le recopie dans la fiche au debut de chaque
            // resolution. Le diviser ici puis le remettre fait donc un coup deux fois moins fort,
            // sans rien laisser derriere.
            short power = *(short*)(model + 0x30);
            *(short*)(model + 0x30) = (short)(power >> 1);
            ResolveMeleeHit_00539B80((uint*)e, (uint*)prey);
            *(short*)(model + 0x30) = power;

            Aud.PlayPositionalSound(3, 0x300, 0x1800, (int*)(prey + 0x1c));

            // Une victime que le coup vient d'emporter n'est pas projetee.
            if ((*(uint*)prey & 0x40000000) != 0) return;

            int impact = *(short*)(e + 0x32);
            *(int*)(prey + 0x50) = (int)Winsys3d.GetSinTableEntry(impact) * 30;
            *(int*)(prey + 0x58) = (int)Winsys3d.GetCosTableEntry(impact) * 30;

            uint preyFlags = *(uint*)prey;
            if ((preyFlags & 1) == 0)
            {
                *(int*)(prey + 0x54) = 0x18000;                 // et elle decolle
                *(uint*)prey = preyFlags | 1;
            }

            // Ghidra: LAB_0049c322 — l'effet 0x39 doit naitre AU POINT D'IMPACT. Le binaire n'a pas
            // d'autre moyen de le poser ailleurs qu'a l'entite source, alors il deplace le crabe
            // sur sa victime le temps de l'appel et le remet ensuite. Meme ruse que la trainee de
            // TickSceneEntityAi_0049A980, sur la position au lieu de la vitesse.
            int savedX = *(int*)(e + 0x1c);
            int savedY = *(int*)(e + 0x20);
            int savedZ = *(int*)(e + 0x24);

            *(int*)(e + 0x1c) = *(int*)(prey + 0x1c);
            *(int*)(e + 0x20) = *(int*)(prey + 0x20);
            *(int*)(e + 0x24) = *(int*)(prey + 0x24);

            SpawnEffectEntity(e, 0x39, 0, -1);

            *(int*)(e + 0x1c) = savedX;
            *(int*)(e + 0x20) = savedY;
            *(int*)(e + 0x24) = savedZ;
            return;
        }

        // ================================================================ la posture tenue
        // Ghidra: LAB_0049c3ed — ni le recul (0x10) ni la fin de geste (0x01) ne donnent lieu a
        // quoi que ce soit ici : le crabe encaisse sans se retourner.
        if ((flags & 0x11) != 0) return;
        if ((flags & 0x804) != 0) return;

        byte stance = e[0x42];
        if (stance > 3) return;

        switch (stance)
        {
            // ---------------------------------------------------------- 0 : attendre
            case 0:
                if (*(ushort*)(e + 0x18) != 0)
                {
                    flags |= 0x1000000;
                    *(int*)(e + 0x18) = 0;
                    *(uint*)e = flags;
                }

                if (distance < 0x12c)
                {
                    e[0x43] = 0;
                    return;
                }

                if (e[0x43] != 0) e[0x43]--;
                *(int*)(e + 0x5c) = 0;
                return;

            // ---------------------------------------------------------- 1 : se tourner
            case 1:
                if (*(ushort*)(e + 0x18) != 1)
                {
                    flags |= 0x1000000;
                    *(int*)(e + 0x18) = 1;
                    *(uint*)e = flags;
                }

                if (TurnSceneEntityTowardTarget(e, boldness * 2 + 0x80, heading)) e[0x43] = 0;
                *(int*)(e + 0x5c) = 0;
                return;

            // ---------------------------------------------------------- 2 : s'approcher
            case 2:
                if (*(ushort*)(e + 0x18) != 1)
                {
                    flags |= 0x1000000;
                    *(int*)(e + 0x18) = 1;
                    *(uint*)e = flags;
                }

                if (distance < *(short*)(e + 0x10))
                {
                    e[0x43] = 0;
                    return;
                }

                if (e[0x43] != 0) e[0x43]--;

                TurnSceneEntityTowardTarget(e, boldness * 2 + 0x80, heading);
                *(int*)(e + 0x5c) = (boldness + 0xc0) << 7;
                return;

            // ---------------------------------------------------------- 3 : marcher
            default:
            {
                if (e[0x43] != 0) e[0x43]--;

                if (*(ushort*)(e + 0x18) != 1)
                {
                    flags |= 0x1000000;
                    *(int*)(e + 0x18) = 1;
                    *(uint*)e = flags;
                }

                // La POSITION avance directement, sans passer par la vitesse — et sans le facteur
                // de vitesse que la sœur 0x0049a980 applique ici.
                int walk = (boldness + 0x80) << 7;
                *(int*)(e + 0x5c) = walk;

                int course = *(short*)(e + 0x10);
                *(int*)(e + 0x1c) += ((int)Winsys3d.GetSinTableEntry(course) * walk) >> 0xc;
                *(int*)(e + 0x24) += ((int)Winsys3d.GetCosTableEntry(course) * walk) >> 0xc;
                *(int*)(e + 0x5c) = 0;

                TurnSceneEntityTowardTarget(e, boldness * 4 + 0x32, heading);
                return;
            }
        }
    }

    /// <summary>
    /// Ghidra: <c>0x0049c628..0x0049c8c0</c> — <b>le troisieme temps</b> du Crabe geant : quelle
    /// posture prendre pour la suite.
    ///
    /// <para>
    /// <b>C'est celle de <see cref="TickSceneEntityAi_0049A980"/> a deux differences pres</b>, et
    /// les deux tiennent au fait que la ruee remplace le « foncer » : au corps a corps, une attaque
    /// refusee mene droit a l'hesitation, sans l'esquive de cote ni la charge que la sœur essaie
    /// avant d'y renoncer ; a l'approche, la sortie qui se tournait vers la cible LANCE LA RUEE —
    /// drapeau de geste, animation 4, posture 1 et le compte a trois temps arme a 2 dans
    /// <c>+0x10</c>.
    /// </para>
    /// <para>
    /// <b>Un chiffre de 1998 qui ne dit rien.</b> Le compte a rebours de la ruee vaut
    /// <c>(timidite &gt;&gt; 8) + 8</c>, et la timidite ne depasse jamais <c>0x40</c> : le decalage
    /// rend toujours zero, donc la duree est invariablement 8. Le <c>sar ecx,8</c> est bien dans le
    /// binaire — c'est vraisemblablement un <c>/2</c> ecrit trop grand, mais rien ne le prouve, et
    /// la transcription garde le calcul tel quel.
    /// </para>
    /// </summary>
    private static void ReplanLungingEntityAction_0049C0B0(byte* e, int boldness, int timid)
    {
        byte* chased = *(byte**)(e + 0x6c);

        int dx = (*(int*)(chased + 0x1c) - *(int*)(e + 0x1c)) >> 0xc;
        int dz = (*(int*)(chased + 0x24) - *(int*)(e + 0x24)) >> 0xc;

        int distance = (int)Winsys3d.Ordinal_442((uint)(dx * dx + dz * dz));
        int heading = (Winsys3d.Ordinal_457(dx, dz) - *(ushort*)(e + 0x32)) & 0xfff;

        // ================================================================ le corps a corps
        if (distance < 0xfa)
        {
            int roll = CrtRand() % 100;

            if (roll < 0x1e)
            {
                // La pince : dans le cone ET assez pres, la portee tiree s'elargissant avec la
                // timidite. Sinon on hesite — le crabe n'a pas d'esquive.
                if (((heading + timid * 4 + 0x100) & 0xfff) <= timid * 8 + 0x200
                    && distance < CrtRand() % (timid * 2 + 1) + 100)
                {
                    uint state = *(uint*)e;
                    *(int*)(e + 0x18) = 3;
                    e[0x42] = 0;
                    *(int*)(e + 0x5c) = 0;
                    *(uint*)e = (state & 0xfeffffff) | 2;
                    return;
                }

                HesitateSceneEntity(e);
                return;
            }

            if (roll < 0x3c)
            {
                HoldSceneEntityAtRange(e, timid, 0x64);
                return;
            }

            WanderSceneEntity(e, boldness, timid, heading, 0x800);
            return;
        }

        // ================================================================ l'approche
        if (distance < 0x1f4)
        {
            int roll = CrtRand() % 100;

            if (roll < 0x2d)
            {
                // La cible doit etre dans la moitie avant : on ne se rue pas sur ce qu'on a dans
                // le dos.
                if (((heading + 0x400) & 0xfff) >= 0x800)
                {
                    HesitateSceneEntity(e);
                    return;
                }

                // Ghidra: LAB_0049c795 — LA RUEE. Le geste s'arme ici ; la machine a trois temps
                // de la decision le deroule.
                uint state = *(uint*)e;
                *(int*)(e + 0x18) = 4;
                *(uint*)e = (state & 0xfeffffff) | 2;
                e[0x42] = 1;
                e[0x43] = (byte)((timid >> 8) + 8);
                *(ushort*)(e + 0x10) = 2;
                return;
            }

            if (roll < 0x46)
            {
                WanderSceneEntity(e, boldness, timid, heading, 0);
                return;
            }

            if (roll < 0x5a)
            {
                HoldSceneEntityAtRange(e, timid, 0x64);
                return;
            }

            RestSceneEntity(e, timid);
            return;
        }

        // ================================================================ l'errance
        int far = CrtRand() % 100;

        if (far < 0x1e)
        {
            RestSceneEntity(e, timid);
            return;
        }

        if (far < 0x3c)
        {
            HesitateSceneEntity(e);
            return;
        }

        // Ghidra: LAB_0049c899 — trop loin pour que la cible compte : le cap est entierement tire.
        e[0x42] = 3;
        e[0x43] = SceneEntityDelay(timid);
        *(ushort*)(e + 0x10) = (ushort)CrtRand();
    }

    // =============================================================================================
    // 0x0049B840 — LE GRIZZLY, sous-type 4 du bloc A de la foret. Transcrite le 2026-08-29 au
    // desassembleur (Legacy/Raw/Blaze/FUN_0049B840.asm, 2 141 octets de corps, absente de Blaze.c).
    //
    // C'EST LE JUMEAU DU CRABE, et le premier cas ou la recette « calquer sur une sœur de meme
    // milieu » a vraiment tenu de bout en bout : integration terrestre FUN_00488160, quatre postures
    // aiguillees par une table de sauts (0x0049c0a0), mesme decoupage des gestes sur +0x42, meme
    // machine a trois temps sur +0x10 pour le bond, et la meme division par deux de l'attaque du
    // bloc de modele autour de FUN_00539b80. Les quatre postures tenues sont identiques au mot pres.
    //
    // TROIS CHOSES LUI SONT PROPRES, ET ELLES CHANGENT LA SILHOUETTE :
    //
    //   - IL QUITTE LE SOL. La ou le crabe se rue a plat, le Grizzly pose une vitesse verticale de
    //     0x24000 et allume le bit 0 (« en l'air ») au moment de se lancer ; son geste ne se ferme
    //     donc PAS sur un compte a rebours mais a l'ATTERRISSAGE, quand ce bit retombe. Et il ecrit
    //     0x6000 dans +0x9a a chaque image, avant l'integration : c'est sa gravite propre, qu'aucune
    //     des six routines precedentes ne touche.
    //
    //   - SES GABARITS SONT DANS .data. Ses deux sondes ne sont pas construites sur la pile mais
    //     lues a 0x00552960 (la griffe) et 0x0055296c (le bond) — un cas que Comportement.md n'avait
    //     pas encore rencontre. La griffe porte `probe[4] = -0x100`, donc elle frappe EN HAUTEUR :
    //     une patte qui s'abat, la ou le bond frappe au ras du sol.
    //
    //   - SA GRIFFE SE CORRIGE EN COURS DE GESTE. Jusqu'a la neuvieme image elle continue de se
    //     tourner vers sa cible, a la neuvieme elle avance d'un a-coup, et elle balaie ensuite les
    //     images 10 a 13. Le crabe, lui, part droit et ne rectifie plus. C'est pour cela qu'un
    //     Grizzly rate beaucoup moins souvent.
    // =============================================================================================

    /// <summary>
    /// Ghidra: <c>0x00552960</c> et <c>0x0055296c</c> — <b>les deux gabarits de portee du
    /// Grizzly</b>, releves dans <c>.data</c> (<c>OpenForesia.Tools -- at</c>). C'est la premiere
    /// routine d'intelligence dont les sondes soient <b>statiques</b> : les six precedentes les
    /// construisaient sur la pile a chaque image.
    ///
    /// <para>
    /// Les six termes sont ceux de <see cref="TestMeleeReach_00535A90"/>, dans l'ordre de
    /// <see cref="s_MeleeProbes_00562cf0"/>. Le cinquieme est un <b>decalage vertical</b> : la
    /// griffe le porte a <c>-0x100</c> — elle s'abat d'en haut — quand le bond reste a zero.
    /// </para>
    /// <para>
    /// Trois entrees de la meme forme les precedent a <c>0x00552930</c>, <c>0x0055293c</c> et
    /// <c>0x00552948</c> ; elles appartiennent a une routine non encore transcrite et ne sont pas
    /// reprises ici. La suite immediate (<c>0x00552978</c>) n'a plus la forme d'une sonde, donc la
    /// paire du Grizzly s'arrete bien a deux entrees.
    /// </para>
    /// </summary>
    private static readonly short[] s_GrizzlyProbes_00552960 =
    [
        0x0000, 0x001e, 0x0046, 0x0096, unchecked((short)0xff00), 0x0050,   // 0x00552960 — la griffe
        0x0000, 0x001e, 0x0032, 0x0096, 0x0000, 0x0050,                     // 0x0055296c — le bond
    ];

    private static short* s_GrizzlyProbeStorage;

    /// <summary>Une des deux entrees de <see cref="s_GrizzlyProbes_00552960"/> en memoire native,
    /// puisque <see cref="SweepPartyForMeleeHit_00519C30"/> la recoit par pointeur.</summary>
    private static short* GrizzlyProbe(int row)
    {
        if (s_GrizzlyProbeStorage == null)
        {
            s_GrizzlyProbeStorage =
                (short*)NativeMemory.Alloc((nuint)s_GrizzlyProbes_00552960.Length, sizeof(short));

            for (int i = 0; i < s_GrizzlyProbes_00552960.Length; i++)
            {
                s_GrizzlyProbeStorage[i] = s_GrizzlyProbes_00552960[i];
            }
        }

        return s_GrizzlyProbeStorage + row * 6;
    }

    /// <summary>
    /// Ghidra: <c>0x0049b840</c> — <b>l'intelligence du Grizzly</b>, sous-type 4 de la table
    /// installee <c>0x0056ad48</c> en foret. Septieme gestionnaire d'entite de scene, sixieme
    /// routine d'intelligence.
    ///
    /// <para>
    /// <b>Quatre postures</b>, table de sauts a <c>0x0049c0a0</c> (<c>0x0049bed3</c>,
    /// <c>0x0049bf0c</c>, <c>0x0049bf6f</c>, <c>0x0049bff7</c>) : 0 attendre, 1 se tourner,
    /// 2 s'approcher, 3 marcher. Elles sont <b>identiques a celles du Crabe</b> — memes cones
    /// <c>hardiesse * 2 + 0x80</c>, meme distance tenue <c>0x64</c>, meme poussee
    /// <c>(hardiesse + 0xc0) &lt;&lt; 7</c>.
    /// </para>
    /// <para>
    /// <b>Le rappel au sol est ecrit ici, a chaque image</b> : <c>+0x9a = 0x6000</c> avant
    /// l'integration. C'est le terme que <see cref="IntegrateSceneEntityMotion_00488160"/> retranche
    /// de la vitesse verticale, donc la gravite que le Grizzly s'impose — et il l'impose meme quand
    /// sa vitesse est nulle, l'ecriture etant sur le chemin commun de sortie.
    /// </para>
    /// </summary>
    private static void TickSceneEntityAi_0049B840(byte* record)
    {
        byte* e = record;

        // Comme le Crabe, il lui faut le bloc de MODELE : son bond ampute l'attaque de moitie.
        ResolveEntityBlocks(e, out byte* stats, out _, out byte* model);

        int boldness, distance, heading, speed;
        uint traits;
        ReadSceneEntitySituation_00535F20(e, &boldness, &distance, &heading, &speed, &traits);

        int timid = 0x40 - boldness;

        // ---------------------------------------------------------------- 1. decider
        DecidePouncingEntityAction_0049B840(e, model, boldness, distance, heading, speed, traits);

        // ---------------------------------------------------------------- 2. appliquer
        // Ghidra: LAB_0049baa8 — sa gravite, reposee a chaque image et sur toutes les sorties.
        *(ushort*)(e + 0x9a) = 0x6000;

        IntegrateSceneEntityMotion_00488160(e, speed);
        FinalizeEntityPlacement2((uint*)e);
        EndSceneEntityAnimation_004DFAF0((uint*)e);
        InterruptSceneEntity_004E3770((uint*)e, stats);

        // ---------------------------------------------------------------- 3. replanifier
        if (speed == 0) return;
        if ((*(uint*)e & 0x817) != 0) return;
        if (e[0x43] != 0) return;

        ReplanPouncingEntityAction_0049B840(e, boldness, timid);
    }

    /// <summary>
    /// Ghidra: <c>0x0049b8a5..0x0049c098</c> — <b>le premier temps</b> du Grizzly.
    ///
    /// <para>
    /// <b>Deux gestes, comme le Crabe</b>, et lus au meme endroit : posture 0 c'est la griffe,
    /// posture 1 c'est le bond. Mais les deux different de ceux du Crabe sur un point chacun — la
    /// griffe <i>corrige son cap</i> pendant les neuf premieres images du geste, et le bond
    /// <i>quitte le sol</i> au lieu de glisser.
    /// </para>
    /// </summary>
    private static void DecidePouncingEntityAction_0049B840(
        byte* e, byte* model, int boldness, int distance, int heading, int speed, uint traits)
    {
        if (speed == 0) return;

        AdvanceEntityAnimation_004DB5A0((uint*)e);
        uint flags = *(uint*)e;

        // ================================================================ le geste en cours
        if ((flags & 2) != 0)
        {
            // Le trait 0x10 coupe court : l'espece ne poursuit pas son geste.
            if ((traits & 0x10) != 0)
            {
                e[0x43] = 0;
                *(uint*)e = flags & 0xfffffffd;
                return;
            }

            byte posture = e[0x42];

            // ------------------------------------------------------------ 0 : LA GRIFFE
            if (posture == 0)
            {
                // Ghidra: LAB_0049bd9b — tant que la patte n'est pas partie, la bete se replace.
                // Aucune des six routines precedentes ne rectifie son cap DANS un geste.
                short frame = *(short*)(e + 0x1a);
                if (frame < 9) TurnSceneEntityTowardTarget(e, (boldness >> 1) + 0x20, heading);

                // A la neuvieme image, l'a-coup en avant : la patte porte le corps avec elle.
                if (frame == 9)
                {
                    int lunge = (boldness + 0x300) << 7;
                    *(int*)(e + 0x5c) = lunge;

                    int course = *(short*)(e + 0x32);
                    *(int*)(e + 0x50) += ((int)Winsys3d.GetSinTableEntry(course) * lunge) >> 0xc;
                    *(int*)(e + 0x58) += ((int)Winsys3d.GetCosTableEntry(course) * lunge) >> 0xc;
                    *(int*)(e + 0x5c) = 0;
                }

                // Ghidra: LAB_0049be2d — quatre images de contact, sans verrou : une victime restee
                // dessous encaisse quatre fois, comme chez le Crabe. Degats PLEINS ici.
                short hitFrame = *(short*)(e + 0x1a);
                if (hitFrame >= 0x0a && hitFrame <= 0x0d)
                {
                    byte* victim = SweepPartyForMeleeHit_00519C30(e, (int*)(e + 0x1c), GrizzlyProbe(0), 0);

                    if (*Mem.Camera(0x005de0b8) != 0)
                    {
                        *(ushort*)(victim + 0x96) = 0x10;      // le clignotement de degat
                        *(uint*)victim |= 0x40;
                        ResolveMeleeHit_00539B80((uint*)e, (uint*)victim);
                        Aud.PlayPositionalSound(3, 0x300, 0x1800, (int*)(victim + 0x1c));
                    }
                }

                // Ghidra: LAB_0049be8e
                flags = *(uint*)e;
                if ((flags & 0x2000000) != 0)
                {
                    *(int*)(e + 0x5c) = 0;
                    *(uint*)e = flags & 0xfffffffd;
                    return;
                }

                *(int*)(e + 0x5c) = 0;                          // Ghidra: LAB_0049bf63
                return;
            }

            if (posture != 1) return;

            // ------------------------------------------------------------ 1 : LE BOND
            short phase = *(short*)(e + 0x10);

            // -------------------------------------------------------- 2 : s'accroupir et viser
            if (phase == 2)
            {
                int carried = *(int*)(e + 0x5c);
                *(int*)(e + 0x5c) = carried - (carried >> 4);

                if (*(short*)(e + 0x1a) == 0x0e) *(short*)(e + 0x10) = (short)(phase - 1);

                TurnSceneEntityTowardTarget(e, (boldness >> 2) + 0x20, heading);
                return;
            }

            // -------------------------------------------------------- 1 : detendre
            if (phase == 1)
            {
                // Ghidra: LAB_0049b923 — plus fort que la ruee du Crabe (0x380), et VERTICAL en
                // plus : le bit 0 dit « en l'air », et c'est sa retombee qui fermera le geste.
                int thrust = (boldness + 0x440) << 7;
                *(int*)(e + 0x5c) = thrust;

                int course = *(short*)(e + 0x32);
                *(int*)(e + 0x50) += ((int)Winsys3d.GetSinTableEntry(course) * thrust) >> 0xc;
                *(int*)(e + 0x58) += ((int)Winsys3d.GetCosTableEntry(course) * thrust) >> 0xc;
                *(int*)(e + 0x54) = 0x24000;
                *(uint*)e |= 1;

                *(short*)(e + 0x10) -= 1;
                *(int*)(e + 0x5c) = 0;
                return;
            }

            if (phase != 0) return;

            // -------------------------------------------------------- 0 : la chute et le contact
            // Ghidra: LAB_0049b981 — le geste ne se ferme QU'AU SOL. Le Crabe attendait un compte a
            // rebours ; ici c'est le bit 0 qui commande, donc un bond long tient plus longtemps.
            if ((flags & 0x2000000) != 0 && (flags & 1) == 0)
            {
                *(uint*)e = flags & 0xffffffdd;                 // le geste ET le verrou de coup
            }

            // Ghidra: LAB_0049b990 — le verrou : un bond ne touche qu'une fois.
            if ((*(uint*)e & 0x20) != 0) return;

            byte* prey = SweepPartyForMeleeHit_00519C30(e, (int*)(e + 0x1c), GrizzlyProbe(1), 0);
            if (prey != null) *(uint*)e |= 0x20;

            // Ghidra: LAB_0049b9b9
            if (*Mem.Camera(0x005de0b8) == 0) return;

            *(ushort*)(prey + 0x96) = 0x10;
            *(uint*)prey |= 0x40;

            // LA MOITIE, exactement comme le Crabe : l'attaque du bloc de MODELE est divisee le
            // temps de la resolution, puis remise. Deux routines voisines la partagent — c'est donc
            // un idiome de la famille, pas une singularite.
            short power = *(short*)(model + 0x30);
            *(short*)(model + 0x30) = (short)(power >> 1);
            ResolveMeleeHit_00539B80((uint*)e, (uint*)prey);
            *(short*)(model + 0x30) = power;

            Aud.PlayPositionalSound(3, 0x300, 0x1800, (int*)(prey + 0x1c));

            // Une victime que le coup vient d'emporter n'est pas projetee.
            if ((*(uint*)prey & 0x40000000) != 0) return;

            int impact = *(short*)(e + 0x32);
            *(int*)(prey + 0x50) = (int)Winsys3d.GetSinTableEntry(impact) * 30;
            *(int*)(prey + 0x58) = (int)Winsys3d.GetCosTableEntry(impact) * 30;

            uint preyFlags = *(uint*)prey;
            if ((preyFlags & 1) == 0)
            {
                *(int*)(prey + 0x54) = 0x18000;                 // et elle decolle
                *(uint*)prey = preyFlags | 1;
            }

            // Ghidra: LAB_0049ba5a — l'effet 0x39 au point d'impact, par le meme detour que le
            // Crabe : la bete se pose une image sur sa victime, puis reprend sa position.
            int savedX = *(int*)(e + 0x1c);
            int savedY = *(int*)(e + 0x20);
            int savedZ = *(int*)(e + 0x24);

            *(int*)(e + 0x1c) = *(int*)(prey + 0x1c);
            *(int*)(e + 0x20) = *(int*)(prey + 0x20);
            *(int*)(e + 0x24) = *(int*)(prey + 0x24);

            SpawnEffectEntity(e, 0x39, 0, -1);

            *(int*)(e + 0x1c) = savedX;
            *(int*)(e + 0x20) = savedY;
            *(int*)(e + 0x24) = savedZ;
            return;
        }

        // ================================================================ la posture tenue
        // Ghidra: LAB_0049beab — ni recul ni relance, comme le Crabe.
        if ((flags & 0x11) != 0) return;
        if ((flags & 0x804) != 0) return;

        byte stance = e[0x42];
        if (stance > 3) return;

        switch (stance)
        {
            // ---------------------------------------------------------- 0 : attendre
            case 0:
                if (*(ushort*)(e + 0x18) != 0)
                {
                    flags |= 0x1000000;
                    *(int*)(e + 0x18) = 0;
                    *(uint*)e = flags;
                }

                if (distance < 0x12c)
                {
                    e[0x43] = 0;
                    return;
                }

                if (e[0x43] != 0) e[0x43]--;
                *(int*)(e + 0x5c) = 0;
                return;

            // ---------------------------------------------------------- 1 : se tourner
            case 1:
                if (*(ushort*)(e + 0x18) != 1)
                {
                    flags |= 0x1000000;
                    *(int*)(e + 0x18) = 1;
                    *(uint*)e = flags;
                }

                if (TurnSceneEntityTowardTarget(e, boldness * 2 + 0x80, heading)) e[0x43] = 0;
                *(int*)(e + 0x5c) = 0;
                return;

            // ---------------------------------------------------------- 2 : s'approcher
            case 2:
                if (*(ushort*)(e + 0x18) != 1)
                {
                    flags |= 0x1000000;
                    *(int*)(e + 0x18) = 1;
                    *(uint*)e = flags;
                }

                if (distance < *(short*)(e + 0x10))
                {
                    e[0x43] = 0;
                    return;
                }

                if (e[0x43] != 0) e[0x43]--;

                TurnSceneEntityTowardTarget(e, boldness * 2 + 0x80, heading);
                *(int*)(e + 0x5c) = (boldness + 0xc0) << 7;
                return;

            // ---------------------------------------------------------- 3 : marcher
            default:
            {
                if (e[0x43] != 0) e[0x43]--;

                if (*(ushort*)(e + 0x18) != 1)
                {
                    flags |= 0x1000000;
                    *(int*)(e + 0x18) = 1;
                    *(uint*)e = flags;
                }

                int walk = (boldness + 0x80) << 7;
                *(int*)(e + 0x5c) = walk;

                int course = *(short*)(e + 0x10);
                *(int*)(e + 0x1c) += ((int)Winsys3d.GetSinTableEntry(course) * walk) >> 0xc;
                *(int*)(e + 0x24) += ((int)Winsys3d.GetCosTableEntry(course) * walk) >> 0xc;
                *(int*)(e + 0x5c) = 0;

                TurnSceneEntityTowardTarget(e, boldness * 4 + 0x32, heading);
                return;
            }
        }
    }

    /// <summary>
    /// Ghidra: <c>0x0049bb02..0x0049bd9a</c> — <b>le troisieme temps</b> du Grizzly.
    ///
    /// <para>
    /// <b>Il bondit depuis les DEUX plages utiles</b>, et c'est ce qui le distingue le plus a l'œil
    /// du Crabe. Au corps a corps, un tirage sur cent le fait griffer sous <c>0x32</c>, tenir sa
    /// distance sous <c>0x4b</c>, <b>bondir</b> entre <c>0x4b</c> et <c>0x59</c> s'il est dans le
    /// cone, et s'ecarter au-dela. A l'approche, la sortie qui se tournait vers la cible chez la
    /// famille terrestre bondit ici aussi.
    /// </para>
    /// <para>
    /// <b>Le bond ne pose aucun compte a rebours</b> — ni <c>+0x43</c>, ni remise a zero de la
    /// poussee. Il n'en a pas besoin : le geste vit tant que la bete est en l'air.
    /// </para>
    /// <para>
    /// L'errance lointaine n'a que deux sorties, contre trois chez toutes les precedentes : sous
    /// <c>0x32</c> il se repose, au-dela il part dans une direction entierement tiree. <b>Il
    /// n'hesite jamais de loin.</b>
    /// </para>
    /// </summary>
    private static void ReplanPouncingEntityAction_0049B840(byte* e, int boldness, int timid)
    {
        byte* chased = *(byte**)(e + 0x6c);

        int dx = (*(int*)(chased + 0x1c) - *(int*)(e + 0x1c)) >> 0xc;
        int dz = (*(int*)(chased + 0x24) - *(int*)(e + 0x24)) >> 0xc;

        int distance = (int)Winsys3d.Ordinal_442((uint)(dx * dx + dz * dz));
        int heading = (Winsys3d.Ordinal_457(dx, dz) - *(ushort*)(e + 0x32)) & 0xfff;

        // ================================================================ le corps a corps
        if (distance < 0xfa)
        {
            int roll = CrtRand() % 100;

            if (roll < 0x32)
            {
                if (((heading + timid * 4 + 0x100) & 0xfff) <= timid * 8 + 0x200
                    && distance < CrtRand() % (timid * 2 + 1) + 100)
                {
                    uint state = *(uint*)e;
                    *(int*)(e + 0x18) = 3;
                    e[0x42] = 0;
                    *(int*)(e + 0x5c) = 0;
                    *(uint*)e = (state & 0xfeffffff) | 2;
                    return;
                }

                HesitateSceneEntity(e);
                return;
            }

            if (roll < 0x4b)
            {
                HoldSceneEntityAtRange(e, timid, 0x64);
                return;
            }

            // Ghidra: LAB_0049bbd2 — le bond de pres, sur le meme cone que la griffe.
            if (roll < 0x5a && ((heading + timid * 4 + 0x100) & 0xfff) <= timid * 8 + 0x200)
            {
                PounceAt(e);
                return;
            }

            WanderSceneEntity(e, boldness, timid, heading, 0x800);
            return;
        }

        // ================================================================ l'approche
        if (distance < 0x1f4)
        {
            int roll = CrtRand() % 100;

            if (roll < 0x2d)
            {
                // On ne bondit pas sur ce qu'on a dans le dos.
                if (((heading + 0x400) & 0xfff) >= 0x800)
                {
                    HesitateSceneEntity(e);
                    return;
                }

                PounceAt(e);
                return;
            }

            if (roll < 0x46)
            {
                WanderSceneEntity(e, boldness, timid, heading, 0);
                return;
            }

            if (roll < 0x5a)
            {
                HoldSceneEntityAtRange(e, timid, 0x64);
                return;
            }

            RestSceneEntity(e, timid);
            return;
        }

        // ================================================================ l'errance
        if (CrtRand() % 100 < 0x32)
        {
            RestSceneEntity(e, timid);
            return;
        }

        // Ghidra: LAB_0049bd6f — trop loin pour que la cible compte : le cap est entierement tire.
        e[0x42] = 3;
        e[0x43] = SceneEntityDelay(timid);
        *(ushort*)(e + 0x10) = (ushort)CrtRand();
    }

    /// <summary>Ghidra: LAB_0049bc99 / LAB_0049bca4 — <b>armer le bond</b> : le drapeau de geste,
    /// l'animation 4, la posture 1 et la machine a trois temps mise a 2 dans <c>+0x10</c>. Les deux
    /// sites qui bondissent partagent ce corps, et ni l'un ni l'autre ne pose de compte a
    /// rebours.</summary>
    private static void PounceAt(byte* e)
    {
        *(uint*)e = (*(uint*)e & 0xfeffffff) | 2;
        *(int*)(e + 0x18) = 4;
        e[0x42] = 1;
        *(ushort*)(e + 0x10) = 2;
    }

    // =============================================================================================
    // 0x0049B220 — L'ABEILLE (et l'Abeille tueuse), sous-type 3 du bloc A de la foret. Transcrite
    // le 2026-08-29 au desassembleur (Legacy/Raw/Blaze/FUN_0049B220.asm, 1 542 octets de corps,
    // absente de Blaze.c).
    //
    // LE TRI A TROIS LECTURES L'A CLASSEE EN UNE MINUTE : elle appelle FUN_0049A8E0, l'integration
    // VOLANTE, et FUN_004A1CF0, l'interruption volante — c'est donc une sœur de la Coccinelle, pas
    // des quatre terrestres. Elle a une table de sauts (0x0049b828, quatre entrees) et sa sonde est
    // construite sur la pile.
    //
    // MAIS ELLE EST BATIE COMME UNE TERRESTRE. Son squelette est celui de FUN_0049A980 — quatre
    // postures, trois plages de replanification a 0xfa et 0x1f4, le meme cone hardiesse * 2 + 0x80,
    // la meme distance tenue 0x64, le meme SceneEntityDelay. La Coccinelle, elle, n'a que deux
    // plages, un delai qui lui est propre et un engagement sans animation. AUTREMENT DIT : « volante
    // ou terrestre » ne decide que de trois appels et du bloc de vol ; la charpente, elle, se choisit
    // independamment. C'est la premiere routine ou les deux axes se croisent.
    //
    // CE QUI LUI EST PROPRE : LA POSTURE 3 EST UN TRAIT, PAS UNE MARCHE.
    //
    //   +0x43 y sert de machine a deux temps au lieu de compte a rebours. A 2 l'abeille verse d'un
    //   coup (timidite + 0x120) << 8 dans ses vitesses, le long du cap range en +0x10 ; a 1 elle
    //   attend que cette vitesse soit retombee sous hardiesse/8 + 1 avant de rendre la main. Et a
    //   chaque image de cette posture elle ORIENTE son corps plein cap sur la cible, sans cone.
    //   C'est le vol d'insecte : des traits rectilignes separes par des arrets face a vous.
    //
    //   La poussee du trait se prend sur la TIMIDITE, pas sur la hardiesse — une abeille craintive
    //   file plus vite. Aucune autre routine ecrite ne fait cela ; verifie deux fois au
    //   desassembleur (edi vaut 0x40 - hardiesse depuis 0x0049b29a et n'est pas reecrit sur ce
    //   chemin) avant d'etre transcrit tel quel.
    //
    // ET SON COUP TIENT EN UNE IMAGE : la seizieme du geste, exactement. Ni les quatre images du
    // Crabe et du Grizzly, ni le balayage continu de la Coccinelle — un dard, une fois.
    // =============================================================================================

    /// <summary>
    /// Ghidra: <c>0x0049b220</c> — <b>l'intelligence de l'Abeille</b>, sous-type 3 de la table
    /// installee <c>0x0056ad48</c> en foret. Huitieme gestionnaire d'entite de scene, septieme
    /// routine d'intelligence, et <b>deuxieme bete volante</b>.
    ///
    /// <para>
    /// <b>Quatre postures</b>, table de sauts a <c>0x0049b828</c> (<c>0x0049b36b</c>,
    /// <c>0x0049b3ac</c>, <c>0x0049b420</c>, <c>0x0049b4a8</c>) : 0 attendre, 1 se tourner,
    /// 2 s'approcher, <b>3 filer en ligne droite</b>. Les trois premieres sont celles des
    /// terrestres, a ceci pres que la poussee y est <i>amortie</i> ou <i>montee par seiziemes</i>
    /// au lieu d'etre remise a zero — elle vole, elle ne pile pas.
    /// </para>
    /// <para>
    /// Sa sonde est <c>{0, 0x1e, 0x32, 0x64, 0, 0x50}</c>, exactement celle de la Fourmi geante
    /// <see cref="TickSceneEntityAi_0049A980"/> — et notamment <b>sans</b> le decalage vertical
    /// <c>-0x100</c> de la Coccinelle. Elle pique a hauteur d'homme.
    /// </para>
    /// <para>
    /// <b>Elle ne pose pas le bit 0 de ses drapeaux</b> a l'entree, la ou la Coccinelle le fait a
    /// chaque image. Son garde de posture n'en tient pas compte non plus : il teste <c>0x10</c> seul
    /// quand les terrestres testent <c>0x11</c>. Les deux choix vont ensemble.
    /// </para>
    /// </summary>
    private static void TickSceneEntityAi_0049B220(byte* record)
    {
        byte* e = record;

        ResolveEntityBlocks(e, out byte* stats, out _, out _);

        short* probe = stackalloc short[6];
        probe[0] = 0;
        probe[1] = 0x1e;
        probe[2] = 0x32;
        probe[3] = 0x64;
        probe[4] = 0;
        probe[5] = 0x50;

        int boldness, distance, heading, speed;
        uint traits;
        ReadSceneEntitySituation_00535F20(e, &boldness, &distance, &heading, &speed, &traits);

        int timid = 0x40 - boldness;

        // ---------------------------------------------------------------- 1. decider
        DecideDartingEntityAction_0049B220(e, probe, boldness, distance, heading, speed, timid, traits);

        // ---------------------------------------------------------------- 2. appliquer
        // La meme queue que la Coccinelle, bloc de vol compris : c'est le meme corps, emis deux
        // fois par le compilateur de 1998.
        IntegrateFlyingEntityMotion_0049A8E0(e, speed);
        FinalizeEntityPlacement2((uint*)e);
        BeatWings_0049A68F(e);
        InterruptFlyingEntity_004A1CF0((uint*)e, stats);

        // ---------------------------------------------------------------- 3. replanifier
        if (speed == 0) return;
        if ((*(uint*)e & 0x816) != 0) return;
        if (e[0x43] != 0) return;

        ReplanDartingEntityAction_0049B220(e, boldness, timid);
    }

    /// <summary>
    /// Ghidra: <c>0x0049b2a8..0x0049b549</c> — <b>le premier temps</b> de l'Abeille.
    ///
    /// <para>
    /// <b>Un seul geste, et un seul coup.</b> Contrairement au Crabe et au Grizzly, la posture n'est
    /// pas relue pendant le geste : il n'y a qu'une forme de frappe, et elle porte a la
    /// <b>seizieme</b> image, une seule fois. Aucun verrou n'est necessaire — l'egalite stricte sur
    /// <c>+0x1a</c> en tient lieu.
    /// </para>
    /// </summary>
    private static void DecideDartingEntityAction_0049B220(
        byte* e, short* probe, int boldness, int distance, int heading, int speed, int timid, uint traits)
    {
        if (speed == 0) return;

        AdvanceEntityAnimation_004DB5A0((uint*)e);
        uint flags = *(uint*)e;

        // ================================================================ le geste en cours
        if ((flags & 2) != 0)
        {
            // Le trait 0x10 coupe court : l'espece ne poursuit pas son geste.
            if ((traits & 0x10) != 0)
            {
                e[0x43] = 0;
                *(uint*)e = flags & 0xfffffffd;
                return;
            }

            // Ghidra: LAB_0049b2d5 — le dard, a la seizieme image et a elle seule. Le 0x10 compare
            // ici est le meme registre que le clignotement pose plus bas : le compilateur a garde
            // la constante dans ebx.
            if (*(short*)(e + 0x1a) == 0x10)
            {
                byte* victim = SweepPartyForMeleeHit_00519C30(e, (int*)(e + 0x1c), probe, 0);

                if (*Mem.Camera(0x005de0b8) != 0)
                {
                    *(ushort*)(victim + 0x96) = 0x10;      // le clignotement de degat
                    *(uint*)victim |= 0x40;
                    ResolveMeleeHit_00539B80((uint*)e, (uint*)victim);
                    Aud.PlayPositionalSound(3, 0x300, 0x1800, (int*)(victim + 0x1c));
                }
            }

            // Ghidra: LAB_0049b329 — la fin du geste libere aussi la replanification, puisque c'est
            // +0x43 qui la retient depuis l'engagement.
            flags = *(uint*)e;
            if ((flags & 0x2000000) != 0)
            {
                e[0x43] = 0;
                *(uint*)e = flags & 0xfffffffd;
            }

            return;
        }

        // ================================================================ la posture tenue
        // Ghidra: LAB_0049b343 — 0x10 seul, sans le bit 0 que les terrestres excluent aussi.
        if ((flags & 0x10) != 0) return;
        if ((flags & 0x804) != 0) return;

        byte stance = e[0x42];
        if (stance > 3) return;

        switch (stance)
        {
            // ---------------------------------------------------------- 0 : attendre
            case 0:
                if (*(ushort*)(e + 0x18) != 0)
                {
                    flags |= 0x1000000;
                    *(int*)(e + 0x18) = 0;
                    *(uint*)e = flags;
                }

                if (distance < 0x12c)
                {
                    e[0x43] = 0;
                    return;
                }

                if (e[0x43] != 0) e[0x43]--;
                DampFlyingEntityPush(e);
                return;

            // ---------------------------------------------------------- 1 : se tourner
            case 1:
                if (*(ushort*)(e + 0x18) != 1)
                {
                    flags |= 0x1000000;
                    *(int*)(e + 0x18) = 1;
                    *(uint*)e = flags;
                }

                if (TurnSceneEntityTowardTarget(e, boldness * 2 + 0x80, heading)) e[0x43] = 0;
                DampFlyingEntityPush(e);
                return;

            // ---------------------------------------------------------- 2 : s'approcher
            case 2:
                if (*(ushort*)(e + 0x18) != 1)
                {
                    flags |= 0x1000000;
                    *(int*)(e + 0x18) = 1;
                    *(uint*)e = flags;
                }

                if (distance < *(short*)(e + 0x10))
                {
                    e[0x43] = 0;
                    return;
                }

                if (e[0x43] != 0) e[0x43]--;

                TurnSceneEntityTowardTarget(e, boldness * 2 + 0x80, heading);
                RampFlyingEntityPush(e, (boldness + 0x200) << 7);
                return;

            // ---------------------------------------------------------- 3 : filer
            default:
            {
                if (*(ushort*)(e + 0x18) != 1)
                {
                    flags |= 0x1000000;
                    *(int*)(e + 0x18) = 1;
                    *(uint*)e = flags;
                }

                // Ghidra: LAB_0049b4bd — +0x43 n'est pas ici un compte a rebours mais une machine a
                // deux temps : 2 lance le trait, 1 attend qu'il soit retombe. Toute autre valeur ne
                // fait que l'orientation ci-dessous.
                byte phase = e[0x43];

                if (phase == 2)
                {
                    // La poussee se prend sur la TIMIDITE : une abeille craintive file plus vite.
                    // Le decalage est de huit bits et non de sept comme partout ailleurs.
                    int thrust = (timid + 0x120) << 8;
                    *(int*)(e + 0x5c) = thrust;

                    int course = *(short*)(e + 0x10);
                    *(int*)(e + 0x50) += ((int)Winsys3d.GetSinTableEntry(course) * thrust) >> 0xc;
                    *(int*)(e + 0x58) += ((int)Winsys3d.GetCosTableEntry(course) * thrust) >> 0xc;
                    *(int*)(e + 0x5c) = 0;

                    e[0x43]--;
                }
                else if (phase == 1)
                {
                    // Ghidra: LAB_0049b513 — le trait est fini quand la vitesse horizontale est
                    // retombee sous hardiesse/8 + 1. Une bete hardie repart donc plus tot.
                    int vx = *(int*)(e + 0x50) >> 0xc;
                    int vz = *(int*)(e + 0x58) >> 0xc;

                    if ((int)Winsys3d.Ordinal_442((uint)(vx * vx + vz * vz)) <= (boldness >> 3) + 1)
                    {
                        e[0x43] = 0;
                    }
                }

                // Ghidra: LAB_0049b541 — plein cap sur la cible, sans cone et a chaque image. C'est
                // ce qui donne l'arret face au joueur entre deux traits.
                *(ushort*)(e + 0x32) += (ushort)heading;
                return;
            }
        }
    }

    /// <summary>
    /// Ghidra: <c>0x0049b613..0x0049b81d</c> — <b>le troisieme temps</b> de l'Abeille.
    ///
    /// <para>
    /// <b>C'est la replanification des terrestres</b>, plages comprises : le corps a corps sous
    /// <c>0xfa</c>, l'approche sous <c>0x1f4</c>, l'errance au-dela, et le meme
    /// <see cref="SceneEntityDelay"/> pour le repos et la tenue de distance. La Coccinelle n'avait
    /// ni ces bornes ni ce delai.
    /// </para>
    /// <para>
    /// <b>Trois differences, toutes du meme cote.</b> Son engagement pose <c>+0x43 = 1</c> et laisse
    /// la posture telle quelle — le geste n'a pas de forme a choisir, et ce 1 sert seulement a
    /// retenir la replanification jusqu'a la fin de l'animation. Ses trois sorties d'errance posent
    /// <c>+0x43 = 2</c>, qui arme le trait au lieu de compter des images. Et elle n'a ni bond, ni
    /// recul, ni esquive.
    /// </para>
    /// </summary>
    private static void ReplanDartingEntityAction_0049B220(byte* e, int boldness, int timid)
    {
        byte* chased = *(byte**)(e + 0x6c);

        int dx = (*(int*)(chased + 0x1c) - *(int*)(e + 0x1c)) >> 0xc;
        int dz = (*(int*)(chased + 0x24) - *(int*)(e + 0x24)) >> 0xc;

        int distance = (int)Winsys3d.Ordinal_442((uint)(dx * dx + dz * dz));
        int heading = (Winsys3d.Ordinal_457(dx, dz) - *(ushort*)(e + 0x32)) & 0xfff;

        // ================================================================ le corps a corps
        if (distance < 0xfa)
        {
            int roll = CrtRand() % 100;

            if (roll < 0x1e)
            {
                if (((heading + timid * 4 + 0x100) & 0xfff) <= timid * 8 + 0x200
                    && distance < CrtRand() % (timid * 2 + 1) + 100)
                {
                    // Ghidra: 0x0049b6b7 — le dard. +0x42 n'est pas touche : il n'y a qu'un geste.
                    uint state = *(uint*)e;
                    *(int*)(e + 0x18) = 3;
                    e[0x43] = 1;
                    *(int*)(e + 0x5c) = 0;
                    *(uint*)e = (state & 0xfeffffff) | 2;
                    return;
                }

                HesitateSceneEntity(e);
                return;
            }

            if (roll < 0x3c)
            {
                HoldSceneEntityAtRange(e, timid, 0x64);
                return;
            }

            DartSceneEntity(e, boldness, heading, 0x800);
            return;
        }

        // ================================================================ l'approche
        if (distance < 0x1f4)
        {
            int roll = CrtRand() % 100;

            if (roll < 0x2d)
            {
                HesitateSceneEntity(e);
                return;
            }

            if (roll < 0x46)
            {
                DartSceneEntity(e, boldness, heading, 0);
                return;
            }

            if (roll < 0x5a)
            {
                HoldSceneEntityAtRange(e, timid, 0x64);
                return;
            }

            RestSceneEntity(e, timid);
            return;
        }

        // ================================================================ l'errance
        int far = CrtRand() % 100;

        if (far < 0x1e)
        {
            RestSceneEntity(e, timid);
            return;
        }

        if (far < 0x3c)
        {
            HesitateSceneEntity(e);
            return;
        }

        // Ghidra: LAB_0049b80d — trop loin pour que la cible compte : le cap est entierement tire,
        // mais le trait s'arme quand meme.
        e[0x42] = 3;
        e[0x43] = 2;
        *(ushort*)(e + 0x10) = (ushort)CrtRand();
    }

    /// <summary>
    /// Ghidra: LAB_0049b6e7 et LAB_0049b756 — <b>armer un trait</b> : posture 3, la machine a deux
    /// temps mise a 2, et un cap tire dans une fourchette large de <c>(hardiesse + 0x80) * 16</c>
    /// centree sur la cible.
    ///
    /// <para>C'est <see cref="WanderSceneEntity"/> avec un compte a rebours fixe a la place du
    /// delai tire : l'Abeille ne tient pas un cap pendant vingt images, elle file une fois et
    /// s'arrete. <paramref name="bias"/> vaut <c>0x800</c> au corps a corps — elle s'ecarte — et
    /// zero a l'approche.</para>
    /// </summary>
    private static void DartSceneEntity(byte* e, int boldness, int heading, int bias)
    {
        e[0x42] = 3;
        e[0x43] = 2;

        int spread = (boldness + 0x80) << 4;
        int offset = CrtRand() % spread - (spread >> 1);

        *(ushort*)(e + 0x10) = (ushort)(offset + heading + *(short*)(e + 0x32) + bias);
    }

    // =============================================================================================
    // 0x0049D030 — L'HOMME-LEZARD, sous-type 7 du bloc A de la foret. Transcrite le 2026-08-29 au
    // desassembleur (Legacy/Raw/Blaze/FUN_0049D030.asm, 2 546 octets de corps, absente de Blaze.c).
    //
    // LA PLUS RICHE DE LA FAMILLE, et la premiere a reunir tout ce que les sept precedentes avaient
    // chacune de leur cote : les CINQ postures de la Fourmi geante (0x0049a980), sa branche de
    // recul, sa relance d'attaque en fin de geste, son esquive de cote — ET les deux gestes du
    // Crabe et du Grizzly. Rien de neuf dans la charpente, tout dans la combinaison.
    //
    // SA CHARGE NE FAIT AUCUN DEGAT. C'est le fait le plus inattendu de la routine, et il est net
    // dans le binaire : FUN_00539b80 n'est appele qu'une seule fois dans les 2 546 octets, depuis le
    // geste de posture 0. Le geste de posture 1 — la course — croise pourtant le gabarit a chaque
    // image, mais tout ce qu'il fait d'une victime touchee c'est la faire clignoter, la projeter a
    // trente unites par image, la decoller du sol et poser l'effet 0x39. Elle BOUSCULE, elle ne
    // blesse pas.
    //
    // LA COURSE TOURNE EN BOUCLE. Des que l'animation depasse sa huitieme image, la routine la
    // REMET a 8 : le cycle de course se rejoue tant que la bete file. Elle ne s'arrete pas sur un
    // compte a rebours ni a l'atterrissage, mais quand sa vitesse horizontale — mesuree au
    // sqrt de FUN_00545a10 sur +0x50 et +0x58 — est retombee sous hardiesse/8 + 1. Une bete hardie
    // court donc moins longtemps, ce qui est l'inverse de l'intuition et se lit tel quel.
    //
    // ET ELLE A DEUX SONDES SUR LA PILE, ce qu'aucune des sept precedentes ne fait : le Grizzly
    // avait deux gabarits, mais dans .data. Ici les douze mots sont ecrits a la main dans le cadre,
    // en deux blocs de six, et les zeros du debut du corps (0x0049d033..0x0049d04b) en font partie.
    // =============================================================================================

    /// <summary>
    /// Ghidra: <c>0x0049d030</c> — <b>l'intelligence de l'Homme-lezard</b>, sous-type 7 de la table
    /// installee <c>0x0056ad48</c> en foret. Neuvieme gestionnaire d'entite de scene, huitieme
    /// routine d'intelligence.
    ///
    /// <para>
    /// <b>Cinq postures</b>, table de sauts a <c>0x0049da24</c> (<c>0x0049d42d</c>,
    /// <c>0x0049d466</c>, <c>0x0049d4bb</c>, <c>0x0049d543</c>, <c>0x0049d642</c>) : 0 attendre,
    /// 1 se tourner, 2 s'approcher, 3 marcher ou bondir, 4 foncer. C'est la charpente complete de
    /// <see cref="TickSceneEntityAi_0049A980"/>, branche de recul et relance comprises — la seule
    /// des huit routines ecrites a la reprendre entiere.
    /// </para>
    /// <para>
    /// <b>Deux sondes, toutes deux sur la pile</b> : <c>{0, 0x28, 0x32, 0x64, 0, 0x78}</c> pour le
    /// coup de posture 0 — la plus longue portee de la famille, <c>0x78</c> — et
    /// <c>{0, 0, 0x3c, 0x64, 0, 0x5a}</c> pour la course, plus courte et plus basse.
    /// </para>
    /// </summary>
    private static void TickSceneEntityAi_0049D030(byte* record)
    {
        byte* e = record;

        ResolveEntityBlocks(e, out byte* stats, out _, out _);

        // Ghidra: les deux gabarits occupent 0x18 octets contigus du cadre, et les quatre `mov
        // [esp+…],ax` du prologue sont les zeros de leurs termes 0, 4 et 1.
        short* strikeProbe = stackalloc short[6];
        strikeProbe[0] = 0;
        strikeProbe[1] = 0x28;
        strikeProbe[2] = 0x32;
        strikeProbe[3] = 0x64;
        strikeProbe[4] = 0;
        strikeProbe[5] = 0x78;

        short* rushProbe = stackalloc short[6];
        rushProbe[0] = 0;
        rushProbe[1] = 0;
        rushProbe[2] = 0x3c;
        rushProbe[3] = 0x64;
        rushProbe[4] = 0;
        rushProbe[5] = 0x5a;

        int boldness, distance, heading, speed;
        uint traits;
        ReadSceneEntitySituation_00535F20(e, &boldness, &distance, &heading, &speed, &traits);

        int timid = 0x40 - boldness;

        // ---------------------------------------------------------------- 1. decider
        DecideRushingEntityAction_0049D030(
            e, strikeProbe, rushProbe, boldness, distance, heading, speed, traits);

        // ---------------------------------------------------------------- 2. appliquer
        IntegrateSceneEntityMotion_00488160(e, speed);
        FinalizeEntityPlacement2((uint*)e);
        EndSceneEntityAnimation_004DFAF0((uint*)e);
        InterruptSceneEntity_004E3770((uint*)e, stats);

        // ---------------------------------------------------------------- 3. replanifier
        if (speed == 0) return;
        if ((*(uint*)e & 0x817) != 0) return;
        if (e[0x43] != 0) return;

        ReplanRushingEntityAction_0049D030(e, boldness, timid);
    }

    /// <summary>
    /// Ghidra: <c>0x0049d0e7..0x0049d69e</c> — <b>le premier temps</b> de l'Homme-lezard.
    ///
    /// <para>
    /// <b>Deux gestes, lus sur la posture</b> comme chez le Crabe et le Grizzly : posture 0 c'est le
    /// coup — il se replace jusqu'a la treizieme image, avance d'un a-coup a la treizieme, et balaie
    /// les images 14 a 16 ; posture 1 c'est la course, qui bouscule sans blesser.
    /// </para>
    /// <para>
    /// <b>Le bit 0 retient le coup.</b> Si la bete est en l'air quand son geste atteint sa fenetre
    /// de contact, l'image d'animation <b>recule</b> d'un cran au lieu d'avancer : le coup attend
    /// qu'elle ait touche terre. Le meme motif existe chez <see cref="TickSceneEntityAi_0049A980"/>,
    /// et il prend ici tout son sens puisque sa posture 3 peut bondir.
    /// </para>
    /// </summary>
    private static void DecideRushingEntityAction_0049D030(
        byte* e, short* strikeProbe, short* rushProbe,
        int boldness, int distance, int heading, int speed, uint traits)
    {
        if (speed == 0) return;

        AdvanceEntityAnimation_004DB5A0((uint*)e);
        uint flags = *(uint*)e;

        // ================================================================ le geste en cours
        if ((flags & 2) != 0)
        {
            // Le trait 0x10 coupe court : l'espece ne poursuit pas son geste.
            if ((traits & 0x10) != 0)
            {
                e[0x43] = 0;
                *(uint*)e = flags & 0xfffffffd;
                return;
            }

            byte posture = e[0x42];

            // ------------------------------------------------------------ 0 : LE COUP
            if (posture == 0)
            {
                // Ghidra: LAB_0049d29e — trois images de contact, sans verrou.
                short frame = *(short*)(e + 0x1a);

                if (frame >= 0x0e && frame <= 0x10)
                {
                    byte* victim =
                        SweepPartyForMeleeHit_00519C30(e, (int*)(e + 0x1c), strikeProbe, 0);

                    if (*Mem.Camera(0x005de0b8) != 0)
                    {
                        *(uint*)victim |= 0x40;
                        *(ushort*)(victim + 0x96) = 0x10;      // le clignotement de degat
                        ResolveMeleeHit_00539B80((uint*)e, (uint*)victim);
                        Aud.PlayPositionalSound(3, 0x300, 0x1800, (int*)(victim + 0x1c));
                    }

                    // En l'air, le geste ne progresse pas : l'image recule d'un cran et le coup
                    // sera rejoue a la prochaine.
                    flags = *(uint*)e;
                    if ((flags & 1) != 0)
                    {
                        *(short*)(e + 0x1a) -= 1;
                        return;
                    }
                }
                else if ((flags & 1) != 0)
                {
                    return;
                }

                // Ghidra: LAB_0049d310 — au sol seulement.
                short ground = *(short*)(e + 0x1a);

                if (ground < 0x0d) TurnSceneEntityTowardTarget(e, boldness + 0x20, heading);

                if (ground == 0x0d)
                {
                    // L'a-coup en avant, a la treizieme image : le corps suit la griffe.
                    int lunge = (boldness + 0x280) << 7;
                    *(int*)(e + 0x5c) = lunge;

                    int course = *(short*)(e + 0x32);
                    *(int*)(e + 0x50) += ((int)Winsys3d.GetSinTableEntry(course) * lunge) >> 0xc;
                    *(int*)(e + 0x58) += ((int)Winsys3d.GetCosTableEntry(course) * lunge) >> 0xc;
                    *(int*)(e + 0x5c) = 0;
                }

                // Ghidra: LAB_0049d39a
                flags = *(uint*)e;
                if ((flags & 0x2000000) != 0) *(uint*)e = flags & 0xfffffffd;
                return;
            }

            if (posture != 1) return;

            // ------------------------------------------------------------ 1 : LA COURSE
            // La vitesse horizontale mene tout ce bloc : elle decide de la fin de la course et de
            // la capacite a bousculer.
            int vx = *(int*)(e + 0x50) >> 0xc;
            int vz = *(int*)(e + 0x58) >> 0xc;
            int rush = (int)Winsys3d.Ordinal_442((uint)(vx * vx + vz * vz));

            if (*(short*)(e + 0x1a) > 8)
            {
                // Le cycle de course se rejoue : l'image est ramenee a 8 tant que la bete file.
                *(short*)(e + 0x1a) = 8;

                if (rush <= (boldness >> 3) + 1)
                {
                    *(uint*)e = *(uint*)e & 0xfffffffd;
                    return;
                }
            }

            // Ghidra: LAB_0049d167 — bousculer demande d'etre lance : passe la troisieme image du
            // geste, et au-dessus de six unites de vitesse.
            if (*(short*)(e + 0x1a) > 3 && rush >= 6)
            {
                byte* prey = SweepPartyForMeleeHit_00519C30(e, (int*)(e + 0x1c), rushProbe, 0);

                if (*Mem.Camera(0x005de0b8) != 0)
                {
                    *(uint*)prey |= 0x40;
                    *(ushort*)(prey + 0x96) = 0x10;
                    Aud.PlayPositionalSound(3, 0x300, 0x1800, (int*)(prey + 0x1c));

                    // ET C'EST TOUT : pas de FUN_00539b80 ici. La course projette et renverse,
                    // elle ne resout aucun coup.
                    int impact = *(short*)(e + 0x32);
                    *(int*)(prey + 0x50) = (int)Winsys3d.GetSinTableEntry(impact) * 30;
                    *(int*)(prey + 0x58) = (int)Winsys3d.GetCosTableEntry(impact) * 30;

                    uint preyFlags = *(uint*)prey;
                    if ((preyFlags & 1) == 0)
                    {
                        *(int*)(prey + 0x54) = 0x18000;         // et elle decolle
                        *(uint*)prey = preyFlags | 1;
                    }

                    // Ghidra: LAB_0049d200 — l'effet 0x39 au point d'impact, par le meme detour que
                    // le Crabe et le Grizzly.
                    int savedX = *(int*)(e + 0x1c);
                    int savedY = *(int*)(e + 0x20);
                    int savedZ = *(int*)(e + 0x24);

                    *(int*)(e + 0x1c) = *(int*)(prey + 0x1c);
                    *(int*)(e + 0x20) = *(int*)(prey + 0x20);
                    *(int*)(e + 0x24) = *(int*)(prey + 0x24);

                    SpawnEffectEntity(e, 0x39, 0, -1);

                    *(int*)(e + 0x1c) = savedX;
                    *(int*)(e + 0x20) = savedY;
                    *(int*)(e + 0x24) = savedZ;
                }
            }

            // Ghidra: LAB_0049d24d / LAB_0049d251 — le lancement n'a lieu qu'a la troisieme image.
            if (*(short*)(e + 0x1a) != 3)
            {
                *(int*)(e + 0x5c) = 0;                          // Ghidra: LAB_0049d698
                return;
            }

            // La plus forte poussee de toutes les routines ecrites — 0x360 contre 0x380 pour la
            // ruee du Crabe, mais versee dans les vitesses SANS composante verticale : il court, il
            // ne bondit pas.
            int drive = (boldness + 0x360) << 7;
            *(int*)(e + 0x5c) = drive;

            int bearing = *(short*)(e + 0x32);
            *(int*)(e + 0x50) += ((int)Winsys3d.GetSinTableEntry(bearing) * drive) >> 0xc;
            *(int*)(e + 0x58) += ((int)Winsys3d.GetCosTableEntry(bearing) * drive) >> 0xc;

            *(int*)(e + 0x5c) = 0;                              // Ghidra: LAB_0049d698
            return;
        }

        // ================================================================ le recul
        // Ghidra: LAB_0049d3b0 — la branche que le Crabe, le Grizzly et l'Abeille n'ont pas : la
        // bete encaisse et se tourne vers ce qui l'a touchee.
        if ((flags & 0x10) != 0)
        {
            if ((flags & 0x2000000) != 0 && e[0x43] != 0)
            {
                e[0x43]--;
                if (e[0x43] == 0)
                {
                    flags &= 0xffffffef;
                    *(uint*)e = flags;
                }
            }

            TurnSceneEntityTowardTarget(e, boldness + 0x40, heading);
            return;
        }

        // ================================================================ la posture tenue
        if ((flags & 0x804) != 0) return;

        if ((flags & 1) != 0)
        {
            // Ghidra: LAB_0049d3e4 — la relance : une chance sur cent par quart de hardiesse de
            // repartir sur un coup des que le geste precedent est fini.
            if (CrtRand() % 100 >= (boldness >> 2)) return;

            uint state = *(uint*)e;
            *(int*)(e + 0x18) = 3;
            e[0x42] = 0;
            *(uint*)e = (state & 0xfeffffff) | 2;
            return;
        }

        // Ghidra: LAB_0049d418 — cinq postures, table de sauts 0x0049da24.
        byte stance = e[0x42];
        if (stance > 4) return;

        switch (stance)
        {
            // ---------------------------------------------------------- 0 : attendre
            case 0:
                if (*(ushort*)(e + 0x18) != 0)
                {
                    flags |= 0x1000000;
                    *(int*)(e + 0x18) = 0;
                    *(uint*)e = flags;
                }

                if (distance < 0x12c)
                {
                    e[0x43] = 0;
                    return;
                }

                if (e[0x43] != 0) e[0x43]--;
                *(int*)(e + 0x5c) = 0;
                return;

            // ---------------------------------------------------------- 1 : se tourner
            case 1:
                if (*(ushort*)(e + 0x18) != 1)
                {
                    flags |= 0x1000000;
                    *(int*)(e + 0x18) = 1;
                    *(uint*)e = flags;
                }

                if (TurnSceneEntityTowardTarget(e, boldness * 2 + 0x80, heading)) e[0x43] = 0;
                *(int*)(e + 0x5c) = 0;
                return;

            // ---------------------------------------------------------- 2 : s'approcher
            case 2:
                if (*(ushort*)(e + 0x18) != 1)
                {
                    flags |= 0x1000000;
                    *(int*)(e + 0x18) = 1;
                    *(uint*)e = flags;
                }

                if (distance < *(short*)(e + 0x10))
                {
                    e[0x43] = 0;
                    return;
                }

                if (e[0x43] != 0) e[0x43]--;

                TurnSceneEntityTowardTarget(e, boldness * 2 + 0x80, heading);
                *(int*)(e + 0x5c) = (boldness + 0x100) << 7;
                return;

            // ---------------------------------------------------------- 3 : marcher ou bondir
            case 3:
            {
                if (e[0x43] != 0) e[0x43]--;

                if (*(ushort*)(e + 0x18) != 1)
                {
                    flags |= 0x1000000;
                    *(int*)(e + 0x18) = 1;
                    *(uint*)e = flags;
                }

                // Le bond est deux fois plus rare que chez la Fourmi geante — un seizieme de la
                // hardiesse et non un huitieme — mais il pousse plus fort et monte plus haut.
                if (CrtRand() % 100 < (boldness >> 4))
                {
                    int leap = (boldness + 0x140) << 7;
                    *(int*)(e + 0x5c) = leap;

                    int course = *(short*)(e + 0x10);
                    *(int*)(e + 0x50) += ((int)Winsys3d.GetSinTableEntry(course) * leap) >> 0xc;
                    *(int*)(e + 0x58) += ((int)Winsys3d.GetCosTableEntry(course) * leap) >> 0xc;
                    *(int*)(e + 0x54) = 0x14000;
                    *(uint*)e |= 1;
                    return;
                }

                // La marche : la POSITION avance directement, sans facteur de vitesse.
                int walk = (boldness + 0xc0) << 7;
                *(int*)(e + 0x5c) = walk;

                int walkCourse = *(short*)(e + 0x10);
                *(int*)(e + 0x1c) += ((int)Winsys3d.GetSinTableEntry(walkCourse) * walk) >> 0xc;
                *(int*)(e + 0x24) += ((int)Winsys3d.GetCosTableEntry(walkCourse) * walk) >> 0xc;
                *(int*)(e + 0x5c) = 0;

                TurnSceneEntityTowardTarget(e, boldness * 4 + 0x32, heading);
                return;
            }

            // ---------------------------------------------------------- 4 : foncer
            default:
            {
                flags = (flags & 0xfeffffff) | 1;
                *(int*)(e + 0x18) = 5;
                *(uint*)e = flags;

                // La seule posture qui ECRASE la vitesse au lieu de s'y ajouter, et la seule ou le
                // pas passe par la vitesse rendue par la lecture de situation.
                int thrust = (boldness + 0x280) << 7;
                int step = (speed * thrust) >> 0xc;
                *(int*)(e + 0x5c) = thrust;

                int course = *(short*)(e + 0x10);
                *(int*)(e + 0x50) = ((int)Winsys3d.GetSinTableEntry(course) * step) >> 0xc;
                *(int*)(e + 0x58) = ((int)Winsys3d.GetCosTableEntry(course) * step) >> 0xc;
                *(int*)(e + 0x54) = 0x1c000;

                *(int*)(e + 0x5c) = 0;                          // Ghidra: LAB_0049d698
                return;
            }
        }
    }

    /// <summary>
    /// Ghidra: <c>0x0049d6f0..0x0049da19</c> — <b>le troisieme temps</b> de l'Homme-lezard.
    ///
    /// <para>
    /// <b>C'est la replanification de <see cref="TickSceneEntityAi_0049A980"/> au complet</b>,
    /// esquive de cote comprise, avec quatre nombres changes et une sortie de plus :
    /// </para>
    /// <list type="bullet">
    /// <item>il tente son coup dans la moitie des tirages au corps a corps, et non dans trois
    /// dixiemes ;</item>
    /// <item>sa portee tiree part de <b><c>0xc8</c></b> et non de 100 — c'est la plus longue allonge
    /// de la famille, et elle va avec sa sonde a <c>0x78</c> ;</item>
    /// <item>l'esquive envoie l'animation 4 au lieu de 5 ;</item>
    /// <item>entre <c>0x46</c> et <c>0x59</c>, une sortie que la Fourmi geante n'a pas :
    /// <b>la course</b>, armee si la cible est dans le cone.</item>
    /// </list>
    /// </summary>
    private static void ReplanRushingEntityAction_0049D030(byte* e, int boldness, int timid)
    {
        byte* chased = *(byte**)(e + 0x6c);

        int dx = (*(int*)(chased + 0x1c) - *(int*)(e + 0x1c)) >> 0xc;
        int dz = (*(int*)(chased + 0x24) - *(int*)(e + 0x24)) >> 0xc;

        int distance = (int)Winsys3d.Ordinal_442((uint)(dx * dx + dz * dz));
        int heading = (Winsys3d.Ordinal_457(dx, dz) - *(ushort*)(e + 0x32)) & 0xfff;

        // ================================================================ le corps a corps
        if (distance < 0xfa)
        {
            int roll = CrtRand() % 100;

            if (roll < 0x32)
            {
                if (((heading + timid * 4 + 0x100) & 0xfff) <= timid * 8 + 0x200
                    && distance < CrtRand() % (timid * 2 + 1) + 0xc8)
                {
                    uint state = *(uint*)e;
                    *(int*)(e + 0x18) = 3;
                    e[0x42] = 0;
                    *(int*)(e + 0x5c) = 0;
                    *(uint*)e = (state & 0xfeffffff) | 2;
                    return;
                }

                // Ghidra: LAB_0049d7ba — l'esquive de cote, dans un cone deux fois plus large.
                if (((heading + timid * 4 + 0x200) & 0xfff) > timid * 8 + 0x400
                    || CrtRand() % 100 >= (timid >> 1) + 0x20)
                {
                    HesitateSceneEntity(e);
                    return;
                }

                uint dodge = *(uint*)e;
                *(int*)(e + 0x18) = 4;
                *(uint*)e = (dodge & 0xfeffffff) | 0x10;
                *(int*)(e + 0x5c) = 0;
                e[0x43] = (byte)(CrtRand() % 5 + 10);
                return;
            }

            // Ghidra: LAB_0049d82a — foncer, mais seulement s'il reste de la place devant.
            if (roll < 0x46 && distance > boldness + 0x64)
            {
                e[0x42] = 4;
                e[0x43] = 1;
                *(ushort*)(e + 0x10) = (ushort)CrtRand();
                return;
            }

            // Ghidra: LAB_0049d857 — LA COURSE, la sortie que la Fourmi geante n'a pas.
            if (roll < 0x5a && ((heading + timid * 4 + 0x100) & 0xfff) <= timid * 8 + 0x200)
            {
                uint state = *(uint*)e;
                *(int*)(e + 0x18) = 4;
                e[0x42] = 1;
                *(uint*)e = (state & 0xfeffffff) | 2;
                return;
            }

            WanderSceneEntity(e, boldness, timid, heading, 0x800);
            return;
        }

        // ================================================================ l'approche
        if (distance < 0x1f4)
        {
            int roll = CrtRand() % 100;

            if (roll < 0x2d)
            {
                HesitateSceneEntity(e);
                return;
            }

            if (roll < 0x46)
            {
                WanderSceneEntity(e, boldness, timid, heading, 0);
                return;
            }

            if (roll < 0x5a)
            {
                HoldSceneEntityAtRange(e, timid, 0x64);
                return;
            }

            RestSceneEntity(e, timid);
            return;
        }

        // ================================================================ l'errance
        int far = CrtRand() % 100;

        if (far < 0x1e)
        {
            RestSceneEntity(e, timid);
            return;
        }

        if (far < 0x3c)
        {
            HesitateSceneEntity(e);
            return;
        }

        // Ghidra: LAB_0049d9f2 — trop loin pour que la cible compte : le cap est entierement tire.
        e[0x42] = 3;
        e[0x43] = SceneEntityDelay(timid);
        *(ushort*)(e + 0x10) = (ushort)CrtRand();
    }

    // =============================================================================================
    // 0x0049DA40 — LE GOBLIN, sous-type 8 du bloc A de la foret. Transcrite le 2026-08-29 au
    // desassembleur (Legacy/Raw/Blaze/FUN_0049DA40.asm, 1 841 octets de corps, absente de Blaze.c).
    //
    // C'EST LA PREMIERE BETE QUI ATTAQUE DE LOIN. Ses deux gestes ne se ressemblent en rien :
    //
    //   - posture 0 en geste, LE COUP : un seul balayage du gabarit, a la neuvieme image.
    //   - posture 1 en geste, LE JET : aucun balayage. A la septieme image elle fait naitre
    //     l'effet 0x49 et n'en fait plus rien. C'est le projectile qui portera le coup, pas elle.
    //
    // Et sa replanification le lui fait lancer depuis les DEUX plages lointaines — l'approche, mais
    // aussi l'errance jusqu'a 0x2bc, ou aucune des huit routines precedentes ne fait autre chose que
    // marcher. Un goblin vous vise de l'autre bout de la clairiere.
    //
    // LA CHANCE DE VISER SE PREND SUR LA HARDIESSE ET NON SUR UN SEUIL FIXE : hardiesse / 2 + 8
    // sur cent, aux deux plages. C'est le seul tirage de la famille dont le seuil bouge avec l'etat
    // de la bete plutot qu'avec sa timidite.
    // =============================================================================================

    /// <summary>
    /// Ghidra: <c>0x0049da40</c> — <b>l'intelligence du Goblin</b>, sous-type 8 de la table
    /// installee <c>0x0056ad48</c> en foret. Dixieme gestionnaire d'entite de scene, neuvieme
    /// routine d'intelligence.
    ///
    /// <para>
    /// <b>Cinq postures</b>, table de sauts a <c>0x0049e174</c> (<c>0x0049dc14</c>,
    /// <c>0x0049dc4c</c>, <c>0x0049dc8c</c>, <c>0x0049dd14</c>, <c>0x0049ddb5</c>) : 0 attendre,
    /// 1 se tourner, 2 s'approcher, 3 marcher, 4 foncer. Comme la Fourmi geante et l'Homme-lezard,
    /// mais <b>sans branche de recul</b> : le bit <c>0x10</c> la renvoie directement a
    /// l'application.
    /// </para>
    /// <para>
    /// Sa sonde est <c>{0, 0x1e, 0x32, 0x64, 0, 0x46}</c> — la plus courte portee de la famille
    /// apres celle du Poisson volant. Elle va avec une bete qui prefere lancer.
    /// </para>
    /// <para>
    /// <b>Sa marche et son « foncer » tiennent compte de la vitesse</b> rendue par la lecture de
    /// situation, la ou le Crabe, le Grizzly et l'Homme-lezard l'ignorent dans leur marche. Le
    /// facteur est bien dans les deux corps.
    /// </para>
    /// </summary>
    private static void TickSceneEntityAi_0049DA40(byte* record)
    {
        byte* e = record;

        ResolveEntityBlocks(e, out byte* stats, out _, out _);

        short* probe = stackalloc short[6];
        probe[0] = 0;
        probe[1] = 0x1e;
        probe[2] = 0x32;
        probe[3] = 0x64;
        probe[4] = 0;
        probe[5] = 0x46;

        int boldness, distance, heading, speed;
        uint traits;
        ReadSceneEntitySituation_00535F20(e, &boldness, &distance, &heading, &speed, &traits);

        int timid = 0x40 - boldness;

        // ---------------------------------------------------------------- 1. decider
        DecideThrowingEntityAction_0049DA40(e, probe, boldness, distance, heading, speed, traits);

        // ---------------------------------------------------------------- 2. appliquer
        IntegrateSceneEntityMotion_00488160(e, speed);
        FinalizeEntityPlacement2((uint*)e);
        EndSceneEntityAnimation_004DFAF0((uint*)e);
        InterruptSceneEntity_004E3770((uint*)e, stats);

        // ---------------------------------------------------------------- 3. replanifier
        if (speed == 0) return;
        if ((*(uint*)e & 0x817) != 0) return;
        if (e[0x43] != 0) return;

        ReplanThrowingEntityAction_0049DA40(e, boldness, timid);
    }

    /// <summary>
    /// Ghidra: <c>0x0049dacd..0x0049de1b</c> — <b>le premier temps</b> du Goblin.
    ///
    /// <para>
    /// <b>Le jet ne touche personne.</b> La posture 1 en geste ne croise aucun gabarit : elle fait
    /// naitre l'effet <c>0x49</c> a la septieme image et rend la main. Tout ce qui suit — la
    /// trajectoire, la portee, le coup — appartient au projectile.
    /// </para>
    /// <para>
    /// <b>Le bit 0 retient le coup</b>, comme chez <see cref="TickSceneEntityAi_0049D030"/> : en
    /// l'air, l'image d'animation recule d'un cran au lieu d'avancer. Le jet, lui, n'a pas ce
    /// garde.
    /// </para>
    /// </summary>
    private static void DecideThrowingEntityAction_0049DA40(
        byte* e, short* probe, int boldness, int distance, int heading, int speed, uint traits)
    {
        if (speed == 0) return;

        AdvanceEntityAnimation_004DB5A0((uint*)e);
        uint flags = *(uint*)e;

        // ================================================================ le geste en cours
        if ((flags & 2) != 0)
        {
            // Le trait 0x10 coupe court : l'espece ne poursuit pas son geste.
            if ((traits & 0x10) != 0)
            {
                e[0x43] = 0;
                *(uint*)e = flags & 0xfffffffd;
                return;
            }

            byte posture = e[0x42];

            // ------------------------------------------------------------ 0 : LE COUP
            if (posture == 0)
            {
                if (*(short*)(e + 0x1a) == 9)
                {
                    byte* victim = SweepPartyForMeleeHit_00519C30(e, (int*)(e + 0x1c), probe, 0);

                    if (*Mem.Camera(0x005de0b8) != 0)
                    {
                        ResolveMeleeHit_00539B80((uint*)e, (uint*)victim);
                        *(uint*)victim |= 0x40;
                        *(ushort*)(victim + 0x96) = 0x10;      // le clignotement de degat
                        Aud.PlayPositionalSound(3, 0x300, 0x1800, (int*)(victim + 0x1c));
                    }

                    // En l'air, le geste ne progresse pas : l'image recule et le coup sera rejoue.
                    flags = *(uint*)e;
                    if ((flags & 1) != 0)
                    {
                        *(short*)(e + 0x1a) -= 1;
                        return;
                    }
                }
                else if ((flags & 1) != 0)
                {
                    return;
                }

                // Ghidra: LAB_0049db9b
                if ((flags & 0x2000000) != 0) *(uint*)e = flags & 0xfffffffd;

                *(int*)(e + 0x5c) = 0;                          // Ghidra: LAB_0049de19
                return;
            }

            if (posture != 1) return;

            // ------------------------------------------------------------ 1 : LE JET
            // Ghidra: 0x0049db0a — l'effet 0x49 nait a la septieme image, et c'est tout ce que la
            // bete fait de son geste. Aucun gabarit n'est croise ici.
            if (*(short*)(e + 0x1a) == 7)
            {
                SpawnEffectEntity(e, 0x49, 0, -1);
            }

            flags = *(uint*)e;
            if ((flags & 0x2000000) != 0) *(uint*)e = flags & 0xfffffffd;
            return;
        }

        // ================================================================ la posture tenue
        // Ghidra: LAB_0049dbaf — pas de branche de recul : le bit 0x10 renvoie a l'application.
        if ((flags & 0x10) != 0) return;
        if ((flags & 0x804) != 0) return;

        if ((flags & 1) != 0)
        {
            // La relance : une chance sur cent par quart de hardiesse de repartir sur un coup.
            if (CrtRand() % 100 >= (boldness >> 2)) return;

            uint state = *(uint*)e;
            *(int*)(e + 0x18) = 3;
            e[0x42] = 0;
            *(uint*)e = (state & 0xfeffffff) | 2;
            *(int*)(e + 0x5c) = 0;                              // Ghidra: LAB_0049de19
            return;
        }

        // Ghidra: LAB_0049dbff — cinq postures, table de sauts 0x0049e174.
        byte stance = e[0x42];
        if (stance > 4) return;

        switch (stance)
        {
            // ---------------------------------------------------------- 0 : attendre
            case 0:
                if (*(ushort*)(e + 0x18) != 0)
                {
                    flags |= 0x1000000;
                    *(int*)(e + 0x18) = 0;
                    *(uint*)e = flags;
                }

                if (distance < 0x12c)
                {
                    e[0x43] = 0;
                    return;
                }

                if (e[0x43] != 0) e[0x43]--;
                *(int*)(e + 0x5c) = 0;
                return;

            // ---------------------------------------------------------- 1 : se tourner
            case 1:
                if (*(ushort*)(e + 0x18) != 1)
                {
                    flags |= 0x1000000;
                    *(int*)(e + 0x18) = 1;
                    *(uint*)e = flags;
                }

                if (TurnSceneEntityTowardTarget(e, boldness * 2 + 0x80, heading)) e[0x43] = 0;
                *(int*)(e + 0x5c) = 0;
                return;

            // ---------------------------------------------------------- 2 : s'approcher
            case 2:
                if (*(ushort*)(e + 0x18) != 1)
                {
                    flags |= 0x1000000;
                    *(int*)(e + 0x18) = 1;
                    *(uint*)e = flags;
                }

                if (distance < *(short*)(e + 0x10))
                {
                    e[0x43] = 0;
                    return;
                }

                if (e[0x43] != 0) e[0x43]--;

                TurnSceneEntityTowardTarget(e, boldness * 2 + 0x80, heading);
                *(int*)(e + 0x5c) = (boldness + 0xc0) << 7;
                return;

            // ---------------------------------------------------------- 3 : marcher
            case 3:
            {
                if (e[0x43] != 0) e[0x43]--;

                if (*(ushort*)(e + 0x18) != 1)
                {
                    flags |= 0x1000000;
                    *(int*)(e + 0x18) = 1;
                    *(uint*)e = flags;
                }

                int walk = (boldness + 0x80) << 7;
                int step = (speed * walk) >> 0xc;
                *(int*)(e + 0x5c) = walk;

                int course = *(short*)(e + 0x10);
                *(int*)(e + 0x1c) += ((int)Winsys3d.GetSinTableEntry(course) * step) >> 0xc;
                *(int*)(e + 0x24) += ((int)Winsys3d.GetCosTableEntry(course) * step) >> 0xc;

                TurnSceneEntityTowardTarget(e, boldness * 4 + 0x32, heading);
                *(int*)(e + 0x5c) = 0;                          // Ghidra: LAB_0049de19
                return;
            }

            // ---------------------------------------------------------- 4 : foncer
            default:
            {
                flags = (flags & 0xfeffffff) | 1;
                *(int*)(e + 0x18) = 4;
                *(uint*)e = flags;

                // Elle S'AJOUTE a sa vitesse au lieu de l'ecraser, contrairement au « foncer » de
                // la Fourmi geante et de l'Homme-lezard, et sa detente verticale s'ajoute aussi.
                int thrust = (boldness + 0xc0) << 7;
                int step = (speed * thrust) >> 0xc;
                *(int*)(e + 0x5c) = thrust;

                int course = *(short*)(e + 0x10);
                *(int*)(e + 0x50) += ((int)Winsys3d.GetSinTableEntry(course) * step) >> 0xc;
                *(int*)(e + 0x58) += ((int)Winsys3d.GetCosTableEntry(course) * step) >> 0xc;
                *(int*)(e + 0x54) += 0x19000;

                *(int*)(e + 0x5c) = 0;                          // Ghidra: LAB_0049de19
                return;
            }
        }
    }

    /// <summary>
    /// Ghidra: <c>0x0049de6d..0x0049e168</c> — <b>le troisieme temps</b> du Goblin.
    ///
    /// <para>
    /// <b>Le jet a deux portes, et ce sont les deux plages lointaines.</b> A l'approche comme dans
    /// l'errance, un tirage de <c>hardiesse / 2 + 8</c> sur cent l'arme — c'est le seul seuil de la
    /// famille qui monte avec la hardiesse au lieu de descendre avec la timidite. De loin il faut
    /// en plus etre a moins de <c>0x2bc</c> et dans le cone ; a l'approche, il suffit d'avoir la
    /// cible dans la moitie avant.
    /// </para>
    /// <para>
    /// Le reste est la replanification ordinaire des terrestres, avec le corps a corps de
    /// <see cref="TickSceneEntityAi_0049A980"/> mais <b>sans son esquive de cote</b> : une attaque
    /// refusee mene droit a l'hesitation.
    /// </para>
    /// </summary>
    private static void ReplanThrowingEntityAction_0049DA40(byte* e, int boldness, int timid)
    {
        byte* chased = *(byte**)(e + 0x6c);

        int dx = (*(int*)(chased + 0x1c) - *(int*)(e + 0x1c)) >> 0xc;
        int dz = (*(int*)(chased + 0x24) - *(int*)(e + 0x24)) >> 0xc;

        int distance = (int)Winsys3d.Ordinal_442((uint)(dx * dx + dz * dz));
        int heading = (Winsys3d.Ordinal_457(dx, dz) - *(ushort*)(e + 0x32)) & 0xfff;

        // ================================================================ le corps a corps
        if (distance < 0xfa)
        {
            int roll = CrtRand() % 100;

            if (roll < 0x2d)
            {
                if (((heading + timid * 4 + 0x100) & 0xfff) <= timid * 8 + 0x200
                    && distance < CrtRand() % (timid * 2 + 1) + 100)
                {
                    uint state = *(uint*)e;
                    *(int*)(e + 0x18) = 3;
                    e[0x42] = 0;
                    *(int*)(e + 0x5c) = 0;
                    *(uint*)e = (state & 0xfeffffff) | 2;
                    return;
                }

                HesitateSceneEntity(e);
                return;
            }

            if (roll < 0x3c)
            {
                HoldSceneEntityAtRange(e, timid, 0x64);
                return;
            }

            if (roll < 0x4b && distance > boldness + 0x64)
            {
                e[0x42] = 4;                                    // foncer
                *(ushort*)(e + 0x10) = (ushort)CrtRand();
                return;
            }

            WanderSceneEntity(e, boldness, timid, heading, 0x800);
            return;
        }

        // ================================================================ l'approche
        if (distance < 0x1f4)
        {
            int roll = CrtRand() % 100;

            if (roll < (boldness >> 1) + 8)
            {
                // On ne lance pas sur ce qu'on a dans le dos.
                if (((heading + 0x400) & 0xfff) >= 0x800)
                {
                    HesitateSceneEntity(e);
                    return;
                }

                ThrowAt(e);
                return;
            }

            if (roll < 0x46)
            {
                WanderSceneEntity(e, boldness, timid, heading, 0);
                return;
            }

            if (roll < 0x5a)
            {
                HoldSceneEntityAtRange(e, timid, 0x64);
                return;
            }

            RestSceneEntity(e, timid);
            return;
        }

        // ================================================================ l'errance
        int far = CrtRand() % 100;

        if (far < (boldness >> 1) + 8)
        {
            // Ghidra: LAB_0049e0b4 — de loin, le jet demande une portee ET un cone.
            if (distance >= 0x2bc
                || ((heading + timid * 4 + 0x100) & 0xfff) > timid * 8 + 0x200)
            {
                HesitateSceneEntity(e);
                return;
            }

            ThrowAt(e);
            return;
        }

        if (far < 0x3c)
        {
            RestSceneEntity(e, timid);
            return;
        }

        // Ghidra: LAB_0049e141 — trop loin pour viser : le cap est entierement tire.
        e[0x42] = 3;
        e[0x43] = SceneEntityDelay(timid);
        *(ushort*)(e + 0x10) = (ushort)CrtRand();
    }

    /// <summary>Ghidra: LAB_0049e0eb et son entree de LAB_0049dfff — <b>armer le jet</b> : le
    /// drapeau de geste, l'animation 3 et la posture 1, qui fera naitre le projectile a la septieme
    /// image. Aucun compte a rebours : c'est la fin de l'animation qui rend la main.</summary>
    private static void ThrowAt(byte* e)
    {
        *(uint*)e = (*(uint*)e & 0xfeffffff) | 2;
        *(int*)(e + 0x18) = 3;
        e[0x42] = 1;
        *(int*)(e + 0x5c) = 0;
    }

    /// <summary>
    /// Ghidra: FUN_0047aa70 @ 0x0047aa70 — la passe sur la table <c>DAT_005ff400</c>, 0x20
    /// enregistrements. Elle ne raccroche <b>rien</b> a la grille spatiale : c'est la seule des six
    /// dans ce cas, donc ces entites ne sont pas cherchees par proximite.
    /// </summary>
    private static void TickEntityTable_005ff400()
    {
        byte* record = Mem.Entity(0x005ff400);

        for (int i = 0; i < 0x20; i++, record += 0x9c)
        {
            if ((*(uint*)record & 0x80000000) == 0) continue;

            if ((*(uint*)record & 0x4000008) == 0)
            {
                CallIndexedEntityHandler(
                    0x00551c30, 0x0056adc8, record[5], record,
                    $"FUN_0047aa70, table 0x005ff400 entree {i}");
            }

            // Le mot d'etat est RELU : le gestionnaire a pu eteindre l'entite lui-meme.
            if ((*(uint*)record & 0x80000000) == 0)
            {
                FreeEntitySlot(Mem.Entity(0x005fa5a0), record[8]);
            }
        }
    }

    /// <summary>
    /// Ghidra: FUN_0047ab70 @ 0x0047ab70 — la passe sur la table <c>DAT_005edee0</c>, 0x80
    /// enregistrements.
    /// </summary>
    private static void TickEntityTable_005edee0()
    {
        byte* mainMem = GetMainMemPtr();
        byte* record = Mem.Entity(0x005edee0);

        for (int i = 0; i < 0x80; i++, record += 0x9c)
        {
            if ((*(uint*)record & 0x80000000) == 0) continue;

            if ((*(uint*)record & 0x4000008) == 0)
            {
                record[0x36] &= 0x7f;
                CallIndexedEntityHandler(
                    0x00551f30, 0x0056aec8, record[5], record,
                    $"FUN_0047ab70, table 0x005edee0 entree {i}");
            }

            if ((*(uint*)record & 0x80000000) == 0)
            {
                FreeEntitySlot(Mem.Entity(0x006007a0), record[8]);
            }
            else
            {
                LinkIntoWorldGrid(mainMem, 0x1c5000, record);
            }
        }
    }

    /// <summary>
    /// Ghidra: FUN_0047acf0 @ 0x0047acf0 — la passe sur la table <c>DAT_005f2d40</c>, 0x80
    /// enregistrements. Copie conforme de <see cref="TickEntityTable_005edee0"/> a trois adresses
    /// pres — la table, son pool et sa table de sauts. Les deux sont ecrites separement plutot que
    /// factorisees : ce sont deux fonctions distinctes du binaire, et l'oracle compare des corps.
    /// </summary>
    private static void TickEntityTable_005f2d40()
    {
