    // ---------------------------------------------------------------------------------------------
    // Les verbes 23 a 25 rappellent la camera libre. Les trois blocs qu'ils lisent sont ceux que la
    // carte du monde utilise hors scenette, et ce sont les memes que `BeginScriptedCamera` avait
    // debranches en leur substituant ses copies de travail :
    //
    //     DAT_005e9ae0 -> &DAT_00564650   les trois angles      (shorts)
    //     DAT_005edebc -> &DAT_005de068   la position           (ints)
    //     DAT_005eca94 -> &DAT_005de078   la cible              (ints)
    //
    // Un verbe 23/24/25 remet donc la consigne correspondante sur la valeur de la camera libre :
    // c'est le « reviens ou tu etais » du scenariste, composante par composante.
    // ---------------------------------------------------------------------------------------------

    /// <summary>
    /// Ghidra: verbe 23 @ 0x00504170 — <b>consigne d'angles = ceux de la camera libre</b>
    /// (<c>DAT_00564650</c>, trois <c>short</c>). Un seul octet : le verbe n'a pas d'operande.
    /// </summary>
    private static byte* CutsceneVerb23_00504170(byte* cursor)
    {
        short* free = (short*)s_WorldMapCamera_00564650;
        short* goal = (short*)Mem.EntityStateBytes(0x005719f0);
        goal[0] = free[0];
        goal[1] = free[1];
        goal[2] = free[2];
        return cursor + 1;
    }

    /// <summary>
    /// Ghidra: verbe 24 @ 0x005041a0 — <b>consigne de position = celle de la camera libre</b>
    /// (<c>DAT_005de068</c>, trois <c>int</c>). Sans operande.
    /// </summary>
    private static byte* CutsceneVerb24_005041A0(byte* cursor)
    {
        int* goal = Mem.EntityState(0x005719f8);
        goal[0] = *Mem.Camera(0x005de068);
        goal[1] = *Mem.Camera(0x005de06c);
        goal[2] = *Mem.Camera(0x005de070);
        return cursor + 1;
    }

    /// <summary>
    /// Ghidra: verbe 25 @ 0x005041d0 — <b>consigne de cible = celle de la camera libre</b>
    /// (<c>DAT_005de078</c>, trois <c>int</c>). Sans operande.
    /// </summary>
    private static byte* CutsceneVerb25_005041D0(byte* cursor)
    {
        int* goal = Mem.EntityState(0x00571a28);
        goal[0] = *Mem.Camera(0x005de078);
        goal[1] = *Mem.Camera(0x005de07c);
        goal[2] = *Mem.Camera(0x005de080);
        return cursor + 1;
    }

    /// <summary>
    /// Ghidra: verbe 26 @ 0x00504200 — <b>le mouvement inverse des trois precedents</b> : il verse
    /// l'etat courant de la scenette <b>dans</b> les blocs de la camera libre, de sorte que la
    /// sortie de scenette ne fasse pas sauter l'image.
    ///
    /// <list type="bullet">
    ///   <item>les trois angles de travail (<c>DAT_005719e8</c>) vers <c>DAT_00564650</c> ;</item>
    ///   <item>la cible de travail (<c>DAT_00571a08</c>) <b>moins</b> <c>DAT_005de088</c> vers
    ///         <c>DAT_00564658</c>.</item>
    /// </list>
    ///
    /// <para>La soustraction n'est pas gratuite : <c>FUN_00516350</c> fait le chemin dans l'autre
    /// sens — <c>DAT_005de078 = DAT_00564658 + DAT_005de088</c>, apres avoir amorti
    /// <c>DAT_00564658</c> d'un huitieme a chaque image. <c>DAT_00564658</c> est donc un
    /// <b>ecart</b> par rapport a <c>DAT_005de088</c>, et pas une position ; le verbe le reconstitue
    /// dans la bonne unite pour que l'amortissement reprenne sans discontinuite.</para>
    ///
    /// <para>Sans operande, comme les trois precedents.</para>
    /// </summary>
    private static byte* CutsceneVerb26_00504200(byte* cursor)
    {
        short* viewWork = (short*)Mem.EntityStateBytes(0x005719e8);
        short* free = (short*)s_WorldMapCamera_00564650;
        free[0] = viewWork[0];
        free[1] = viewWork[1];
        free[2] = viewWork[2];

        int* targetWork = Mem.EntityState(0x00571a08);
        int* slide = (int*)(s_WorldMapCamera_00564650 + 8);
        slide[0] = targetWork[0] - *Mem.Camera(0x005de088);
        slide[1] = targetWork[1] - *Mem.Camera(0x005de08c);
        slide[2] = targetWork[2] - *Mem.Camera(0x005de090);

        return cursor + 1;
    }

    /// <summary>
    /// Ghidra: verbe 27 @ 0x00504270 — <b>pose des bits dans le mot de scenette</b>. Il lit
    /// l'octet qui suit l'indice et l'ajoute par <c>ou</c> a <c>DAT_00604b78</c>, puis avance de
    /// deux. Il ne touche pas a <c>continuer</c> : le verbe suivant part dans le meme appel.
    ///
    /// <para>L'original travaille <b>sur un octet</b> (<c>mov dl,[604B78h]</c> … <c>or dl,cl</c>) ;
    /// comme l'operande est lui-meme un octet, le resultat sur le mot complet est identique et
    /// l'ecriture ci-dessous est fidele.</para>
    ///
    /// <para>Le bit 0 est celui que <c>BeginScriptedCamera</c> pose et que l'echappement du joueur
    /// teste plus haut : ce verbe est donc, entre autres, le « rends la main au joueur » du
    /// scenariste.</para>
    /// </summary>
    private static byte* CutsceneVerb27_00504270(byte* cursor)
    {
        Saves.s_CutsceneActive_00604b78 |= cursor[1];
        return cursor + 2;
    }

    /// <summary>
    /// Ghidra: verbe 28 @ 0x00504290 — <b>l'exact contraire du verbe 27</b> : il <c>et-non</c>
    /// l'octet <c>+1</c> dans <c>DAT_00604b78</c> au lieu de l'y ajouter par <c>ou</c>, et avance
    /// lui aussi de deux. Meme remarque sur la largeur : l'original travaille sur l'octet bas, et
    /// comme le complement d'un octet laisse les bits hauts a un, l'ecriture sur le mot entier est
    /// fidele.
    /// </summary>
    private static byte* CutsceneVerb28_00504290(byte* cursor)
    {
        Saves.s_CutsceneActive_00604b78 &= ~cursor[1];
        return cursor + 2;
    }

    /// <summary>
    /// Ghidra: verbe 29 @ 0x005042b0 — <b>secousse d'angles</b>. Deux amplitudes de 16 bits lues
    /// dans le script ; pour chacune, <c>CrtRand() % (2 * amplitude) - amplitude</c> est
    /// <b>ajoute</b> a la consigne d'angles. C'est le tremblement de camera, tire a neuf a chaque
    /// passage du verbe.
    ///
    /// <para>Une amplitude nulle est <b>remontee a un</b> avant la division, ce qui evite le
    /// division-par-zero et donne un tirage constamment nul — le verbe reste donc inoffensif si le
    /// scenario ecrit un zero.</para>
    ///
    /// <para><b>Le diviseur et le recentrage n'ont pas la meme signature.</b> L'original divise par
    /// <c>movsx ecx,di</c> — l'amplitude <b>signee</b> sur 16 bits — puis retranche <c>edi</c>, qui
    /// est la meme amplitude <b>non signee</b>. Les deux ne coincident que sous 0x8000 ; transcrit
    /// tel quel plutot que normalise.</para>
    /// </summary>
    private static byte* CutsceneVerb29_005042B0(byte* cursor)
    {
        int rangeA = cursor[1] | (cursor[2] << 8);
        int rangeB = cursor[3] | (cursor[4] << 8);
        if ((ushort)rangeA == 0) rangeA = 1;
        if ((ushort)rangeB == 0) rangeB = 1;

        short* goal = (short*)Mem.EntityStateBytes(0x005719f0);
        goal[0] += (short)(CrtRand() % ((short)rangeA * 2) - rangeA);
        goal[1] += (short)(CrtRand() % ((short)rangeB * 2) - rangeB);

        return cursor + 5;
    }

    /// <summary>
    /// Ghidra: verbe 30 @ 0x00504310 — <b>secousse de position</b>, le verbe 29 porte a trois
    /// composantes et applique a la consigne de position, avec le decalage de douze bits qui est la
    /// convention de ce bloc. Meme remontee des amplitudes nulles a un, meme melange d'amplitude
    /// signee au diviseur et non signee au recentrage.
    /// </summary>
    private static byte* CutsceneVerb30_00504310(byte* cursor)
    {
        int rangeX = cursor[1] | (cursor[2] << 8);
        int rangeY = cursor[3] | (cursor[4] << 8);
        int rangeZ = cursor[5] | (cursor[6] << 8);
        if ((ushort)rangeX == 0) rangeX = 1;
        if ((ushort)rangeY == 0) rangeY = 1;
        if ((ushort)rangeZ == 0) rangeZ = 1;

        int* goal = Mem.EntityState(0x005719f8);
        goal[0] += (CrtRand() % ((short)rangeX * 2) - rangeX) << 12;
        goal[1] += (CrtRand() % ((short)rangeY * 2) - rangeY) << 12;
        goal[2] += (CrtRand() % ((short)rangeZ * 2) - rangeZ) << 12;

        return cursor + 7;
    }

    /// <summary>
    /// Ghidra: verbe 31 @ 0x005043c0 — <b>secousse de cible</b>, le troisieme du triptyque
    /// 29/30/31 : meme tirage <c>CrtRand() % (2 * amplitude) - amplitude</c> sur trois composantes,
    /// applique cette fois a la consigne de cible <c>DAT_00571a28</c>, et sans decalage — la meme
    /// difference d'echelle qui separe deja les verbes 18 et 19.
    ///
    /// <para><b>L'ecart de 0x8c0 octets jusqu'a l'entree suivante de la table ne mesure rien</b> :
    /// le verbe se termine des <c>0x0050445d</c>, et le code qui suit (a partir de
    /// <c>0x00504460</c>, une initialisation qui alloue huit tampons et ouvre un fichier) n'a rien
    /// a voir avec lui. Un ecart entre deux entrees d'une table de pointeurs n'est pas une taille.</para>
    /// </summary>
    private static byte* CutsceneVerb31_005043C0(byte* cursor)
    {
        int rangeX = cursor[1] | (cursor[2] << 8);
        int rangeY = cursor[3] | (cursor[4] << 8);
        int rangeZ = cursor[5] | (cursor[6] << 8);
        if ((ushort)rangeX == 0) rangeX = 1;
        if ((ushort)rangeY == 0) rangeY = 1;
        if ((ushort)rangeZ == 0) rangeZ = 1;

        int* goal = Mem.EntityState(0x00571a28);
        goal[0] += CrtRand() % ((short)rangeX * 2) - rangeX;
        goal[1] += CrtRand() % ((short)rangeY * 2) - rangeY;
        goal[2] += CrtRand() % ((short)rangeZ * 2) - rangeZ;

        return cursor + 7;
    }

    // =====================================================================
    // FUN_0050bf20 — LE PAS PAR PERSONNAGE
    //
    // 1 002 lignes de pseudo-C, 8 Ko de code, appelees une fois par membre du groupe et par image.
    // C'est le plus gros corps que le depot ait transcrit, et **la pseudo-C seule n'y suffit pas** :
    // Ghidra y perd trois registres et tout un bloc de calcul. Les quatre points ci-dessous ont ete
    // tranches au desassembleur avant d'ecrire une ligne, et ils valent pour toute fonction de
    // cette taille.
    //
    // **`iStack_4`, jamais affecte dans la pseudo-C, est `[esp+68h]`** — et `[esp+68h]` est
    // l'emplacement du PARAMETRE, que le prologue ecrase (`mov [esp+68h],eax` en 0x0050bf52) avec
    // `&DAT_005e9180 + membre * 0x4c`, l'entree d'emplacement. Confirme en 0x0050ce71 :
    // `mov edi,[esp+68h] ; movsx ebx,word [edi+44h]` est exactement le `*(short *)(iStack_4 + 0x44)`
    // de la pseudo-C. C'est donc le `puVar11` que Ghidra nomme correctement ailleurs dans la meme
    // fonction : **le meme objet sous deux noms**, l'un des deux perdu.
    //
    // **`unaff_EBP` est le bloc par personnage** (`MainMem + 0xf0000 + membre * 0x2000`), pose en
    // 0x0050bf61 et sauve en `[esp+10h]`. C'est le `iVar23` de la pseudo-C ; Ghidra le perd parce
    // que 0x0050cee9 (`mov ebp,[esi+78h]`) reutilise le registre en cours de route.
    //
    // **`unaff_EBX` est l'etat de manette** (`&DAT_00604a20 + slotKind * 0x10`), pose en 0x0050bf63
    // et sauve en `[esp+14h]`. C'est le `puVar21`.
    //
    // **Le bloc de matrices de 0x0050cfb1..0x0050d290** est rendu par Ghidra comme une cascade de
    // `__allmul`/`__allshr` dont les resultats sont perdus, ce qui le rend illisible. Au
    // desassembleur c'est deux produits matrice-vecteur parfaitement reguliers, decalage `>> 12`
    // (le `mov ecx,0Ch` de 0x0050d02f et de ses cinq jumeaux). Voir
    // <see cref="ComputeCarrierOffset"/>.
    // =====================================================================

    /// <summary>
    /// Ghidra: <c>&amp;DAT_00562cc0</c> — huit entiers releves dans le binaire
    /// (<c>at Legacy/Binaries/Blaze.exe 0x00562cc0 32</c>), indexes par les trois bits bas de
    /// <c>bloc + 0x150</c>, la posture. C'est la <b>vitesse de deplacement</b> de cette posture.
    ///
    /// <para>
    /// <b>Le role n'a ete etabli qu'avec le deuxieme lecteur.</b> Vu de
    /// <see cref="TickFollowingMember"/> seul, la table ressemblait a une portee de detection ; vu
    /// de <see cref="HandleDirectionalInput_0050E140"/>, qui la decale de 12 bits pour en faire
    /// directement la vitesse du personnage, c'est une vitesse. Les deux se recoupent : le membre
    /// suivi s'arrete a une distance egale a un pas de son meneur, quelle que soit la posture.
    /// </para>
    /// </summary>
    private static readonly int[] s_PostureSpeed_00562cc0 =
        [0x13, 0x13, 0x15, 0x12, 0x14, 0x14, 0x12, 0x15];

    /// <summary>
    /// Ghidra: <c>&amp;DAT_00562dc8</c> — seize octets releves dans le binaire, juste apres la table
    /// de pas sonores. Indexes par le <b>quartet haut</b> de <c>manette[0]</c>, c'est-a-dire la
    /// croix directionnelle : ils rendent un <b>secteur sur huit</b>, ou zero quand la direction
    /// est nulle ou contradictoire.
    ///
    /// <para>
    /// Le contenu se lit tout seul une fois qu'on remarque que les quatre bits sont haut, droite,
    /// bas, gauche dans cet ordre : <c>1→1</c>, <c>3→2</c>, <c>2→3</c>, <c>6→4</c>, <c>4→5</c>,
    /// <c>12→6</c>, <c>8→7</c>, <c>9→8</c> — les huit secteurs dans le sens horaire, diagonales
    /// comprises. Les deux paires opposees (<c>5</c> = haut+bas, <c>10</c> = gauche+droite) et
    /// toutes les combinaisons de trois touches rendent zero : elles s'annulent, et c'est ce zero
    /// qui fait retomber le personnage a l'arret.
    /// </para>
    /// </summary>
    private static readonly sbyte[] s_PadDirection_00562dc8 =
        [0, 1, 3, 2, 5, 0, 4, 0, 7, 8, 0, 0, 6, 0, 0, 0];

    /// <summary>
    /// Ghidra: <c>&amp;PTR_FUN_00562ca0</c> — huit gestionnaires de posture, releves dans le binaire.
    /// <b>Quatre d'entre eux sont <c>0x0040A600</c></b>, le corps vide deja verifie au
    /// desassembleur, donc seules les postures 0, 4, 6 et 7 font quelque chose.
    /// </summary>
    private static readonly uint[] s_PostureHandlers_00562ca0 =
        [0x0051A670, 0x0040A600, 0x0040A600, 0x0040A600, 0x0051A6B0, 0x0040A600, 0x0051A700, 0x0051A710];

    /// <summary>
    /// Ghidra: <c>&amp;PTR_FUN_00562ce0</c> — quatre gestionnaires de commande, releves dans le
    /// binaire. Aucun n'est le corps vide.
    /// </summary>
    private static readonly uint[] s_InputHandlers_00562ce0 =
        [0x0050E140, 0x0050DE90, 0x0050DD00, 0x0050DFF0];

    /// <summary>Ghidra: DAT_005de708 — l'index de membre que le declenchement du repartiteur
    /// <c>DAT_005e9ae4</c> met de cote, en meme temps que <c>DAT_005de540</c>. Hors du bloc de
    /// camera (qui s'arrete a 0x005de100), donc declare a part.</summary>
    private static int s_Unknown_005de708;

    /// <summary>
    /// Ghidra: FUN_0050bf20 @ 0x0050bf20 — <b>le pas par personnage</b>. Voir le pave ci-dessus pour
    /// les quatre lectures que seule la machine donne.
    ///
    /// <para>
    /// La fonction fait, dans l'ordre : avancer l'animation, lire la manette (ou l'intention de
    /// l'IA), decider d'un changement d'etat, appliquer le deplacement au terrain, gerer le
    /// portage par une autre entite, puis publier le resultat. Elle sort tot dans six cas
    /// distincts, tous conserves.
    /// </para>
    /// <para>
    /// <b>Onze appelees ne sont pas encore transcrites</b> et levent chacune en se nommant. Toutes
    /// sont dans <c>Blaze.c</c> — aucune ne demande de desassemblage. Elles n'ont pas ete ecrites
    /// d'avance : c'est le jeu qui dira lesquelles il emprunte, comme pour les verbes de zone et
    /// les gestionnaires d'entite.
    /// </para>
    /// </summary>
    private static void TickPartyMember(int member)
    {
        byte* mainMem = GetMainMemPtr();

        byte* s = Inp.s_SlotFlags_005e93c0 + member * 0x9c;      // Ghidra: puVar3
        uint* slot = (uint*)s;
        byte* entry = Inp.s_SlotArea_005e9180 + member * 0x4c;   // Ghidra: puVar11, alias iStack_4
        byte slotKind = Inp.s_PlayerSlots_005e9188[member * 0x4c];
        byte* pad = Inp.s_InputStateBase_00604a20 + slotKind * 0x10;   // Ghidra: puVar21, alias unaff_EBX
        byte* perChar = mainMem + 0xf0000 + member * 0x2000;           // Ghidra: iVar23, alias unaff_EBP

        if ((*slot & 0x4000008) != 0) return;

        if (perChar[0x207] != 0) perChar[0x207]--;

        // La cible tenue a +0x74 est oubliee des qu'elle cesse d'etre active.
        byte* watched = *(byte**)(s + 0x74);
        if (watched != null && (*(uint*)watched & 0x80000000) == 0) *(byte**)(s + 0x74) = null;

        // Le bouton 3 ouvre le menu, mais seulement si le repartiteur est au repos.
        if ((*slot & 0x40010000) == 0 && (pad[2] & 8) != 0 && (*(uint*)Mem.Arena(0x005e9ae4) & 3) == 0)
        {
            s_Unknown_005de540 = s[8];
            s_Unknown_005de708 = s_Unknown_005de540;
            (*Mem.Arena(0x005e9ae4))++;
            *Mem.Entity(0x005fa580) = 1;
        }

        // Le compte a rebours de transition : tant qu'il tourne, le membre est fige.
        if (*(ushort*)(s + 0x12) != 0)
        {
            *(ushort*)(s + 0x12) = 0x14;
            if ((*slot & 0x10000000) != 0) return;

            *(short*)(s + 0x32) = *(short*)(s + 0x98);
            *slot |= 0x10000000;
            return;
        }

        // ---------------------------------------------------------------- animation
        uint state = *slot;
        uint running = state & 0xfdffffff;
        *slot = running;

        byte* animSet = *(byte**)(Mem.Arena(0x005e9680) + s[4] * 4);
        byte* anim = *(byte**)(animSet + *(short*)(s + 0x18) * 4);

        if ((state & 0x1000000) == 0)
        {
            short frame = *(short*)(s + 0x1a);
            if (frame + 1 < (int)*(ushort*)(anim + 0x16))
            {
                // Un membre porte par une autre entite (0x40000000) n'avance qu'une image sur deux.
                if ((state & 0x40000000) == 0) *(short*)(s + 0x1a) = (short)(frame + 1);
                else if ((*(uint*)Mem.Entity(0x005f2cf0) & 1) != 0) *(short*)(s + 0x1a) = (short)(frame + 1);
            }
            else
            {
                *slot = running | 0x2000000;
                if ((state & 0x40000005) == 0)
                {
                    // Ghidra rend l'ecriture par CONCAT31 — c'est un `mov [.],al` sur l'octet bas,
                    // qui laisse la valeur inchangee puisque 0x2000000 ne touche pas cet octet.
                    *(uint*)(s + 0x18) = 0;
                    *slot = ((running | 0x2000000) & 0xfffffffd) | 0x1000000;
                }

                if ((*slot & 0x40) != 0) *slot &= 0xffffffbf;
            }
        }
        else
        {
            (*(short*)(s + 0x1a))++;
            if ((int)*(ushort*)(anim + 0x16) <= *(short*)(s + 0x1a)) *(short*)(s + 0x1a) = 0;
        }

        short stateId = *(short*)(s + 0x18);
        if (stateId == 0) *slot &= 0xfffffffb;

        state = *slot;
        if ((state & 0x40000000) == 0)
        {
            // La regeneration lente, un centieme d'image, tant qu'aucune touche n'est tenue.
            if ((*(ushort*)pad & *(ushort*)(perChar + 0x1fc4)) == 0)
            {
                short maximum = *(short*)(perChar + 0x14a);
                if (*(short*)(perChar + 0x14e) < maximum
                    && (perChar[0x140] & 2) == 0
                    && (state & 0x80) == 0
                    && *(uint*)Mem.Entity(0x005f2cf0) % 100 == 0)
                {
                    short raised = (short)(*(short*)(perChar + 0x156) + *(short*)(perChar + 0x14e));
                    *(short*)(perChar + 0x14e) = raised;
                    if (maximum < raised) *(short*)(perChar + 0x14e) = maximum;
                }
            }
        }
        else if (stateId == 7)
        {
            if ((state & 0x2000000) != 0 && (state & 0x200000) == 0) *slot = state | 0x200000;
        }
        else
        {
            // Porte, mais pas dans l'etat de portage : on y bascule.
            *(uint*)Mem.Arena(0x005e99c0) = 0;
            TriggerEquippedItems_005238E0(slot, 0x15);

            state = *slot;
            if ((state & 0x40000000) != 0)
            {
                *(uint*)(s + 0x18) = 7;
                *(uint*)(s + 0x38) = 0xffffff;
                *slot = (state & 0xf6fffff9) | 0x12000;
                byte carried = s[8];
                *(short*)(s + 0x36) = 1;
                *(short*)(s + 0x96) = 0;

                if (carried == (byte)Mem.s_Unknown_005de538)
                {
                    PassLeaderToNextEligible(slot, entry, 0);
                }

                *(uint*)(perChar + 0x140) = 0x40000000;
                for (int i = 0; i < 0x20; i++) ((uint*)(perChar + 0x180))[i] = 0;
            }
        }

        *(uint*)(s + 0x5c) = 0;

        // ---------------------------------------------------------------- l'aiguillage principal
        if ((*(uint*)(perChar + 0x140) & 0x400001c0) != 0)
        {
            // Hors de combat : l'etat retombe et le role de meneur passe.
            if ((*slot & 0x40000000) == 0) *(uint*)(s + 0x18) = 0;

            byte previousLeader = (byte)Mem.s_Unknown_005de538;
            if (s[8] == previousLeader)
            {
                PassLeaderToNextEligible(slot, entry, 0);
                if (previousLeader != (byte)Mem.s_Unknown_005de538) *slot |= 0x10000;
            }

            TickPartyMemberTail(member, s, slot, entry, pad, perChar, mainMem);
            return;
        }

        if ((*slot & 0x80) != 0)
        {
            TickPartyMemberTail(member, s, slot, entry, pad, perChar, mainMem);
            return;
        }

        if (*(ushort*)(pad + 2) != 0)
        {
        }

        if ((*slot & 0x8000000) != 0)
        {
            TickQuickMenu_00530070(slot, entry, perChar, pad);
            TickPartyMemberTail(member, s, slot, entry, pad, perChar, mainMem);
            return;
        }

        // Le tampon de commande : quatre images de memoire sur le bouton d'action.
        if (pad[0x0e] != 0) pad[0x0e]--;
        if ((*(ushort*)(pad + 2) & *(ushort*)(perChar + 0x1fc4)) != 0) pad[0x0e] = 4;

        if ((*slot & 0x10002) == 0)
        {
            if ((*slot & 0x40) == 0)
            {
                DispatchInputHandler(perChar[0x2b7], slot, perChar, pad);
            }

            if ((*slot & 1) == 0)
            {
                ApplyGroundMotion_0051A020(slot, entry, perChar, pad, anim);
            }
        }

        DispatchPostureHandler((byte)(perChar[0x150] & 7), slot, entry, perChar, pad, anim);

        state = *slot;
        if ((state & 4) != 0)
        {
            TickPartyMemberTail(member, s, slot, entry, pad, perChar, mainMem);
            return;
        }

        if ((state & 0x10000) == 0)
        {
            TickPlayableMember(member, s, slot, entry, slotKind, pad, perChar, state);
            TickPartyMemberTail(member, s, slot, entry, pad, perChar, mainMem);
            return;
        }

        // ---------------------------------------------------------------- le membre suivi par l'IA
        if (s[8] == (byte)Mem.s_Unknown_005de538) PassLeaderToNextEligible(slot, entry, 0);

        uint follow = Mem.Entity(0x005edec0)[*Mem.Entity(0x005f2ce4)];
        (*Mem.Entity(0x005f2ce4))++;

        if (*(ushort*)(Inp.s_SlotFlags_005e93c0 + follow * 0x9c + 0x12) != 0)
        {
            uint held = *slot;
            *(short*)(s + 0x98) = *(short*)(s + 0x32);
            *slot = (held & 0xf7fffdff) | 0x2000;
            (*(ushort*)(s + 0x12))++;
            return;
        }

        TickFollowingMember(member, s, slot, entry, slotKind, pad, perChar, mainMem, follow);
        TickPartyMemberTail(member, s, slot, entry, pad, perChar, mainMem);
    }

    /// <summary>
    /// Ghidra: la branche <c>(*puVar3 &amp; 0x10000) == 0</c> de <see cref="TickPartyMember"/>
    /// (0x0050c396..0x0050c771) — <b>le membre que le joueur pilote</b>. Elle lit la manette et rien
    /// d'autre : coup, saut, et le tampon de quatre images qui rattrape une frappe legerement en
    /// avance.
    ///
    /// <para>
    /// Les deux moities du <c>if</c> final se ressemblent au point qu'on les croirait factorisables
    /// — meme pose de <c>0x4000</c> dans <c>+0x9a</c>, meme etat 4, meme decalage de position quand
    /// <c>+0x90</c> porte <c>0x100</c>. Elles different par une seule ligne : la premiere choisit sa
    /// portee selon le bouton tenu, la seconde la fixe a <c>0x1c000</c>. Transcrites separement,
    /// parce que ce sont deux blocs distincts du binaire et que l'oracle compare des corps.
    /// </para>
    /// </summary>
    private static void TickPlayableMember(
        int member, byte* s, uint* slot, byte* entry, byte slotKind, byte* pad, byte* perChar, uint state)
    {
        // Le coup : bouton d'attaque, pas deja en train de frapper, et le mode de mise au point
        // n'est pas en train de geler le monde.
        if ((state & 0x42) == 0
            && (*(ushort*)(pad + 2) & *(ushort*)(perChar + 0x1fc0)) != 0
            && (sbyte)perChar[0x2b0] != -1
            && s_Unknown_00566c84 != 0
            && (perChar[0x140] & 0x10) == 0)
        {
            *(uint*)Mem.Arena(0x005e99c0) = 0;
            TriggerEquippedItems_005238E0(slot, 1);
            *slot = (*slot & 0xfcffffff) | 2;

            *(uint*)(s + 0x18) = (perChar[0x150] & 7) == 0 && (pad[2] & 0xf0) != 0 ? 6u : 3u;
        }

        // Le tampon de saut : quatre images de memoire sur le bouton, remis a zero si le bouton
        // RELACHE arrive dans la meme image — d'ou les deux mots de manette lus, +2 et +4.
        if ((sbyte)pad[0x0c] != 0) pad[0x0c]--;
        if ((*(ushort*)(pad + 2) & *(ushort*)(perChar + 0x1fc2)) != 0) pad[0x0c] = 4;

        if ((*(ushort*)(perChar + 0x1fc2) & *(ushort*)(pad + 4)) != 0)
        {
            pad[0x0c] = 0;
            *(short*)(s + 0x9a) = 0x6000;
        }

        if ((*slot & 0x47) == 0)
        {
            if (pad[0x0c] == 0)
            {
                // Rien de tampon : reste le bouton de garde, qui libere une texture et un son.
                if ((*(ushort*)(pad + 2) & *(ushort*)(perChar + 0x1fca)) != 0)
                {
                    Winsys3d.ReleaseTexture(0x18);
                    uint held = *slot;
                    *(uint*)(s + 0x18) = 0;
                    *slot = held | 0x9000000;
                    pad[0x0a] = 0xff;
                    Aud.PlayUiSound38();
                }

                return;
            }

            pad[0x0c] = 0;
            uint before = *slot;
            *(short*)(s + 0x9a) = 0x4000;
            *slot = (before & 0xfcffffff) | 1;

            // La portee du saut depend du bouton tenu, sauf en mode de mise au point.
            *(int*)(s + 0x54) = Mem.s_DebugModeLatch_005633a8 == 0
                ? (int)((uint)-(((*(ushort*)pad & 1) != 0) ? 1 : 0) & 0x7a000) + 0x1c000
                : 0x1c000;

            uint attributes = *(uint*)(s + 0x90);
            *(uint*)(s + 0x18) = 4;
            if ((attributes & 0x100) != 0)
            {
                *(int*)(s + 0x50) += *(short*)(entry + 0x44) * 8;
                *(int*)(s + 0x58) += *(short*)(entry + 0x48) * 8;
            }

            entry[0x0a] = 0;
        }
        else
        {
            if ((*slot & 0x46) != 0 || entry[0x0a] == 0) return;

            entry[0x0a]--;
            if ((*(ushort*)(pad + 2) & *(ushort*)(perChar + 0x1fc2)) == 0) return;

            entry[0x0a] = 0;
            uint before = *slot;
            *(short*)(s + 0x9a) = 0x4000;
            *(int*)(s + 0x54) = 0x1c000;
            *slot = (before & 0xfcffffff) | 1;

            uint attributes = *(uint*)(s + 0x90);
            *(uint*)(s + 0x18) = 4;
            if ((attributes & 0x100) != 0)
            {
                *(int*)(s + 0x50) += *(short*)(entry + 0x44) * 8;
                *(int*)(s + 0x58) += *(short*)(entry + 0x48) * 8;
            }
        }

        Aud.PlayPositionalSound(0, 0xd00, 0x800, (int*)(s + 0x1c));
    }

    /// <summary>
    /// Ghidra: la branche <c>else</c> de 0x0050c3c8..0x0050caf3 — <b>le membre que l'IA fait
    /// suivre</b>. Il court derriere sa cible tant qu'il en est loin, se tourne vers elle en
    /// arrivant, et sonde le terrain devant lui pour sauter ce qui doit l'etre.
    ///
    /// <para>
    /// <b>Le flot a ete reconstruit, pas translittere.</b> Ghidra en rend deux labels
    /// (<c>LAB_0050c4d6</c> et <c>LAB_0050c781</c>) sautes depuis trois endroits, ce qui donne
    /// l'impression d'un graphe irreductible. Il ne l'est pas : <b>toutes</b> les routes qui
    /// atteignent <c>LAB_0050c781</c> le font avec une distance restante nulle ou negative, et
    /// toutes celles qui atteignent le bloc de sonde le font avec une distance d'au moins 1. Les
    /// deux labels se ramenent donc a un seul <c>if (distance &gt;= 1)</c>, et le drapeau
    /// « entrer en approche » que la lecture naive suggere est inutile.
    /// </para>
    /// <para>
    /// La cible est le membre suivant dans la liste <c>DAT_005edec0</c> quand celui-ci est
    /// disponible, sinon le meneur ; la distance d'arret vaut 100 dans le premier cas et la portee
    /// de posture <see cref="s_PostureSpeed_00562cc0"/> dans le second.
    /// </para>
    /// </summary>
    private static void TickFollowingMember(
        int member, byte* s, uint* slot, byte* entry, byte slotKind,
        byte* pad, byte* perChar, byte* mainMem, uint follow)
    {
        // L'echelle de portee, choisie par les drapeaux du bloc par personnage.
        uint posture = *(uint*)(perChar + 0x140);
        int scale = 0x1000;
        if ((posture & 0x4000) != 0) scale = 0x1333;
        if ((posture & 0x8000) != 0) scale = 0xccc;
        if ((posture & 4) != 0) scale = 0x800;

        uint leaderIndex = (uint)(byte)Mem.s_Unknown_005de538;
        byte* leaderSlot = Inp.s_SlotFlags_005e93c0 + leaderIndex * 0x9c;
        byte* leaderBlock = mainMem + 0xf0000 + leaderIndex * 0x2000;

        int reach = s_PostureSpeed_00562cc0[leaderBlock[0x150] & 7] * scale >> 0xc;

        int dx = 0;
        int dz = 0;
        int distance;

        if (*(ushort*)(Inp.s_SlotFlags_005e93c0 + follow * 0x9c + 0x12) == 0
            && (leaderSlot[0] & 1) == 0)
        {
            byte* target = Inp.s_SlotFlags_005e93c0 + follow * 0x9c;
            dx = (*(int*)(target + 0x1c) - *(int*)(s + 0x1c)) >> 0xc;
            dz = (*(int*)(target + 0x24) - *(int*)(s + 0x24)) >> 0xc;
            distance = (int)Winsys3d.Ordinal_442((uint)(dx * dx + dz * dz)) - 100;
        }
        else if ((*(uint*)(leaderSlot + 0x90) & 0x8000) == 0)
        {
            dx = (*(int*)(leaderSlot + 0x1c) - *(int*)(s + 0x1c)) >> 0xc;
            dz = (*(int*)(leaderSlot + 0x24) - *(int*)(s + 0x24)) >> 0xc;
            distance = (int)Winsys3d.Ordinal_442((uint)(dx * dx + dz * dz)) - reach;
        }
        else
        {
            // Ghidra laisse ici dx et dz a leur valeur precedente ; ils sont pourtant relus par
            // l'appel a ratan2 ci-dessous. Conserve tel quel — c'est ce que fait l'original, qui
            // lit deux emplacements de pile non ecrits sur ce chemin.
            distance = 0;
        }

        uint held = *slot;
        if ((distance < 1 && (held & 1) == 0) || (held & 2) != 0)
        {
            if (*(short*)(s + 0x18) != 0 && (*slot & 0x47) == 0)
            {
                *(uint*)(s + 0x18) = 0;
                *slot |= 0x1000000;
            }

            *(short*)(s + 0x98) = *(short*)(s + 0x32);
        }
        else
        {
            *(short*)(s + 0x98) = (short)Winsys3d.Ordinal_457(dx, dz);

            if ((*(uint*)(leaderSlot + 0x90) & 0x8000) == 0 && (*slot & 0x40) == 0)
            {
                held = *slot;
                if ((held & 7) == 0 && *(short*)(s + 0x18) != 1)
                {
                    *(uint*)(s + 0x18) = 1;
                    *slot = held | 0x1000000;
                }

                if (distance > 0)
                {
                    *(uint*)(s + 0x5c) = (uint)Math.Min(distance, reach) << 0xc;
                }
            }
        }

        if (distance >= 1)
        {
            if ((*slot & 0x46) == 0 && entry[0x0a] != 0)
            {
                entry[0x0a]--;
                if (ProbeGroundAhead(member, s, slot, entry, perChar, mainMem)) return;
            }
        }
        else if ((*slot & 0x46) == 0)
        {
            byte* obstacle = FindNearestOpponent_00474EB0(slot, 0xffffffff, 1);
            if (obstacle != null)
            {
                int ox = (*(int*)(obstacle + 0x1c) - *(int*)(s + 0x1c)) >> 0xc;
                int oy = (*(int*)(obstacle + 0x20) - *(int*)(s + 0x20)) >> 0xc;
                int oz = (*(int*)(obstacle + 0x24) - *(int*)(s + 0x24)) >> 0xc;
                int range = (int)Winsys3d.Ordinal_442((uint)(ox * ox + oy * oy + oz * oz));

                // Ghidra passe `iStack_24` en premier argument de ratan2, un emplacement qu'aucune
                // route n'ecrit sur ce chemin. Conserve tel quel.
                uint turn = (uint)(Winsys3d.Ordinal_457(ox, oy) - *(ushort*)(s + 0x32)) & 0xfff;
                byte stance = (byte)(perChar[0x150] & 7);

                if (range < (int)((uint)-(stance != 4 ? 1 : 0) & 0xffffff06) + 400
                    && ((turn + 0x80) & 0xfff) < 0x100
                    && *(ushort*)Mem.Arena(0x005e9ae6) != 0)
                {
                    if ((perChar[0x140] & 0x10) == 0 && (sbyte)perChar[0x2b0] != -1
                        && s_Unknown_00566c84 != 0)
                    {
                        *(uint*)Mem.Arena(0x005e99c0) = 0;
                        TriggerEquippedItems_005238E0(slot, 1);
                        held = *slot;
                        short facing = *(short*)(s + 0x98);
                        *(uint*)(s + 0x18) = 3;
                        *slot = (held & 0xfcffffff) | 2;
                        *(short*)(s + 0x32) = facing;
                        return;
                    }
                }
                else if (range < (int)((uint)-(stance != 4 ? 1 : 0) & 0xfffffed4) + 500
                         && ((turn + 0x80) & 0xfff) > 0x100)
                {
                    // Un pas de 0x80 vers la cible, dans le sens le plus court.
                    *(short*)(s + 0x98) += (short)((((turn > 0x7ff ? 1 : 0) - 1) & 0x100) - 0x80);
                }
            }
        }

        *(short*)(s + 0x32) = *(short*)(s + 0x98);
    }

    /// <summary>
    /// Ghidra: 0x0050c4f0..0x0050c780 — <b>la sonde de terrain</b> que le membre suivi lance devant
    /// lui avant d'avancer. Elle recopie l'entite dans le bloc d'essai <c>DAT_005e9a40</c>, la
    /// deplace de quatre pas d'un seizieme d'unite le long de son cap, et regarde ce que
    /// <see cref="FinalizeEntityPlacement2"/> rend a chaque pas.
    ///
    /// <para>
    /// <b>L'axe de chaque pas a ete verifie au desassembleur, pas suppose</b> : Ghidra reutilise le
    /// meme emplacement de pile pour le sinus et le cosinus, si bien que la pseudo-C ajoute deux
    /// fois la meme valeur. Le binaire (0x0050c512..0x0050c57b) donne <c>sinus &lt;&lt; 4</c> sur X et
    /// <c>cosinus &lt;&lt; 4</c> sur Z — la meme convention que
    /// <see cref="TrySpawnRandomEncounter"/>.
    /// </para>
    /// <para>
    /// Deux verdicts sortent de la sonde : un obstacle franchissable (bit 1) fait sauter, un mur
    /// (bit 0x800) fait tourner. Le bloc de rotation calcule l'angle de la pente rencontree et
    /// arrondit le cap au multiple le plus proche, avec trois plages distinctes selon l'ecart.
    /// </para>
    /// </summary>
    /// <returns><c>true</c> quand la sonde a change l'etat du membre et que l'appelant doit rendre
    /// la main sans poser le cap.</returns>
    private static bool ProbeGroundAhead(
        int member, byte* s, uint* slot, byte* entry, byte* perChar, byte* mainMem)
    {
        int facing = *(short*)(s + 0x98);
        int stepX = (int)Winsys3d.GetSinTableEntry(facing) << 4;
        int stepZ = Winsys3d.GetCosTableEntry(facing) << 4;

        byte* probe = Mem.Arena(0x005e9a40);
        byte* probeEntry = Mem.Entity(0x005f7d80);

        Mem.CopyDwords(slot, (uint*)probe, 0x27);
        Mem.CopyDwords((uint*)entry, (uint*)probeEntry, 0x13);
        *(uint*)probe |= 0x2000;

        *(int*)(probe + 0x1c) = *(int*)(s + 0x1c) + stepX;
        *(int*)(probe + 0x20) = *(int*)(s + 0x60) + 0x6e000;
        *(int*)(probe + 0x24) = *(int*)(s + 0x24) + stepZ;

        uint verdict = 0;
        int ground = *(int*)(s + 0x60);

        // Ghidra: `iStack_c = DAT_005e9abc;` avant chaque placement, restaure au bloc de rotation.
        // C'est une mise de cote, pas un calcul.
        int savedAbc = *(int*)Mem.Arena(0x005e9abc);
        int hereY = *(int*)(s + 0x20);

        FinalizeEntityPlacement2((uint*)probe);
        ApplyEntityMotion_00519DF0((uint*)probe, probeEntry);

        if ((*(uint*)(probe + 0x90) & 0x800) == 0)
        {
            if ((*(uint*)(probe + 0x90) & 0x2000) != 0) verdict |= 2;

            if ((*(uint*)(probe + 0x90) & 0x8000) == 0
                && (((*(uint*)(probe + 0x90) & 0x400) != 0
                     && (perChar[0x150] & 7) != 7
                     && (*(uint*)(perChar + 0x140) & 0x400000) == 0)
                    || ground + 0x32000 <= *(int*)(probe + 0x64)
                    || *(int*)(probe + 0x64) <= ground - 0x64000
                    || ((*(uint*)(probe + 0x90) & 0x100) != 0 && ground < *(int*)(probe + 0x60))))
            {
                verdict |= 1;
            }

            bool blocked = false;
            for (int step = 3; step != 0; step--)
            {
                ground = *(int*)(probe + 0x60);
                hereY = ground;
                savedAbc = *(int*)Mem.Arena(0x005e9abc);
                *(int*)(probe + 0x1c) += stepX;
                *(int*)(probe + 0x20) = *(int*)(probe + 0x60) + 0x6e000;
                *(int*)(probe + 0x24) += stepZ;

                FinalizeEntityPlacement2((uint*)probe);
                ApplyEntityMotion_00519DF0((uint*)probe, probeEntry);

                if ((*(uint*)(probe + 0x90) & 0x800) != 0) { blocked = true; break; }

                if ((*(uint*)(probe + 0x90) & 0x8000) == 0 && ground + 0x32000 <= *(int*)(probe + 0x64))
                {
                    verdict = 1;
                }
                else if (step == 3 && (*(uint*)(probe + 0x90) & 0x2000) == 0)
                {
                    verdict &= 1;
                }
            }

            if (!blocked)
            {
                if (verdict == 0) return false;

                // Franchissable : le membre saute, exactement comme le fait la branche jouable.
                entry[0x0a] = 0;
                uint before = *slot;
                uint attributes = *(uint*)(s + 0x90);
                *(short*)(s + 0x9a) = 0x4000;
                *slot = (before & 0xfcffffff) | 1;
                *(int*)(s + 0x54) = 0x1c000;
                *(uint*)(s + 0x18) = 4;

                if ((attributes & 0x100) != 0)
                {
                    *(int*)(s + 0x50) += *(short*)(entry + 0x44) * 8;
                    *(int*)(s + 0x58) += *(short*)(entry + 0x48) * 8;
                }

                Aud.PlayPositionalSound(0, 0xd00, 0x800, (int*)(s + 0x1c));
                *(short*)(s + 0x32) = *(short*)(s + 0x98);
                return true;
            }
        }

        // Ghidra: LAB_0050dc15 — un mur. Le cap est recale sur la normale de la pente rencontree,
        // et l'arrondi depend de l'ecart : moins d'un huitieme de tour se colle, sinon on tourne
        // d'un quart de l'ecart, dans un sens ou dans l'autre.
        if (*(uint*)Mem.Arena(0x005e9ab8) != 0) return false;

        *(int*)Mem.Arena(0x005e9abc) = savedAbc;

        // Ghidra passe `&iStack_20`, c'est-a-dire l'adresse de trois locales contigues : la
        // position du membre, avec en Y la hauteur de sol relevee au dernier pas de sonde.
        int* here = stackalloc int[3];
        here[0] = *(int*)(s + 0x1c);
        here[1] = hereY;
        here[2] = *(int*)(s + 0x24);

        int wallAngle = GroundSlopeAngle_005335E0((uint*)probe, here);
        ushort probeFacing = *(ushort*)(probe + 0x32);

        int corrected = ((wallAngle - (uint)*(ushort*)(s + 0x98)) & 0xfff) < 0x800
            ? wallAngle - 0x428
            : wallAngle + 0x428;

        *(ushort*)(s + 0x98) = probeFacing;
        uint delta = (uint)(corrected - probeFacing) & 0xfff;

        short newFacing;
        if (((delta + 0x80) & 0xfff) < 0x101)
        {
            uint signed = delta > 0x7ff ? delta - 0x1000 : delta;
            newFacing = (short)(probeFacing + (short)signed);
        }
        else if (delta < 0x800)
        {
            newFacing = (short)(probeFacing + (short)((int)delta >> 2));
        }
        else
        {
            newFacing = (short)(probeFacing - (short)((int)(0x1000 - delta) >> 2));
        }

        *(short*)(s + 0x98) = newFacing;
        *(short*)(s + 0x32) = newFacing;
        return true;
    }

    // =====================================================================
    // Les lacunes de FUN_0050bf20. Toutes ses appelees manquantes sont dans `Blaze.c` — aucune ne
    // demande de desassemblage — et aucune n'a ete ecrite d'avance : c'est le jeu qui dira
    // lesquelles il emprunte, comme pour les verbes de zone et les gestionnaires d'entite.
    // =====================================================================

    /// <summary>
    /// Ghidra: FUN_005238e0 @ 0x005238e0 — <b>l'evenement d'objet equipe</b> : elle balaie les cinq
    /// emplacements de <c>+0x2b0</c> et fait tourner le script <b>declenche</b> de chaque objet dont
    /// <c>item[0x84]</c> vaut <paramref name="ev"/>.
    ///
    /// <para>C'est la <b>seconde entree</b> de <see cref="RunItemScript_00523AA0"/>, et elle ne
    /// prend pas le meme script que la premiere : <c>FUN_00523a20</c> part de <c>item[0x82]</c> la
    /// ou <c>FUN_00523860</c> part de <c>item[0x80]</c>. Chaque bloc d'objet porte donc deux
    /// scripts — celui qu'on declenche en s'en servant, et celui qui reagit aux evenements.</para>
    ///
    /// <para><b>Trois protections encadrent l'appel</b>, et elles disent que ce script peut en
    /// declencher un autre :</para>
    /// <list type="bullet">
    /// <item><c>DAT_005e99c0</c> est un masque de cinq bits, un par emplacement : un objet deja
    /// entre ne se re-declenche pas. C'est l'appelant qui le remet a zero avant d'ouvrir une
    /// serie.</item>
    /// <item>la banque de variables de script (<c>0x005e9060</c>, 0x10 dwords) est empilee dans
    /// <c>0x005de170</c> au pas de 0x40, et depilee au retour.</item>
    /// <item>la cible <c>slot[0x70]</c> est empilee en parallele dans <c>0x005de2b8</c>.</item>
    /// </list>
    ///
    /// <para>La profondeur vit dans l'octet bas de <c>0x005de2b0</c> — et <b>ce compteur suit
    /// immediatement la pile qu'il indexe</b> : <c>0x005de170 + 5 * 0x40</c> vaut exactement
    /// <c>0x005de2b0</c>. Cinq places, cinq emplacements d'equipement ; la disposition de 1998 est
    /// juste au dernier octet pres, et c'est pourquoi la pile de sauvegarde et son compteur vivent
    /// dans la meme allocation ici.</para>
    ///
    /// <para>Le nom precedent, « SetEntityAnimationState », etait faux : rien dans ce corps ne
    /// touche a une animation.</para>
    /// </summary>
    private static void TriggerEquippedItems_005238E0(uint* slot, uint ev)
    {

        byte* record = GetMainMemPtr() + (((byte*)slot)[8] + 0x78) * 0x2000;

        byte* entered = Mem.Arena(0x005e99c0);
        byte* bank = Mem.Arena(0x005e9060);
        byte* saveStack = Mem.ItemMenuBytes(0x005de170);
        byte* depth = Mem.ItemMenuBytes(0x005de2b0);
        byte* targetStack = Mem.ItemMenuBytes(0x005de2b8);

        for (int i = 0; i < 5; i++)
        {
            if ((*entered & (byte)(1 << i)) != 0) continue;

            byte worn = record[0x2b0 + i];
            if (worn >= 10) continue;

            int block = worn * 0x280;
            if (*(ushort*)(record + block + 0x384) != ev) continue;

            // La premiere entree d'une serie repart d'une pile vide.
            if (*entered == 0) *depth = 0;

            Mem.CopyDwords((uint*)bank, (uint*)(saveStack + *depth * 0x40), 0x10);
            byte slotOfSave = *depth;
            (*depth)++;
            *(uint*)(targetStack + slotOfSave * 4) = *(uint*)((byte*)slot + 0x70);

            *entered |= (byte)(1 << i);

            RunTriggeredItemScript_00523A20(slot, record, record + block + 0x300);

            (*depth)--;
            Mem.CopyDwords((uint*)(saveStack + *depth * 0x40), (uint*)bank, 0x10);
            *(uint*)((byte*)slot + 0x70) = *(uint*)(targetStack + *depth * 4);
        }
    }

    /// <summary>
    /// Ghidra: FUN_00523a20 @ 0x00523a20 — le meme sas que <see cref="RunItemScriptSaved_00523860"/>
    /// autour de l'allocateur de <c>winsys3d</c>, mais sur le script <b>declenche</b> de
    /// <c>item[0x82]</c> et non sur celui de <c>item[0x80]</c>.
    ///
    /// <para>Ghidra y perd le meme parametre que dans son jumeau — sa seconde branche appelle
    /// <c>FUN_00523aa0(unaff_retaddr, param_1, param_2, …)</c>, decalee d'un cran. Trois arguments
    /// dans les deux branches.</para>
    /// </summary>
    private static void RunTriggeredItemScript_00523A20(uint* slot, byte* record, byte* item)
    {
        byte* script = item + *(ushort*)(item + 0x82);

        if (Winsys3d.Ordinal_46() < 0)
        {
            RunItemScript_00523AA0(slot, record, item, script);
            return;
        }

        *(int*)Mem.Arena(0x005e9318) = Winsys3d.Ordinal_46();
        Winsys3d.Ordinal_45(GetMainMemPtr() + 0x1c0000);
        RunItemScript_00523AA0(slot, record, item, script);
        Winsys3d.Ordinal_45((void*)(nint)(*(int*)Mem.Arena(0x005e9318)));
    }

    /// <summary>Ghidra: &amp;DAT_00564600 — <b>le nombre de sorts par école</b>, indexé par
    /// <c>personnage[0x2b5]</c>. Trois écoles seulement : la table de pointeurs
    /// <c>PTR_DAT_00564640</c> porte trois rangées puis un mot nul, et la rangée cumulée voisine
    /// (<c>DAT_00564608</c>, <c>00 1d 35 49</c>) est bien la somme courante de <c>1d 18 14</c>.
    /// Relevé verbatim dans <c>Legacy/Binaries/Blaze.exe</c>.
    ///
    /// <para>Ces comptes bornent le balayage de <see cref="TickQuickMenu_00530070"/> et l'index de
    /// bit dans <c>personnage + 0x160 + école * 8</c>, huit octets par école — soit 64 bits pour au
    /// plus 29 sorts.</para></summary>
    private static readonly byte* s_SpellCounts_00564600 = AllocBytes([
        0x1d, 0x18, 0x14, 0x01, 0x01, 0x01, 0x26, 0x00,
    ]);

    // =====================================================================
    // Le menu rapide — l'anneau au-dessus du personnage, ouvert par le bouton `+0x1fca`.
    //
    // `DrawSpeechOverlay_005309B0` le dessine ; `TickQuickMenu_00530070` le pilote. Les deux lisent
    // la meme table de disposition `s_MenuLayout_0056a850` : la categorie courante est
    // `personnage[0x2be] & 0xf`, l'entree choisie dans la categorie est `personnage[0x2bf]`, et
    // `personnage[0x2d0]` porte le nombre d'entrees que la categorie courante propose (la liste
    // elle-meme etant a `+0x2d1`).
    //
    // Le bit 0x80 de `personnage[0x2be]` distingue les deux etages : eteint on change de categorie,
    // allume on parcourt les entrees de la categorie. Le bit 0x8000000 du mot d'etat est ce qui
    // maintient l'anneau a l'ecran ; l'eteindre le ferme.
    //
    // Les quatre sons sont ceux de tout le jeu : 0x38 valider, 0x39 annuler, 0x3a deplacer,
    // 0x3b refuser (Ghidra: FUN_0053db80 / FUN_0053dba0 / FUN_0053db60 / FUN_0053dbc0, quatre
    // enveloppes d'une ligne autour de FUN_0053cea0).
    // =====================================================================

    private static void QuickMenuConfirmSound() => Aud.PlaySoundEffect(0x38, 0x400, 0x2000, 0x2000);
    private static void QuickMenuCancelSound() => Aud.PlaySoundEffect(0x39, 0x400, 0x2000, 0x2000);
    private static void QuickMenuMoveSound() => Aud.PlaySoundEffect(0x3a, 0x400, 0x2000, 0x2000);
    private static void QuickMenuRefuseSound() => Aud.PlaySoundEffect(0x3b, 0x400, 0x2000, 0x2000);

    /// <summary>
    /// Ghidra: FUN_00530070 @ 0x00530070 — <b>le menu rapide</b>, la boucle d'entree de l'anneau
    /// qu'un membre du groupe ouvre au-dessus de lui. Prise quand le mot d'etat porte
    /// <c>0x8000000</c>.
    ///
    /// <para>Elle fait trois choses dans cet ordre : ouvrir, fermer ou valider l'etage courant ;
    /// deplacer le curseur d'entree et agir sur la validation, par un aiguillage sur le genre de la
    /// categorie ; puis — c'est la queue commune, atteinte par tous les chemins — deplacer le
    /// curseur de categorie et <b>recalculer la liste d'entrees</b> que la nouvelle categorie
    /// propose.</para>
    ///
    /// <para><b>Les deux axes ne font pas la meme chose selon que le bouton d'ouverture est
    /// tenu.</b> Bouton tenu : haut/bas changent de categorie, gauche/droite changent d'entree.
    /// Bouton relache : les deux axes changent d'entree, et la categorie ne bouge que si l'anneau
    /// n'est pas encore ouvert. Le repetiteur est <c>manette[6]</c>, le mot que
    /// <see cref="Input.UpdateButtonEdges"/> remplit avec la croix et sa repetition automatique —
    /// <c>0x10</c> haut, <c>0x20</c> droite, <c>0x40</c> bas, <c>0x80</c> gauche.</para>
    ///
    /// <para><b>Le test « le curseur a-t-il bouge » du genre 6 lit un registre ecrase.</b> Ghidra
    /// rend <c>puVar11</c> comme la valeur d'avant le deplacement, puis les deux boucles de
    /// recherche l'ecrasent avec leur compteur d'essais restants ; le binaire confirme
    /// (<c>cmp ebx,edx</c> en <c>0x00530376</c>, ou <c>ebx</c> sort de <c>dec ebx</c>). Transcrit
    /// tel quel : le son de deplacement se declenche donc des qu'une recherche a tourne, meme si
    /// elle est revenue sur le meme sort. C'est le comportement de 1998.</para>
    ///
    /// <para><b>Le genre <c>-1</c> de la table est inatteignable</b> — voir
    /// <see cref="s_MenuLayout_0056a850"/>. Le binaire n'y initialise pas le masque de la queue : le
    /// <c>ja</c> non signe saute par-dessus les cinq <c>mov ebx</c>, puis le <c>jg</c> signe laisse
    /// entrer la boucle avec <c>ebx</c> = le pointeur de manette. On pose zero a la place, ce qui
    /// rend la liste vide plutot qu'aleatoire, et on le dit ici.</para>
    ///
    /// <para><b>Un seul trou</b> : le genre 5 valide fait tourner le script d'objet
    /// (<see cref="RunItemScript_00523AA0"/>), une seconde machine a opcodes de 23 gestionnaires
    /// que le depot n'a pas encore abordee. Tout le reste du menu — navigation, equipement,
    /// sorts, passage de la main — est transcrit.</para>
    ///
    /// <para>Le desassemblage complet est conserve dans
    /// <c>Legacy/Raw/Blaze/FUN_00530070.disasm.txt</c> : Ghidra s'arrete au <c>ret</c> de
    /// <c>0x00530714</c> alors que les genres 8 et 9 vivent apres lui, et trois tables de sauts
    /// (<c>0x00530948</c>, <c>0x00530970</c>, <c>0x00530998</c>) ne se lisent que la.</para>
    /// </summary>
    private static void TickQuickMenu_00530070(uint* slot, byte* entry, byte* perChar, byte* pad)
    {

        byte state = perChar[0x2be];
        int kind = (sbyte)s_SpeechIconIndex_0056a851[(state & 0xf) + (perChar[0x150] & 7) * 9];

        ushort openMask = *(ushort*)(perChar + 0x1fca);
        byte* target = pad;                    // Ghidra: puVar7 / eax, l'emplacement qu'on equipera
        bool close = false;                    // Ghidra: LAB_005304f7, atteint des deux etages

        if ((state & 0x80) == 0)
        {
            // ---------------------------------------------- l'anneau n'est pas encore ouvert
            ushort edge = *(ushort*)(pad + 2);
            ushort dismiss = (ushort)(openMask | 0x4000);

            if ((dismiss & edge) != 0)
            {
                *(ushort*)(pad + 2) = (ushort)(~dismiss & edge);
                close = true;
            }
            else if (((*(ushort*)pad & openMask) != 0 && (pad[6] & 0xa0) != 0)
                     || (edge & 0x8000) != 0)
            {
                // Le genre 5 se refuse tant que le delai d'objet du personnage court.
                if ((kind == 5 && perChar[0x207] != 0) || perChar[0x2d0] == 0)
                {
                    QuickMenuRefuseSound();
                }
                else
                {
                    perChar[0x2be] = (byte)(state | 0x80);
                    QuickMenuConfirmSound();
                }
            }
        }
        else
        {
            // ---------------------------------------------- l'anneau est ouvert sur une categorie
            ushort edge = *(ushort*)(pad + 2);

            if ((edge & openMask) != 0)
            {
                *(ushort*)(pad + 2) = (ushort)(edge & ~openMask);
                close = true;
            }
            else if (((*(ushort*)pad & openMask) != 0 && (pad[6] & 0x50) != 0)
                     || (edge & 0x4000) != 0)
            {
                perChar[0x2be] = (byte)(state & 0xf);
                QuickMenuCancelSound();
            }
            else if (perChar[0x2d0] != 0)
            {
                byte entries = perChar[0x2d0];            // Ghidra: bVar1, releve une seule fois

                // --- le curseur d'entree ; le genre 6 a son propre balayage plus bas ------------
                if (kind != 6)
                {
                    sbyte before = (sbyte)perChar[0x2bf];
                    byte repeat = pad[6];
                    byte forward;

                    if ((*(ushort*)pad & openMask) == 0)
                    {
                        if ((repeat & 0x90) != 0) perChar[0x2bf] = (byte)(before - 1);
                        forward = (byte)(pad[6] & 0x60);
                    }
                    else
                    {
                        if ((repeat & 0x80) != 0) perChar[0x2bf] = (byte)(before - 1);
                        forward = (byte)(pad[6] & 0x20);
                    }

                    if (forward != 0) perChar[0x2bf]++;
                    if (perChar[0x2bf] == 0xff) perChar[0x2bf] = (byte)(entries - 1);
                    if (perChar[0x2bf] >= entries) perChar[0x2bf] = 0;
                    if (before != (sbyte)perChar[0x2bf]) QuickMenuMoveSound();
                }

                switch (kind)
                {
                    // --- 0 a 4 : les cinq emplacements d'equipement ----------------------------
                    case 0:
                    case 1:
                    case 2:
                    case 3:
                    case 4:
                        target = perChar + 0x2b0 + kind;
                        break;

                    // --- 5 : se servir de l'objet designe --------------------------------------
                    case 5:
                    {
                        byte item = perChar[perChar[0x2bf] + 0x2d1];

                        if ((pad[3] & 0x80) != 0)
                        {
                            if ((perChar[item * 0x280 + 0x313] & 0x10) == 0
                                || s_Unknown_00566c84 == 0
                                || (*(uint*)(perChar + 0x140) & 0x400003c0) != 0)
                            {
                                QuickMenuRefuseSound();
                            }
                            else
                            {
                                UseCarriedItem_00523820(slot, item);
                                CommitStagedStatBlock(perChar);              // Ghidra: FUN_00538ab0
                                ScaleStatBlockByDifficulty(perChar + 0x100); // Ghidra: FUN_00538f50
                                ComputeDerivedStats(perChar);                // Ghidra: FUN_00538c50
                                ApplyEquipmentStatBonuses(perChar);          // Ghidra: FUN_00538e20
                                FinalizeEquipmentEffects(perChar + 0x100);   // Ghidra: FUN_00538fa0
                                QuickMenuConfirmSound();

                                perChar[0x207] = 0x28;
                                perChar[0x2be] &= 0xf;
                                *slot &= 0xf7ffffff;
                            }
                        }
                        break;
                    }

                    // --- 6 : les sorts, parcourus en sautant ceux qui ne sont pas appris --------
                    case 6:
                    {
                        byte school = perChar[0x2b5];
                        int spells = s_SpellCounts_00564600[school];
                        uint* learned = (uint*)(perChar + 0x160 + school * 8);

                        // Ghidra: puVar11 / ebx. Charge ici avec l'index d'avant, puis ecrase par
                        // le compteur d'essais de chaque recherche — voir l'en-tete.
                        int witness = perChar[0x2bf];

                        ushort held = (ushort)(*(ushort*)pad & openMask);
                        if ((held != 0 && (pad[6] & 0x80) != 0)
                            || (held == 0 && (pad[6] & 0x90) != 0))
                        {
                            int index = witness;
                            int tries = spells;
                            while (tries != 0)
                            {
                                index--;
                                if (index < 0) index = spells - 1;
                                if ((learned[index >> 5] & (1u << (index & 0x1f))) != 0) break;
                                tries--;
                            }
                            witness = tries;
                            perChar[0x2bf] = (byte)index;
                        }

                        held = (ushort)(*(ushort*)pad & openMask);
                        if ((held != 0 && (pad[6] & 0x20) != 0)
                            || (held == 0 && (pad[6] & 0x60) != 0))
                        {
                            int index = perChar[0x2bf];
                            int tries = spells;
                            while (tries != 0)
                            {
                                index = (index + 1) % spells;
                                if ((learned[index >> 5] & (1u << (index & 0x1f))) != 0) break;
                                tries--;
                            }
                            witness = tries;
                            perChar[0x2bf] = (byte)index;
                        }

                        if (witness != perChar[0x2bf]) QuickMenuMoveSound();

                        if ((pad[3] & 0x80) != 0)
                        {
                            perChar[0x2b6] = perChar[0x2bf];
                            perChar[0x2be] &= 0xf;
                            *slot &= 0xf7ffffff;
                            QuickMenuConfirmSound();
                        }
                        break;
                    }

                    // --- 7 : un choix simple, garde a +0x2b6 -----------------------------------
                    case 7:
                        if ((*(ushort*)(pad + 2) & 0x8000) != 0)
                        {
                            perChar[0x2b6] = perChar[0x2bf];
                            perChar[0x2be] &= 0xf;
                            *slot &= 0xf7ffffff;
                            QuickMenuConfirmSound();
                        }
                        break;

                    // --- 8 : trois reglages selon la tranche ou tombe l'entree ------------------
                    case 8:
                        if ((*(ushort*)(pad + 2) & 0x8000) != 0)
                        {
                            byte pick = perChar[0x2bf];
                            if (pick <= 2) perChar[0x2b7] = pick;
                            if (pick >= 3 && pick <= 4) perChar[0x2b9] = (byte)((pick - 3) ^ 1);
                            if (pick >= 5 && pick <= 6) perChar[0x2ba] = (byte)((pick - 5) ^ 1);
                            QuickMenuConfirmSound();
                        }
                        break;

                    // --- 9 : passer la main a un autre membre ----------------------------------
                    case 9:
                    {
                        ushort confirmed = *(ushort*)(pad + 2);
                        if ((confirmed & 0x8000) != 0)
                        {
                            *(ushort*)(pad + 2) = (ushort)(confirmed & 0xfff);
                            pad[0x0e] = 0;

                            byte pick = perChar[0x2bf];
                            uint* pickFlags = (uint*)(Inp.s_SlotFlags_005e93c0 + pick * 0x9c);

                            if ((byte)Mem.s_Unknown_005de538 == pick
                                || (*pickFlags & 0x50000000) != 0)
                            {
                                QuickMenuRefuseSound();
                            }
                            else
                            {
                                // Ecriture d'octet dans l'original ; les huit ecrivains du global
                                // n'y posent jamais plus de 255, donc l'affectation entiere donne
                                // la meme valeur — voir DataSymbols.md, « 0x005de538 ».
                                Mem.s_Unknown_005de538 = pick;

                                if ((*pickFlags & 0x10000) == 0)
                                {
                                    QuickMenuConfirmSound();
                                }
                                else
                                {
                                    // Le membre vise etait mene par l'IA : on lui donne la manette.
                                    byte* mainMem = GetMainMemPtr();
                                    byte leader = (byte)Mem.s_Unknown_005de538;
                                    byte* leaderBlock = mainMem + 0xf0000 + leader * 0x2000;

                                    leaderBlock[0x2d0] = (byte)s_PartySize_005e9020;
                                    leaderBlock[0x2be] = (byte)(
                                        s_MenuLayout_0056a850[(leaderBlock[0x150] & 7) * 9] - 1);
                                    leaderBlock[0x2bf] = leader;
                                    leaderBlock[0x2b8] = 0;

                                    perChar[0x2b8] = 1;
                                    perChar[0x2be] &= 0xf;

                                    // Les deux octets d'affectation de manette s'echangent entre
                                    // l'entree de ce membre et celle du nouveau meneur.
                                    byte* leaderEntry = Inp.s_PlayerSlots_005e9188 + leader * 0x4c;
                                    byte keptKind = entry[9];
                                    byte keptPad = entry[8];
                                    entry[8] = leaderEntry[0];
                                    entry[9] = leaderEntry[1];
                                    leaderEntry[0] = keptPad;
                                    leaderEntry[1] = keptKind;

                                    *(uint*)(Inp.s_SlotFlags_005e93c0 + leader * 0x9c) &= 0xfffeffff;
                                    *slot |= 0x10000;
                                    QuickMenuConfirmSound();
                                }
                            }

                            perChar[0x2be] &= 0xf;
                            *slot &= 0xf7ffffff;
                            *(uint*)(Inp.s_SlotFlags_005e93c0
                                     + (byte)Mem.s_Unknown_005de538 * 0x9c) &= 0xf7ffffff;
                        }
                        break;
                    }
                }

                // --- la validation des cinq emplacements d'equipement --------------------------
                if (kind < 5)
                {
                    byte item = perChar[perChar[0x2bf] + 0x2d1];

                    if ((pad[3] & 0x80) != 0)
                    {
                        if ((*(ushort*)(perChar + item * 0x280 + 0x312)
                             & *(ushort*)(perChar + 0x112)) == 0)
                        {
                            QuickMenuRefuseSound();
                        }
                        else
                        {
                            // Les deux mains, +0x2b3 et +0x2b4, ne peuvent pas tenir le meme objet :
                            // on refuse quand la validation viserait une main alors que l'autre le
                            // porte deja. Tout autre emplacement passe.
                            byte* left = perChar + 0x2b3;
                            byte* right = perChar + 0x2b4;

                            if ((target == left && perChar[0x2b4] != item)
                                || (target == right && perChar[0x2b3] != item)
                                || (target != left && target != right))
                            {
                                // Revalider l'objet deja en place le retire.
                                *target = *target == item ? (byte)0xff : item;

                                CommitStagedStatBlock(perChar);              // Ghidra: FUN_00538ab0
                                ScaleStatBlockByDifficulty(perChar + 0x100); // Ghidra: FUN_00538f50
                                ComputeDerivedStats(perChar);                // Ghidra: FUN_00538c50
                                ApplyEquipmentStatBonuses(perChar);          // Ghidra: FUN_00538e20
                                FinalizeEquipmentEffects(perChar + 0x100);   // Ghidra: FUN_00538fa0
                                QuickMenuConfirmSound();
                            }
                            else
                            {
                                QuickMenuRefuseSound();
                            }
                        }
                    }
                }
            }
        }

        if (close)
        {
            perChar[0x2be] &= 0xf;
            *slot &= 0xf7ffffff;
            QuickMenuCancelSound();
        }

        // ------------------------------------------------------ la queue : le curseur de categorie
        ushort menuHeld = (ushort)(*(ushort*)pad & *(ushort*)(perChar + 0x1fca));

        // On ne change de categorie que si le bouton est tenu, ou si l'anneau n'est pas ouvert.
        if (menuHeld != 0 || (perChar[0x2be] & 0x80) == 0)
        {
            byte before = perChar[0x2be];
            int beforeCategory = before & 0xf;
            byte repeat = pad[6];
            byte forward;

            if (menuHeld != 0)
            {
                if ((repeat & 0x10) != 0) perChar[0x2be] = (byte)(before - 1);
                forward = (byte)(pad[6] & 0x40);
            }
            else
            {
                if ((repeat & 0x90) != 0) perChar[0x2be] = (byte)(before - 1);
                forward = (byte)(pad[6] & 0x60);
            }

            if (forward != 0) perChar[0x2be]++;

            sbyte categories = (sbyte)s_MenuLayout_0056a850[(perChar[0x150] & 7) * 9];
            if ((perChar[0x2be] & 0xf) == 0xf) perChar[0x2be] = (byte)(categories - 1);
            if ((perChar[0x2be] & 0xf) >= categories) perChar[0x2be] = 0;

            if (beforeCategory != (perChar[0x2be] & 0xf))
            {
                QuickMenuMoveSound();

                // La nouvelle categorie repart d'un etat par defaut, propre a son genre.
                switch ((sbyte)s_SpeechIconIndex_0056a851[
                            (perChar[0x2be] & 0xf) + (perChar[0x150] & 7) * 9])
                {
                    case 0:
                    case 1:
                    case 2:
                    case 3:
                    case 4:
                    case 5:
                        perChar[0x2bf] = 0;
                        break;

                    case 6:
                        perChar[0x2d0] = 1;
                        perChar[0x2bf] = perChar[0x2b6];
                        break;

                    case 7:
                        perChar[0x2d0] = 7;
                        perChar[0x2bf] = perChar[0x2b6];
                        break;

                    case 8:
                        perChar[0x2d0] = 7;
                        perChar[0x2bf] = 0;
                        break;

                    case 9:
                        perChar[0x2d0] = (byte)s_PartySize_005e9020;
                        perChar[0x2bf] = 0;
                        break;
                }
            }
        }

        // ------------------------------------------------ la liste d'entrees de la categorie
        // Les genres 0 a 5 listent les objets portes dont le mot de type porte le bit de la
        // categorie ; les autres genres gardent la liste que le bloc ci-dessus leur a posee.
        int shown = (sbyte)s_SpeechIconIndex_0056a851[
                        (perChar[0x2be] & 0xf) + (perChar[0x150] & 7) * 9];

        uint slotBit = shown switch
        {
            0 => 0x100u,
            1 => 0x200u,
            2 => 0x400u,
            3 or 4 => 0x800u,
            5 => 0x1000u,
            _ => 0u,                            // inatteignable — voir l'en-tete
        };

        if (shown < 6)
        {
            perChar[0x2d0] = 0;

            for (int i = 0; i < 10; i++)
            {
                byte* item = perChar + 0x300 + i * 0x280;
                if (item[0] == 0 || (*(ushort*)(item + 0x12) & slotBit) == 0) continue;

                perChar[0x2d1 + perChar[0x2d0]] = (byte)i;
                perChar[0x2d0]++;
            }
        }
    }

    /// <summary>
    /// Ghidra: FUN_00523820 @ 0x00523820 — <b>se servir d'un objet porte</b>. Elle retrouve le bloc
    /// du personnage a partir de l'index range en <c>emplacement[8]</c>, puis lance le script de
    /// l'objet <paramref name="item"/> par <c>FUN_00523860</c>.
    ///
    /// <para>Le garde <c>item &lt; 10</c> est celui de l'original : dix objets portes au plus, et
    /// un index hors borne ne fait rien du tout.</para>
    /// </summary>
    private static void UseCarriedItem_00523820(uint* slot, uint item)
    {
        if (item >= 10) return;

        byte* record = GetMainMemPtr() + (((byte*)slot)[8] + 0x78) * 0x2000;
        RunItemScriptSaved_00523860(slot, record, record + item * 0x280 + 0x300);
    }

    /// <summary>
    /// Ghidra: FUN_00523860 @ 0x00523860 — le meme sas que <see cref="RunEntityScript"/> : bascule
    /// l'allocateur de <c>winsys3d</c> sur le tampon de travail le temps du script d'objet, si tant
    /// est qu'il y ait un etat a preserver.
    ///
    /// <para><b>Ghidra perd un parametre dans la seconde branche</b> — elle y appelle
    /// <c>FUN_00523aa0(unaff_retaddr, param_1, param_2, …)</c>, decale d'un cran, et prend le mot
    /// de retour pour un argument. Les deux branches passent les memes trois arguments ; c'est la
    /// forme retenue ici, et <c>FUN_00539190</c> porte le meme defaut sur le meme squelette.</para>
    /// </summary>
    private static void RunItemScriptSaved_00523860(uint* slot, byte* record, byte* item)
    {
        byte* script = item + *(ushort*)(item + 0x80);

        if (Winsys3d.Ordinal_46() < 0)
        {
            RunItemScript_00523AA0(slot, record, item, script);
            return;
        }

        *(int*)Mem.Arena(0x005e9318) = Winsys3d.Ordinal_46();
        Winsys3d.Ordinal_45(GetMainMemPtr() + 0x1c0000);
        RunItemScript_00523AA0(slot, record, item, script);
        Winsys3d.Ordinal_45((void*)(nint)(*(int*)Mem.Arena(0x005e9318)));
    }

    // =====================================================================
    // La machine a opcodes des objets (Ghidra: FUN_00523aa0 et la table PTR_LAB_00564f80).
    //
    // C'est la SECONDE machine a opcodes du jeu. Sa boucle est celle de `RunScript` a la ligne
    // pres — arret sur 0xff, ou des qu'un gestionnaire pose un resultat, sauf l'opcode 2 qui est
    // la branche — mais sa table est autre : 23 opcodes, 22 corps distincts (12 et 19 partagent le
    // meme), de 0x00523b00 a 0x00524170.
    //
    // **Onze de ces vingt-deux corps sont absents de `Blaze.c`.** Ghidra ne les a vus que pris en
    // adresse dans la table, d'ou le prefixe `PTR_LAB_`. Ils sont transcrits depuis le
    // desassemblage, conserve dans `Legacy/Raw/Blaze/FUN_00523aa0-handlers.disasm.txt`.
    //
    // Les quatre arguments que chaque gestionnaire recoit, etablis en croisant les corps decompiles
    // avec les decalages de pile des autres :
    //
    //   slot    l'enregistrement d'entite de 0x9c octets de celui qui se sert de l'objet ;
    //           `slot[0x70]` designe sa cible, ce que les opcodes 16 et 17 posent
    //   record  son bloc par personnage de 0x2000 octets (statistiques, equipement, inventaire)
    //   item    le bloc de 0x280 octets de l'objet employe, dans `record + 0x300 + n * 0x280`
    //   s       le curseur de script, qui vit DANS le bloc d'objet — d'ou les sauts des opcodes
    //           1 et 2, qui sont relatifs a `item` et non a `s`
    // =====================================================================

    /// <summary>
    /// Ghidra: FUN_00523aa0 @ 0x00523aa0 — <b>la machine a opcodes des objets</b>. Jumelle exacte
    /// de <see cref="RunScript"/> : elle s'arrete sur <c>0xff</c>, et aussi des qu'un gestionnaire
    /// pose un resultat non nul — <b>sauf pour l'opcode 2</b>, le seul a continuer malgre un
    /// resultat pose. C'est le mecanisme de condition : un test rend 1, la boucle s'arreterait, et
    /// l'opcode 2 est la branche qui reprend la main.
    /// </summary>
    private static void RunItemScript_00523AA0(uint* slot, byte* record, byte* item, byte* script)
    {
        uint condition = 0;                              // Ghidra: local_4

        for (uint op = *script; op != 0xff && (op == 2 || condition == 0); op = *script)
        {
            script = DispatchItemOp(op, slot, record, item, script, &condition);
        }
    }

    /// <summary>
    /// Ghidra: <c>(*(code *)(&amp;PTR_LAB_00564f80)[opcode])(…)</c> — les 23 gestionnaires.
    ///
    /// <para>Rendue en <c>switch</c> comme <see cref="DispatchScriptOp"/>, et pour la meme raison :
    /// c'est une table de sauts dans l'original, et <c>Strategy.md</c> demande de reconstruire le
    /// flot. L'etendue est <b>deduite</b> : le dword qui suit l'entree 22 est nul.</para>
    ///
    /// <para><b>Un opcode inconnu n'est pas garde dans l'original</b> — il saute dans la table sans
    /// borne, donc au-dela de 22 il lit un pointeur quelconque. Le rendre bruyant ici vaut mieux
    /// qu'un saut dans le vide : c'est le seul endroit ou la transcription s'ecarte, et elle
    /// s'ecarte vers un plantage nomme.</para>
    /// </summary>
    private static byte* DispatchItemOp(
        uint op, uint* slot, byte* record, byte* item, byte* s, uint* result)
        => op switch
        {
            0 => ItemOpConsume(record, item, s),                          // 0x00523b00
            1 => ItemOpJump(item, s),                                     // 0x00523bb0
            2 => ItemOpJumpIf(item, s, result),                           // 0x00523bd0
            3 => ItemOpAluSelf(slot, s, result),                          // 0x00523c00
            4 => ItemOpAluTarget(slot, s, result),                        // 0x00523c30
            5 => ItemOpAluRecord(record, 0x100, s, result),               // 0x00523c70
            6 => ItemOpAluTargetStats(slot, 0, s, result),                // 0x00523cb0
            7 => ItemOpAluRecord(record, 0x200, s, result),               // 0x00523d20
            8 => ItemOpAluTargetStats(slot, 0x100, s, result),            // 0x00523d60
            9 => ItemOpSpawnSelf(slot, s),                                // 0x00523dd0
            10 => ItemOpSpawnTarget(slot, s),                             // 0x00523e10
            11 => ItemOpAluBank(s, result),                               // 0x00523e50
            12 => ItemOpParticleSelf(slot, s),                            // 0x00524060
            13 => ItemOpAluEquipped(record, s, result),                   // 0x00523e80
            14 => ItemOpCast(slot, s),                                    // 0x00523ed0
            15 => ItemOpRefuseSound(s),                                   // 0x00523f00
            16 => ItemOpPickTargetByIndex(slot, s, result),               // 0x00523f10
            17 => ItemOpPickTargetBySearch(slot, s, result),              // 0x00523f80
            18 => ItemOpApplyEffect(slot, item, s, result),               // 0x00523fc0
            19 => ItemOpParticleSelf(slot, s),                            // 0x00524060, le meme
            20 => ItemOpParticleTarget(slot, s),                          // 0x005240d0
            21 => ItemOpSound(s),                                         // 0x00524140
            22 => ItemOpOpenItemMenu(s),                                  // 0x00524170
            _ => throw new NotImplementedException(
                     $"Script d'objet : opcode {op} hors des 23 de PTR_LAB_00564f80. "
                     + "L'original saute dans la table sans borne ; ici on le dit."),
        };

    /// <summary>Ghidra: LAB_00523b00 — <b>consommer l'objet</b>, avec une chance sur cent de
    /// <c>s[1]</c>.
    ///
    /// <para>Le tirage rate ne fait rien du tout. Reussi, il decremente le compte de l'objet
    /// (<c>item[0x10]</c>, un mot) et, <b>seulement si ce compte tombe pile a zero</b>, vide
    /// l'emplacement puis reconstruit deux choses : la liste d'inventaire de <c>record[0x2c0]</c> /
    /// <c>+0x2c1</c>, et les cinq emplacements d'equipement de <c>+0x2b0</c>, dont celui qui
    /// designait l'objet retire repasse a <c>0xff</c>.</para>
    ///
    /// <para>La liste de <c>+0x2c0</c> n'est pas celle du menu rapide (<c>+0x2d0</c>/<c>+0x2d1</c>,
    /// voir <see cref="TickQuickMenu_00530070"/>) : celle-ci recense tous les objets portes, celle-la
    /// ceux d'une categorie.</para>
    ///
    /// <para>Un compte deja nul retombe a <c>0xffff</c> et l'objet survit : c'est ce que fait
    /// l'original, le test porte sur l'egalite a zero et non sur le signe.</para></summary>
    private static byte* ItemOpConsume(byte* record, byte* item, byte* s)
    {
        if (CrtRand() % 100 >= s[1]) return s + 2;        // Ghidra: FUN_00547140

        if (--*(ushort*)(item + 0x10) != 0) return s + 2;

        item[0] = 0;
        record[0x2c0] = 0;

        for (int i = 0; i < 10; i++)
        {
            byte* candidate = record + 0x300 + i * 0x280;

            if (candidate[0] != 0)
            {
                record[0x2c1 + record[0x2c0]] = (byte)i;
                record[0x2c0]++;
                continue;
            }

            // L'emplacement vide qu'on vient de liberer, et lui seul, deshabille le personnage.
            if (candidate != item) continue;

            byte* worn = record + 0x2b0;
            for (int k = 5; k != 0; k--, worn++)
            {
                if (*worn == i) { *worn = 0xff; break; }
            }
        }

        return s + 2;
    }

    /// <summary>Ghidra: LAB_00523bb0 — le saut. La destination est un decalage de <b>seize bits</b>
    /// depuis le debut du <b>bloc d'objet</b>, pas depuis le curseur : le script vit dans ce bloc,
    /// donc c'est bien lui la base.</summary>
    private static byte* ItemOpJump(byte* item, byte* s) => item + (s[1] | (s[2] << 8));

    /// <summary>Ghidra: LAB_00523bd0 — le saut conditionnel, et <b>le seul opcode que la boucle
    /// laisse passer quand un resultat est pose</b>. Il saute si la condition est non nulle, et la
    /// remet a zero du meme geste ; sinon il avance de trois.</summary>
    private static byte* ItemOpJumpIf(byte* item, byte* s, uint* result)
    {
        if (*result == 0) return s + 3;

        byte* destination = item + (s[1] | (s[2] << 8));
        *result = 0;
        return destination;
    }

    /// <summary>Ghidra: FUN_00523c00 — l'unite arithmetique sur <b>l'enregistrement d'entite</b> de
    /// celui qui se sert de l'objet.</summary>
    private static byte* ItemOpAluSelf(uint* slot, byte* s, uint* result)
    {
        *result = ApplyScriptOp((byte*)slot + s[1], s[2], s[3]) ? 1u : 0u;
        return s + 4;
    }

    /// <summary>Ghidra: FUN_00523c30 — la meme, sur l'enregistrement de <b>la cible</b>
    /// (<c>slot[0x70]</c>).</summary>
    private static byte* ItemOpAluTarget(uint* slot, byte* s, uint* result)
    {
        byte* target = *(byte**)((byte*)slot + 0x70);
        *result = ApplyScriptOp(target + s[1], s[2], s[3]) ? 1u : 0u;
        return s + 4;
    }

    /// <summary>Ghidra: FUN_00523c70 (<paramref name="bank"/> = 0x100) et FUN_00523d20
    /// (0x200) — l'unite arithmetique sur l'une des deux banques du <b>bloc par personnage</b>.
    /// Deux corps identiques a la constante pres dans l'original.</summary>
    private static byte* ItemOpAluRecord(byte* record, int bank, byte* s, uint* result)
    {
        *result = ApplyScriptOp(record + bank + s[1], s[2], s[3]) ? 1u : 0u;
        return s + 4;
    }

    /// <summary>Ghidra: LAB_00523cb0 (<paramref name="bank"/> = 0) et LAB_00523d60 (0x100) —
    /// l'unite arithmetique sur le <b>bloc de statistiques de la cible</b>.
    ///
    /// <para>La resolution du bloc est celle de <see cref="StatusBubbleHeight_00538BC0"/>, et elle
    /// depend du bit <c>0x800000</c> : un membre du groupe passe par <c>MainMem + 0xf0100</c>, toute
    /// autre entite par <see cref="s_EntityStatBlocks_005ea560"/>. Passer par une vue d'arene ici
    /// serait le defaut d'aliasing deja resolu une fois pour cette table.</para></summary>
    private static byte* ItemOpAluTargetStats(uint* slot, int bank, byte* s, uint* result)
    {
        byte* target = *(byte**)((byte*)slot + 0x70);

        byte* stats = (*(uint*)target & 0x800000) != 0
            ? GetMainMemPtr() + 0xf0100 + target[8] * 0x2000
            : s_EntityStatBlocks_005ea560 + target[8] * 0x120;

        *result = ApplyScriptOp(stats + bank + s[1], s[2], s[3]) ? 1u : 0u;
        return s + 4;
    }

    /// <summary>Ghidra: FUN_00523dd0 — <b>engendre un effet sur soi</b>. Le mot de <c>+0x0a</c> est
    /// mis a zero le temps de l'appel puis restaure : c'est ce qui empeche l'effet d'heriter du
    /// compteur de son parent.</summary>
    private static byte* ItemOpSpawnSelf(uint* slot, byte* s)
    {
        byte* e = (byte*)slot;
        ushort kept = *(ushort*)(e + 0x0a);
        *(ushort*)(e + 0x0a) = 0;
        SpawnEffectEntity(e, s[1], s[2], s[3]);          // Ghidra: FUN_0047a9d0
        *(ushort*)(e + 0x0a) = kept;
        return s + 4;
    }

    /// <summary>Ghidra: LAB_00523e10 — la meme, sur <b>la cible</b>.</summary>
    private static byte* ItemOpSpawnTarget(uint* slot, byte* s)
    {
        byte* target = *(byte**)((byte*)slot + 0x70);
        ushort kept = *(ushort*)(target + 0x0a);
        *(ushort*)(target + 0x0a) = 0;
        SpawnEffectEntity(target, s[1], s[2], s[3]);     // Ghidra: FUN_0047a9d0
        *(ushort*)(target + 0x0a) = kept;
        return s + 4;
    }

    /// <summary>Ghidra: FUN_00523e50 — l'unite arithmetique sur <b>la banque de variables de
    /// script</b>, celle que les deux machines partagent.</summary>
    private static byte* ItemOpAluBank(byte* s, uint* result)
    {
        *result = ApplyScriptOp(Mem.Arena(0x005e9060) + s[1], s[2], s[3]) ? 1u : 0u;
        return s + 4;
    }

    /// <summary>Ghidra: FUN_00523e80 — l'unite arithmetique sur le bloc de <b>l'objet equipe</b> a
    /// l'emplacement <c>s[1]</c> : <c>record[0x2b0 + s[1]]</c> donne l'indice, et le bloc suit a
    /// <c>record + 0x300 + indice * 0x280</c>. Cinq octets d'opcode, seul de son espece.</summary>
    private static byte* ItemOpAluEquipped(byte* record, byte* s, uint* result)
    {
        byte* equipped = record + 0x300 + record[0x2b0 + s[1]] * 0x280;
        *result = ApplyScriptOp(equipped + s[2], s[3], s[4]) ? 1u : 0u;
        return s + 5;
    }

    /// <summary>Ghidra: FUN_00523ed0 — <b>declenche un sort ou un effet d'objet</b> par
    /// <see cref="CastSpell_0053A980"/>. Les quatre octets de script sont pousses en <b>zero</b>
    /// extension (<c>xor</c> puis <c>mov al</c> dans le binaire), donc les deux tests de signe de
    /// l'appelee ne peuvent pas se declencher par ce chemin — ils servent a ses autres
    /// appelants.</summary>
    private static byte* ItemOpCast(uint* slot, byte* s)
    {
        CastSpell_0053A980(slot, s[1], s[2], s[3], s[4]);
        return s + 5;
    }

    /// <summary>Ghidra: LAB_00523f00 — le son de refus, et rien d'autre. Un octet
    /// d'opcode.</summary>
    private static byte* ItemOpRefuseSound(byte* s)
    {
        QuickMenuRefuseSound();                          // Ghidra: FUN_0053dbc0
        return s + 1;
    }

    /// <summary>Ghidra: LAB_00523f10 — <b>choisit la cible par son indice</b>, pris dans la banque
    /// de variables a <c>s[2]</c> et non dans le script : c'est donc une cible calculee.
    ///
    /// <para><c>s[1]</c> choisit la famille : zero les quatre emplacements de groupe
    /// (<see cref="Input.s_SlotFlags_005e93c0"/>), non nul les trente-deux entites de scene
    /// (<c>0x005ecaa0</c>). Les deux tables ont le meme pas de <c>0x9c</c>. Un indice hors borne
    /// <b>pose la condition a 1</b> et laisse la cible inchangee — c'est le seul opcode de choix
    /// qui signale son echec.</para></summary>
    private static byte* ItemOpPickTargetByIndex(uint* slot, byte* s, uint* result)
    {
        uint index = Mem.Arena(0x005e9060)[s[2]];

        if (s[1] != 0)
        {
            if (index >= 0x20) { *result = 1; return s + 3; }
            *(byte**)((byte*)slot + 0x70) = Mem.Entity(0x005ecaa0) + index * 0x9c;
        }
        else
        {
            if (index >= 4) { *result = 1; return s + 3; }
            *(byte**)((byte*)slot + 0x70) = Inp.s_SlotFlags_005e93c0 + index * 0x9c;
        }

        return s + 3;
    }

    /// <summary>Ghidra: LAB_00523f80 — <b>choisit la cible par recherche</b>.
    ///
    /// <para>Le tour de passe-passe est dans les trois champs sauves : <c>+0x74</c> est pointe sur
    /// l'entite elle-meme le temps de l'appel, parce que <c>FUN_00474ad0</c> cherche depuis
    /// <c>[+0x74]</c> et non depuis son argument ; puis le resultat, que la recherche a range en
    /// <c>+0x78</c>, est recopie en <c>+0x70</c>, et <c>+0x74</c> comme <c>+0x78</c> sont
    /// restaures. La cible du script est donc <b>ce que la recherche a trouve</b>, sans que rien
    /// d'autre de l'entite ne bouge.</para></summary>
    private static byte* ItemOpPickTargetBySearch(uint* slot, byte* s, uint* result)
    {
        byte* e = (byte*)slot;

        byte* keptWatched = *(byte**)(e + 0x74);
        byte* keptFound = *(byte**)(e + 0x78);

        *(byte**)(e + 0x74) = e;
        *result = PickTargetBySearch_00474AD0(slot, s[1]);

        byte* found = *(byte**)(e + 0x78);
        *(byte**)(e + 0x74) = keptWatched;
        *(byte**)(e + 0x70) = found;
        *(byte**)(e + 0x78) = keptFound;

        return s + 2;
    }

    /// <summary>Ghidra: &amp;DAT_0052403c — <b>la famille de l'objet</b>, indexee par le mot de
    /// <c>item[0x84]</c> (0 a 0x15). Relevee verbatim. Elle ne sert qu'a choisir, par la table de
    /// sauts de <c>0x00524014</c>, entre les deux seules valeurs que l'opcode 18 passe en troisieme
    /// argument : <b>0 ou 1</b>. Les familles 1, 3, 5 et 7 donnent 1, les autres 0.</summary>
    private static readonly byte[] s_ItemFamily_0052403c =
    [
        0x00, 0x00, 0x01, 0x01, 0x01, 0x02, 0x02, 0x03, 0x03, 0x03, 0x03,
        0x04, 0x05, 0x05, 0x05, 0x06, 0x06, 0x07, 0x07, 0x07, 0x07, 0x08,
    ];

    /// <summary>Ghidra: LAB_00523fc0 — <b>applique un effet</b> de la table de 48 fonctions de
    /// <c>0x0056d4e0</c>, choisi par <c>s[1]</c>.
    ///
    /// <para>Le troisieme argument vaut 1 pour les familles impaires 1, 3, 5 et 7 de
    /// <see cref="s_ItemFamily_0052403c"/>, et 0 partout ailleurs — <b>y compris</b> quand
    /// <c>item[0x84]</c> depasse 0x15, ou le binaire saute directement a la branche zero. Le detour
    /// par une table de sauts a neuf entrees dont sept sont des doublons est ce que le compilateur
    /// a fait d'un <c>switch</c> ; le resultat tient en une comparaison.</para></summary>
    private static byte* ItemOpApplyEffect(uint* slot, byte* item, byte* s, uint* result)
    {
        ushort kind = *(ushort*)(item + 0x84);

        uint flag = 0;
        if (kind <= 0x15)
        {
            byte family = s_ItemFamily_0052403c[kind];
            flag = family == 1 || family == 3 || family == 5 || family == 7 ? 1u : 0u;
        }

        byte* target = *(byte**)((byte*)slot + 0x70);
        *result = ApplyItemEffect_0056D4E0(s[1], slot, target, flag);
        return s + 2;
    }

    /// <summary>Ghidra: FUN_00524060 (opcodes 12 et 19, le meme corps) — <b>pose une particule</b>
    /// a la position de celui qui se sert de l'objet.
    ///
    /// <para><c>s[1]</c> dit la largeur avec laquelle lire la banque de variables a <c>s[2]</c> :
    /// 0 octet, 1 mot, 2 double mot. <b>Toute autre valeur passe le curseur de script lui-meme</b>
    /// comme parametre — le registre n'est pas initialise dans cette branche, et Ghidra le rend
    /// exactement ainsi (<c>uVar2 = param_4</c>). Transcrit tel quel.</para></summary>
    private static byte* ItemOpParticleSelf(uint* slot, byte* s)
    {
        SpawnParticle_0050F070((uint*)((byte*)slot + 0x1c), ScriptBankValue(s), s[3]);
        return s + 4;
    }

    /// <summary>Ghidra: FUN_005240d0 (opcode 20) — la meme, a la position de <b>la cible</b>.</summary>
    private static byte* ItemOpParticleTarget(uint* slot, byte* s)
    {
        byte* target = *(byte**)((byte*)slot + 0x70);
        SpawnParticle_0050F070((uint*)(target + 0x1c), ScriptBankValue(s), s[3]);
        return s + 4;
    }

    /// <summary>La lecture de banque commune aux opcodes 12, 19 et 20 — voir
    /// <see cref="ItemOpParticleSelf"/> pour la quatrieme branche, celle qui n'initialise
    /// rien.</summary>
    private static uint ScriptBankValue(byte* s)
    {
        byte* bank = Mem.Arena(0x005e9060);

        return s[1] switch
        {
            0 => bank[s[2]],
            1 => *(ushort*)(bank + s[2]),
            2 => *(uint*)(bank + s[2]),
            _ => (uint)(nuint)s,
        };
    }

    /// <summary>Ghidra: FUN_00524140 — <b>joue un son</b>. Le meme mot sert de gain gauche et de
    /// gain droit : l'original lit deux fois <c>s+4</c>, ce n'est pas une coquille de
    /// transcription.</summary>
    private static byte* ItemOpSound(byte* s)
    {
        Aud.PlaySoundEffect(s[1], *(ushort*)(s + 2), *(ushort*)(s + 4), *(ushort*)(s + 4));
        return s + 6;
    }

    /// <summary>Ghidra: LAB_00524170 — <b>ouvre le menu objets</b>, ecran complet, depuis le script
    /// de l'objet. Le corps est celui de <see cref="RunItemMenuState"/> (<c>FUN_00524180</c>)
    /// duplique par le compilateur, a ceci pres que le second appel y est un saut de queue.
    ///
    /// <para><b>TODO(REVERSE) — cet opcode rend une valeur qui n'est pas un curseur de script.</b>
    /// Le saut de queue fait de la valeur rendue celle de <c>FUN_00524320</c>, dont le dernier
    /// appel est <c>FUN_00524190</c> — <see cref="DrawItemMenuTitle"/>, qui rend un <b>curseur de
    /// liste d'affichage</b>. La boucle de la machine dereference ensuite ce pointeur comme un
    /// opcode. C'est un defaut de 1998, latent : il ne se manifeste que si un script d'objet emet
    /// reellement l'opcode 22, ce qu'on n'a pas observe. Il n'est donc pas verse dans
    /// <c>legacy-bug.md</c>, qui ne recense que l'observe.</para>
    ///
    /// <para>La transcription s'arrete au bord : elle fait les deux appels de l'original et leve
    /// plutot que d'inventer une valeur de retour. Le jour ou le jeu y passe, la levee dira ou
    /// regarder.</para></summary>
    private static byte* ItemOpOpenItemMenu(byte* s)
    {
        _ = s;
        LoadItemMenuResources();                         // Ghidra: FUN_00524210
        RunItemMenuFrameLoop();                          // Ghidra: FUN_00524320

        throw new NotImplementedException(
            "Script d'objet, opcode 22 (LAB_00524170) : l'ecran du menu objets a tourne, et "
            + "l'original rend ici la valeur de FUN_00524320 — c'est-a-dire le curseur de liste "
            + "d'affichage de FUN_00524190, pas un curseur de script. La machine le dereference "
            + "ensuite comme un opcode. Defaut de 1998, jamais observe jusqu'ici : voir le "
            + "TODO(REVERSE) sur ItemOpOpenItemMenu avant de choisir quoi en faire.");
    }

    /// <summary>Ghidra: FUN_0050f070 @ 0x0050f070 — <b>pose une particule</b> dans le pool de 64
    /// emplacements de <c>0x005e9b60</c>, pas <c>0x28</c>.
    ///
    /// <para>Le mot d'etat de <c>+0x24</c> empile trois choses : <c>0x14</c> en octet haut, qui est
    /// le compte a rebours que <c>FUN_0050f0d0</c> decremente par image, le genre en octet 2, et
    /// l'indice de l'emplacement en octet 1. Le pool plein ne fait rien du tout.</para></summary>
    private static void SpawnParticle_0050F070(uint* position, uint kind, byte flavour)
    {
        int index = AllocEntitySlot((ushort*)Mem.Arena(0x005e99e0));   // Ghidra: FUN_00532740
        if (index < 0) return;

        byte* entry = Mem.Arena(0x005e9b60) + index * 0x28;

        *(ushort*)(entry + 0x0c) = (ushort)kind;
        *(uint*)(entry + 0x24) = ((0x1400u | flavour) << 8 | (uint)(index & 0xff)) << 8;

        *(uint*)(entry + 0) = position[0];
        *(uint*)(entry + 4) = position[1];
        *(uint*)(entry + 8) = position[2];
    }

    /// <summary>Ghidra: FUN_0053a980 @ 0x0053a980 — <b>declenche le sort ou l'effet d'objet</b>
    /// designe par sa famille et son indice.
    ///
    /// <para>L'entree de description vit dans le repertoire de ressources : la table de
    /// <c>+0x9c</c> donne un tableau par famille, indexe au pas de <c>0x30</c>. Ses octets
    /// <c>+0x10</c>, <c>+0x11</c> et <c>+0x12</c> fournissent le genre d'effet et deux parametres —
    /// et ce sont eux qui servent quand l'appelant passe <c>-1</c>, ce que le script d'objet ne
    /// fait jamais mais que ses autres appelants font.</para>
    ///
    /// <para>Comme <see cref="ItemOpSpawnSelf"/>, elle neutralise trois champs de l'entite le temps
    /// de l'appel — <c>+0x74</c>, <c>+0x78</c> et le mot de <c>+0x0a</c> — puis les restaure.
    /// L'entree trouvee est rendue : deux appelants la relisent.</para></summary>
    private static byte* CastSpell_0053A980(uint* caster, int family, int index, int a, int b)
    {
        byte* e = (byte*)caster;

        // Le mot de +6 porte les DEUX : la famille en octet haut, l'indice en octet bas. Ghidra
        // l'ecrit `CONCAT31((int3)param_2, (char)param_3)` tronque en `short`, ce qui se lit mal ;
        // le binaire est sans ambiguite (`mov dh,cl ; mov dl,al ; mov [esi+6],dx` en 0x0053a991).
        *(short*)(e + 6) = (short)(((family & 0xff) << 8) | (index & 0xff));

        byte* keptWatched = *(byte**)(e + 0x74);
        byte* keptFound = *(byte**)(e + 0x78);
        ushort keptCounter = *(ushort*)(e + 0x0a);

        byte* entry = *(byte**)(*(byte**)(Mem.s_MainResourceDirectory_005e97c4 + 0x9c) + family * 4)
                      + index * 0x30;

        *(byte**)(e + 0x74) = e;
        *(byte**)(e + 0x78) = null;
        *(ushort*)(e + 0x0a) = 0;

        if (a < 0) a = entry[0x11];
        if (b < 0) b = entry[0x12];

        SpawnEffectEntity(e, entry[0x10], (byte)a, b);   // Ghidra: FUN_0047a9d0

        *(byte**)(e + 0x78) = keptFound;
        *(byte**)(e + 0x74) = keptWatched;
        *(ushort*)(e + 0x0a) = keptCounter;

        return entry;
    }

    /// <summary>Ghidra: FUN_00474ad0 @ 0x00474ad0 — <b>la recherche de cible</b> de l'opcode 17.
    /// Deux balayages selon que la source est un membre du groupe ou une entite de scene, croises
    /// avec l'argument : elle cherche donc <b>dans le camp d'en face</b>.</summary>
    private static uint PickTargetBySearch_00474AD0(uint* slot, byte mode)
        => throw new NotImplementedException(
            $"FUN_00474ad0 (0x00474ad0), mode {mode} : non transcrite. 47 lignes dans Blaze.c, "
            + "mais elle ouvre le sous-arbre de ciblage : FUN_00519af0 (52 l., le balayage des "
            + "entites de scene par cellule) et FUN_00519c30 (63 l., le balayage du groupe), qui "
            + "tirent a leur tour FUN_00535a90, FUN_00538af0 et FUN_005238e0. C'est le ciblage de "
            + "combat, pas le script d'objet — il se fera pour lui-meme.");

    /// <summary>Ghidra: <c>(*(code *)(&amp;DAT_0056d4e0)[genre])(…)</c> — <b>la table des 48
    /// effets</b>, de <c>0x0053afb0</c> a <c>0x0053cdf0</c>. L'etendue est deduite : le dword qui
    /// suit la 48e entree vaut 1, debut d'une table de masques de bits.</summary>
    private static uint ApplyItemEffect_0056D4E0(byte kind, uint* source, byte* target, uint flag)
        => throw new NotImplementedException(
            $"Table d'effets 0x0056d4e0, genre {kind} (drapeau {flag}) : non transcrite. "
            + "48 fonctions, 0x0053afb0..0x0053cdf0, chacune une alteration d'etat ou un degat "
            + "applique a la cible ; la premiere, FUN_0053afb0, pose le bit 0x8000000 sur le mot "
            + "d'etat de la cible apres FUN_00538870. C'est le sous-systeme des effets, atteint "
            + "aussi par les sorts — il se fera pour lui-meme, pas au fil du script d'objet.");

    /// <summary>Ghidra: FUN_0051a020 @ 0x0051a020 (221 l.) — l'integration du deplacement au sol,
    /// appelee quand le personnage n'est pas en l'air.</summary>
    private static void ApplyGroundMotion_0051A020(uint* slot, byte* entry, byte* perChar, byte* pad, byte* anim)
    {
        byte* s = (byte*)slot;

        switch (perChar[0x150] & 7)
        {
            // ------------------------------------------------ la marche et sa variante
            case 0:
            case 6:
                if (pad[0x0e] != 0
                    && (sbyte)perChar[0x2b2] != -1
                    && s_Unknown_00566c84 != 0
                    && (*slot & 0x44) == 0
                    && (*(uint*)(perChar + 0x140) & 0x400003c0) == 0)
                {
                    *(uint*)(s + 0x18) = 5;
                    *slot = (*slot & 0xfeffffff) | 4;
                }

                if ((*(ushort*)pad & *(ushort*)(perChar + 0x1fc4)) == 0 && (*slot & 0x2000000) != 0)
                {
                    *slot &= 0xfffffffb;
                }

                if (*(short*)(s + 0x18) == 5)
                {
                    *(int*)(s + 0x5c) = 0;
                    return;
                }

                break;

            // ------------------------------------------------ les quatre postures d'incantation
            case 1:
            case 3:
            case 5:
            case 7:
            {
                byte* spellSet = *(byte**)(*(byte**)(Mem.s_MainResourceDirectory_005e97c4 + 0x9c)
                                           + perChar[0x2b5] * 4);
                uint held = *slot;

                if ((held & 4) == 0)
                {
                    if ((held & 0x40) != 0) return;
                    if ((*(uint*)(perChar + 0x140) & 0x400003e8) != 0) return;

                    if ((*(ushort*)(pad + 2) & 1) != 0 && s_Unknown_00566c84 != 0)
                    {
                        // Annulation : l'incantation part quand meme, mais sans effet retenu.
                        *slot = held | 0x1000004;
                        *(uint*)(s + 0x18) = 5;
                        entry[0x0b] = 0;
                        *(ushort*)(pad + 0x0c) = 0;
                        *(ushort*)(pad + 0x0e) = 0;
                        *(short*)(s + 0x14) = 0;
                        SpawnCastEntity_0047AAE0(s, 0xbd, 0, 0);
                        return;
                    }

                    if ((*(ushort*)(perChar + 0x1fc4) & *(ushort*)(pad + 2)) == 0) return;
                    if (s_Unknown_00566c84 == 0) return;

                    *(uint*)(s + 0x18) = 5;
                    *slot = held | 0x1000004;

                    byte* spell = spellSet + perChar[0x2b6] * 0x30;
                    *(ushort*)(s + 0x14) = spell[0x13];
                    *(ushort*)(perChar + 0x204) = *(ushort*)(spell + 0x14);
                    SpawnCastEntity_0047AAE0(s, 0xbd, 0, 0);
                    *(uint*)Mem.Arena(0x005e99c0) = 0;
                    TriggerEquippedItems_005238E0(slot, 5);
                    return;
                }

                *(int*)(s + 0x5c) = 0;

                if (*(short*)(s + 0x18) == 5)
                {
                    if (*(short*)(s + 0x14) == 0)
                    {
                        if ((*(ushort*)pad & 1) == 0)
                        {
                            // Le bouton est relache : on choisit la cible et on passe a l'etat 6.
                            *slot = held & 0xfeffffff;
                            *(uint*)(s + 0x18) = 6;
                            *(short*)(s + 0x14) = 5;

                            int chosen = PickCastTarget_0051A5D0(entry, perChar);
                            bool armed = false;

                            if (chosen >= 0)
                            {
                                uint* mask = (uint*)(perChar + ((chosen >> 5) + 0x58 + perChar[0x2b5] * 2) * 4);
                                if ((*mask & (1u << (chosen & 0x1f))) != 0)
                                {
                                    *(ushort*)(perChar + 0x204) = *(ushort*)(spellSet + chosen * 0x30 + 0x14);
                                    *(short*)(s + 0x16) = (short)chosen;
                                    armed = true;
                                }
                            }

                            if (!armed)
                            {
                                *slot = (*slot & 0xfffffffb) | 0x1000000;
                                *(uint*)(s + 0x18) = 0;
                            }
                        }
                        else if ((*(ushort*)(pad + 2) & 0xf000) != 0 && entry[0x0b] < 0x10)
                        {
                            // Le bouton est tenu : chaque direction s'empile dans la combinaison.
                            entry[0x0c + entry[0x0b]] = (byte)((*(ushort*)(pad + 2) >> 8) & 0xf0);
                            entry[0x0b]++;
                        }
                    }
                    else
                    {
                        if ((*(ushort*)pad & *(ushort*)(perChar + 0x1fc4)) == 0)
                        {
                            *slot = (held & 0xfffffffb) | 0x1000000;
                            *(uint*)(s + 0x18) = 0;
                        }
                        else
                        {
                            short remaining = (short)(*(short*)(s + 0x14) - 1);
                            *(short*)(s + 0x14) = remaining;
                            if (remaining == 0)
                            {
                                *(uint*)(s + 0x18) = 6;
                                *slot = held & 0xfeffffff;
                                *(short*)(s + 0x14) = 5;

                                uint index = perChar[0x2b6];
                                uint* mask = (uint*)(perChar + (((int)index >> 5) + 0x58 + perChar[0x2b5] * 2) * 4);
                                if ((*mask & (1u << (perChar[0x2b6] & 0x1f))) == 0) index = 0xffffffff;
                                *(short*)(s + 0x16) = (short)index;
                            }
                        }
                    }
                }

                if (*(short*)(s + 0x18) == 6)
                {
                    held = *slot;
                    if ((held & 0x2000000) != 0)
                    {
                        *(short*)(s + 0x14) = (short)(*(short*)(s + 0x14) - 1);
                        if (*(short*)(s + 0x14) == 0)
                        {
                            *(uint*)(s + 0x18) = 0;
                            *slot = (held & 0xfffffffb) | 0x1000000;
                            return;
                        }

                        *slot = held & 0xfeffffff;

                        // L'etat et l'image sont poses d'un seul dword : l'animation demarre a sa
                        // DERNIERE image.
                        *(uint*)(s + 0x18) = ((uint)(*(ushort*)(anim + 0x16) - 1) << 0x10) | 6;

                        if (*(short*)(s + 0x16) >= 0)
                        {
                            *(uint*)Mem.Arena(0x005e99c0) = 0;
                            TriggerEquippedItems_005238E0(slot, 6);

                            // Le cout n'est preleve que si la reserve le couvre — sinon
                            // l'incantation part sans rien consommer ni produire.
                            if (*(ushort*)(perChar + 0x204) <= (int)*(short*)(perChar + 0x14e))
                            {
                                *(ushort*)(perChar + 0x14e) =
                                    (ushort)(*(short*)(perChar + 0x14e) - *(ushort*)(perChar + 0x204));
                                CastSpell_0053A980(slot, perChar[0x2b5], *(short*)(s + 0x16), -1, -1);
                            }

                            *(ushort*)(s + 0x16) = 0xffff;
                            return;
                        }
                    }
                }

                break;
            }

            // ------------------------------------------------ la charge
            case 2:
                if (*(short*)(s + 0x18) != 5 || (*slot & 0x2000000) != 0)
                {
                    *(short*)(s + 0x14) = 0;
                    *slot &= 0xfffffffb;
                }

                if (*(short*)(s + 0x14) == 0)
                {
                    if (pad[0x0e] != 0
                        && (*slot & 0x44) == 0
                        && (*(uint*)(perChar + 0x140) & 0x400003c0) == 0)
                    {
                        *(ushort*)(pad + 2) &= 0x7fff;
                        *(uint*)(s + 0x18) = 5;
                        *(short*)(s + 0x14) = 0x10;
                        *slot = (*slot & 0xfeffffff) | 4;
                        *(short*)(s + 0x98) = *(short*)(s + 0x32);
                    }
                }
                else
                {
                    short remaining = (short)(*(short*)(s + 0x14) - 1);
                    *(short*)(s + 0x14) = remaining;
                    if (remaining == 0) *slot &= 0xfffffffb;
                }

                if (*(short*)(s + 0x18) == 5)
                {
                    uint posture = *(uint*)(perChar + 0x140);
                    int scale = 0x1000;
                    if ((posture & 0x4000) != 0) scale = 0x1333;
                    if ((posture & 0x8000) != 0) scale = 0xccc;
                    if ((posture & 4) != 0) scale = 0x800;

                    // La charge decelere toute seule : la vitesse suit le compte a rebours.
                    *(int*)(s + 0x5c) = *(short*)(s + 0x14) * 0x2000 * scale >> 0xc;
                    return;
                }

                break;

            // ------------------------------------------------ l'objet consommable
            case 4:
                if ((*slot & 0x44) == 0
                    && (*(ushort*)pad & *(ushort*)(perChar + 0x1fc4)) != 0
                    && (*(ushort*)(pad + 2) & *(ushort*)(perChar + 0x1fc4)) != 0
                    && s_Unknown_00566c84 != 0
                    && (*(uint*)(perChar + 0x140) & 0x400003c0) == 0)
                {
                    *(uint*)(s + 0x18) = 5;
                    *slot = (*slot & 0xfcffffff) | 4;
                    *(short*)(s + 0x14) = 5;
                }

                if ((*slot & 4) != 0)
                {
                    if ((*slot & 0x2000000) != 0)
                    {
                        if (*(short*)(s + 0x14) == 5)
                        {
                            // Ghidra lit ici les huit octets de +0x160 comme un COMPTE par
                            // emplacement, la ou la posture d'incantation lit la meme region
                            // comme un MASQUE de bits. Les deux vues coexistent dans l'original ;
                            // transcrites telles quelles. TODO(REVERSE) : etablir laquelle est la
                            // bonne, ou si les deux `kind` ne se recouvrent jamais.
                            byte* charges = perChar + 0x160 + perChar[0x2b5] * 8;
                            sbyte left = (sbyte)charges[perChar[0x2b6]];
                            if (left != 0)
                            {
                                charges[perChar[0x2b6]] = (byte)(left - 1);
                                s[6] = perChar[0x2b6];
                                *slot |= 0x800;
                                CastSpell_0053A980(slot, perChar[0x2b5], perChar[0x2b6], -1, -1);
                            }
                        }

                        *(short*)(s + 0x14) = (short)(*(short*)(s + 0x14) - 1);
                        if (*(short*)(s + 0x14) != 0)
                        {
                            *slot &= 0xfeffffff;
                            ushort frames = *(ushort*)(anim + 0x16);
                            *(int*)(s + 0x5c) = 0;
                            *(uint*)(s + 0x18) = ((uint)(frames - 1) << 0x10) | 5;
                            return;
                        }

                        *(uint*)(s + 0x18) = 0;
                        *slot = (*slot & 0xfffffffb) | 0x1000000;
                    }

                    *(int*)(s + 0x5c) = 0;
                    return;
                }

                break;

            default:
                *slot &= 0xfffffffb;
                break;
        }
    }

    /// <summary>
    /// Ghidra: FUN_0047aae0 @ 0x0047aae0 — <b>fait naitre une entite d'incantation</b> dans la table
    /// <c>DAT_005edee0</c>, en recopiant les 0x27 dwords du lanceur puis en remplacant six champs.
    /// Jumelle de <c>SpawnEffectEntity</c> (<c>FUN_0047a9d0</c>) a la table pres.
    ///
    /// <para>Le masque final <c>&amp; 0x10e82f02 | 0x80109000</c> ne garde du mot d'etat copie que ce
    /// qui a un sens pour une entite d'effet.</para>
    /// </summary>
    /// <returns>1 si un emplacement etait libre, 0 sinon.</returns>
    private static uint SpawnCastEntity_0047AAE0(byte* source, byte subtype, byte param3, int param4)
    {
        int index = AllocEntitySlot((ushort*)Mem.Entity(0x006007a0));
        if (index < 0) return 0;

        byte* born = Mem.Entity(0x005edee0) + index * 0x9c;
        Mem.CopyDwords((uint*)source, (uint*)born, 0x27);

        born[0x36] |= 0x80;
        born[0x08] = (byte)index;
        born[0x05] = subtype;
        *(byte**)(born + 0x6c) = source;
        born[0x0b] = param3;
        if (param4 >= 0) born[0x0a] = (byte)param4;

        *(uint*)born = (*(uint*)born & 0x10e82f02) | 0x80109000;
        *(ushort*)(born + 0x10) = 0;
        return 1;
    }

    /// <summary>
    /// Ghidra: FUN_004765d0 @ 0x004765d0 — <b>l'aureole d'incantation</b> : le gestionnaire du
    /// sous-type <c>0xbd</c>, creneau 189 de la table statique <see cref="s_StaticEntityHandlers_00551f30"/>.
    /// 350 octets, <b>absente de <c>Blaze.c</c></b>, transcrite au desassembleur — le releve est
    /// garde sous <c>Legacy/Raw/Blaze/FUN_004765D0.asm</c>.
    ///
    /// <para>
    /// C'est le pendant vivant de <see cref="SpawnCastEntity_0047AAE0"/> : ce que
    /// <see cref="ApplyGroundMotion_0051A020"/> fait naitre a chaque fois qu'un personnage prend la
    /// posture d'incantation (<c>+0x18 == 5</c>), et ce qui plantait a l'appui sur Select en foret.
    /// </para>
    ///
    /// <para>
    /// <b>La premiere entite n'est qu'une graine.</b> Le sous-type se comporte de deux façons selon
    /// que sa source porte ou non le bit <c>0x100000</c> — celui qui, dans la boucle de dessin de la
    /// grille, designe une entite <b>rendue comme modele du paquet</b>, indexee par <c>+0x04</c>.
    /// Un personnage ne le porte pas (il passe par la branche <c>0x440000</c>, le modele anime),
    /// mais <see cref="SpawnCastEntity_0047AAE0"/> le <b>force</b> sur tout ce qu'elle engendre.
    /// Le test lit donc « ma source est-elle une de mes semblables ? » :
    /// </para>
    /// <list type="bullet">
    /// <item><b>source = le personnage</b> — la graine se recopie <b>deux fois</b> par
    /// <see cref="SpawnCastEntity_0047AAE0"/>, en avançant sa rotation <c>+0x32</c> de <c>0x800</c>
    /// avant chaque copie, puis se marque <c>0x2000000</c> et s'eteint a l'image suivante. Trois
    /// tiers de tour, donc, dont il ne reste que deux exemplaires.</item>
    /// <item><b>source = la graine</b> — la copie se reaccroche au <b>personnage</b>
    /// (<c>source + 0x6c</c>), prend le modele <c>0x3d</c>, la teinte pleine <c>0xffffff</c>, et
    /// mesure une fois pour toutes la hauteur de tete du lanceur par
    /// <see cref="StatusBubbleHeight_00538BC0"/>.</item>
    /// </list>
    ///
    /// <para>
    /// Ensuite, a chaque image : la position est recopiee du lanceur avec la hauteur en decalage
    /// vertical (<c>(hauteur &amp; ~1) &lt;&lt; 11</c>), l'echelle des trois axes <b>approche</b> sa
    /// cible d'un quart de la distance restante — la cible etant <c>(hauteur &lt;&lt; 12) / 150</c>,
    /// que le binaire ecrit en multiplication magique <c>0x1B4E81B5</c> suivie de <c>sar 4</c> —
    /// et la rotation avance de <c>0x40</c> sur <c>+0x32</c>, <c>0x80</c> sur <c>+0x34</c>.
    /// </para>
    /// <para>
    /// <b>Trois conditions rendent la main</b>, et posent <c>0x2000000</c> sur le mot d'etat, ce qui
    /// bascule l'entite dans la branche d'extinction : le lanceur porte <c>0x50000000</c> ; c'est un
    /// membre du groupe (<c>0x800000</c>) qui a <b>quitte la posture 5</b> ; ou son mot d'etat
    /// vaut <c>0x400000</c> sur le masque <c>0x400004</c>. L'extinction <b>divise l'echelle par
    /// deux</b> a chaque image et rend le creneau des qu'elle passe sous <c>0x100</c>, en mettant le
    /// mot d'etat a zero — la passe <see cref="TickEntityTable_005edee0"/> relit ce mot juste apres
    /// et libere l'emplacement.
    /// </para>
    /// </summary>
    private static void TickCastAura_004765D0(byte* record)
    {
        byte* e = record;

        // ------------------------------------------------------------------ l'extinction
        if ((*(uint*)e & 0x2000000) != 0)
        {
            int scale = *(short*)(e + 0x28);
            scale -= scale >> 1;                       // la moitie, arrondie vers le haut

            *(short*)(e + 0x2c) = (short)scale;
            *(uint*)(e + 0x28) = ((uint)scale << 0x10) | (uint)scale;

            *(ushort*)(e + 0x32) += 0x40;
            *(ushort*)(e + 0x34) += 0x80;

            // Le mot d'etat a zero : la passe rend le creneau au pool 0x006007a0.
            if (scale < 0x100) *(uint*)e = 0;
            return;
        }

        // ------------------------------------------------------------------ l'amorcage
        if (*(ushort*)(e + 0x10) == 0)
        {
            byte* source = *(byte**)(e + 0x6c);

            e[0x36] |= 6;
            *(ushort*)(e + 0x10) = 1;
            *(uint*)(e + 0x38) = 0xffffff;
            *(uint*)(e + 0x28) = 0;
            *(ushort*)(e + 0x2c) = 0;
            *(ushort*)(e + 0x34) = 0;

            if ((*(uint*)source & 0x100000) == 0)
            {
                // Ghidra: LAB_004766f4 — la graine se dedouble et se marque pour l'extinction.
                *(ushort*)(e + 0x32) += 0x800;
                SpawnCastEntity_0047AAE0(e, 0xbd, 0, 0);
                *(ushort*)(e + 0x32) += 0x800;
                SpawnCastEntity_0047AAE0(e, 0xbd, 0, 0);

                *(uint*)e |= 0x2000000;
                return;
            }

            // La copie saute par-dessus la graine et se raccroche au lanceur lui-meme.
            byte* caster = *(byte**)(source + 0x6c);
            e[0x04] = 0x3d;
            *(byte**)(e + 0x6c) = caster;
            e[0x0b] = 0;
            e[0x0a] = 0x0f;
            *(short*)(e + 0x12) = (short)StatusBubbleHeight_00538BC0((uint*)caster);
        }

        // Ghidra: LAB_0047666c — le suivi, hors de toute branche d'etat.
        int height = *(short*)(e + 0x12);
        byte* anchor = *(byte**)(e + 0x6c);

        // `imul 0x1B4E81B5` puis `sar edx,4` et la correction de signe : une division signee par
        // 150, l'idiome du compilateur de 1998.
        int target = (height << 0xc) / 150;
        int current = *(short*)(e + 0x28);
        current += (target - current) >> 2;            // un quart de ce qui reste, par image

        *(short*)(e + 0x2c) = (short)current;
        *(uint*)(e + 0x28) = ((uint)current << 0x10) | (uint)current;

        *(int*)(e + 0x1c) = *(int*)(anchor + 0x1c);
        *(int*)(e + 0x20) = *(int*)(anchor + 0x20) + ((height & ~1) << 0xb);
        *(int*)(e + 0x24) = *(int*)(anchor + 0x24);

        uint state = *(uint*)anchor;
        bool spent;

        if ((state & 0x50000000) != 0) spent = true;
        else if ((state & 0x800000) != 0 && *(ushort*)(anchor + 0x18) != 5) spent = true;
        else spent = (state & 0x400004) == 0x400000;   // Ghidra: LAB_004766d3

        if (spent) *(uint*)e |= 0x2000000;

        // Ghidra: LAB_004766e5 — la rotation, commune aux deux branches.
        *(ushort*)(e + 0x32) += 0x40;
        *(ushort*)(e + 0x34) += 0x80;
    }

    /// <summary>
    /// Ghidra: FUN_0051a5d0 @ 0x0051a5d0 — <b>la reconnaissance de la combinaison de directions</b>
    /// saisie pendant l'incantation. Elle rend l'indice du sort dont la combinaison correspond, ou
    /// <c>-1</c>.
    ///
    /// <para>
    /// <b>C'est la table de sorts elle-meme qui porte les combinaisons.</b> Chaque fiche fait
    /// <c>0x30</c> octets ; <c>+0x1f</c> est la <b>longueur</b> de sa combinaison et <c>+0x20</c>
    /// ouvre la suite des directions attendues. La borne du balayage vient de
    /// <see cref="s_SpellCounts_00564600"/>, indexee par l'ecole <c>personnage[0x2b5]</c>.
    /// </para>
    /// <para>
    /// Cote joueur, <see cref="ApplyGroundMotion_0051A020"/> empile chaque direction tenue dans
    /// <c>entree[0x0c + n]</c> sous la forme <c>(manette[2..3] &gt;&gt; 8) &amp; 0xf0</c> et compte
    /// les coups dans <c>entree[0x0b]</c>, plafonne a <c>0x10</c>. <b>Les deux bornes se repondent
    /// exactement</b> : seize octets tiennent entre <c>+0x20</c> et la fin de la fiche, ce qui
    /// confirme les deux lectures l'une par l'autre.
    /// </para>
    /// <para>
    /// La comparaison est un <c>memcmp</c> que Ghidra a deroule ; il est reecrit en boucle. Le test
    /// <c>longueur != 0</c> est invariant de boucle dans le binaire — il est remonte avant, ce qui
    /// ne change rien : une combinaison vide ne correspond a rien et le balayage rendait
    /// <c>-1</c> apres l'avoir parcouru pour rien.
    /// </para>
    /// </summary>
    private static int PickCastTarget_0051A5D0(byte* entry, byte* perChar)
    {
        byte school = perChar[0x2b5];
        int count = s_SpellCounts_00564600[school];
        if (count == 0) return -1;

        byte length = entry[0x0b];
        if (length == 0) return -1;

        // La fiche de sort commence 0x20 octets plus tot ; on balaye directement les combinaisons.
        byte* combo = *(byte**)(*(byte**)(Mem.s_MainResourceDirectory_005e97c4 + 0x9c)
                                + school * 4) + 0x20;

        for (int index = 0; index < count; index++, combo += 0x30)
        {
            if (length != combo[-1]) continue;          // la longueur, en +0x1f de la fiche

            int matched = 0;
            while (matched < length && entry[0x0c + matched] == combo[matched]) matched++;

            if (matched == length) return index;
        }

        return -1;
    }

    /// <summary>
    /// Ghidra: <c>(*(code *)(&amp;PTR_FUN_00562ce0)[bloc + 0x2b7])(…)</c> — quatre gestionnaires de
    /// commande, releves dans le binaire sous <see cref="s_InputHandlers_00562ce0"/>. Aucun n'est
    /// le corps vide.
    /// </summary>
    private static void DispatchInputHandler(byte index, uint* slot, byte* perChar, byte* pad)
    {
        uint target = index < s_InputHandlers_00562ce0.Length
            ? s_InputHandlers_00562ce0[index]
            : 0;

        switch (target)
        {
            case 0x0050E140: HandleDirectionalInput_0050E140(slot, perChar, pad); return;

            default:
                throw new NotImplementedException(
                    $"FUN_0050bf20 : le gestionnaire de commande d'indice {index} (table " +
                    $"0x00562ce0) vaut 0x{target:X6} et n'est pas transcrit. Les quatre entrees de " +
                    "la table sont relevees dans le binaire : 0x0050E140, 0x0050DE90 (toutes deux " +
                    "dans Blaze.c), 0x0050DD00 et 0x0050DFF0 (absentes, a desassembler). Il prend " +
                    "(entite, bloc par personnage, manette).");
        }
    }

    /// <summary>
    /// Ghidra: FUN_0050e140 @ 0x0050e140 — l'entree <b>0</b> de la table de commande
    /// <c>PTR_FUN_00562ce0</c> : <b>la marche a la croix directionnelle</b>. C'est le premier
    /// gestionnaire que la carte du monde atteint, et le seul chemin par lequel le joueur fait
    /// bouger son personnage.
    ///
    /// <para>
    /// Trois façons d'obtenir une direction, selon le bit 3 de <c>bloc + 0x140</c> : normalement
    /// la croix, lue a travers <see cref="s_PadDirection_00562dc8"/> ; quand le bit est pose — le
    /// personnage est desoriente — <b>une direction tiree au sort</b> des qu'une touche est
    /// enfoncee, et rien du tout sinon.
    /// </para>
    /// <para>
    /// La direction n'est convertie en cap qu'a la <b>transition</b> de la croix (bit 1 de
    /// <c>manette + 0xb</c>, consomme au passage), pas a chaque image : c'est ce qui empeche le
    /// personnage de tourner en continu tant qu'une direction est tenue. Le cap est relatif a la
    /// camera, arrondi au seizieme de tour (<c>(angle + 0x80) &amp; 0xf00</c>) — et la meme
    /// desorientation remplace cette reference par un tirage.
    /// </para>
    /// <para>
    /// La vitesse vient de <see cref="s_PostureSpeed_00562cc0"/>, sauf en mode de mise au point
    /// avec le modificateur tenu, ou elle passe a <c>0x3c000</c> — la marche rapide. Elle est
    /// ensuite mise a l'echelle par les memes trois drapeaux de <c>bloc + 0x140</c> que le membre
    /// suivi utilise pour sa distance d'arret.
    /// </para>
    /// </summary>
    private static void HandleDirectionalInput_0050E140(uint* slot, byte* perChar, byte* pad)
    {
        byte* s = (byte*)slot;
        int direction;

        if ((perChar[0x140] & 8) == 0)
        {
            direction = s_PadDirection_00562dc8[*pad >> 4];
        }
        else if ((*pad & 0xf0) == 0)
        {
            direction = 0;
        }
        else
        {
            direction = (CrtRand() & 7) + 1;
        }

        if (direction == 0)
        {
            if ((*slot & 0x47) == 0 && (*pad & 0xf0) == 0 && *(short*)(s + 0x18) != 0)
            {
                *(uint*)(s + 0x18) = 0;
                *slot |= 0x1000000;
            }

            return;
        }

        if ((*slot & 0x8000047) == 0 && *(short*)(s + 0x18) != 1)
        {
            *(uint*)(s + 0x18) = 1;
            *slot |= 0x1000000;
        }

        if ((pad[0x0b] & 2) != 0)
        {
            pad[0x0b] &= 0xfd;

            short reference = (perChar[0x140] & 8) == 0
                ? (short)((*(ushort*)(Mem.s_CameraVector_00604928 + 2) + 0x80u) & 0xf00)
                : (short)(((short)CrtRand() + 0x80u) & 0xf00);

            *(short*)(s + 0x32) = (short)((short)(direction * 0x200) - reference - 0x200);
        }

        *(short*)(s + 0x98) = *(short*)(s + 0x32);

        if (Mem.s_DebugModeLatch_005633a8 == 0)
        {
            *(int*)(s + 0x5c) = (pad[1] & 0x20) == 0
                ? s_PostureSpeed_00562cc0[perChar[0x150] & 7] << 0xc
                : 0x3c000;
        }
        else
        {
            *(int*)(s + 0x5c) = s_PostureSpeed_00562cc0[perChar[0x150] & 7] << 0xc;
        }

        uint posture = *(uint*)(perChar + 0x140);
        int scale = 0x1000;
        if ((posture & 0x4000) != 0) scale = 0x1333;
        if ((posture & 0x8000) != 0) scale = 0xccc;
        if ((posture & 4) != 0) scale = 0x800;

        *(int*)(s + 0x5c) = scale * *(int*)(s + 0x5c) >> 0xc;
    }

    /// <summary>
    /// Ghidra: <c>(*(code *)(&amp;PTR_FUN_00562ca0)[bloc + 0x150 &amp; 7])(…)</c> — huit gestionnaires
    /// de posture, releves sous <see cref="s_PostureHandlers_00562ca0"/>. <b>Quatre sont le corps
    /// vide <c>0x0040A600</c></b>, deja verifie au desassembleur : les postures 1, 2, 3 et 5 ne
    /// font rien.
    /// </summary>
    private static void DispatchPostureHandler(
        byte posture, uint* slot, byte* entry, byte* perChar, byte* pad, byte* anim)
    {
        uint target = s_PostureHandlers_00562ca0[posture];

        switch (target)
        {
            case 0x0040A600: return;   // corps vide verifie au desassembleur
            case 0x0051A670: PostureHandler_0051A670(slot); return;

            default:
                throw new NotImplementedException(
                    $"FUN_0050bf20 : le gestionnaire de posture {posture} (table 0x00562ca0) vaut " +
                    $"0x{target:X6} et n'est pas transcrit. Les trois qui restent — 0x0051A6B0, " +
                    "0x0051A700 et 0x0051A710 — sont **absentes de Blaze.c** : " +
                    $"`OpenForesia.Tools -- disasm Legacy/Binaries/Blaze.exe 0x{target:x8} 512`. " +
                    "Le site d'appel empile (entite, entree d'emplacement, bloc par personnage, " +
                    "manette, animation courante), mais 0x0051A670 ne lit que le premier — " +
                    "verifier au cas par cas ce que chacune consomme reellement.");
        }
    }

    /// <summary>
    /// Ghidra: FUN_0051a670 @ 0x0051a670 — la posture <b>0</b>, la marche : quatorze lignes.
    ///
    /// <para>
    /// Elle ne fait qu'une chose : a la <b>cinquieme image de l'etat 6</b>, elle fait naitre
    /// l'entite d'effet <c>0xba</c> — la trainee de l'arme, dont la table 0x005ff400 porte la
    /// duree de vie. Le test <c>param_1[6] == 0x50006</c> compare l'etat ET l'image en un seul
    /// dword, ce qui est la forme compacte de « etat 6, image 5 » : les deux <c>short</c> de
    /// <c>+0x18</c> et <c>+0x1a</c> lus ensemble.
    /// </para>
    /// <para>
    /// <b>Ghidra ne lui donne qu'un parametre</b> alors que le site d'appel en empile cinq. Ce
    /// n'est pas une signature manquee : le corps ne touche jamais aux quatre autres, et l'appel
    /// est en cdecl, donc sans consequence. Meme precedent que <c>FreezeAllEntities</c>.
    /// </para>
    /// </summary>
    private static void PostureHandler_0051A670(uint* slot)
    {
        byte* s = (byte*)slot;

        if ((*slot & 2) != 0 && *(uint*)(s + 0x18) == 0x50006)
        {
            SpawnEffectEntity(s, 0xba, 0, 0);
        }

        if ((*slot & 1) != 0) *slot &= 0xfffffffb;
    }

    /// <summary>
    /// Ghidra: FUN_00474eb0 @ 0x00474eb0 — <b>cherche la cible la plus proche du camp d'en
    /// face</b>. Dix-neuf lignes d'aiguillage : selon le mode et le bit <c>0x800000</c> qui
    /// distingue un membre du groupe, elle balaie soit la table des entites de scene, soit celle
    /// du groupe.
    ///
    /// <para>
    /// Avec le mode <c>1</c> — le seul que la carte du monde emploie — un membre du groupe cherche
    /// parmi les entites de scene, et une entite de scene parmi les membres du groupe. C'est donc
    /// bien « l'adversaire le plus proche » et non un obstacle quelconque : le nom
    /// <c>FindNearbyObstacle</c> que ce depot lui donnait d'apres son seul site d'appel etait une
    /// supposition, corrigee ici.
    /// </para>
    /// <para>
    /// <b>Ghidra la declare <c>void</c></b> alors que son appelant lit son resultat. Ce n'est pas
    /// une signature manquee : les deux branches sont des appels <b>terminaux</b>, et le resultat
    /// de l'appelee traverse tel quel. Rendu explicitement ici.
    /// </para>
    /// </summary>
    private static byte* FindNearestOpponent_00474EB0(uint* entity, uint mask, int mode)
    {
        if (mode == 0)
        {
            if ((*entity & 0x800000) == 0) return FindNearestSceneEntity_00474DB0(entity, mask);
        }
        else if ((*entity & 0x800000) != 0)
        {
            return FindNearestSceneEntity_00474DB0(entity, mask);
        }

        return FindNearestPartyMember_00474CD0(entity);
    }

    /// <summary>
    /// Ghidra: FUN_00474db0 @ 0x00474db0 — la plus proche des 0x20 entites de scene
    /// (<c>DAT_005ecaa0</c>) dans un rayon de <b>600 unites</b>, en excluant la demanderesse
    /// elle-meme.
    ///
    /// <para>
    /// Quatre conditions filtrent les candidates : active (<c>0x80000000</c>), sans aucun des bits
    /// <c>0x50002040</c>, sans cible deja tenue a <c>+0x74</c>, et sans compte a rebours
    /// d'invulnerabilite a <c>+0x96</c>.
    /// </para>
    /// <para>
    /// Le <paramref name="mask"/> est teste par <c>(*bloc &amp; ~mask) == 0</c> contre le mot de
    /// <c>+0x14</c> du bloc de statistiques. <b>Le seul appelant passe -1</b>, ce qui rend
    /// <c>~mask</c> nul et la condition toujours vraie : le filtre existe mais dort.
    /// </para>
    /// </summary>
    private static byte* FindNearestSceneEntity_00474DB0(uint* entity, uint mask)
    {
        byte* self = (byte*)entity;
        int x = *(int*)(self + 0x1c);
        int y = *(int*)(self + 0x20);
        int z = *(int*)(self + 0x24);

        int best = 600;
        byte* found = null;

        byte* candidate = Mem.Entity(0x005ecaa0);
        byte* stats = s_EntityStatBlocks_005ea560 + 0x14;

        for (int i = 0x20; i != 0; i--, candidate += 0x9c, stats += 0x120)
        {
            if ((*(uint*)candidate & 0x80000000) != 0
                && (*(uint*)candidate & 0x50002040) == 0
                && (*(uint*)stats & ~mask) == 0
                && *(int*)(candidate + 0x74) == 0
                && *(short*)(candidate + 0x96) == 0)
            {
                int dx = (x - *(int*)(candidate + 0x1c)) >> 0xc;
                int dy = (y - *(int*)(candidate + 0x20)) >> 0xc;
                int dz = (z - *(int*)(candidate + 0x24)) >> 0xc;
                int distance = (int)Winsys3d.Ordinal_442((uint)(dx * dx + dy * dy + dz * dz));

                if (distance < best && self != candidate)
                {
                    best = distance;
                    found = candidate;
                }
            }
        }

        return found;
    }

    /// <summary>
    /// Ghidra: FUN_00474cd0 @ 0x00474cd0 — la jumelle de
    /// <see cref="FindNearestSceneEntity_00474DB0"/> sur la table du groupe
    /// (<c>DAT_005e93c0</c>), bornee a la taille reelle du groupe et sans le filtre de masque.
    /// Meme rayon de 600, memes quatre conditions, meme exclusion de soi.
    /// </summary>
    private static byte* FindNearestPartyMember_00474CD0(uint* entity)
    {
        byte* self = (byte*)entity;
        int best = 600;
        byte* found = null;

        int x = *(int*)(self + 0x1c);
        int y = *(int*)(self + 0x20);
        int z = *(int*)(self + 0x24);

        if (s_PartySize_005e9020 == 0) return null;

        byte* candidate = Inp.s_SlotFlags_005e93c0;

        for (int i = s_PartySize_005e9020; i != 0; i--, candidate += 0x9c)
        {
            if ((*(uint*)candidate & 0x80000000) != 0
                && (*(uint*)candidate & 0x50002040) == 0
                && *(int*)(candidate + 0x74) == 0
                && *(short*)(candidate + 0x96) == 0)
            {
                int dx = (x - *(int*)(candidate + 0x1c)) >> 0xc;
                int dy = (y - *(int*)(candidate + 0x20)) >> 0xc;
                int dz = (z - *(int*)(candidate + 0x24)) >> 0xc;
                int distance = (int)Winsys3d.Ordinal_442((uint)(dx * dx + dy * dy + dz * dz));

                if (distance < best && self != candidate)
                {
                    best = distance;
                    found = candidate;
                }
            }
        }

        return found;
    }

    /// <summary>Ghidra: FUN_00519df0 @ 0x00519df0 (51 l.) — applique la vitesse a la position et
    /// met a jour les drapeaux de collision de <c>+0x90</c>.</summary>
    /// <summary>
    /// Ghidra: FUN_00519df0 @ 0x00519df0 — <b>la collision contre le voisinage</b> : un balayage
    /// 3x3 des cellules de la <b>premiere</b> grille spatiale (celle de <c>0x1c4000</c>, que
    /// <see cref="TickEntityTable_005fa5e0"/> alimente) autour de l'entite, qui soumet chaque
    /// occupant a <c>FUN_00534330</c>.
    ///
    /// <para>
    /// La constante <c>0x3880</c> de la pseudo-C est la meme que celle de
    /// <see cref="LinkIntoWorldGrid"/> : <c>0x3880 * 0x20 * 4 = 0x1c4000</c>. Le pas de
    /// <c>0x80</c> entre deux cellules avance d'une rangee (0x20 cellules de quatre octets).
    /// </para>
    /// <para>
    /// <b>Ghidra reutilise <c>param_1</c> comme compteur de boucle</b> apres l'avoir sauve dans
    /// <c>puVar3</c> — d'ou un corps ou le meme nom designe tantot l'entite, tantot le nombre 3.
    /// Les deux ont ici des noms distincts.
    /// </para>
    /// <para>
    /// Le porteur de <c>+0x78</c> est <b>remis a zero avant le balayage</b> et relu apres : s'il a
    /// change, la position du nouveau porteur est recopiee dans l'entree d'emplacement. C'est ce
    /// qui permet a <see cref="ComputeCarrierOffset"/> de travailler au tour suivant.
    /// </para>
    /// </summary>
    private static void ApplyEntityMotion_00519DF0(uint* entity, byte* entry)
    {
        byte* e = (byte*)entity;
        byte* mainMem = GetMainMemPtr();

        uint previousCarrier = *(uint*)(e + 0x78);
        *(uint*)(e + 0x78) = 0;

        uint cellX = (uint)((((*(int*)(e + 0x1c) >> 0xc) + 0x2000) >> 9) - 1);
        *entity &= 0xffffffcf;
        uint cellZ = (uint)((((*(int*)(e + 0x24) >> 0xc) + 0x2000) >> 9) - 1);

        for (int column = 3; column != 0; column--)
        {
            int offset = (int)((cellZ + 0x3880) * 0x20 + cellX) * 4;
            uint row = cellZ;

            for (int step = 3; step != 0; step--)
            {
                if (cellX < 0x20 && row < 0x20)
                {
                    for (uint* occupant = *(uint**)(mainMem + offset);
                         occupant != null;
                         occupant = *(uint**)((byte*)occupant + 0x68))
                    {
                        if ((*occupant & 0x2000) == 0)
                        {
                            ResolveEntityContact_00534330(occupant, entity, entry);
                        }
                    }
                }

                offset += 0x80;
                row++;
            }

            cellZ = row - 3;
            cellX++;
        }

        uint carrier = *(uint*)(e + 0x78);
        if (carrier != 0 && carrier != previousCarrier)
        {
            byte* c = (byte*)(nuint)carrier;
            *(uint*)(entry + 0x28) = *(uint*)(c + 0x1c);
            *(uint*)(entry + 0x2c) = *(uint*)(c + 0x20);
            *(uint*)(entry + 0x30) = *(uint*)(c + 0x24);
        }
    }

    /// <summary>
    /// Ghidra: FUN_00534330 @ 0x00534330 — <b>le contact entre deux entites</b> : le personnage
    /// contre le maillage de collision d'un occupant voisin. Appelee par
    /// <see cref="ApplyEntityMotion_00519DF0"/> pour chaque occupant des neuf cellules de grille.
    /// C'est elle qui pose le porteur de <c>+0x78</c> et les bits de <c>+0x90</c>.
    ///
    /// <para>
    /// <b>2 464 octets</b> (0x00534330..0x00534cd0), 277 lignes de pseudo-C : une boucle sur les
    /// faces du maillage, avec par face un produit vectoriel dans les registres GTE emules puis
    /// jusqu'a trois <c>NormalClip</c> pour le test d'appartenance au triangle.
    /// </para>
    /// <para>
    /// <b>La pseudo-C ne peut pas etre transcrite telle quelle : elle confond les DEUX entites.</b>
    /// Ghidra declare <c>FUN_00534330(uint *param_1)</c> alors que le site d'appel en empile trois
    /// (<c>add esp,0Ch</c> en 0x00519e83), et il fait porter a un meme nom des acces qui visent des
    /// objets differents. La correspondance ci-dessous est <b>etablie au desassembleur</b> et
    /// suffit a rendre la pseudo-C utilisable :
    /// </para>
    /// <list type="table">
    /// <item><term><c>param_1</c>, <c>puStack_18</c></term><description>l'<b>argument 1</b>,
    /// l'occupant — <c>[esp+74h]</c> apres les quatre <c>push</c> du prologue. Les deux noms
    /// designent le meme objet : <c>puStack_18 = param_1</c> en tete de boucle et
    /// <c>param_1 = puStack_18</c> en queue.</description></item>
    /// <item><term><c>local_14</c> <i>vu comme une entite</i></term><description>l'<b>argument
    /// 2</b>, le personnage qui se deplace — <c>[esp+78h]</c>.</description></item>
    /// <item><term><c>local_14</c> <i>passe a FUN_0051c300 / FUN_005327b0 / Ordinal_366</i></term>
    /// <description>un <b>tampon local de neuf shorts</b> a <c>[esp+5Ch]</c>, la matrice de
    /// l'occupant. Rien a voir avec l'entite ci-dessus : Ghidra a fusionne deux emplacements de
    /// pile voisins.</description></item>
    /// <item><term><c>iStack_10</c></term><description>l'<b>argument 3</b>, l'entree
    /// d'emplacement — <c>[esp+7Ch]</c>. Elle recoit le vecteur de contact a <c>+0x1c</c> et la
    /// pose de l'occupant a <c>+0x28</c>..<c>+0x48</c>.</description></item>
    /// <item><term><c>puStack_54</c></term><description>le bloc de modele de l'occupant, mis de
    /// cote en tete et restaure a chaque tour de boucle.</description></item>
    /// </list>
    /// <para>
    /// <b>Le recoupement decisif est 0x00534778</b> : <c>mov [edi+78h],esi</c> puis
    /// <c>mov ecx,[esp+7Ch] ; mov [ecx+1Ch],edx</c> ou <c>edx = [edi+1Ch] - [esi+1Ch]</c>. EDI est
    /// l'argument 2 et ESI l'argument 1, donc <c>entite[0x78] = occupant</c> et
    /// <c>entree[0x1c] = entite.x - occupant.x</c> — ce que la pseudo-C rend en
    /// <c>local_14[0x1e] = puStack_18</c> et
    /// <c>*(uint *)(iStack_10 + 0x1c) = local_14[7] - puStack_18[7]</c>.
    /// </para>
    /// <para>
    /// <b>Le danger de cette fonction est le silence.</b> Intervertir les deux entites compile,
    /// tourne, et rend une collision qui pousse le decor au lieu du personnage. Aucun compteur de
    /// primitives ne le dirait. Verifier chaque acces contre la table ci-dessus avant de
    /// l'ecrire, et ne rien deduire du nom seul.
    /// </para>
    /// <para>
    /// Les six termes du <c>NormalClip</c> sont <b>inlines</b> ici et le depot en porte deja la
    /// version reconstruite (<c>FUN_0051c280</c>, <c>Platform/Winsys3d.cs</c>) : les recouper terme
    /// a terme avant d'appeler, Ghidra les emet dans un autre ordre — precedent deja paye sur
    /// <c>FinalizeEntityPlacement2</c>.
    /// </para>
    /// </summary>
    private static uint ResolveEntityContact_00534330(uint* occupantPtr, uint* entityPtr, byte* entry)
    {
        byte* occupant = (byte*)occupantPtr;
        byte* entity = (byte*)entityPtr;
        byte* mainMem = GetMainMemPtr();

        EnsureGteRegisters();

        // Le maillage de collision de l'occupant, choisi par son type et le decalage de zone.
        byte* model = *(byte**)(Mem.Entity(0x005f7bc0) + (occupant[4] + *Mem.Entity(0x00600838)) * 4);

        // La rangee de translation du registre MATRIX est mise a zero : on travaille en repere
        // local de l'occupant, la translation est faite a la main par les deltas ci-dessous.
        *(int*)(s_GteMatrix814 + 0x1c) = 0;
        *(int*)(s_GteMatrix814 + 0x18) = 0;
        *(int*)(s_GteMatrix814 + 0x14) = 0;

        short* matrix = stackalloc short[9];
        RotMatrix((short*)(occupant + 0x30), matrix);
        ScaleMatrix_005327B0(matrix, (ushort*)(occupant + 0x28));
        Winsys3d.Ordinal_366(matrix);

        // Les deux nappes de sommets transformes : les positions dans MainMem + 0x1b0000, les
        // normales dans + 0x1b8000. Le mot de tete du modele porte les deux comptes.
        uint counts = *(uint*)model;
        Winsys3d.Ordinal_792((short*)(model + 0x40), (short*)(mainMem + 0x1b0000), counts & 0xffff);
        Winsys3d.Ordinal_792(*(short**)(model + 0x24), (short*)(mainMem + 0x1b8000),
            (uint)((int)counts >> 0x10) & 0xffff);

        bool pushed = false;      // Ghidra: bVar6
        bool overFace = false;    // Ghidra: bVar5

        int occupantY = *(int*)(occupant + 0x20);
        int entityY = *(int*)(entity + 0x20);

        short* faceIndex = *(short**)(*(byte**)(model + 0x38) + 4);

        // **L'asymetrie de ces trois deltas est reelle**, verifiee au desassembleur
        // (0x005343ef..0x0053440a) : X et Z sont pris `entite - occupant`, mais Y
        // `occupant - entite`. Ce n'est pas un artefact de Ghidra, et ce n'est pas corrige.
        int deltaX = (*(int*)(entity + 0x1c) - *(int*)(occupant + 0x1c)) >> 0xc;
        int deltaZ = (*(int*)(entity + 0x24) - *(int*)(occupant + 0x24)) >> 0xc;

        *(uint*)s_GteSxy807 = ((uint)deltaZ << 0x10) | ((uint)deltaX & 0xffff);

        int* vec799 = (int*)s_GteVec799;
        int* vec800 = (int*)s_GteVec800;
        int* mac801 = (int*)s_GteMac801;
        short* ir813 = (short*)s_GteIr813;

        while (true)
        {
            short index = *faceIndex;

            if (index < 0)
            {
                if (!overFace) break;

                // L'entite repose sur une face de cet occupant sans le traverser.
                *(uint*)(occupant + 0x70) = (uint)(nuint)entity;
                if ((*entityPtr & 0x10000) == 0)
                {
                    *(uint*)(occupant + 0x6c) = (uint)(nuint)entity;
                    *occupantPtr |= 0x40;
                }

                if ((*entityPtr & 0x40012000) == 0)
                {
                    byte kind = (byte)(occupant[0x0d] & 0xf);
                    if (kind == 0 || (kind == 1 && (occupant[9] & 0xf) == 0))
                    {
                        RunEntityScript(s_Unknown_005e97cc, entity, *(ushort*)(occupant + 0x0e));
                    }
                }

                if (pushed)
                {
                    *(uint*)(entity + 0x90) |= 0x8000800;
                    *(int*)(occupant + 0x50) += *(int*)(entity + 0x50);
                    *(int*)(occupant + 0x58) += *(int*)(entity + 0x58);
                }

                occupant[9] |= (byte)(1 << (int)(*(uint*)(entity + 8) & 0x1f));
                return FinishContact(occupantPtr, entityPtr);
            }

            byte* face = *(byte**)(model + 0x28) + index * 0x10;
            uint corners = *(uint*)face;
            ushort attributes = *(ushort*)(face + 0x0c);
            uint* normal = (uint*)(mainMem + 0x1b8000 + face[4] * 8);

            byte* cache = mainMem + 0x1b0000;
            short* a = (short*)(cache + (corners & 0xff) * 8);
            short* b = (short*)(cache + ((corners >> 8) & 0xff) * 8);
            short* c = (short*)(cache + ((corners >> 0x10) & 0xff) * 8);

            // Le produit vectoriel des deux aretes de la face, depose dans MAC1..3 puis recopie
            // dans IR1..3 — la normale non normalisee.
            vec800[0] = b[0] - a[0];
            vec800[1] = b[1] - a[1];
            vec800[2] = b[2] - a[2];
            vec799[0] = c[0] - a[0];
            vec799[1] = c[1] - a[1];
            vec799[2] = c[2] - a[2];

            mac801[0] = vec799[2] * vec800[1] - vec799[1] * vec800[2];
            mac801[1] = vec800[2] * vec799[0] - vec799[2] * vec800[0];
            mac801[2] = vec799[1] * vec800[0] - vec800[1] * vec799[0];

            ir813[0] = (short)mac801[0];
            ir813[1] = (short)mac801[1];
            ir813[2] = (short)mac801[2];

            int normalY = mac801[1];
            int planar = (deltaZ - a[2]) * mac801[2] + (deltaX - a[0]) * mac801[0];
            int side = (((occupantY - entityY) >> 0xc) - a[1]) * normalY + planar;

            // De quel cote du plan de la face l'entite se trouve-t-elle ? Les faces marquees
            // 0x2000 sont a sens unique et laissent passer par en dessous.
            if ((normalY == 0 && side >= 0)
                || (normalY > 0 && side > 0)
                || (normalY < 0 && side > 0 && (attributes & 0x2000) != 0))
            {
                break;
            }

            if ((attributes & 0x2000) == 0)
            {
                // Le test d'appartenance, en projection sur le plan XZ : trois (ou quatre pour un
                // quad) NormalClip contre les aretes. Les six termes inlines par le compilateur
                // sont **terme a terme** ceux de Winsys3d.NormalClip, deja reconstruit — recoupes
                // avant d'appeler, comme FinalizeEntityPlacement2 l'a exige en aout.
                uint flatA = ((uint)a[2] << 0x10) | (ushort)a[0];
                uint flatB = ((uint)b[2] << 0x10) | (ushort)b[0];
                uint flatC = ((uint)c[2] << 0x10) | (ushort)c[0];

                *(uint*)s_GteSxy805 = flatA;
                *(uint*)s_GteSxy806 = flatB;

                if (NormalClip() >= 0)
                {
                    *(uint*)s_GteSxy805 = flatB;
                    *(uint*)s_GteSxy806 = flatC;

                    if (NormalClip() >= 0)
                    {
                        int last;

                        if ((attributes & 1) == 0)
                        {
                            *(uint*)s_GteSxy805 = flatC;
                            *(uint*)s_GteSxy806 = flatA;
                            last = NormalClip();
                        }
                        else
                        {
                            // Face a quatre sommets : le quatrieme est l'octet haut du mot de
                            // coins, et le test se fait en deux aretes de plus.
                            short* d = (short*)(cache + (corners >> 0x18) * 8);
                            uint flatD = ((uint)d[2] << 0x10) | (ushort)d[0];

                            *(uint*)s_GteSxy805 = flatC;
                            *(uint*)s_GteSxy806 = flatD;
                            if (NormalClip() < 0) goto nextFace;

                            *(uint*)s_GteSxy805 = flatD;
                            *(uint*)s_GteSxy806 = flatA;
                            last = NormalClip();
                        }

                        if (last >= 0)
                        {
                            // L'entite est au-dessus de cette face : on en deduit la hauteur du
                            // plan sous elle.
                            int height = normalY == 0
                                ? occupantY
                                : (planar / normalY - a[1]) * 0x1000 + occupantY;

                            int reach = -0x32000;
                            if (*(int*)(entity + 0x54) < 0) reach = *(int*)(entity + 0x54) - 0x32000;

                            if (height + reach <= entityY)
                            {
                                *occupantPtr |= 0x20;
                                *entityPtr |= 0x20;

                                if ((*(int*)(entity + 0x64) <= height && (attributes & 0x1000) == 0)
                                    || (*(uint*)(entity + 0x90) & 4) != 0)
                                {
                                    *(int*)(entity + 0x64) = height;
                                    *(uint*)(entity + 0x78) = (uint)(nuint)occupant;
                                    PublishContact(entry, entity, occupant, normal);
                                }

                                if (*(int*)(entity + 0x60) <= height
                                    || (*(uint*)(entity + 0x90) & 4) != 0)
                                {
                                    *(int*)(entity + 0x60) = height;
                                    *(uint*)(entity + 0x78) = (uint)(nuint)occupant;

                                    if ((*(uint*)(entity + 0x90) & 0x8800) == 0)
                                    {
                                        *(uint*)(entity + 0x90) = attributes;
                                    }

                                    if (entityY <= height)
                                    {
                                        // Contact franc : l'entite est posee dessus.
                                        (*(short*)(occupant + 0x96))++;
                                        *occupantPtr |= 0x10;
                                        *(int*)(entity + 0x54) = 0;
                                        *entityPtr |= 0x10;
                                        PublishContact(entry, entity, occupant, normal);

                                        uint slotIndex = *(uint*)(entity + 8);
                                        *(uint*)(occupant + 0x70) = (uint)(nuint)entity;
                                        occupant[9] |= (byte)((1 << (int)(slotIndex & 0x1f)) << 4);

                                        if ((*entityPtr & 0x10000) == 0)
                                        {
                                            *(uint*)(occupant + 0x6c) = (uint)(nuint)entity;
                                        }

                                        if ((*entityPtr & 0x40012000) == 0
                                            && (occupant[0x0d] & 0xf) == 4)
                                        {
                                            RunEntityScript(s_Unknown_005e97cc, entity,
                                                *(ushort*)(occupant + 0x0e));
                                        }

                                        return FinishContact(occupantPtr, entityPtr);
                                    }
                                }

                                return 0;
                            }

                            // Trop haut pour se poser : la hauteur est notee et l'entite sera
                            // poussee au tour suivant.
                            *(int*)(entry + 4) = height;
                            pushed = true;
                            overFace = true;
                        }
                    }
                }
            }
            else
            {
                overFace = true;
            }

        nextFace:
            faceIndex++;
        }

        // Ghidra: LAB_0053470b — aucune face ne porte l'entite.
        if ((*entityPtr & 0x40012000) == 0 && (occupant[0x0d] & 0xf) == 2)
        {
            RunEntityScript(s_Unknown_005e97cc, entity, *(ushort*)(occupant + 0x0e));
        }

        occupant[9] &= (byte)~(1 << (int)(*(uint*)(entity + 8) & 0x1f));
        return 0;
    }

    /// <summary>
    /// Ghidra: <c>LAB_005348d5</c> — les deux lignes communes aux deux sorties « contact » de
    /// <see cref="ResolveEntityContact_00534330"/>.
    /// </summary>
    private static uint FinishContact(uint* occupantPtr, uint* entityPtr)
    {
        if ((*occupantPtr & 0x10000000) == 0 && (*entityPtr & 0x10000) == 0)
        {
            *occupantPtr &= 0xbfffffff;
        }

        return 1;
    }

    /// <summary>
    /// Le bloc de treize ecritures que <see cref="ResolveEntityContact_00534330"/> repete
    /// <b>a l'identique</b> a ses deux points de contact : le vecteur qui separe les deux entites,
    /// la pose complete de l'occupant, et les deux mots de normale de la face touchee.
    /// Factorise parce que c'est une unite reellement independante — le meme bloc, deux fois.
    /// </summary>
    private static void PublishContact(byte* entry, byte* entity, byte* occupant, uint* normal)
    {
        *(uint*)(entry + 0x1c) = (uint)(*(int*)(entity + 0x1c) - *(int*)(occupant + 0x1c));
        *(uint*)(entry + 0x20) = (uint)(*(int*)(entity + 0x20) - *(int*)(occupant + 0x20));
        *(uint*)(entry + 0x24) = (uint)(*(int*)(entity + 0x24) - *(int*)(occupant + 0x24));

        *(uint*)(entry + 0x28) = *(uint*)(occupant + 0x1c);
        *(uint*)(entry + 0x2c) = *(uint*)(occupant + 0x20);
        *(uint*)(entry + 0x30) = *(uint*)(occupant + 0x24);
        *(uint*)(entry + 0x34) = *(uint*)(occupant + 0x28);
        *(uint*)(entry + 0x38) = *(uint*)(occupant + 0x2c);
        *(uint*)(entry + 0x3c) = *(uint*)(occupant + 0x30);
        *(uint*)(entry + 0x40) = *(uint*)(occupant + 0x34);

        *(uint*)(entry + 0x44) = normal[0];
        *(uint*)(entry + 0x48) = normal[1];
    }

    /// <summary>
    /// Ghidra: FUN_005327b0 @ 0x005327b0 — le <c>ScaleMatrix</c> du SDK : chaque <b>colonne</b> de
    /// la matrice 3x3 est multipliee par un facteur en 1.12 pris dans un triplet de
    /// <c>ushort</c>.
    ///
    /// <para>
    /// L'original passe par les registres GTE emules — le facteur dans 812, la colonne dans
    /// IR1..3 (813), le produit dans MAC1..3 (801) — et non par des variables. Transcrit tel quel :
    /// ces registres sont observables depuis le reste du moteur, et rien ne garantit qu'aucun
    /// lecteur ne les regarde entre deux appels.
    /// </para>
    /// <para>Ce sont bien les <b>colonnes</b> et non les rangees : la fonction touche les indices
    /// 0/3/6, puis 1/4/7, puis 2/5/8.</para>
    /// </summary>
    private static void ScaleMatrix_005327B0(short* matrix, ushort* scale)
    {
        EnsureGteRegisters();

        ushort* factor = (ushort*)s_GteScale812;
        short* ir = (short*)s_GteIr813;
        int* mac = (int*)s_GteMac801;

        for (int column = 0; column < 3; column++)
        {
            *factor = scale[column];
            ir[0] = matrix[column];
            ir[1] = matrix[column + 3];
            ir[2] = matrix[column + 6];

            mac[0] = (int)(*factor * ir[0]) >> 0xc;
            ir[0] = (short)mac[0];
            mac[1] = (int)(ir[1] * *factor) >> 0xc;
            ir[1] = (short)mac[1];
            mac[2] = (int)(ir[2] * *factor) >> 0xc;
            ir[2] = (short)mac[2];

            matrix[column] = ir[0];
            matrix[column + 3] = ir[1];
            matrix[column + 6] = ir[2];
        }
    }

    /// <summary>
    /// Ghidra: FUN_00519f50 @ 0x00519f50 — <b>la laisse</b> : l'entite est ramenee vers le point
    /// que suit la camera des qu'elle s'en eloigne de plus de 400 unites, proportionnellement a
    /// l'exces. En deca, elle se contente de poser le bit <c>0x100</c>.
    ///
    /// <para>
    /// <b>Ghidra a fondu les deux parametres en un.</b> Il declare
    /// <c>void FUN_00519f50(uint *param_1)</c> et rend l'ecriture de la distance comme
    /// <c>*(undefined2 *)param_1 = …</c>, c'est-a-dire dans la moitie basse du mot d'etat de
    /// l'entite — ce qui ecraserait seize drapeaux. Le desassemblage dit autre chose :
    /// <c>0x00519f9b</c> lit <c>[esp+18h]</c>, soit <b>le second argument</b> apres les quatre
    /// <c>push</c> du prologue, et ecrit la distance dans <c>[ecx]</c>. La distance va donc dans
    /// l'<b>entree d'emplacement</b>, pas dans l'entite.
    /// </para>
    /// <para>
    /// C'est le cinquieme parametre perdu de cet arbre d'appel, et le plus dangereux : les quatre
    /// autres se voyaient parce que la pseudo-C lisait une variable jamais ecrite. Celui-ci
    /// <b>compile et tourne</b>, en corrompant seize drapeaux a chaque image.
    /// </para>
    /// </summary>
    private static void PullEntityTowardCameraTarget_00519F50(uint* entity, byte* entry)
    {
        byte* e = (byte*)entity;

        *entity &= 0xfffffeff;
        if ((*(uint*)(e + 0x90) & 0x8000) != 0) return;

        int dx = (*Mem.Camera(0x005de098) - *(int*)(e + 0x1c)) >> 0xc;
        int dz = (*Mem.Camera(0x005de0a0) - *(int*)(e + 0x24)) >> 0xc;
        *(ushort*)entry = (ushort)Winsys3d.Ordinal_442((uint)(dx * dx + dz * dz));

        dz = (*Mem.Camera(0x005de070) - *(int*)(e + 0x24)) >> 0xc;
        dx = (*Mem.Camera(0x005de068) - *(int*)(e + 0x1c)) >> 0xc;

        int angle = Winsys3d.Ordinal_457(dx, dz);
        int excess = (int)Winsys3d.Ordinal_442((uint)(dx * dx + dz * dz)) - 400;

        uint flags = *entity;
        if (excess < 1)
        {
            if ((flags & 0x4000) == 0) *entity = flags | 0x100;
        }
        else if ((flags & 0x40000000) == 0)
        {
            *(int*)(e + 0x50) += (int)Winsys3d.GetSinTableEntry(angle) * excess;
            *(int*)(e + 0x58) += Winsys3d.GetCosTableEntry(angle) * excess;
        }
    }

    /// <summary>
    /// Ghidra: FUN_00519ee0 @ 0x00519ee0 — <b>le clignotement d'invulnerabilite</b>. Le compte a
    /// rebours de <c>+0x96</c> descend, et sa parite alterne entre le rendu normal (mode 1, blanc)
    /// et le rendu teinte (mode 5, orange <c>0x4080ff</c>). A zero, le bit <c>0x40</c> tombe.
    ///
    /// <para>
    /// La garde du haut fait retomber trois etats de deplacement (0, 1 et 4) sur l'etat 2 des que
    /// <c>0x40</c> est pose : un personnage touche ne marche plus, il encaisse.
    /// </para>
    /// <para>
    /// Comme <see cref="PostureHandler_0051A670"/>, Ghidra ne lui donne qu'un parametre alors que
    /// le site d'appel en empile deux ; le corps ne lit pas le second.
    /// </para>
    /// </summary>
    private static void UpdateEntityShadow_00519EE0(uint* entity, byte* perChar)
    {
        byte* e = (byte*)entity;

        if ((*entity & 0x40) != 0)
        {
            short state = *(short*)(e + 0x18);
            if (state == 0 || state == 1 || state == 4)
            {
                *(uint*)(e + 0x18) = 2;
                *entity &= 0xfefffff9;
            }
        }

        if (*(short*)(e + 0x96) != 0)
        {
            ushort remaining = (ushort)(*(short*)(e + 0x96) - 1);
            *(ushort*)(e + 0x96) = remaining;

            if ((remaining & 1) == 0)
            {
                *(ushort*)(e + 0x36) = 1;
                *(uint*)(e + 0x38) = 0xffffff;
            }
            else
            {
                *(ushort*)(e + 0x36) = 5;
                *(uint*)(e + 0x38) = 0x4080ff;
            }

            if (remaining == 0) *entity &= 0xffffffbf;
        }
    }

    /// <summary>Ghidra: FUN_005335e0 @ 0x005335e0 (78 l.) — l'angle de la pente sous une
    /// position.</summary>
    private static int GroundSlopeAngle_005335E0(uint* entity, int* position)
        => throw new NotImplementedException(
            "FUN_005335e0 (0x005335e0) : non transcrite. 78 lignes dans Blaze.c — l'angle de la " +
            "face du terrain sous une position, dont la sonde se sert pour recaler le cap contre " +
            "un mur.");

    /// <summary>
    /// Ghidra: <c>LAB_0050caf3</c>, 0x0050caf3..0x0050dc0d — <b>la queue commune</b> de
    /// <see cref="TickPartyMember"/> : tous les chemins y aboutissent. Environ 500 lignes de
    /// pseudo-C.
    /// </summary>
    private static void TickPartyMemberTail(
        int member, byte* s, uint* slot, byte* entry, byte* pad, byte* perChar, byte* mainMem)
    {
        // ---------------------------------------------- (A) la restitution d'etat
        uint held = *slot;
        uint attributes = *(uint*)(s + 0x90);

        if (((held & 0x40000001) != 0 || (attributes & 0xad40) != 0)
            && (s[0x90] & 2) == 0 && (held & 0x20000000) != 0)
        {
            if ((held & 0x4000) == 0) *slot = held | 0x4000;

            // Le membre reprend l'etat d'un camarade valide ; a defaut, celui que la sous-zone a
            // mis de cote en entrant. La boucle s'arrete AUSSI sur le premier camarade qui porte
            // 0x4001 sans le bit 0x8000 — auquel cas rien n'est restitue du tout.
            bool restored = false;
            int index = 0;
            uint* donor = (uint*)Inp.s_SlotFlags_005e93c0;

            while (index < s_PartySize_005e9020)
            {
                if (donor != slot && (*donor & 0x50000000) == 0)
                {
                    byte* d = (byte*)donor;
                    if ((*donor & 0x4001) == 0)
                    {
                        Mem.CopyDwords((uint*)(d + 0x7c), (uint*)(s + 0x7c), 7);
                        Mem.CopyDwords((uint*)(d + 0x1c), (uint*)(s + 0x1c), 3);
                        Mem.CopyDwords((uint*)(d + 0x60), (uint*)(s + 0x60), 2);
                        Mem.CopyDwords(
                            (uint*)(Inp.s_SlotArea_005e9180 + index * 0x4c + 0x1c),
                            (uint*)(entry + 0x1c), 0xc);

                        *(int*)(s + 0x78) = *(int*)(d + 0x78);
                        *slot = (*donor & 0xc2dedf77) | (*slot & 0x49212000);
                        *(uint*)(s + 0x90) = *(uint*)(d + 0x90) & 0xffff7eff;
                        restored = true;
                        break;
                    }

                    if ((*(uint*)(d + 0x90) & 0x8000) == 0) break;
                }

                index++;
                donor = (uint*)((byte*)donor + 0x9c);
            }

            if (!restored && index == s_PartySize_005e9020)
            {
                *Mem.Camera(0x005de068) = *(int*)Mem.Arena(0x005e9a30);
                *Mem.Camera(0x005de06c) = *(int*)Mem.Arena(0x005e9a34);
                *Mem.Camera(0x005de070) = *(int*)Mem.Arena(0x005e9a38);

                *(uint*)(s + 0x80) = *(uint*)Mem.Entity(0x005f7d70);
                *(uint*)(s + 0x84) = *(uint*)Mem.Entity(0x005f7d74);
                *(uint*)(s + 0x88) = *(uint*)Mem.Entity(0x005f7d78);
                *(uint*)(s + 0x8c) = *(uint*)Mem.Entity(0x005f7d7c);

                *(int*)(s + 0x1c) = *(int*)Mem.Arena(0x005e9a30);
                int savedY = *(int*)Mem.Arena(0x005e9a34);
                *(int*)(s + 0x20) = savedY;
                *(int*)(s + 0x24) = *(int*)Mem.Arena(0x005e9a38);

                // Ghidra pose la MEME valeur dans +0x60 et +0x64 : le sol et le plafond partent
                // tous deux de la hauteur mise de cote. Transcrit tel quel.
                *(int*)(s + 0x60) = savedY;
                *(int*)(s + 0x64) = savedY;

                *slot = (*(uint*)Mem.Entity(0x005ff3e4) & 0xc2dedf77) | (*slot & 0x49212000);
                *(uint*)(s + 0x90) = *(ushort*)Mem.Arena(0x005e9b38) & 0xffff7effu;
                *(uint*)(s + 0x7c) = *(uint*)Mem.Entity(0x005f7b48);
                restored = true;
            }

            if (restored)
            {
                held = *slot;
                *slot = held & 0xdfffbff8;
                *(uint*)(s + 0x90) &= 0xffff7eff;

                if ((held & 0x40000000) == 0)
                {
                    *(short*)(s + 0x96) = 0;
                    ApplyPercentDamage_005397B0(slot, 2, 0);
                    *(short*)(s + 0x96) = 0x10;
                    *(short*)(s + 0x14) = 0;
                    *(uint*)(s + 0x5c) = 0;
                    *(int*)(s + 0x50) = 0;
                    *(int*)(s + 0x54) = 0;
                    *(int*)(s + 0x58) = 0;
                    s[9] = 0;
                    *(uint*)(s + 0x18) = 0;
                }
            }
        }

        // ---------------------------------------------- (B) la publication vers les globales
        Mem.CopyDwords((uint*)(s + 0x1c), (uint*)Mem.Entity(0x005fa4e0), 10);
        *(uint*)Mem.Arena(0x005e9b4c) = *(uint*)(s + 0x80);
        *(uint*)Mem.Arena(0x005e9b50) = *(uint*)(s + 0x84);
        *(uint*)Mem.Arena(0x005e9b44) = *(uint*)(s + 0x88);
        *(uint*)Mem.Arena(0x005e9b48) = *(uint*)(s + 0x8c);
        *(int*)Mem.Entity(0x005f7cc4) = *(int*)(s + 0x78);

        // Ghidra: `_DAT_005ff3e8 = *puVar3;`. L'adresse LUE plus haut est 0x005ff3e4 et celle
        // ECRITE ici est 0x005ff3e8 — deux cases voisines et distinctes, verifie au
        // desassembleur (`mov [5FF3E8h],eax` en 0x0050cd43).
        *(uint*)Mem.Entity(0x005ff3e8) = *slot;
        *(ushort*)Mem.Entity(0x0060083c) = *(ushort*)(s + 0x90);

        // ---------------------------------------------- (C) l'integration de la vitesse
        //
        // **Le triplet est (sinus, 0, cosinus), verifie au desassembleur** (0x0050cd63..0x0050cd7e)
        // et non deduit de la pseudo-C, qui attache les deux noms aux mauvais emplacements et rend
        // la mise a zero de Y comme un `iStack_10 = 0` mort.
        int facing = *(short*)(s + 0x98);
        int* heading = stackalloc int[3];
        heading[0] = (int)Winsys3d.GetSinTableEntry(facing);
        heading[1] = 0;
        heading[2] = Winsys3d.GetCosTableEntry(facing);

        int* carried = stackalloc int[3];

        if ((*slot & 1) == 0)
        {
            if ((*slot & 0x10) == 0)
            {
                // Le cap est bascule sur la pente : on sonde le sol un seizieme d'unite devant,
                // et Ordinal_439 normalise le vecteur qui joint les deux points.
                int* slope = stackalloc int[3];
                slope[0] = heading[0] * 0x10 + *(int*)(s + 0x1c);
                slope[2] = heading[2] * 0x10 + *(int*)(s + 0x24);

                // Ghidra appelle GroundHeightOnFace AVANT d'ecrire slope[1] : la hauteur passee est
                // celle laissee par le tour precedent. Conserve — la fonction ne lit que X et Z.
                int groundAhead = GroundHeightOnFace(*(uint**)(s + 0x7c), slope);

                slope[1] = ((groundAhead - *(int*)(s + 0x20)) >> 0xc) - 5;
                slope[0] = (heading[0] << 4) >> 0xc;
                slope[2] = (heading[2] << 4) >> 0xc;
                Winsys3d.Ordinal_439(slope, heading);
            }

            int speed = *(int*)(s + 0x5c);
            if ((*(uint*)(s + 0x90) & 0x100) == 0)
            {
                carried[0] = *(int*)(s + 0x50);
                carried[2] = *(int*)(s + 0x58);
                heading[0] = heading[0] * speed >> 0xc;
                heading[1] = heading[1] * speed >> 0xc;
                carried[1] = *(int*)(s + 0x54);
                heading[2] = heading[2] * speed >> 0xc;
            }
            else
            {
                // Le regime « monte » : cinq bits de plus a l'amortissement, et le vecteur de
                // l'entree d'emplacement s'ajoute au cap.
                heading[0] = heading[0] * speed >> 0x11;
                heading[1] = heading[1] * speed >> 0x11;
                heading[2] = heading[2] * speed >> 0x11;

                if ((*slot & 0x10) == 0)
                {
                    heading[0] += *(short*)(entry + 0x44) * 4;
                    heading[1] += *(short*)(entry + 0x46) * 4;
                    heading[2] += *(short*)(entry + 0x48) * 4;
                }

                carried[0] = *(int*)(s + 0x50) >> 5;
                carried[1] = *(int*)(s + 0x54) >> 5;
                carried[2] = *(int*)(s + 0x58) >> 5;
            }
        }
        else
        {
            heading[0] = heading[0] * *(int*)(s + 0x5c) >> 0x10;
            heading[2] = heading[2] * *(int*)(s + 0x5c) >> 0x10;
            carried[0] = *(int*)(s + 0x50) >> 4;
            carried[2] = *(int*)(s + 0x58) >> 4;
            carried[1] = 0;
        }

        // ---------------------------------------------- (D) le porteur
        int* push = stackalloc int[3];
        push[0] = 0;
        push[1] = 0;
        push[2] = 0;

        byte* carrier = *(byte**)(s + 0x78);
        if (carrier != null)
        {
            if ((carrier[7] & 0x40) != 0)
            {
                *(short*)(s + 0x32) += (short)(*(short*)(carrier + 0x32) - *(short*)(entry + 0x3e));
                ComputeCarrierOffset(entry, carrier, push);

                if (((*(ushort*)(carrier + 0x34) | *(ushort*)(entry + 0x40)) & 0xfff) != 0)
                {
                    push[0] = -push[0];
                    push[1] = -0xa000 - push[1];
                    push[2] = -push[2];
                }
            }

            if ((carrier[7] & 0x20) != 0)
            {
                push[0] += *(int*)(carrier + 0x1c) - *(int*)(entry + 0x28);
                push[1] += *(int*)(carrier + 0x20) - *(int*)(entry + 0x2c);
                push[2] += *(int*)(carrier + 0x24) - *(int*)(entry + 0x30);
            }

            if ((carrier[7] & 0x10) != 0)
            {
                push[0] += *(int*)(carrier + 0x50);
                push[1] += *(int*)(carrier + 0x54);
                push[2] += *(int*)(carrier + 0x58);
            }

            if ((*slot & 1) == 0 && (*slot & 0x10) != 0)
            {
                *(int*)(s + 0x50) += push[0];
                *(int*)(s + 0x54) += push[1];
                *(int*)(s + 0x58) += push[2];
            }
        }

        // ---------------------------------------------- (E) deux demi-pas de placement
        *(int*)(s + 0x50) += heading[0] - carried[0];
        *(int*)(s + 0x54) += heading[1] - carried[1];
        *(int*)(s + 0x58) += heading[2] - carried[2];

        PullEntityTowardCameraTarget_00519F50(slot, entry);

        uint gathered = 0;
        *slot &= 0xdfffffff;

        // Deux demi-pas plutot qu'un pas entier : le placement rattrape une marche que le pas
        // entier aurait traversee. Le premier tour efface les trois bits de face du resultat.
        for (int half = 2; half != 0; half--)
        {
            *(int*)(s + 0x1c) += *(int*)(s + 0x50) >> 1;
            *(int*)(s + 0x20) += *(int*)(s + 0x54) >> 1;
            *(int*)(s + 0x24) += *(int*)(s + 0x58) >> 1;

            FinalizeEntityPlacement2(slot);
            gathered |= *(uint*)(s + 0x90);
            if (half == 2) gathered &= 0xfffff8ff;
        }

        *(uint*)(s + 0x90) = gathered;
        ApplyEntityMotion_00519DF0(slot, entry);

        // L'entree dans une zone marquee : le script d'ambiance part une fois.
        if ((*(ushort*)Mem.Entity(0x0060083c) & 0x8000) == 0
            && (*(uint*)(s + 0x90) & 0x8000) != 0
            && *(sbyte*)(s_Unknown_005f2ce0 + 0x11) != -1)
        {
            RunEntityScript(s_Unknown_005e97cc, s, (uint)*(sbyte*)(s_Unknown_005f2ce0 + 0x11));
        }

        // ---------------------------------------------- (F) l'amortissement et le rebond
        short gravity = *(short*)(s + 0x9a);
        int vx = *(int*)(s + 0x50) - (*(int*)(s + 0x50) >> 8);
        *(int*)(s + 0x50) = vx;

        int vy = *(int*)(s + 0x54) + (((gravity >> 8) - (*(int*)(s + 0x54) >> 8)) - gravity);
        int vz = *(int*)(s + 0x58) - (*(int*)(s + 0x58) >> 8);
        *(int*)(s + 0x54) = vy;
        *(int*)(s + 0x58) = vz;

        if (vy < 1) *(short*)(s + 0x9a) = 0x6000;

        attributes = *(uint*)(s + 0x90);
        if ((attributes & 0x800) != 0)
        {
            // Le placement a refuse : on revient a la position d'avant, publiee en (B).
            *(int*)(s + 0x1c) = *(int*)Mem.Entity(0x005fa4e0);
            *(int*)(s + 0x24) = *(int*)Mem.Entity(0x005fa4e8);

            uint after = *slot;
            if ((after & 1) == 0) *(int*)(s + 0x20) = *(int*)Mem.Entity(0x005fa4e4);

            *(uint*)(s + 0x80) = *(uint*)Mem.Arena(0x005e9b4c);
            *(uint*)(s + 0x84) = *(uint*)Mem.Arena(0x005e9b50);
            *(uint*)(s + 0x88) = *(uint*)Mem.Arena(0x005e9b44);
            *(uint*)(s + 0x8c) = *(uint*)Mem.Arena(0x005e9b48);
            *(int*)(s + 0x78) = *(int*)Mem.Entity(0x005f7cc4);

            if ((perChar[0x150] & 7) == 2)
            {
                if ((after & 4) == 0)
                {
                    *(int*)(s + 0x50) = 0;
                    *(int*)(s + 0x58) = 0;
                }
                else
                {
                    // Le rebond contre un mur en pleine course : la vitesse s'inverse de moitie et
                    // le personnage est relance vers le haut.
                    *(short*)(s + 0x9a) = 0x6000;
                    *(uint*)(s + 0x18) = 4;
                    *slot = (after & 0xfefffffb) | 1;
                    *(int*)(s + 0x50) = -(vx >> 1);
                    *(int*)(s + 0x54) = 0xe000;
                    *(int*)(s + 0x20) += 0xe000;
                    *(int*)(s + 0x58) = -(vz >> 1);
                    entry[0x0a] = 0;
                }
            }
            else
            {
                *(int*)(s + 0x50) = 0;
                *(int*)(s + 0x58) = 0;
            }

            if ((*(uint*)(s + 0x90) & 0x10000000) == 0)
            {
                byte* holder = *(byte**)Mem.Entity(0x005f7cc4);
                if (holder != null)
                {
                    *(int*)(s + 0x1c) += push[0];
                    *(int*)(s + 0x24) += push[2];

                    if ((*slot & 1) == 0)
                    {
                        if ((*slot & 0x20) != 0)
                        {
                            int lifted = push[1] + *(int*)(s + 0x20);
                            *(int*)(s + 0x20) = Math.Max(lifted, *(int*)(s + 0x60));
                        }
                    }
                    else
                    {
                        *(int*)(s + 0x50) = push[0];
                        *(int*)(s + 0x58) = push[2];

                        int drop = *(int*)(holder + 0x20) - *(int*)(s + 0x20);
                        if (drop < -0xc7fff)
                        {
                            *(int*)(s + 0x54) = drop >> 4;
                            *(int*)(s + 0x20) += drop >> 4;
                        }
                    }
                }
            }
            else if ((*(uint*)(s + 0x90) & 0x40000000) != 0 && (*slot & 1) == 0)
            {
                *(int*)(s + 0x54) = 0;
            }

            FinalizeEntityPlacement2(slot);
            ApplyEntityMotion_00519DF0(slot, entry);

            attributes = *(uint*)(s + 0x90);
            if ((attributes & 0x800) != 0)
            {
                if ((attributes & 0x10000000) == 0)
                {
                    byte* target = *(byte**)(s + 0x78);
                    if (target != null)
                    {
                        // Toujours refuse : on glisse d'un seizieme vers le porteur plutot que de
                        // rester bloque.
                        int slideX = *(int*)(target + 0x1c) - *(int*)(s + 0x1c);
                        int slideZ = *(int*)(target + 0x24) - *(int*)(s + 0x24);
                        *(int*)(s + 0x1c) += slideX >> 4;
                        *(int*)(s + 0x24) += slideZ >> 4;

                        if ((*slot & 1) == 0)
                        {
                            if ((*slot & 0x20) != 0) *(int*)(s + 0x20) = *(int*)(s + 0x60);
                        }
                        else
                        {
                            *(int*)(s + 0x50) += slideX >> 4;
                            *(int*)(s + 0x58) += slideZ >> 4;
                        }
                    }
                }
                else if ((attributes & 0x40000000) != 0 && (*slot & 1) == 0)
                {
                    *(int*)(s + 0x54) = 0;
                }
            }
        }

        // ---------------------------------------------- (G) le sol et le plafond
        if (*(int*)(s + 0x64) < *(int*)(s + 0x20) || (attributes & 0xa000) != 0)
        {
            uint after = *slot;
            if ((after & 1) == 0)
            {
                *(short*)(s + 0x9a) = 0x6000;
                *slot = (after & 0xfffffffb) | 1;
                if ((after & 0x40000002) == 0)
                {
                    *(uint*)(s + 0x18) = 4;
                    *slot = (after & 0xfefffffb) | 1;
                }
            }
        }
        else
        {
            // Pose au sol : la matiere de la face devient celle des pas, et le contact peut
            // declencher un son et une pose.
            byte* material = Mem.Entity(0x005fa508) + *(ushort*)(*(byte**)(s + 0x7c) + 8) * 8;
            *(uint*)(entry + 0x44) = *(uint*)material;
            *(uint*)(entry + 0x48) = *(uint*)(material + 4);

            int ground = *(int*)(s + 0x64);
            if (*(int*)(s + 0x20) + 0xa000 < ground) *(int*)(s + 0x54) = 0;
            *(int*)(s + 0x20) = ground;

            DispatchEntityHandler(
                Res.ResolveEntityHandler(0x0056afc8, 32), s,
                $"FUN_0050bf20, membre {member} : le crochet de contact au sol PTR_FUN_0056b048");

            if ((*(uint*)(s + 0x90) & 0x400) != 0
                && *(short*)(s + 0x96) == 0
                && (perChar[0x150] & 7) != 7
                && (*(uint*)(perChar + 0x140) & 0x40400000) == 0)
            {
                Aud.PlayPositionalSound(5, 0xa00, 0x1800, (int*)(s + 0x1c));
                ApplyPercentDamage_005397B0(slot, 2, 0);
                pad[0x0c] = 0;
                *(short*)(s + 0x96) = 0x10;
            }

            if ((*slot & 1) != 0)
            {
                if (*(int*)(s + 0x54) < -0x18000)
                {
                    Aud.PlayPositionalSound(1, 0x400, 0x1800, (int*)(s + 0x1c));
                }

                uint landing = *slot;
                if ((landing & 0x40000042) == 0)
                {
                    *(uint*)(s + 0x18) = 0;
                    *slot = landing | 0x1000000;
                }

                *slot &= 0xfffffffe;
            }

            entry[0x0a] = 2;
        }

        // ---------------------------------------------- (H) la cascade de fin
        held = *slot;
        if ((held & 0x40000000) != 0)
        {
            *(short*)(s + 0x96) = 0;
            return;
        }

        // L'instantane que la sous-zone relira si ce membre doit etre restitue.
        if ((held & 0x40000001) == 0
            && ((*(uint*)(s + 0x90) & 0xad40) == 0 || (*(uint*)(s + 0x90) & 2) != 0)
            && (*(int*)(s + 0x78) == 0 || (held & 0x20) == 0))
        {
            *(uint*)Mem.Entity(0x005f7d70) = *(uint*)(s + 0x80);
            *(uint*)Mem.Entity(0x005f7d74) = *(uint*)(s + 0x84);
            *(uint*)Mem.Entity(0x005f7d78) = *(uint*)(s + 0x88);
            *(uint*)Mem.Entity(0x005f7d7c) = *(uint*)(s + 0x8c);
            *(int*)Mem.Arena(0x005e9a30) = *(int*)(s + 0x1c);
            *(int*)Mem.Arena(0x005e9a34) = *(int*)(s + 0x20);
            *(int*)Mem.Arena(0x005e9a38) = *(int*)(s + 0x24);
            *(uint*)Mem.Entity(0x005ff3e4) = *slot;
            *(short*)Mem.Arena(0x005e9b38) = *(short*)(s + 0x90);
            *(uint*)Mem.Entity(0x005f7b48) = *(uint*)(s + 0x7c);
        }

        // Le coup recu : l'entite que la collision a designee, si elle est armee.
        byte* hit = CollectEntityHit_005197D0(slot);
        if (hit != null && (*(uint*)hit & 0x80080000) == 0x80080000)
        {
            uint kind = *(uint*)hit;
            if ((kind & 0x8000) == 0)
            {
                if ((kind & 0x10000000) == 0)
                {
                    // EXPERIENCE repartie sur tout le groupe encore debout — et non « degats »,
                    // comme ce commentaire le disait jusqu'au 2026-08-29 : la part s'ajoute a
                    // +0x158, la jauge que CheckLevelUp_00539190 examine juste apres.
                    int index = 0;
                    int offset = 0;
                    uint* victim = (uint*)Inp.s_SlotFlags_005e93c0;
                    while (index < s_PartySize_005e9020)
                    {
                        if ((*victim & 0x80000000) != 0 && (*victim & 0x50000000) == 0)
                        {
                            int share = (int)(*(uint*)((byte*)hit + 0x5c)
                                              - *(ushort*)(mainMem + 0xf0144 + offset)) >> 1;
                            share += (int)*(uint*)((byte*)hit + 0x5c) >> 1;
                            if (share < 0) share = 0;

                            share += (int)(*(uint*)((byte*)hit + 0x5c) + 0xf) >> 4;
                            *(int*)(mainMem + 0xf0158 + offset) += share;

                            CheckLevelUp_00539190((byte*)victim, mainMem + 0xf0000 + offset);
                        }

                        index++;
                        offset += 0x2000;
                        victim = (uint*)((byte*)victim + 0x9c);
                    }
                }
                else
                {
                    uint purse = (uint)(*(int*)(perChar + 0x26c) + (int)(*(uint*)((byte*)hit + 0x5c) + 9) / 10);
                    *(uint*)(perChar + 0x26c) = purse;
                    if (purse > 99999) *(uint*)(perChar + 0x26c) = 99999;
                }

                *(uint*)hit &= 0x7fffffff;
                FreeEntitySlot(Mem.Entity(0x005f7b60), ((byte*)hit)[8]);
                Aud.PlayPositionalSound(7, 0x800, 0x1000, (int*)(s + 0x1c));
            }
            else if ((*slot & 0x10000) == 0)
            {
                if (((byte*)hit)[6] == 0)
                {
                    *(byte**)(s + 0x6c) = hit;
                    GrantChestContents_00530F20(slot, ((byte*)hit)[7], 0x005312d0);
                    Aud.PlayPositionalSound(0x21, 0x800, 0x1800, (int*)(s + 0x1c));
                }
                else
                {
                    byte* labels = *(byte**)(Mem.s_MainResourceDirectory_005e97c4 + 0x70);
                    if ((perChar[0x150] & 7) == 2)
                    {
                        BindMenuLabels(*(byte**)(labels + 0x5a0), (uint)(nuint)slot,
                            s_WorldMapDescriptor_005633b0, 0);
                    }
                    else
                    {
                        BindMenuLabels(*(byte**)(labels + 0x550), (uint)(nuint)slot,
                            s_WorldMapDescriptor_005633b0, 0);
                        SpawnEffectEntity(s, ((byte*)hit)[6], 0, 0);
                    }

                    ((byte*)hit)[6] = 0;
                    if (*(short*)((byte*)hit + 0x10) < 0x32) *(short*)((byte*)hit + 0x10) = 0x32;
                }
            }
        }

        // LE COUP, sur la derniere image du geste — et non « le pas sonore », comme ce commentaire
        // le disait jusqu'au 2026-08-29 : voir SweepSceneEntitiesForMeleeHit_00519940. Les deux
        // postures ecartees (4 et 7, modulo 8) sont exactement celles dont le gabarit de portee est
        // entierement nul dans la table de 0x00562cf0.
        if ((*slot & 2) != 0)
        {
            byte posture = perChar[0x150];
            if ((posture & 7) != 4 && (posture & 7) != 7)
            {
                byte* animSet = *(byte**)(Mem.Arena(0x005e9680) + s[4] * 4);
                byte* anim = *(byte**)(animSet + *(short*)(s + 0x18) * 4);

                if ((uint)(*(short*)(s + 0x1a) + 1) == *(ushort*)(anim + 0x16))
                {
                    uint row = posture;
                    if ((posture & 7) == 0 && *(short*)(s + 0x18) == 6) row = (row >> 3) + 0x10;

                    SweepSceneEntitiesForMeleeHit_00519940((byte*)slot, (int*)(s + 0x1c), MeleeProbeForPosture(row));
                }
            }
        }

        UpdateEntityShadow_00519EE0(slot, perChar);

        if ((*(uint*)(s + 0x90) & 0x8000) == 0) TestTriggerVolumes_00534CD0(slot);

        // Le changement de sous-zone : la face foulee porte l'identifiant de la zone voisine.
        byte destination = (*(byte**)(s + 0x7c))[0x0f];
        if (destination != 0
            && (uint)*Mem.Camera(0x005de058) != destination - 1u
            && (*(uint*)(s + 0x90) & 0x2000) == 0)
        {
            uint before = *slot;
            *(short*)(s + 0x98) = *(short*)(s + 0x32);
            *slot = (before & 0xf7fffdff) | 0x2000;
            (*(ushort*)(s + 0x12))++;

            Res.s_Unknown_005de528 = s_Unknown_00566c84;
            s_Unknown_005de52c = s_Unknown_00566c88;
            s_Unknown_005de53c = s[8];
            *(byte*)Mem.Camera(0x005de038) = (byte)(destination - 1);
            s_WorldMapStep_005645f8 = 1;
        }

        // L'immobilite : deux comptes a rebours descendent tant que rien ne bouge, et repartent au
        // maximum des qu'une touche ou une vitesse apparait.
        if (*(short*)(s + 0x32) == *(short*)Mem.Entity(0x005fa4f6)
            && *(int*)(s + 0x5c) == 0
            && *(short*)(s + 0x96) == 0
            && (*slot & 6) == 0
            && (*pad & 0xf0) == 0)
        {
            if (perChar[0x206] != 0) perChar[0x206]--;

            if (s[8] == (byte)Mem.s_Unknown_005de538 && *(ushort*)Mem.Arena(0x005e9ae6) != 0)
            {
                (*(ushort*)Mem.Arena(0x005e9ae6))--;
            }
        }
        else
        {
            perChar[0x206] = 100;
            if (s[8] == (byte)Mem.s_Unknown_005de538) *(ushort*)Mem.Arena(0x005e9ae6) = 300;
        }

        if (s_Unknown_00566c84 != 0 && *(ushort*)(s + 0x12) == 0)
        {
            AdvanceSceneEntityAnimation_0053aa10(s);
        }

        *slot |= 0xe00;
    }

    /// <summary>
    /// Ghidra: 0x0050cfb1..0x0050d290 — <b>l'offset impose par le porteur</b>, quand un membre du
    /// groupe est transporte par une autre entite.
    ///
    /// <para>
    /// Deux produits matrice-vecteur en 64 bits, decalage <c>&gt;&gt; 12</c> chacun. La premiere matrice
    /// est la <b>transposee</b> de celle du repere de l'emplacement : le code la construit avec
    /// <c>RotMatrix</c> puis la retourne a la main dans l'ordre 0,3,6 / 1,4,7 / 2,5,8. La seconde
    /// est celle du porteur. Autrement dit : exprimer la position dans le repere local de
    /// l'emplacement, puis la re-exprimer dans celui de ce qui le porte — un attachement
    /// pere-fils. Le resultat est la difference entre la position ainsi transportee et la position
    /// d'origine.
    /// </para>
    /// <para>
    /// <b>Ghidra brouille l'ordre des operandes dans chaque triplet</b>, ce qui donne l'illusion
    /// que les composantes sont permutees entre les deux passes. Elles ne le sont pas : la somme
    /// est commutative, et ce qui compte est quel coefficient va avec quel emplacement de pile. En
    /// suivant les <c>[esp+N]</c> a travers les <c>push</c>, les deux passes sont le meme
    /// <c>ligne_i = (m[3i]*x + m[3i+1]*y + m[3i+2]*z) &gt;&gt; 12</c>.
    /// </para>
    /// </summary>
    private static void ComputeCarrierOffset(byte* entry, byte* carrier, int* offset)
    {
        EnsureGteRegisters();

        short* work = (short*)Mem.Arena(0x005e9b20);
        short* transposed = (short*)Mem.Arena(0x005e9b00);

        RotMatrix((short*)(entry + 0x3c), work);

        transposed[0] = work[0]; transposed[1] = work[3]; transposed[2] = work[6];
        transposed[3] = work[1]; transposed[4] = work[4]; transposed[5] = work[7];
        transposed[6] = work[2]; transposed[7] = work[5]; transposed[8] = work[8];

        RotMatrix((short*)(carrier + 0x30), work);

        int* local = stackalloc int[3];
        int* world = stackalloc int[3];

        Winsys3d.Ordinal_366(transposed);
        ApplyGteMatrix((int*)(entry + 0x1c), local);

        Winsys3d.Ordinal_366(work);
        ApplyGteMatrix(local, world);

        offset[0] = world[0] - *(int*)(entry + 0x1c);
        offset[1] = world[1] - *(int*)(entry + 0x20);
        offset[2] = world[2] - *(int*)(entry + 0x24);
    }

    /// <summary>
    /// Le produit matrice-vecteur que le binaire ecrit en <c>__allmul</c>/<c>__allshr</c> : neuf
    /// multiplications 64 bits et un decalage de 12. La matrice est celle que le dernier
    /// <c>Ordinal_366</c> a chargee dans le registre MATRIX de la DLL (export 814).
    /// </summary>
    private static void ApplyGteMatrix(int* vector, int* result)
    {
        short* m = (short*)s_GteMatrix814;

        for (int row = 0; row < 3; row++)
        {
            long sum = (long)m[row * 3] * vector[0]
                     + (long)m[row * 3 + 1] * vector[1]
                     + (long)m[row * 3 + 2] * vector[2];
            result[row] = (int)(sum >> 12);
        }
    }

    /// <summary>
    /// Ghidra: FUN_005397b0 @ 0x005397b0 — <b>applique des degats en pourcentage des points de vie
    /// maximaux</b>, avec le verrou d'invulnerabilite qui va avec. Le corps est dans
    /// <c>Blaze.c</c> ; il etait stube ici sous le nom <c>SetEntityPose_005397B0</c>, qui <b>etait
    /// faux</b> : il n'y a aucune pose la-dedans.
    ///
    /// <para>
    /// Ce que la lecture du corps donne, et que l'adresse seule ne donnait pas : <c>+0x96</c> est un
    /// <b>verrou d'invulnerabilite</b>. Non nul, le coup ne passe pas du tout ; la fonction le pose
    /// a <c>0x10</c> des qu'elle frappe. Les deux appelants deja transcrits le confirment — ils le
    /// mettent a zero juste avant l'appel et le remettent a <c>0x10</c> juste apres, pour forcer un
    /// coup a travers.
    /// </para>
    /// <para>
    /// Les degats sont <c>PV_max * pourcentage / 100</c>, avec un <b>plancher a 1</b> : un
    /// pourcentage trop petit pour valoir un point en vaut quand meme un. A zero point de vie, le
    /// bit <c>0x40000000</c> part <b>a la fois</b> sur le bloc du personnage et sur son entite.
    /// </para>
    /// <para>
    /// <b>Deux champs sont sauves et rendus</b> autour de la naissance de l'effet <c>0x50</c> :
    /// <c>+0x18</c> et <c>+0x0a</c>. L'effet herite d'une copie de l'entite
    /// (<see cref="SpawnEffectEntity"/>), donc le binaire y glisse <c>100</c> et
    /// <paramref name="effectParam"/> le temps de l'appel, puis remet les valeurs d'origine. Sans
    /// cette restitution, une entite frappee garderait la teinte de son propre effet de degats.
    /// </para>
    /// </summary>
    private static void ApplyPercentDamage_005397B0(uint* entity, int percent, ushort effectParam)
    {
        byte* e = (byte*)entity;

        if (*(short*)(e + 0x96) != 0) return;
        *(short*)(e + 0x96) = 0x10;

        // Ghidra: `((byte)param_1[2] + 0x78) * 0x2000 + MainMem` — l'octet +0x8 est l'index de
        // membre, et 0x78 * 0x2000 vaut 0xf0000, le meme decalage de bloc de personnage que
        // AreaVerb_0053DEA0 ecrit `membre * 0x2000 + 0xf02bc`.
        byte* character = GetMainMemPtr() + (e[8] + 0x78) * 0x2000;

        int damage = *(short*)(character + 0x148) * percent / 100;
        if (damage == 0) damage = 1;

        *(short*)(character + 0x14c) -= (short)damage;
        if (*(short*)(character + 0x14c) < 1)
        {
            *(ushort*)(character + 0x14c) = 0;
            *(uint*)(character + 0x140) |= 0x40000000;
            *(uint*)e |= 0x40000000;
        }

        *(ushort*)(character + 0x196) = 0;
        *(uint*)(character + 0x140) &= 0xffffffbf;

        SpawnParticle_0050F070((uint*)(e + 0x1c), (uint)damage, 0);

        uint savedTint = *(uint*)(e + 0x18);
        ushort savedFacing = *(ushort*)(e + 0x0a);
        *(ushort*)(e + 0x18) = 100;
        *(ushort*)(e + 0x1a) = effectParam;

        SpawnEffectEntity(e, 0x50, 0, 0);                 // Ghidra: FUN_0047a9d0

        *(uint*)(e + 0x18) = savedTint;
        *(ushort*)(e + 0x0a) = savedFacing;
    }


    /// <summary>
    /// Ghidra: FUN_005197d0 @ 0x005197d0 — <b>la collecte du coup recu</b> : un balayage 3x3 des
    /// cellules de la seconde grille spatiale autour du personnage, qui rend la premiere entite
    /// armee (bit <c>0x80000</c>) assez proche pour toucher, ou zero.
    ///
    /// <para>
    /// « Assez proche » se lit en deux temps : moins de 0x28 unites au sol, et une difference de
    /// hauteur dans une bande de <c>±0x50</c> — le test <c>(dy + 0x50) &lt; 0xa0</c> en <b>non
    /// signe</b>, qui rejette les deux debordements d'un coup.
    /// </para>
    /// <para>
    /// <b>Chaque entite ne touche qu'une fois.</b> L'octet <c>+0x09</c> de la candidate porte un
    /// bit par emplacement de personnage : il est pose au moment du coup et n'est efface que
    /// lorsque la distance repasse au-dessus du seuil. Une entite qui reste collee ne blesse donc
    /// pas a chaque image.
    /// </para>
    /// <para>
    /// <b>La constante de grille est <c>0x389f</c> et non <c>0x38a0</c></b> : le <c>-1</c> du
    /// balayage est replie dedans, la ou <see cref="ApplyEntityMotion_00519DF0"/> l'ecrit a part.
    /// La consequence est reelle et conservee : pour un personnage dans la rangee 0, la premiere
    /// des trois rangees balayees est <c>0x389f</c>, c'est-a-dire <b>la derniere rangee de l'autre
    /// grille</b> — les deux pages etant adjacentes (0x1c4000 et 0x1c5000). Le garde
    /// <c>row &lt; 0x71800</c> ne borne que le haut.
    /// </para>
    /// </summary>
    private static byte* CollectEntityHit_005197D0(uint* entityPtr)
    {
        byte* entity = (byte*)entityPtr;
        byte* mainMem = GetMainMemPtr();

        int y = *(int*)(entity + 0x20);
        int x = *(int*)(entity + 0x1c);
        int z = *(int*)(entity + 0x24);

        uint cellX = (uint)(((((x >> 0xc) + 0x2000) >> 9) - 1));
        uint row = (uint)((((z >> 0xc) + 0x2000) >> 9) + 0x389f) * 0x20;

        byte mask = (byte)(1 << (entity[8] & 0x1f));

        for (int outer = 3; outer != 0; outer--)
        {
            uint column = cellX;

            for (int inner = 3; inner != 0; inner--)
            {
                if (column < 0x20 && row < 0x71800)
                {
                    for (byte* candidate = *(byte**)(mainMem + (column + row) * 4);
                         candidate != null;
                         candidate = *(byte**)(candidate + 0x68))
                    {
                        int candidateY = *(int*)(candidate + 0x20);
                        int dx = (x - *(int*)(candidate + 0x1c)) >> 0xc;
                        int dz = (z - *(int*)(candidate + 0x24)) >> 0xc;
                        int distance = (int)Winsys3d.Ordinal_442((uint)(dx * dx + dz * dz));

                        if ((*(uint*)candidate & 0x80000) == 0) continue;

                        if (distance < 0x28 && (uint)(((y - candidateY) >> 0xc) + 0x50) < 0xa0)
                        {
                            if ((candidate[9] & mask) == 0)
                            {
                                candidate[9] |= mask;
                                *Mem.Camera(0x005de0b8) = 1;
                                return candidate;
                            }
                        }
                        else
                        {
                            candidate[9] &= (byte)~mask;
                        }
                    }
                }

                column++;
            }

            cellX = column - 3;
            row += 0x20;
        }

        // Ghidra: `DAT_005de0b8 = local_14;` — le compteur de boucle, nul a la sortie.
        *Mem.Camera(0x005de0b8) = 0;
        return null;
    }

    /// <summary>
    /// Ghidra: FUN_00539190 @ 0x00539190 — <b>la verification de palier apres un gain
    /// d'experience</b>, en basculant l'allocateur de la DLL sur le tampon de travail le temps du
    /// calcul. Exactement la meme enveloppe que <see cref="RunEntityScript"/> autour de
    /// <c>RunScript</c> : <c>Ordinal_46</c> rend l'etat courant de l'allocateur, negatif voulant
    /// dire « rien a preserver ».
    ///
    /// <para>
    /// <b>Elle s'appelait <c>ApplyDamageToMember_00539190</c> et ce nom etait faux</b> — elle
    /// n'applique aucun degat. Le site d'appel le montre : <c>+0x158</c> vient de recevoir
    /// l'experience du coup, et c'est cela qu'elle examine. Troisieme nom invente tombe le
    /// 2026-08-29, tous les trois sur le chemin « taper sur un monstre ».
    /// </para>
    /// <para>
    /// <b>Ghidra rend le second appel comme <c>FUN_005391f0(unaff_retaddr, param_1)</c></b>, ce qui
    /// n'a pas de sens. Le desassemblage tranche : les deux branches font
    /// <c>push [esp+8] ; push [esp+4] ; call</c>, donc les deux passent <c>(param_1, param_2)</c>.
    /// L'artefact vient de ce que Ghidra a perdu le niveau de pile apres l'appel <b>stdcall</b> a
    /// <c>Ordinal_45</c>, qui depile lui-meme son argument.
    /// </para>
    /// </summary>
    private static void CheckLevelUp_00539190(byte* member, byte* character)
    {
        if (Winsys3d.Ordinal_46() < 0)
        {
            LevelUpCharacter_005391F0(member, character);
            return;
        }

        *(int*)Mem.Arena(0x005e9318) = Winsys3d.Ordinal_46();
        Winsys3d.Ordinal_45(GetMainMemPtr() + 0x1c0000);
        LevelUpCharacter_005391F0(member, character);
        Winsys3d.Ordinal_45((void*)(nint)(*(int*)Mem.Arena(0x005e9318)));
    }

    /// <summary>
    /// Ghidra: <c>&amp;DAT_0056d308</c> — <b>la caracteristique favorisee par un ELEMENT</b>, un
    /// octet pour chacun des six premiers. Relevee dans le binaire : <c>00 01 04 03 02 05</c>, une
    /// permutation de 0..5 — chaque element pousse une caracteristique differente d'un cinquieme a
    /// la montee de niveau, et les elements 6 et 7 poussent les six d'un vingtieme.
    ///
    /// <para>
    /// <b>Le champ indexeur est <c>+0x151</c>, et il porte l'element, pas une sous-classe</b> —
    /// <c>DebugParty</c> et l'ecran de creation le remplissent tous deux depuis la <b>huitieme</b>
    /// colonne de <c>s_ClassBaseStats_0056c7e0</c>, celle que le bestiaire a identifiee comme
    /// l'element. Ce symbole s'appelait <c>s_SubClassFavouredStat_0056D308</c> jusqu'au
    /// 2026-08-29 : le nom etait une supposition, pas un releve.
    /// </para>
    /// </summary>
    private static readonly byte[] s_ElementFavouredStat_0056D308 = [0, 1, 4, 3, 2, 5];

    /// <summary>
    /// Ghidra: <c>&amp;DAT_0056d310</c> — <b>les chances de progression par classe</b>, un dword
    /// pour chacune des huit, releve dans le binaire. Chaque dword porte quatre octets lus deux par
    /// deux : <c>(base physique, diviseur physique, base mentale, diviseur mental)</c>, d'ou
    /// <c>chance = septieme caracteristique / diviseur + base</c>.
    ///
    /// <para>Trois valeurs seulement pour huit classes — <c>0x04280241</c>, <c>0x023c0423</c> et
    /// <c>0x03320332</c> — reparties en 0,6 · 1,3,7 · 2,4,5. Les classes se rangent donc en trois
    /// familles de progression.</para>
    /// </summary>
    private static readonly uint[] s_ClassGrowthOdds_0056D310 =
    [
        0x04280241, 0x023c0423, 0x03320332, 0x023c0423,
        0x03320332, 0x03320332, 0x04280241, 0x023c0423,
