    private static readonly byte[] s_LevelUpEffect_005648A8 =
    [
        0xd8, 0x58, 0x27, 0x08, 0x01, 0x00, 0x30, 0x02,
        0xa2, 0x20, 0x32, 0x08, 0x01, 0x00, 0x30, 0x02,
        0x00, 0xf8, 0x08, 0x08, 0x00, 0x00, 0x11, 0x06,
